INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (183,'audit:created',160,'App\\Models\\Contract#160',3,'{\"title\":\"2023HRP_PADCED_ARPACOVID19_WHoleHomeRepairs\",\"contract_number\":\"C000084605\",\"purpose\":null,\"funder_id\":null,\"amount\":\"2729544\",\"start_date\":\"2022-12-12\",\"end_date\":\"2026-12-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-04-03 08:29:06\",\"created_at\":\"2023-04-03 08:29:06\",\"id\":160,\"documents\":[],\"media\":[]}','10.55.0.61','2023-04-03 12:29:06','2023-04-03 12:29:06');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (184,'audit:updated',160,'App\\Models\\Contract#160',3,'{\"purpose\":\"<p>-Address habitability and safety concerns, provide measures to improve energy or water efficiency and make units accessible for individuals with disabilities.&nbsp;<\\/p><p>-$2,348,544 for eligible Whole-Home Repairs<\\/p><p>-109,000 for administrative costs<\\/p><p>-$272,000 for provisions and enhancements<\\/p><p>-This is not a reimbursable grant, and we will be receiving all of the funds upfront.<\\/p>\",\"notes\":\"<p>-Money must be fully obligated by December 31, 2024.<\\/p><p>-Funds must be kept in an interest-bearing account<\\/p><p>-Davis Beacon Act -Prime construction contracts in excess of $2,000 must pay prevailing wage and a copy of the current prevailing wage determination issued by the Dept. of Labor in each solicitation<\\/p><p>-Open and Competitive bidding procedures for any contract in excess of $10,000 (must have 3 arm length bids)<\\/p><p>&nbsp;<strong>-COVID Impact Eligibility Question<\\/strong><\\/p><p>*The project\\/client is presumed eligible if the household is a low- or moderate-income household as defined by the State and Local Fiscal Recovery fund guidance.&nbsp; Per SLFRF, Low- or moderate-income households and communities are those with (i) income at or below 300 percent of the Federal Poverty Guidelines for the size of the household based on the most recently published poverty guidelines or (ii) income at or below 65 percent of the area median income for the county and size of household based on the most recently published data. **For households whose income exceeds the federal definition as defined above but falls within the WHR requirement for an eligible homeowner (household income not to exceed 80% of the area median income), the Grantee should document the Covid impact (\\u201cimpacted or \\u201cdisproportionately impacted\\u201d) using the attached FRAMEWORK FOR ELIGIBLE USES BEYOND THOSE ENUMERATED found within the SLFRF Final Rule Overview.<\\/p><p>-All work needs to be done by a qualified contractor who is licensed and insured. Habitat for Humanity cannot use volunteers who do not meet this criterion.<\\/p>\",\"updated_at\":\"2023-04-03 11:19:50\",\"id\":160,\"documents\":[],\"media\":[]}','10.55.0.61','2023-04-03 15:19:50','2023-04-03 15:19:50');
