INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (193,'audit:created',161,'App\\Models\\Contract#161',3,'{\"title\":\"2023RTCLF_TDBank_InvestmentAgreement\",\"contract_number\":null,\"purpose\":\"<p>To provide financial support to primarily minority-owned or minority-managed businesses.&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"1000000\",\"start_date\":\"2023-05-01\",\"end_date\":null,\"notes\":\"<p>-Interest rate of 2.0% annually<\\/p><p>- &nbsp;During the interest payment only period, which is 5 years from the effective date, interest payments are due on April 1, July 1 and October 1 and January 1 of each year. This interest only period can be extended for an additional 3 years by providing written notice to the lender not more than 90 days or less than 30 days before the expiration of the interest only period.<\\/p><p>-Principal and interest payments shall commence quarterly after the 5-year interest only period.<\\/p><p>-Audit report required within 120 days of the Fiscal year end.<\\/p><p>-Lender requires tax returns within 30 days of filling<\\/p><p>-Reporting- By April 30th each year provide summary of portfolio investments, watch list and delinquency reports, capitalization report, capital deployment report and social impact summaries. See page 4 Section 8 of the contract for more details.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-04-21 08:02:51\",\"created_at\":\"2023-04-21 08:02:51\",\"id\":161,\"documents\":[],\"media\":[]}','10.55.0.162','2023-04-21 12:02:51','2023-04-21 12:02:51');
