INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (201,'audit:created',165,'App\\Models\\Contract#165',3,'{\"title\":\"2022REJ_PMUWGenerationNext\",\"contract_number\":null,\"purpose\":\"<p>PMUW will be initiating the Generation Next Program in the Pocono Mountain School District (PMSD) with the potential to expand into the other Monroe County School Districts such as Stroudsburg, East Stroudsburg and Pleasant Valley.<\\/p><p>-Initial $15,000 to be paid up front.<\\/p><p>-$5,500 to be invoiced annually between June and August if curriculum updates are provided for PMSD<\\/p><p>-$3,000 to be invoiced annually between June and August if no curriculum updates are provided for PMSD<\\/p><p>-Additional $2,000 invoiced annually for each additional school district&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2022-09-01\",\"end_date\":null,\"notes\":\"<p><strong>Responsibilities of Gen Next Staff:<\\/strong><\\/p><p>-Provide Curriculum updates to PMUW each year between June and August<\\/p><p>-Provide Data on past program outcomes, measurements and performance data<\\/p><p>-Visit PMSD at least twice per year to provide training and support (If additional districts are added then two visits per district are required annually)<\\/p><p>-Provide shadowing opportunities twice per year for PMUW Gen Next staff for training purposes<\\/p><p>-One visit per year to PMUW main office to ensure confidentiality of student files and data<\\/p><p>-Provide survey tools and resources for data collection<\\/p><p>-Provide updated marketing and branding updates when they become available<\\/p><p>-CALV Gen Next advisory board will provide support twice per year at mid-year and end of year<\\/p><p>-Conduct a mid-year and end of year progress review\\/evaluation and provide feedback<\\/p><p><strong>***Gen Next Staff will be responsible for invoicing PMUW each year for the appropriate fee<\\/strong><\\/p><p><strong>**** This MOU can be terminated at any time by either party withing 60 days of written notice<\\/strong><\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-04-26 10:50:33\",\"created_at\":\"2023-04-26 10:50:33\",\"id\":165,\"documents\":[],\"media\":[]}','10.55.0.162','2023-04-26 14:50:33','2023-04-26 14:50:33');
