INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (203,'audit:updated',165,'App\\Models\\Contract#165',3,'{\"notes\":\"<p><strong>Responsibilities of Gen Next Staff:<\\/strong><\\/p><p>-Provide Curriculum updates to PMUW each year between June and August<\\/p><p>-Provide Data on past program outcomes, measurements and performance data<\\/p><p>-Visit PMSD at least twice per year to provide training and support (If additional districts are added then two visits per district are required annually)<\\/p><p>-Provide shadowing opportunities twice per year for PMUW Gen Next staff for training purposes<\\/p><p>-One visit per year to PMUW main office to ensure confidentiality of student files and data<\\/p><p>-Provide survey tools and resources for data collection<\\/p><p>-Provide updated marketing and branding materials when they become available<\\/p><p>-CALV Gen Next advisory board will provide support twice per year at mid-year and end of year<\\/p><p>-Conduct a mid-year and end of year progress review\\/evaluation and provide feedback<\\/p><p><strong>***Gen Next Staff will be responsible for invoicing PMUW each year for the appropriate fee<\\/strong><\\/p><p><strong>**** This MOU can be terminated at any time by either party withing 60 days of written notice<\\/strong><\\/p>\",\"updated_at\":\"2023-04-26 10:57:08\",\"id\":165,\"documents\":[{\"id\":201,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":165,\"uuid\":\"829c2c26-3a78-486f-82f6-d9cecc600a8c\",\"collection_name\":\"documents\",\"name\":\"644945d9bab4b_2022REJ_PMUWGENNEXT_executedMOU\",\"file_name\":\"644945d9bab4b_2022REJ_PMUWGENNEXT_executedMOU.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":583769,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-04-26T15:50:33.0