INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (205,'audit:created',166,'App\\Models\\Contract#166',3,'{\"title\":\"2022SHFB_NCCDBGCV_Fresh Food Program\",\"contract_number\":null,\"purpose\":\"<p>Purchase of food (consumable food supplies) for mobile pantries, drive thru pantries, senior food programs, SNAP application assistance, summer meal programs, backpack programs, school pantry programs and kids\' cafe in Northampton County <strong>- $55,000<\\/strong><\\/p><p>Salary and Fring benefits<strong>-$10,000<\\/strong><\\/p>\",\"funder_id\":\"2\",\"amount\":\"65000\",\"start_date\":\"2022-10-01\",\"end_date\":\"2023-09-30\",\"notes\":\"<p>-Reimbursable grant-provide itemized invoices and vouchers monthly<\\/p><p>-Use of competitive bidding requirements for expenditures over $5,001 in one transaction<\\/p><p>-Reporting Requirements- semi-annual reports due May 15, 2023 (October1-April 30th) and November 15, 2023 (May 1st- October 30th)<\\/p><p>-Audit is required for this grant<\\/p><p>-County Contact is Frank Brooks<\\/p><p><strong>Direct line (610) 829-6311<\\/strong><\\/p><p><a href=\\\"mailto:fbrooks@northamptoncounty.org\\\"><strong>fbrooks@norcopa.gov<\\/strong><\\/a><\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-04-28 13:14:52\",\"created_at\":\"2023-04-28 13:14:52\",\"id\":166,\"documents\":[],\"media\":[]}','10.55.0.162','2023-04-28 17:14:52','2023-04-28 17:14:52');
