INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (269,'audit:created',188,'App\\Models\\Contract#188',3,'{\"title\":\"2023CADA_EDSI_Paid Work Experience Worksite Agreement\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This contract does not generate revenue for CADA.<\\/p><p>This contract sets up an agreement between CADA and EDSI in conjunction with Workforce Board Lehigh Valley to provide paid work experience to youth in Allentown.<\\/p><p>This program will take place at 215 North 9th Street and be supervised by Pas Simpson of Big Happy Consultants.<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2023-06-06\",\"end_date\":null,\"notes\":\"<p>Compliance:<\\/p><p>-1 supervisor-12 participants<\\/p><p>-Cooperation with PA CareerLink to provide training and education<\\/p><p>-Assess participants with pre and post testing with a Work Readiness Attainment Rating sheet and provide testing to EDSI<\\/p><p>-Summer Youth Program shall not exceed 8 wees continuously and no more than 30 hours a week inclusive of lunch and breaks.<\\/p><p>-Time and attendance signed by participant and supervisor is required to be turned into PA Career Link Lehigh Valley and EDSI staff regularly.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-06-09 09:33:01\",\"created_at\":\"2023-06-09 09:33:01\",\"id\":188,\"documents\":[],\"media\":[]}','10.55.0.203','2023-06-09 13:33:01','2023-06-09 13:33:01');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (270,'audit:updated',188,'App\\Models\\Contract#188',3,'{\"notes\":\"<p>Compliance:<\\/p><p>-1 supervisor-12 participants<\\/p><p>-Cooperation with PA CareerLink to provide training and education<\\/p><p>-Assess participants with pre and post testing with a Work Readiness Attainment Rating sheet and provide testing to EDSI<\\/p><p>-Summer Youth Program shall not exceed 8 wees continuously and no more than 30 hours a week inclusive of lunch and breaks.<\\/p><p>-Time and attendance signed by participant and supervisor is required to be turned into PA Career Link Lehigh Valley and EDSI staff on a weekly basis.<\\/p>\",\"updated_at\":\"2023-06-09 09:35:31\",\"id\":188,\"documents\":[{\"id\":281,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":188,\"uuid\":\"c76db124-27f1-4bc4-bdbd-04a5202581c4\",\"collection_name\":\"documents\",\"name\":\"6483377443f4f_2023CADA_EDSI Paid Worksite Agreement\",\"file_name\":\"6483377443f4f_2023CADA_EDSI-Paid-Worksite-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":430749,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-06-09T14:33:01.000000Z\",\"updated_at\":\"2023-06-09T14:33:01.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/281\\/6483377443f4f_2023CADA_EDSI-Paid-Worksite-Agreement.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":281,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":188,\"uuid\":\"c76db124-27f1-4bc4-bdbd-04a5202581c4\",\"collection_name\":\"documents\",\"name\":\"6483377443f4f_2023CADA_EDSI Paid Worksite Agreement\",\"file_name\":\"6483377443f4f_2023CADA_EDSI-Paid-Worksite-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":430749,\