INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (271,'audit:created',189,'App\\Models\\Contract#189',3,'{\"title\":\"2023SHFB_FAConstcoFoodPurchase\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-Purchase food from Costco\'s to primarily support rural and or communities of color.<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":\"149\",\"amount\":\"40625\",\"start_date\":\"2023-06-01\",\"end_date\":\"2024-02-29\",\"notes\":\"<p>Reporting:<\\/p><p>Initial Progress Report due October 31, 2023, covering June 1, 2023- September 30, 2023.<\\/p><p>Final Report due March 19th, 2024, covering entire grant period of June 1st, 2023- February 29, 2024.&nbsp;<\\/p><p>****Final report will only be required if the funds were not fully expended by the initial progress report.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-06-09 09:56:38\",\"created_at\":\"2023-06-09 09:56:38\",\"id\":189,\"documents\":[],\"media\":[]}','10.55.0.203','2023-06-09 13:56:38','2023-06-09 13:56:38');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (272,'audit:updated',163,'App\\Models\\Contract#163',3,'{\"purpose\":\"<p>TEFAP-as authorized (.10 cents per pound of food distributed)<\\/p><p>HAP Rental Assistance- $317,680<\\/p><p>HAP Rental Assistance Care Management (Salary of Fiscal staff to process HAP Checks)-$28,328<\\/p><p>HAP Aftercare Managment (SSS Case Management)- $35,543 (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 3,6, and 12 months)<\\/p>\",\"notes\":\"<p>-Reimbursable Grant<\\/p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served.<\\/p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.<\\/p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services<\\/p><p>-Keep records for 7 years<\\/p>\",\"updated_at\":\"2023-06-09 10:47:41\",\"id\":163,\"documents\":[{\"id\":196,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":163,\"uuid\":\"e0b469f0-26bc-42d9-994b-fb683f460fa8\",\"collection_name\":\"documents\",\"name\":\"6446e790f0d8f_2023CALV_LCAAA_signed contract\",\"file_name\":\"6446e790f0d8f_2023CALV_LCAAA_signed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":3142770,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-04-24T20:36:05.000000Z\",\"updated_at\":\"2023-04-24T20:36:05.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/196\\/6446e790f0d8f_2023CALV_LCAAA_signed-contract.pdf\",\"prev