INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (283,'audit:updated',180,'App\\Models\\Contract#180',3,'{\"purpose\":\"<p>Kids hunger initiatives- school pantries.<\\/p><p>&nbsp;<\\/p>\",\"notes\":\"<p>-Social Media acknowledgment, media stories, press releases and testimonials are highly encouraged and asked for in the regular reporting cycle.<\\/p><p>Per donor request and as stated in the grant award notification, as a grant recipient, your food bank is required to submit a minimum of one (1) testimonial &amp; photo of a child impacted by this grant funding.&nbsp; &nbsp;<\\/p><ol><li>Please provide and\\/or upload <strong>stories, testimonials, photographs, and children\\u2019s artwork<\\/strong> illustrating the effect of your program.&nbsp; Please also upload any photographs and\\/or video footage of employee events\\/activities.&nbsp;Please upload release forms with photographs and videos, if they are available.&nbsp; If not, Feeding America will assume that they are for our internal use only and can be shared with the donor for its internal use only.<\\/li><\\/ol>\",\"updated_at\":\"2023-06-22 09:52:09\",\"id\":180,\"documents\":[{\"id\":246,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":180,\"uuid\":\"afa4513e-0d1e-4dbf-a90c-ce2493ac9562\",\"collection_name\":\"documents\",\"name\":\"64666a679a577_1_1481134_FY23_Sheetz_for_the_Kidz_Child_Hunger_Grant_Agreement_\",\"file_name\":\"64666a679a577_1_1481134_FY23_Sheetz_for_the_Kidz_Child_Hunger_Grant_Agreement_.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":45867,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-05-18T18:11:59.000000Z\",\"updated_at\":\"2023-05-18T18:11:59.000000Z\",\"original_url\":\"http:\