INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (306,'audit:created',200,'App\\Models\\Contract#200',3,'{\"title\":\"2023HRP_Dual Temp Air Conditioner Initiative\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>HRP will purchase 20 window air-conditioning units at $250 a piece and be reimbursed by Dual Temp in the amount of $5000 within 30 days of receipt of invoice.<\\/p><p>HRP will assess the location for compatibility with the air-conditioning unit and select recipients for this program from existing clients.<\\/p><p>Upon receipt of referral, Dual Temp will pick up AC unit, install at location and train the client on usage.<\\/p><p>Dual Temp is volunteering its time and labor for this initiative.<\\/p>\",\"funder_id\":null,\"amount\":\"5000\",\"start_date\":null,\"end_date\":null,\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-07-19 08:41:40\",\"created_at\":\"2023-07-19 08:41:40\",\"id\":200,\"documents\":[],\"media\":[]}','10.55.0.203','2023-07-19 12:41:40','2023-07-19 12:41:40');
