INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (316,'audit:created',203,'App\\Models\\Contract#203',3,'{\"title\":\"2023SSS_C&Y\",\"contract_number\":\"23-CY-084\",\"cfda_number\":null,\"purpose\":\"<p>Daily Apartment Rate=$65<\\/p><p>Supportive Services Rate\\/Case Management=$62 per hour<\\/p><p>Extraordinary Expenses for damages per agreed cost (must get prior approval and provide receipt for damages or repair)<\\/p><p>Curfew Cheks-1 hour per day at $62<\\/p><p>SHIFT rate= $60 per hour<\\/p><p>Family Emergency Fund- $9,375 per receipt for move in expenses for SHIFT clients.<\\/p><p><strong>*This grant is reimbursable.<\\/strong>&nbsp;<\\/p><p>**Daily apartment rate, Supportive Services, Curfew Checks and SHIFT rate <strong>billed monthly<\\/strong> with appropriate signed logs and back up<\\/p><p>*** Family Emergency fund reimbursable per instance with proper receipts and backup<\\/p><p>****Extraordinary Expenses reimbursable per instance with proper receipts and backup<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2023-07-01\",\"end_date\":\"2024-06-30\",\"notes\":\"<p><strong>Other requirements<\\/strong>-Case Workers are required to take 12 hours of training per year.<\\/p><p><strong>Reporting Requirements:<\\/strong><\\/p><p>-Monthly reports with invoice as usual with apartment occupancy and case managements times accompanies by signed logs<\\/p><p>-Quarterly Numbers as requested by Children and Youth (they send out an email request)<\\/p><p>-Semi-Annual Reports and Final Report (they send out an email request)<\\/p><p>-Outcome reports due Mid-January for July 1-December 2023 and July 1st for January- June 2024 (send this to Sharon Dunn)<\\/p>\",\"grant_code\":\"1300\",\"updated_at\":\"2023-07-24 15:32:12\",\"created_at\":\"2023-07-24 15:32:12\",\"id\":203,\"documents\":[],\"media\":[]}','10.55.0.203','2023-07-24 19:32:12','2023-07-24 19:32:12');
