INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (319,'audit:created',205,'App\\Models\\Contract#205',45,'{\"title\":\"2022-2025SHFB Lehigh LFPA MOU\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The Pennsylvania Local Food Purchase Assistance Cooperative Agreement Program (PA-LFPA) will work with Pennsylvania\\u2019s local food system to procure top-graded, high-quality products for distribution through the charitable food system serving all 67 of Pennsylvania\\u2019s counties. PDA will distribute food products produced in-state with a goal of reaching at least 1 million low-income households by working with at least 40 farms, producers, and food companies, including at least 10 vendors which identify as underserved and at least 10 direct-to-agency delivery partnerships.<\\/p>\",\"funder_id\":\"149\",\"amount\":\"0.00\",\"start_date\":\"2023-07-27\",\"end_date\":\"2023-07-31\",\"notes\":\"<p>All purchases must be made or committed to by July 31, 2025.<\\/p><p>Final invoices to be submitted on or before August 10, 2025<\\/p><p>All services must be complete by November 1, 2025<\\/p><p>Reports due to tmainzer@feedingpa.org by the 10th calendar day of the following month. Reports should include:<\\/p><ul><li>Product Info (including source, types, unit cost)<\\/li><li>Pounds of food distributed<\\/li><li>Address and manner of distribution<\\/li><li>Number of households served<\\/li><\\/ul><p>SHFB must also obtain written testimonials and feedback rom member agencies, clients and agriculture partners.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-07-27 10:45:07\",\"created_at\":\"2023-07-27 10:45:07\",\"id\":205,\"documents\":[],\"media\":[]}','10.55.4.74','2023-07-27 14:45:07','2023-07-27 14:45:07');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (320,'audit:created',206,'App\\Models\\Contract#206',45,'{\"title\":\"2023-2024SHFB Lehigh PASS Mou\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The Pennsylvania Agricultural Surplus System (PASS) program was designed to support Pennsylvania\\u2019s agricultural industry statewide \\u2013 to reduce waste of surplus product, support local farms, and getting more nutritious food into the hands of Pennsylvanians at risk of hunger. Food must be grown or produced in PA.<\\/p>\",\"funder_id\":\"149\",\"amount\":\"0.00\",\"start_date\":\"2023-07-27\",\"end_date\":\"2025-12-31\",\"notes\":\"<p>Must attend a bi-weekly conference call led by Feeding Pennsylvania\'s Director of Agricultural Partnerships<\\/p><p>All purchases and commitments must be made by <strong>June 30, 2024<\\/strong><\\/p><p>All documentation must be submitted by <strong>July 10, 2024<\\/strong><\\/p><p>All services must be complete by <strong>Augut 15, 2024<\\/strong><\\/p><p>SHFB must distribute 50% or more of their total funding allocation by <strong>December 31, 2023<\\/strong>.<\\/p><p>Monthly reports should be emailed to tmainzer@feedingpa.org by the 10th day of the following month.<\\/p><p>Reports should include:<\\/p><ul><li>Source of product<\\/li><li>Product type and unit cost<\\/li><li>Pounds of food distributed<\\/li><li>Address and manner of distribution<\\/li><li>The number of households served<\\/li><\\/ul><p>SHFB is also required to obtain written testimonials and other feedback from member Agencies, clients and agriculture partners.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-07-27 10:58:19\",\"created_at\":\"2023-07-27 10:58:19\",\"id\":206,\"documents\":[],\"media\":[]}','10.55.4.74','2023-07-27 14:58:19','2023-07-27 14:58:19');
