INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (396,'audit:updated',226,'App\\Models\\Contract#226',45,'{\"title\":\"2023SHFB_FA_CVS General Operating Funds\",\"purpose\":\"<p><strong>Purpose:<\\/strong><\\/p><p>This grant supports SHFB\'s Retail Recovery Initiative. CVS General Operating Funds will be used for salary and benefits for SHFB\'s Retail Recovery Coordinator at $21,210.19 per year for two years, totaling $42,420.38.<\\/p><p>Grant period is from 8\\/1\\/2023 - 7\\/31\\/2025.<\\/p><p>Two reports are due via the Feeding America Grants Management System:<\\/p><p>Year 1 Final Report Deadline, Tuesday, September 10, 2024<br>Year 2 Final Report Deadline, Tuesday, September 9, 2025<\\/p><p>SHFB commits to:<\\/p><ul><li>Engaging a group of CVS employees in at lease one volunteer activity per year<\\/li><li>Hosting a CVS meeting\\/event at SHFB<\\/li><li>Publicly recognizing the support of CVS through social media, print publications and a check presentation event at the SHFB.<\\/li><\\/ul>\",\"amount\":\"42420.38\",\"start_date\":\"2023-08-01\",\"end_date\":\"2025-07-31\",\"updated_at\":\"2023-09-11 08:57:45\",\"funder_id\":\"149\",\"id\":226,\"documents\":[],\"media\":[]}','10.55.4.140','2023-09-11 12:57:45','2023-09-11 12:57:45');
