INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (399,'audit:created',227,'App\\Models\\Contract#227',45,'{\"title\":\"2023SHFB_PATEFAP\",\"contract_number\":\"227\",\"cfda_number\":\"10.568\",\"purpose\":\"<p>This agreement between SHFB and the PA Dept of Agriculture (PDA), establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries).<\\/p><p>Food designated as TEFAP must be accounted for separately from other food.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p>\",\"funder_id\":\"172\",\"amount\":\"0.00\",\"start_date\":\"2023-10-01\",\"end_date\":\"2028-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-09-13 09:30:13\",\"created_at\":\"2023-09-13 09:30:13\",\"id\":227,\"documents\":[],\"media\":[]}','10.55.4.140','2023-09-13 13:30:13','2023-09-13 13:30:13');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (400,'audit:updated',227,'App\\Models\\Contract#227',45,'{\"purpose\":\"<p>This agreement between SHFB and the PA Dept of Agriculture (PDA), establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries).<\\/p><p>Food designated as TEFAP must be accounted for separately from other food.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p>\",\"updated_at\":\"2023-09-13 09:34:06\",\"id\":227,\"documents\":[{\"id\":410,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":227,\"uuid\":\"7b6e891d-f135-4fc6-aad6-e767cf2e096e\",\"collection_name\":\"documents\",\"name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed program management agreement\",\"file_name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1417347,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T14:30:13.000000Z\",\"updated_at\":\"2023-09-13T14:30:13.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/410\\/6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":410,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":227,\"uuid\":\"7b6e891d-f135-4fc6-aad6-e767cf2e096e\",\"collection_name\":\"documents\",\"name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed program management agreement\",\"file_name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1417347,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T14:30:13.000000Z\",\"updated_at\":\"2023-09-13T14:30:13.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/410\\/6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"preview_url\":\"\"}]}','10.55.4.140','2023-09-13 13:34:06','2023-09-13 13:34:06');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (401,'audit:updated',227,'App\\Models\\Contract#227',45,'{\"purpose\":\"<p>This agreement between SHFB and the PA Dept of Agriculture (PDA), establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the Counties in Eastern PA.<\\/p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.<\\/p>\",\"updated_at\":\"2023-09-13 10:16:20\",\"id\":227,\"documents\":[{\"id\":410,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":227,\"uuid\":\"7b6e891d-f135-4fc6-aad6-e767cf2e096e\",\"collection_name\":\"documents\",\"name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed program management agreement\",\"file_name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1417347,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T14:30:13.000000Z\",\"updated_at\":\"2023-09-13T14:30:13.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/410\\/6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":410,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":227,\"uuid\":\"7b6e891d-f135-4fc6-aad6-e767cf2e096e\",\"collection_name\":\"documents\",\"name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed program management agreement\",\"file_name\":\"6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1417347,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T14:30:13.000000Z\",\"updated_at\":\"2023-09-13T14:30:13.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/410\\/6501c73ee9c6b_2023SHFB_PATEFAP_signed-program-management-agreement.pdf\",\"preview_url\":\"\"}]}','10.55.4.140','2023-09-13 14:16:20','2023-09-13 14:16:20');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (402,'audit:created',228,'App\\Models\\Contract#228',45,'{\"title\":\"2023SHFB_CarbonCountyTEFAP\",\"contract_number\":\"228\",\"cfda_number\":\"10.568\",\"purpose\":\"<p>This agreement between SHFB and Carbon County establishes the terms and conditions for SHFB to provide TEFAP services to Carbon County.<\\/p><p>SHFB must prepare a budget for the fiscal period of 10\\/1\\/2023 - 9\\/30\\/2024 identifying estimated operating costs fo the distribution of Federal and State issued food commodities, using the following Allowable Costs line items as determined by PDA.<\\/p><ul><li>Storage costs<\\/li><li>Transportation Costs<\\/li><li>Equipment Rental Costs<\\/li><li>Printing\\/Copying Costs<\\/li><li>Administrative Costs<\\/li><\\/ul><p>Invoices are required quarterly as follows:<\\/p><ul><li>Invoice #1 for (10\\/01\\/2023-12\\/31\\/2023); Due to COUNTY: 01\\/20\\/2024<\\/li><li>Invoice #2 for (01\\/01\\/2024-03\\/31\\/2024); Due to COUNTY: 04\\/20\\/2024<\\/li><li>Invoice #3 for (04\\/01\\/2024-06\\/30\\/2024); Due to COUNTY: 07\\/20\\/2024<\\/li><li>Invoice #4 for (07\\/01\\/2024-09\\/30\\/2024); Due to COUNTY: 10\\/20\\/2024<\\/li><\\/ul><p><strong>NOTE<\\/strong>: The invoice shall be accompanied by a completed TEFAP INVENTORY\\/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \\\"TEFAP INVENTORY\\/PARTICIPATION REPORT\\\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED.<\\/p><p>Contact:<\\/p><p><strong>Cindy Bizarre<\\/strong><br>401 Delaware Avenue, Third Floor<br>Palmerton, PA &nbsp;18071<br>Phone: 1-800-441-1315 ext. 4511 or 610-824-7830 ext. 4511<br>Fax: &nbsp;610-824-7836<br>Email: &nbsp;cbizarre@ptd.net<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2023-10-01\",\"end_date\":\"2024-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-09-13 14:37:00\",\"created_at\":\"2023-09-13 14:37:00\",\"id\":228,\"documents\":[],\"media\":[]}','10.55.4.140','2023-09-13 18:37:00','2023-09-13 18:37:00');
