\":412,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":228,\"uuid\":\"9098b547-3d50-409f-9940-8d70b567454a\",\"collection_name\":\"documents\",\"name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed contract\",\"file_name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":411729,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T19:37:00.000000Z\",\"updated_at\":\"2023-09-13T19:37:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/412\\/65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":412,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":228,\"uuid\":\"9098b547-3d50-409f-9940-8d70b567454a\",\"collection_name\":\"documents\",\"name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed contract\",\"file_name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":411729,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T19:37:00.000000Z\",\"updated_at\":\"2023-09-13T19:37:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/412\\/65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"preview_url\":\"\"}]}','10.55.4.140','2023-09-13 18:45:49','2023-09-13 18:45:49');
