INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (406,'audit:updated',228,'App\\Models\\Contract#228',45,'{\"purpose\":\"<p>This agreement between SHFB and Carbon County establishes the terms and conditions for SHFB to provide TEFAP services to Carbon County.<\\/p><p>SHFB must prepare a budget for the fiscal period of 10\\/1\\/2023 - 9\\/30\\/2024 identifying estimated operating costs for the distribution of Federal and State issued food commodities, using the following Allowable Costs line items as determined by PDA.<\\/p><ul><li>Storage costs<\\/li><li>Transportation Costs<\\/li><li>Equipment Rental Costs<\\/li><li>Printing\\/Copying Costs<\\/li><li>Administrative Costs<\\/li><\\/ul><p>Services provided from 10\\/01\\/2023 - 9\\/30\\/2024 will be reimbursed at $.12 per lb distributed.<\\/p><p>Invoices are required quarterly as follows:<\\/p><ul><li>Invoice #1 for (10\\/01\\/2023-12\\/31\\/2023); Due: <strong>01\\/20\\/2024<\\/strong><\\/li><li>Invoice #2 for (01\\/01\\/2024-03\\/31\\/2024); Due: <strong>04\\/20\\/2024<\\/strong><\\/li><li>Invoice #3 for (04\\/01\\/2024-06\\/30\\/2024); Due: <strong>07\\/20\\/2024<\\/strong><\\/li><li>Invoice #4 for (07\\/01\\/2024-09\\/30\\/2024); Due: <strong>10\\/20\\/2024<\\/strong><\\/li><\\/ul><p><strong>NOTE<\\/strong>: The invoice shall be accompanied by a completed TEFAP INVENTORY\\/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \\\"TEFAP INVENTORY\\/PARTICIPATION REPORT\\\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED.<\\/p><p>Contact:<\\/p><p><strong>Cindy Bizarre<\\/strong><br>401 Delaware Avenue, Third Floor<br>Palmerton, PA &nbsp;18071<br>Phone: 1-800-441-1315 ext. 4511 or 610-824-7830 ext. 4511<br>Fax: &nbsp;610-824-7836<br>Email: &nbsp;cbizarre@ptd.net<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-09-14 11:57:33\",\"id\":228,\"documents\":[{\"id\":412,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":228,\"uuid\":\"9098b547-3d50-409f-9940-8d70b567454a\",\"collection_name\":\"documents\",\"name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed contract\",\"file_name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":411729,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T19:37:00.000000Z\",\"updated_at\":\"2023-09-13T19:37:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/412\\/65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":412,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":228,\"uuid\":\"9098b547-3d50-409f-9940-8d70b567454a\",\"collection_name\":\"documents\",\"name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed contract\",\"file_name\":\"65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":411729,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-13T19:37:00.000000Z\",\"updated_at\":\"2023-09-13T19:37:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/412\\/65020d9a8dd2e_2023SHFB_CarbonCountyTEFAP_signed-contract.pdf\",\"preview_url\":\"\"}]}','10.55.4.140','2023-09-14 15:57:33','2023-09-14 15:57:33');
