INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (427,'audit:updated',232,'App\\Models\\Contract#232',45,'{\"purpose\":\"<p>This grant provides $9,000 in funding: Funds will be used to support the purchase and distribution of food for the MilitaryShare program ($4,500) and supplies for The Seed Farm ($4,500).<\\/p><p>SHFB has agreed to acknowledge the contribution from Sanofi on our social media platforms.<\\/p><p>SHFB has offered to host a volunteer event for Sanofi employees. More information is available to them on volunteermark.com\\/shfb or contacting Allison Czapp at aczapp@calv.org .<\\/p><p>There is no reporting requirement for this contract.<\\/p><p>Two distinct funds have been established:<\\/p><p>F8042 - $4,500 Supplies for The Seed Farm<\\/p><p>F8052 - $4,500 MilitaryShare<\\/p>\",\"updated_at\":\"2023-09-29 11:59:19\",\"id\":232,\"documents\":[{\"id\":439,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":232,\"uuid\":\"0f9c4406-2607-4355-8fdd-276c99fc16bd\",\"collection_name\":\"documents\",\"name\":\"6516ffc3d3d93_2023_SHFB_Sanofi_ProposalSubmitted\",\"file_name\":\"6516ffc3d3d93_2023_SHFB_Sanofi_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":203009,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-09-29T16:48:56.000000Z\",\"updated_at\":\"2023-09-29T16:48:56.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/439\\/6516ffc3d3d93_2023_SHFB_Sanofi_ProposalSubmitted.pdf\",\"preview_url\":\"\"},{\"id\":440,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":232,\"uuid\":\"9d81ece0-fd9a-4b9b-8e94-a9afc5fc34ee\",\"collection_name\":\"documents\",\"name\":\"6516ffc3d4b3e_2023SHFB_Sanofi_Signed Acknowledgment of donation\",\"file_name\":\"6516ffc3d4b3e_2023SHFB_Sanofi_Signed-Ack