INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (434,'audit:created',233,'App\\Models\\Contract#233',45,'{\"title\":\"2022SHFB_SpecialtyCropBlockGrant\",\"contract_number\":\"233\",\"cfda_number\":null,\"purpose\":\"<p>The purpose of this grant is to increase the sale of specialty crops through Farmers Market Nutrition Program (FMNP) checks distribution and redemption in Lehigh and Northampton Counties.<\\/p><p>This grant runs from 9\\/30\\/2022 - 6\\/30\\/2025. This is a <strong>reimbursable <\\/strong>grant. Grant is not to exceed $50,478.00.&nbsp;<\\/p><p>Information on reporting is pasted below. <strong>Final report is due by July 30, 2025<\\/strong>.<\\/p><p>SHFB has committed to helping increase redemption of FMNP checks by 10% over 2021 levels.<\\/p><p>SHFB will implement outreach initiatives including printed materials, event attendance, pop-up markets, and an online information portal. Specific activity details are available in the 2022 SCBGP State approved plan, linked below.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/444\\/image.png\\\"><\\/figure>\",\"funder_id\":\"172\",\"amount\":\"50478.00\",\"start_date\":\"2023-09-30\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-10-04 12:02:15\",\"created_at\":\"2023-10-04 12:02:15\",\"id\":233,\"documents\":[],\"media\":[]}','10.55.4.94','2023-10-04 16:02:15','2023-10-04 16:02:15');
