INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (436,'audit:updated',206,'App\\Models\\Contract#206',3,'{\"notes\":\"<p>-SHFB representative must attend a bi-weekly conference call led by Feeding Pennsylvania\'s Director of Agricultural Partnerships to provide updates on food sourcing and distributions using PASS funds.<\\/p><p>-All purchases and commitments must be made by <strong>June 30, 2024<\\/strong><\\/p><p>-All documentation of purchases and commitments must be submitted by <strong>July 10, 2024<\\/strong><\\/p><p>-All services must be complete by <strong>August 15, 2024<\\/strong><\\/p><p>-SHFB must distribute 50% or more of their total funding allocation by <strong>December 31, 2023<\\/strong>.<\\/p><p>-Monthly reports should be emailed to tmainzer@feedingpa.org by the 10th day of the following month until program completion.<\\/p><p>Reports should include:<\\/p><ul><li>Source of product<\\/li><li>Product type and unit cost<\\/li><li>Pounds of food distributed<\\/li><li>Address and manner of distribution<\\/li><li>The number of households served<\\/li><li>Expense and Reimbursement reports in Microsoft Excel format<\\/li><\\/ul><p>SHFB is also required to obtain written testimonials and other feedback from member Agencies, clients and agriculture partners.<\\/p>\",\"updated_at\":\"2023-10-05 10:07:10\",\"id\":206,\"documents\":[{\"id\":336,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":206,\"uuid\":\"bffd5c64-1a4e-4745-a39e-999ed9c893e9\",\"collection_name\":\"documents\",\"name\":\"64c29278028ef_SHFB Lehigh_23-23 PASS MOU\",\"file_name\":\"64c29278028ef_SHFB-Lehigh_23-23-PASS-MOU.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":462432,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-07-27T15:58:19.000000Z\",\"updated_at\":\"2023-07-27T15:58:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/336\\/64c29278028ef_SHFB-Lehigh_23-23-PASS-MOU.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":336,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":206,\"uuid\":\"bffd5c64-1a4e-4745-a39e-999ed9c893e9\",\"collection_name\":\"documents\",\"name\":\"64c29278028ef_SHFB Lehigh_23-23 PASS MOU\",\"file_name\":\"64c29278028ef_SHFB-Lehigh_23-23-PASS-MOU.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":462432,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-07-27T15:58:19.000000Z\",\"updated_at\":\"2023-07-27T15:58:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/336\\/64c29278028ef_SHFB-Lehigh_23-23-PASS-MOU.pdf\",\"preview_url\":\"\"}]}','10.55.0.203','2023-10-05 14:07:10','2023-10-05 14:07:10');
