INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (467,'audit:created',247,'App\\Models\\Contract#247',45,'{\"title\":\"2020SHFB_SFPP_LehighCounty\",\"contract_number\":\"247\",\"cfda_number\":null,\"purpose\":\"<p>The State Food Purchase Program (SFPP) provides funds for the purchase, transportation, storage and distribution of food to program participants who self-identify as 150% or more below the poverty level using the TEFAP Self-Declaration of Need form.&nbsp;<\\/p><p>The 2020 SFPP Contract extends through June 30, 2025.<\\/p><p>The initial program award for Lehigh County is $553,453.44 for the period July 1, 2020 - June 30, 2021. In each subsequent Program years, PDA shall provide written notice of the maximum grant amount awarded.<\\/p><p>By July 1 of each calendar year of the Program, SFHB must deliver a Plan of Operation to PDA. Previous plans can be found <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:f:\\/s\\/SecondHarvestFoodBank\\/ElpIq8Vg5ONPqypOHaeIjwAB54CkMCDGqSNtEleNTgaG-w?e=xfdnZK\\\">here<\\/a>.<\\/p><p>Allowable costs include:<\\/p><ul><li>Purchase of food consistent with the PDA\'s Food Standard Guidelines for State Food Purchase program (below).<\\/li><li>Processing and repackaging of food for distribution with prior approval by PDA<\\/li><li>Transportation, storage fees and direct administrative costs of the Program, per PDA\'s maximum administrative allowance percentage.<\\/li><li>Capital asset funds may be used to purchase capital equipment or develop new initiatives seeking to increase volumes of food available. More information on capital asset allowances can be found <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EQqsv46YzjRDuR0W5MEYJXMBEPdL_4DpOCg9LZD-jYKZiw?e=YKKZ3A\\\">here<\\/a>. (A capital expense allowance form is attached below.)<\\/li><\\/ul><p><strong>Reporting<\\/strong><\\/p><p><i>Annually<\\/i>, SHFB must submit to PDA an Expense and Data Report for each program year within 30 days of the close of the Program year and reflect activity for the entire period. The report shall include, but not be limited to:<\\/p><ul><li>Allocation and expenditure of funds<\\/li><li>Number of individuals\\/households served<\\/li><li>Variety, pounds and cost of food purchase.<\\/li><\\/ul><p><i>Quarterly<\\/i>, SHFB must submit to PDA quarterly report and copies of all detailed itemized invoices paid for with Program funds during the quarter, within 20 days after the end of each quarter. The next quarter funds will not be released until all required documents are submitted.<\\/p><p>Contact at the PA Dept of Agriculture for SFPP-related inquiries is:<\\/p><p><strong>Melissa Patterson | Assistant Bureau Director<\\/strong><\\/p><p>PA Department of Agriculture | Bureau of Food Assistance<\\/p><p>2301 North Cameron Street | Harrisburg, PA 17110<\\/p><p>Office: 717-772-2694 | Work Cell: 717-836-2003 | Fax 717-787-2387<\\/p><p>melpatters@pa.gov<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"553453.44\",\"start_date\":\"2020-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-10-24 12:58:24\",\"created_at\":\"2023-10-24 12:58:24\",\"id\":247,\"documents\":[],\"media\":[]}','10.55.4.140','2023-10-24 16:58:24','2023-10-24 16:58:24');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (468,'audit:updated',247,'App\\Models\\Contract#247',45,'{\"purpose\":\"<p>The State Food Purchase Program (SFPP) for Lehigh County provides funds for the purchase, transportation, storage and distribution of food to program participants in Lehigh County who self-identify as 150% or more below the poverty level using the TEFAP Self-Declaration of Need form.&nbsp;<\\/p><p>The 2020 SFPP Contract extends through June 30, 2025.<\\/p><p>The initial program award for Lehigh County is $553,453.44 for the period July 1, 2020 - June 30, 2021. In each subsequent Program years, PDA shall provide written notice of the maximum grant amount awarded.<\\/p><p>By July 1 of each calendar year of the Program, SFHB must deliver a Plan of Operation to PDA. Previous plans can be found <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:f:\\/s\\/SecondHarvestFoodBank\\/ElpIq8Vg5ONPqypOHaeIjwAB54CkMCDGqSNtEleNTgaG-w?e=xfdnZK\\\">here<\\/a>.<\\/p><p>Allowable costs include:<\\/p><ul><li>Purchase of food consistent with the PDA\'s Food Standard Guidelines for State Food Purchase program (below).<\\/li><li>Processing and repackaging of food for distribution with prior approval by PDA<\\/li><li>Transportation, storage fees and direct administrative costs of the Program, per PDA\'s maximum administrative allowance percentage.<\\/li><li>Capital asset funds may be used to purchase capital equipment or develop new initiatives seeking to increase volumes of food available. More information on capital asset allowances can be found <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EQqsv46YzjRDuR0W5MEYJXMBEPdL_4DpOCg9LZD-jYKZiw?e=YKKZ3A\\\">here<\\/a>. (A capital expense allowance form is attached below.)<\\/li><\\/ul><p><strong>Reporting<\\/strong><\\/p><p><i>Annually<\\/i>, SHFB must submit to PDA an Expense and Data Report for each program year within 30 days of the close of the Program year and reflect activity for the entire period. The report shall include, but not be limited to:<\\/p><ul><li>Allocation and expenditure of funds<\\/li><li>Number of individuals\\/households served<\\/li><li>Variety, pounds and cost of food purchase.<\\/li><\\/ul><p><i>Quarterly<\\/i>, SHFB must submit to PDA quarterly report and copies of all detailed itemized invoices paid for with Program funds during the quarter, within 20 days after the end of each quarter. The next quarter funds will not be released until all required documents are submitted.<\\/p><p>Contact at the PA Dept of Agriculture for SFPP-related inquiries is:<\\/p><p><strong>Melissa Patterson | Assistant Bureau Director<\\/strong><\\/p><p>PA Department of Agriculture | Bureau of Food Assistance<\\/p><p>2301 North Cameron Street | Harrisburg, PA 17110<\\/p><p>Office: 717-772-2694 | Work Cell: 717-836-2003 | Fax 717-787-2387<\\/p><p>melpatters@pa.gov<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-10-24 12:59:02\",\"id\":247,\"documents\":[{\"id\":480,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":247,\"uuid\":\"6cb9618e-bb23-4330-936d-272ad235343d\",\"collection_name\":\"documents\",\"name\":\"65380592387cb_FOOD STANDARD GUIDELINE FOR STATE FOOD PURCHASE PROGRAM_March 2017\",\"file_name\":\"65380592387cb_FOOD-STANDARD-GUIDELINE-FOR-STATE-FOOD-PURCHASE-PROGRAM_March-2017.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":517567,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-10-24T17:58:24.000000Z\",\"updated_at\":\"2023-10-24T17:58:24.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/480\\/65380592387cb_FOOD-STANDARD-GUIDELINE-FOR-STATE-FOOD-PURCHASE-PROGRAM_March-2017.pdf\",\"preview_url\":\"\"},{\"id\":481,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":247,\"uuid\":\"