INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (510,'audit:created',262,'App\\Models\\Contract#262',3,'{\"title\":\"2023HRP_City of Allentown_HOME_CHDO_136N8thStreet\",\"contract_number\":null,\"cfda_number\":\"14.239\",\"purpose\":\"<p>-Money to be used for 136 North 8th Street Rehabilitation<\\/p><p>-Homeownership to low-income families<\\/p><p>-Reimbursable grant<\\/p><p>-Project shall be considered finished when the homeownership unit has been purchased by a qualifying individual and this must occur within 9 months of completion<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2023-01-01\",\"end_date\":\"2027-12-31\",\"notes\":\"<ul><li>Grantee with ensure compliance with HOME requirements for five years from the date of occupancy.&nbsp;<ul><li>Monitor units for principal residency and recapture funds at time of resale and for rentals ongoing property standards, occupancy and rent limits.<\\/li><\\/ul><\\/li><li>See scope of work section III ON PAGES 3-4 must follow property standards, HUD Requirements, Rehabilitation Standards, etc...<\\/li><li>See Affordability Restrictions section IV- pages 5 --------<\\/li><li>See Budget Revisions and Un-reimbursable Expenses Section V pages 5-6.<\\/li><li>Page 15 Reporting Requirments-09-80p970p7989797<\\/li><\\/ul><p>Exhibit 1- Budget.9098080<\\/p>\",\"grant_code\":null,\"updated_at\":\"2023-12-04 10:01:29\",\"created_at\":\"2023-12-04 10:01:29\",\"id\":262,\"documents\":[],\"media\":[]}','10.55.0.94','2023-12-04 15:01:29','2023-12-04 15:01:29');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (511,'audit:updated',262,'App\\Models\\Contract#262',3,'{\"purpose\":\"<p>-Money to be used for 136 North 8th Street Rehabilitation<\\/p><p>-Homeownership to low-income families<\\/p><p>-Reimbursable grant<\\/p><p>-Project shall be considered finished when the homeownership unit has been purchased by a qualifying individual and this must occur within 9 months of completion<\\/p><p>-Reporting Requirements Section XIX Page 15 every April 1st, October 1st, January 1st.<\\/p><p>-Please see Budget Exhibit 1&nbsp;<\\/p><p>-HOME funds must be matched by a non-federal source<\\/p>\",\"notes\":\"<p><i><strong>******Areas of Compliance <\\/strong><\\/i><strong>******<\\/strong><\\/p><ul><li>Grantee will ensure compliance with HOME requirements for five years from the date of occupancy.<ul><li>Monitor units for principal residency and recapture funds at time of resale. &nbsp;For rentals ongoing property standards, occupancy and rent limits.<\\/li><\\/ul><\\/li><li>See scope of work section III on pages 3-4 must follow property standards, HUD Requirements, Rehabilitation Standards, etc...<\\/li><li>See Affordability Restrictions section IV- pages 5 -6<\\/li><li>See Project Requirements section VII pages 6-8<\\/li><li>IX page 9 we must maintain CHDO status throughout this project agreement.<\\/li><li>See procurement standards section X pages 9-10<\\/li><li>See Budget Revisions and Un-reimbursable Expenses Section V pages 5-6.<\\/li><li>Follow income Qualification requirements page 552.<\\/li><li>Qualification as affordable housing: Rental Income pages 575-577 (See DEED restrictions)<\\/li><li>Qualification as affordable housing: Homeownership pages 580-582 (See Recapture)<\\/li><li>Labor page 594 (See Prevailing wage)<\\/li><li>Lead-Based Pain pages 594-595 (See Lead Pain)<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-12-04 11:12:08\",\"id\":262,\"documents\":[],\"media\":[]}','10.55.0.94','2023-12-04 16:12:08','2023-12-04 16:12:08');
