INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (521,'audit:updated',262,'App\\Models\\Contract#262',3,'{\"notes\":\"<p><i><strong>******Areas of Compliance <\\/strong><\\/i><strong>******<\\/strong><\\/p><ul><li>Grantee will ensure compliance with HOME requirements for 15 years from the date of occupancy.<ul><li>Monitor units for principal residency and recapture funds at time of resale. &nbsp;For rentals ongoing property standards, occupancy and rent limits.<\\/li><\\/ul><\\/li><li>See scope of work section III on pages 3-4 must follow property standards, HUD Requirements, Rehabilitation Standards, etc...<\\/li><li>See Affordability Restrictions section IV- pages 5 -6<\\/li><li>See Reimbursement of Expenses VI page 6.<\\/li><li>See Project Requirements section VII pages 6-8<\\/li><li>IX page 9 we must maintain CHDO status throughout this project agreement.<\\/li><li>See procurement standards section X pages 9-10<\\/li><li>See Budget Revisions and Un-reimbursable Expenses Section V pages 5-6.<\\/li><li>Follow income Qualification requirements page 552.<\\/li><li>Qualification as affordable housing: Rental Income pages 575-577 (See DEED restrictions)<\\/li><li>Qualification as affordable housing: Homeownership pages 580-582 (See Recapture)<\\/li><li>Labor page 594 (See Prevailing wage)<\\/li><li>Lead-Based Pain pages 594-595 (See Lead Pain)<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-12-05 09:16:02\",\"id\":262,\"documents\":[{\"id\":547,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":262,\"uuid\":\"29fdfea6-7084-4865-a220-b727d4404610\",\"collection_name\":\"documents\",\"name\":\"656df9d2f31f7_Signed Request for Release of Funds Allentown HOME\",\"file_name\":\"656df9d2f31f7_Signed-Request-for-Release-of-Funds-Allentown-HOME.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":178003,\"manipulations\"