INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (537,'audit:updated',265,'App\\Models\\Contract#265',3,'{\"title\":\"2022-2026RTCLF_PACDFI_ARPA_Small Business Growth Program\",\"purpose\":\"<p>-Original Contract $232,944 ($184,000 for small business loans, maximum loan amount can be $35,000, $48,941 for technical assistance)<\\/p><p>-At least 5 business loans must be provided, and technical assistance must be provided to at least 30 businesses.<\\/p><p>-All funds must be fully obligated by December 31, 2024, and fully expended by December 31st, 2026.&nbsp;<\\/p><p>-Grantee must attend regular CDFI network meeting and complete accurate quarterly reports.<\\/p><p>-Amendment adds $250,000 for technical assistance.<\\/p>\",\"amount\":\"482944\",\"grant_code\":\"F3590\",\"updated_at\":\"2023-12-14 10:22:35\",\"id\":265,\"documents\":[{\"id\":558,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":265,\"uuid\":\"1f1e6122-86ba-4770-b139-a33b27b4f227\",\"collection_name\":\"documents\",\"name\":\"657749ceeaa5d_SBG_II_Amendment_-_Rising_Tide.docx\",\"file_name\":\"657749ceeaa5d_SBG_II_Amendment_-_Rising_Tide.docx.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":429904,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-11T17:41:37.000000Z\",\"updated_at\":\"2023-12-11T17:41:37.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/558\\/657749ceeaa5d_SBG_II_Amendment_-_Rising_Tide.docx.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":558,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":265,\"uuid\":\"1f1e6122-86ba-4770-b139-a33b27b4f227\",\"collection_name\":\"documents\",\"name\":\"657749ceeaa5d_SBG_II_Amendment_-_Rising_Tide.docx\",\"file_name\":\"657749ceeaa5d_SBG_II_Amendment_-_Rising_Tide.docx.pdf\",\"mime_typ