INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (545,'audit:updated',266,'App\\Models\\Contract#266',45,'{\"purpose\":\"<p>$10,000 grant toward General Operating. Announcement email pasted below.<\\/p><p>Impact statement due approximately 10\\/31\\/2024. An email with instructions will be sent to planner-SHFB@caclv.org.<\\/p><p>Login Information is<\\/p><p>Username: planner-SHFB@caclv.org<\\/p><p>Password: cclv1337<\\/p><p>Last year\'s report can be found <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EcJfovpJQipBuBvoy8BA_sIBEU6K8G4KHDK9B0ZqzpiuNA?e=RMuf53\\\">here<\\/a>.<\\/p><p>********<\\/p><p><strong>From:<\\/strong>&nbsp;positiveNRG &lt;<a href=\\\"mailto:noreply@system.versaic.com\\\">noreply@system.versaic.com<\\/a>&gt;<br><strong>Sent:<\\/strong>&nbsp;Tuesday, November 14, 2023 3:45 PM<br><strong>To:<\\/strong>&nbsp;planner-SHFB &lt;<a href=\\\"mailto:planner-SHFB@caclv.org\\\">planner-SHFB@caclv.org<\\/a>&gt;<br><strong>Cc:<\\/strong>&nbsp;<a href=\\\"mailto:positiveNRG@nrg.com\\\">positiveNRG@nrg.com<\\/a> &lt;<a href=\\\"mailto:positiveNRG@nrg.com\\\">positiveNRG@nrg.com<\\/a>&gt;<br><strong>Subject:<\\/strong>&nbsp;Message from positiveNRG - Community Action Committee of the Lehigh Valley<\\/p><p>&nbsp;<\\/p><p>Congratulations!<br><br>We are pleased to confirm that your&nbsp;positiveNRG application has been approved in the amount of $10,000.00. &nbsp;<br><br>We are happy to award this donation and would like to make you aware of the following terms and conditions:<\\/p><ul><li>This contribution is to be used exclusively for the purpose described in the application submitted to us by Briana McGonagle.<\\/li><li>Community Action Committee of the Lehigh Valley will contact us for approval prior to any use of the NRG name and logo, and its family of brands, in connection with any publicity.<\\/li><\\/ul><p>To agree to the terms and conditions above, you will need to log in to your account on <a href=\\\"https:\\/\\/nrg.versaic.com\\/login\\\">nrg.versaic.com<\\/a>.&nbsp; &nbsp;<br><br>Choose the application you submitted and click on Required Actions to agree to the terms and conditions.<br><br>We appreciate the valuable services your organization provides to the community and our team at&nbsp;positiveNRG looks forward to working with you.<br>&nbsp;<br>Thank you very much and please let us know if you have any questions.&nbsp; We can be contacted at <a href=\\\"mailto:positiveNRG@nrg.com\\\">positiveNRG@nrg.com<\\/a>.<br>&nbsp;<br>Sincerely,<br>PositiveNRG<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-12-18 10:09:57\",\"id\":266,\"documents\":[{\"id\":559,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":266,\"uuid\":\"ed6ef152-6005-4e3f-b7fe-f07cfbe3eb61\",\"collection_name\":\"documents\",\"name\":\"6577595b47214_PositiveNRG Grant Application 11032023\",\"file_name\":\"6577595b47214_PositiveNRG-Grant-Application-11032023.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":125951,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-11T18:48:29.000000Z\",\"updated_at\":\"2023-12-11T18:48:29.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/559\\/6577595b47214_PositiveNRG-Grant-Application-11032023.pdf\",\"preview_url\":\"\"},{\"id\":560,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":266,\"uuid\":\"b8b32356-6c11-48d2-aeb0-789f5cbfe42f\",\"collection_name\":\"documents\",\"name\":\"6577597489211_Fw Message from positiveNRG\",\"file_name\":\"6577597489211_Fw-Message-from-positiveNRG.msg\",\"mime_type\":\"application\\/vnd.ms-outlook\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":116224,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"cre