INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (548,'audit:created',271,'App\\Models\\Contract#271',45,'{\"title\":\"2023SHFB_ClifFamilyFoundation_SeedFarm\",\"contract_number\":\"271\",\"cfda_number\":null,\"purpose\":\"<p>The Clif Family Foundation has awarded a $15,000 grant to The Seed Farm for general operating purposes. The grant period begins on 12\\/18\\/2023 and ends 12\\/18\\/2024. The Foundation will send information regarding the final report to the <a href=\\\"mailto:planner-shfb@caclv.org\\\">planner-shfb@caclv.org<\\/a> email. Last year the Foundation requested a general Seed Farm <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EYKNuEp_XYtAoKBJPY6hZJQBALrQxoJvuQEPg7EfDqDksA?e=GLtfU3\\\">Impact Statement<\\/a> as the final report.<\\/p><p>This is a lump sum award with no restrictions.<\\/p>\",\"funder_id\":\"116\",\"amount\":\"15000.00\",\"start_date\":\"2023-12-18\",\"end_date\":\"2024-12-18\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-12-20 08:42:23\",\"created_at\":\"2023-12-20 08:42:23\",\"id\":271,\"documents\":[],\"media\":[]}','10.55.4.140','2023-12-20 13:42:23','2023-12-20 13:42:23');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (549,'audit:updated',271,'App\\Models\\Contract#271',45,'{\"purpose\":\"<p>The Clif Family Foundation has awarded a $15,000 grant to The Seed Farm for general operating purposes. The grant period begins on 12\\/18\\/2023 and ends 12\\/18\\/2024. The Foundation will send information regarding the final report to the <a href=\\\"mailto:planner-shfb@caclv.org\\\">planner-shfb@caclv.org<\\/a> email. Last year the Foundation requested a general Seed Farm <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EYKNuEp_XYtAoKBJPY6hZJQBALrQxoJvuQEPg7EfDqDksA?e=GLtfU3\\\">Impact Statement<\\/a> as the final report.<\\/p><p>This is a lump sum award with no restrictions.<\\/p><p>The below email contains important information regarding the Clif Family Foundation\'s support of The Seed Farm:<\\/p><p>Dear Briana,<\\/p><p>&nbsp;We\\u2019ve appreciated being your partner for these years and having the opportunity to support your progress. We\\u2019d like to do so again this year with a final contribution of $15,000.00. We hope this grant will allow you time to build your support base and cultivate additional funding streams to help carry your efforts forward.<\\/p><p>&nbsp;The decision to provide this larger, final grant follows a 2022 in-depth look at our portfolio in its entirety. During that review, we realized that we needed to narrow our focus, hone in on certain funding criteria, and provide more significant grants to build capacity. We did not take that work lightly. We partnered with the Center for Effective Philanthropy, which surveyed our grantees. Through the 385 responses the Center received, our grantees made clear that they would be better served by greater clarity in our process, increased focus on our strategic priorities, larger grants, and more time building relationships with Foundation staff, even if that meant reducing the number of annual grants. In accepting this important feedback, we recognize that many organizations we\\u2019ve supported for some time will not be funded in the future. &nbsp;<\\/p><p>&nbsp;Everyone at the Foundation joins me in thanking you for your good work and wishing you ongoing success.<\\/p><p>&nbsp;Kind regards,<\\/p><p>&nbsp;Thao Pham<\\/p><p>Executive Director<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-12-20 08:44:23\",\"id\":271,\"documents\":[{\"id\":585,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":271,\"uuid\":\"c91e0766-f849-4c93-b98d-368b2b4149fd\",\"collection_name\":\"documents\",\"name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation\",\"file_name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":168875,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-20T13:42:23.000000Z\",\"updated_at\":\"2023-12-20T13:42:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/585\\/6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":585,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":271,\"uuid\":\"c91e0766-f849-4c93-b98d-368b2b4149fd\",\"collection_name\":\"documents\",\"name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation\",\"file_name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":168875,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-20T13:42:23.000000Z\",\"updated_at\":\"2023-12-20T13:42:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/585\\/6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"preview_url\":\"\"}]}','10.55.4.140','2023-12-20 13:44:23','2023-12-20 13:44:23');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (550,'audit:updated',271,'App\\Models\\Contract#271',45,'{\"purpose\":\"<p>The Clif Family Foundation has awarded a $15,000 grant to The Seed Farm for general operating purposes. The grant period begins on 12\\/18\\/2023 and ends 12\\/18\\/2024. The Foundation will send information regarding the final report to the <a href=\\\"mailto:planner-shfb@caclv.org\\\">planner-shfb@caclv.org<\\/a> email. Last year the Foundation requested a general Seed Farm <a href=\\\"https:\\/\\/caclv.sharepoint.com\\/:b:\\/s\\/SecondHarvestFoodBank\\/EYKNuEp_XYtAoKBJPY6hZJQBALrQxoJvuQEPg7EfDqDksA?e=GLtfU3\\\">Impact Statement<\\/a> as the final report.<\\/p><p>This is a lump sum award with no restrictions.<\\/p><p>The below email contains important information regarding the Clif Family Foundation\'s support of The Seed Farm:<\\/p><p>- - - - - - - - - - - - -&nbsp;<\\/p><p>Dear Briana,<\\/p><p>&nbsp;We\\u2019ve appreciated being your partner for these years and having the opportunity to support your progress. We\\u2019d like to do so again this year with a final contribution of $15,000.00. We hope this grant will allow you time to build your support base and cultivate additional funding streams to help carry your efforts forward.<\\/p><p>&nbsp;The decision to provide this larger, final grant follows a 2022 in-depth look at our portfolio in its entirety. During that review, we realized that we needed to narrow our focus, hone in on certain funding criteria, and provide more significant grants to build capacity. We did not take that work lightly. We partnered with the Center for Effective Philanthropy, which surveyed our grantees. Through the 385 responses the Center received, our grantees made clear that they would be better served by greater clarity in our process, increased focus on our strategic priorities, larger grants, and more time building relationships with Foundation staff, even if that meant reducing the number of annual grants. In accepting this important feedback, we recognize that many organizations we\\u2019ve supported for some time will not be funded in the future. &nbsp;<\\/p><p>&nbsp;Everyone at the Foundation joins me in thanking you for your good work and wishing you ongoing success.<\\/p><p>&nbsp;Kind regards,<\\/p><p>&nbsp;Thao Pham<\\/p><p>Executive Director<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2023-12-20 08:52:47\",\"id\":271,\"documents\":[{\"id\":585,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":271,\"uuid\":\"c91e0766-f849-4c93-b98d-368b2b4149fd\",\"collection_name\":\"documents\",\"name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation\",\"file_name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":168875,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-20T13:42:23.000000Z\",\"updated_at\":\"2023-12-20T13:42:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/585\\/6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":585,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":271,\"uuid\":\"c91e0766-f849-4c93-b98d-368b2b4149fd\",\"collection_name\":\"documents\",\"name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation\",\"file_name\":\"6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":168875,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-20T13:42:23.000000Z\",\"updated_at\":\"2023-12-20T13:42:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/585\\/6582ef3a8bea4_2023SHFB_CLifFamilyFoundation.pdf\",\"preview_url\":\"\"