INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (556,'audit:created',272,'App\\Models\\Contract#272',45,'{\"title\":\"2024SHFB_AllOne_GeneralOperating\",\"contract_number\":\"272\",\"cfda_number\":null,\"purpose\":\"<p>SHFB has been awarded a $100,000.00 grant from the AllOne Foundation to increase access to nutritious foods for the people of Carbon, Monroe, Pike, and Wayne Counties.<\\/p><p>Grant period starts Dec 18, 2023 and ends Dec 17, 2024.<\\/p><p>A full and complete narrative and financial report to the Foundation at the mid-project date as stated in the proposal as well as 30 days following the conclusion of the grant period. Information on submitting the report will be emailed to planner-SHFB@caclv.org.<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"100000.00\",\"start_date\":\"2023-12-18\",\"end_date\":\"2024-12-17\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2023-12-29 08:15:12\",\"created_at\":\"2023-12-29 08:15:12\",\"id\":272,\"documents\":[],\"media\":[]}','10.55.4.140','2023-12-29 13:15:12','2023-12-29 13:15:12');
