\":649,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":292,\"uuid\":\"b124a665-cb6e-42a4-aeab-b4d08719ff47\",\"collection_name\":\"documents\",\"name\":\"65a8257c8bda2_Beth Redev Authority Cooperation Agreement_updated 1.20.2022_unexecuted (1)\",\"file_name\":\"65a8257c8bda2_Beth-Redev-Authority-Cooperation-Agreement_updated-1.20.2022_unexecuted-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":485353,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-01-17T19:07:55.000000Z\",\"updated_at\":\"2024-01-17T19:07:55.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/649\\/65a8257c8bda2_Beth-Redev-Authority-Cooperation-Agreement_updated-1.20.2022_unexecuted-(1).pdf\",\"preview_url\":\"\"},{\"id\":650,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":292,\"uuid\":\"fe918aab-79fa-4871-b32b-00044b8e4d84\",\"collection_name\":\"documents\",\"name\":\"65a82582f11fb_HRP_720 Broadway Blight Remediation_third amendment_signed (3)\",\"file_name\":\"65a82582f11fb_HRP_720-Broadway-Blight-Remediation_third-amendment_signed-(3).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":75838,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-01-17T19:07:55.000000Z\",\"updated_at\":\"2024-01-17T19:07:55.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/650\\/65a82582f11fb_HRP_720-Broadway-Blight-Remediation_third-amendment_signed-(3).pdf\",\"preview_url\":\"\"}]}','10.55.0.159','2024-01-17 19:08:39','2024-01-17 19:08:39');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (620,'audit:created',293,'App\\Models\\Contract#293',45,'{\"title\":\"2024SHFB_FeedingPA_Service Insights\",\"contract_number\":\"293\",\"cfda_number\":null,\"purpose\":\"<p>Feeding PA has provided a $50,000.00 grant to support implementation of Service Insights to partner agencies. This is a lump sum grant.<\\/p><ul><li>Hire a Community Programs&nbsp;Coordinator&nbsp;who will dedicate\\u00be&nbsp;of their time to the electronic data collection initiative (approximately&nbsp;.75 FTE).<\\/li><li>Work through the Feeding America checklists to&nbsp;create a framework for building out an electronic data collection pilot program, identify and begin implementation with an initial cohort&nbsp;of five (S) partner&nbsp;agencies,&nbsp;and subsequently continue implementation with additional partners.<\\/li><\\/ul><p>A SHFB representative&nbsp;must participate in the monthly Data Project Taskforce calls hosted by FPA and&nbsp;submit two&nbsp;brief reports summarizing the&nbsp;progress of implementation.&nbsp;Reports are due as follows: on or before June 1, 2024; and on or before December 31, 2024. Guidelines regarding the report will be forthcoming from Feeding PA.<\\/p><p>Questions may be submitted to Shea Saman at Feeding PA (ssaman@feedingpa.org).<\\/p>\",\"funder_id\":\"165\",\"amount\":\"50000.00\",\"start_date\":\"2024-01-01\",\"end_date\":\"2024-12-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-01-18 15:30:48\",\"created_at\":\"2024-01-18 15:30:48\",\"id\":293,\"documents\":[],\"media\":[]}','10.55.4.140','2024-01-18 20:30:48','2024-01-18 20:30:48');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (621,'audit:updated',293,'App\\Models\\Contract#293',45,'{\"purpose\":\"<p>Feeding PA has provided a $50,000.00 grant to support implementation of Service Insights to partner agencies. This is a lump sum grant.<\\/p><ul><li>Hire a Community Programs&nbsp;Coordinator&nbsp;who will dedicate\\u00be&nbsp;of their time to the electronic data collection initiative (approximately&nbsp;.75 FTE).<\\/li><li>Work through the Feeding America checklists to&nbsp;create a framework for building out an electronic data collection pilot program, identify and begin implementation with an initial cohort&nbsp;of five (S) partner&nbsp;agencies,&nbsp;and subsequently continue implementation with additional partners.<\\/li><\\/ul><p>A SHFB representative&nbsp;must participate in the monthly Data Project Taskforce calls hosted by FPA and&nbsp;submit two&nbsp;brief reports summarizing the&nbsp;progress of implementation.&nbsp;<\\/p><p>Reports are due as follows: on or before <strong>June 1, 2024<\\/strong>; and on or before <strong>December 31, 2024<\\/strong>. Guidelines regarding the report will be forthcoming from Feeding PA.<\\/p><p>Questions may be submitted to Shea Saman at Feeding PA (ssaman@feedingpa.org).<\\/p>\",\"updated_at\":\"2024-01-18 15:44:20\",\"id\":293,\"documents\":[{\"id\":652,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":293,\"uuid\":\"0dcd18a3-5d28-4e25-9ee0-fa39887a9850\",\"collection_name\":\"documents\",\"name\":\"65a98a0a1bf5b_2024SHFB_FA_Feeding PA_ Services Insights- signed\",\"file_name\":\"65a98a0a1bf5b_2024SHFB_FA_Feeding-PA_-Services-Insights--signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":94643,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-01-18T20: