INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (631,'audit:created',298,'App\\Models\\Contract#298',45,'{\"title\":\"2024SHFB_TEFAP Reach and Resiliency\",\"contract_number\":\"297\",\"cfda_number\":\"10.568\",\"purpose\":\"<p><strong>Purpose:<\\/strong><br>&nbsp;<\\/p><p>Pennsylvania Dept of Agriculture has awarded SHFB $40,330.00 TEFAP Reach &amp; Resiliency for Warehouse Infrastructure. Per the contract:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/665\\/image.png\\\"><\\/figure><p>The budget submitted is as follows:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/666\\/image.png\\\"><\\/figure><p>This is a reimbursable grant.&nbsp;<\\/p><p>Payment by PDA shall be made not more more than once each month, upon submission of a certified invoice, on a reimbursement of costs incurred basis. Invoices shall indicate expenditures incurred by budget categories.<\\/p><p>At the conclusion of the TEFAP Reach and Resiliency Grant Award period, you will have 45 days in which to submit a final report on your project to the Pennsylvania Department of Agriculture\\u2019s Bureau of Food Assistance. <strong>By no later than July 15, 2024, please submit a final report to Caryn Long Earl (<\\/strong><a href=\\\"mailto:cearl@pa.gov\\\"><strong>cearl@pa.gov<\\/strong><\\/a><strong>)&nbsp;<\\/strong>detailing the following:<\\/p><ul><li>Final project expenditures<\\/li><li>Information on any new partner agencies through whom you are distributing TEFAP<\\/li><li>Information detailing how you have used these funds to expanded the reach of TEFAP in your service territory<\\/li><li>If applicable, information regarding increased geographic areas served through this project<\\/li><li>Metrics on the increased numbers of individuals served and demographics of increased individuals served<\\/li><li>Pounds of TEFAP distributed before and after implementation of project<\\/li><li>Information regarding client satisfaction<\\/li><li>Other relevant data or information regarding improved TEFAP reach in the community being served<\\/li><\\/ul>\",\"funder_id\":\"172\",\"amount\":\"40330.00\",\"start_date\":\"2022-06-13\",\"end_date\":\"2024-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-01-25 14:07:16\",\"created_at\":\"2024-01-25 14:07:16\",\"id\":298,\"documents\":[],\"media\":[]}','10.55.4.140','2024-01-25 19:07:16','2024-01-25 19:07:16');
