INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (646,'audit:created',301,'App\\Models\\Contract#301',3,'{\"title\":\"2024REJ_ Nature Nurture Center_ CBO _ Create Connections: Linking a Vision of Resilience to Action\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>Community Based Partner with the Nurture Nature Center for project entitled \\\"CREATE Connections: Linking a Vision of Resilience to Action\\\"<\\/p><p>&nbsp;<\\/p><p>This agreement spans 4 years and ends on August 31, 2027.<\\/p><p>&nbsp;<\\/p><p>Responsibilities of the CBO (REJ) are:&nbsp;<\\/p><p>\\u2002\\u2002\\u2002\\u2002\\u2002\\u2002-&nbsp;participate in project meetings and provide input<\\/p><p>\\u2002\\u2002\\u2002\\u2002\\u2002\\u2002-help disseminate outreach and educational materials through its community networks on an ongoing basis<\\/p><p>\\u2002\\u2002\\u2002\\u2002\\u2002\\u2002-&nbsp;participate in evaluation activities and report on project activities.&nbsp;<\\/p><p>&nbsp;Please see agreement for more details.&nbsp;<\\/p><p>Total yearly compensation to CADCB is $500. Invoice template attached.<\\/p>\",\"funder_id\":\"181\",\"amount\":\"0.00\",\"start_date\":null,\"end_date\":\"2027-08-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-02-09 12:57:02\",\"created_at\":\"2024-02-09 12:57:02\",\"id\":301,\"documents\":[],\"media\":[]}','10.55.0.173','2024-02-09 17:57:02','2024-02-09 17:57:02');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (647,'audit:created',302,'App\\Models\\Contract#302',45,'{\"title\":\"2023SHFB_TEFAP_CountyCommoditiesAgreements\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This agreement between SHFB and the PA Dept of Agriculture (PDA), establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the Counties in Eastern PA.<\\/p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":null,\"end_date\":null,\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-02-14 09:25:57\",\"created_at\":\"2024-02-14 09:25:57\",\"id\":302,\"documents\":[],\"media\":[]}','10.55.4.140','2024-02-14 14:25:57','2024-02-14 14:25:57');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (648,'audit:updated',302,'App\\Models\\Contract#302',45,'{\"contract_number\":\"302\",\"purpose\":\"<p>These are the TEFAP Commodities Agreements between SHFB and the counties of <strong>Carbon<\\/strong>, <strong>Lehigh<\\/strong>, and <strong>Northampton<\\/strong>. These agreements, establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the counties listed above.<\\/p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.<\\/p>\",\"start_date\":\"2021-10-01\",\"end_date\":\"2026-09-30\",\"grant_code\":\"10.568\",\"updated_at\":\"2024-02-14 09:31:45\",\"funder_id\":\"172\",\"cfda_number\":\"10.568\",\"id\":302,\"documents\":[],\"media\":[]}','10.55.4.140','2024-02-14 14:31:45','2024-02-14 14:31:45');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (649,'audit:updated',302,'App\\Models\\Contract#302',45,'{\"purpose\":\"<p>These are the TEFAP Commodities Agreements between SHFB and the counties of <strong>Carbon<\\/strong>, <strong>Lehigh<\\/strong>, and <strong>Northampton<\\/strong>. These agreements, establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;<\\/p><p>The program directs SHFB in the receipt of food provided by PDA\\/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the counties listed above.<\\/p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.<\\/p><p>This is a <strong>reimbursable grant<\\/strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.<\\/p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.<\\/p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.<\\/p><p>The statewide TEFAP agreement can be found here: <a href=\\\"http:\\/\\/contracts.caclv.org\\/contracts\\/227\\\">http:\\/\\/contracts.caclv.org\\/contracts\\/227<\\/a><\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-02-14 09:37:11\",\"id\":302,\"documents\":[{\"id\":697,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":302,\"uuid\":\"d66a4380-719e-4f7f-a2d7-a7f76ce3343e\",\"collection_name\":\"documents\",\"name\":\"65ccce96d8a0b_Carbon County TEFAP Program Mgmt Agreement\",\"file_name\":\"65ccce96d8a0b_Carbon-County-TEFAP-Program-Mgmt-Agreement.pdf\",\"mime_type\":\"applica