INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (664,'audit:deleted',297,'App\\Models\\Contract#297',45,'{\"id\":297,\"title\":\"2024SHFB_TEFAP Reach and Resiliency\",\"contract_number\":\"297\",\"purpose\":null,\"date_of_award\":null,\"amount\":\"0.00\",\"start_date\":null,\"end_date\":null,\"archived\":null,\"date_archived\":null,\"notes\":null,\"grant_code\":null,\"created_at\":\"2024-01-25 13:43:41\",\"updated_at\":\"2024-02-22 14:57:46\",\"deleted_at\":\"2024-02-22 14:57:46\",\"funder_id\":null,\"cfda_number\":\"10\",\"documents\":[],\"media\":[]}','10.55.4.140','2024-02-22 19:57:46','2024-02-22 19:57:46');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (665,'audit:created',304,'App\\Models\\Contract#304',45,'{\"title\":\"2021_2026SHFB_LehighCountyTEFAP\",\"contract_number\":null,\"cfda_number\":\"10.568\",\"purpose\":\"<p>This is a reimbursement grant. Billing and invoicing instructions are below. Reports must be submitted according to the schedule outlined below. &nbsp;<\\/p><p><strong>Purpose:<\\/strong><\\/p><p>This agreement between SHFB and Lehigh County establishes the terms and conditions for SHFB to provide TEFAP services to Lehigh County. SHFB shall accept for storage, prepare for distribution, distribute via its network of affiliated food pantries, and account for food commodities made available to Lehigh County residents via TEFAP. SHFB shall publicize availability of foods via public service announcements. &nbsp;<\\/p><p>The following costs are allowable:<\\/p><ul><li>Storage costs<\\/li><li>Transportation Costs<\\/li><li>Equipment Rental Costs<\\/li><li>Printing\\/Copying Costs<\\/li><li>Administrative Costs<\\/li><\\/ul><p>Services provided from 10\\/01\\/2021 - 9\\/30\\/2026 will be reimbursed at $.12 per lb distributed, unless otherwise communicated by the State or County.<\\/p><p>Invoices are required quarterly for all program years as follows:<\\/p><p><strong>Invoice #1<\\/strong> for (10\\/01-12\\/31); Due: 01\\/30<\\/p><p><strong>Invoice #2<\\/strong> for (01\\/01-03\\/31; Due: 04\\/30<\\/p><p><strong>Invoice #3<\\/strong> for (04\\/01-06\\/30); Due: 07\\/30<\\/p><p><strong>Invoice #4<\\/strong> for (07\\/01-09\\/30); Due: 10\\/30 &nbsp;<\\/p><p>NOTE: The invoice shall be accompanied by a completed TEFAP INVENTORY\\/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \\\"TEFAP INVENTORY\\/PARTICIPATION REPORT\\\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED.<\\/p><p>Contact:<br>Joel Pattison<br>County of Lehigh<br>Lehigh County Aging &amp; Adult Services<br>610-782-3442<br>joelpattison@lehighcounty.org<\\/p>\",\"funder_id\":\"145\",\"amount\":\"0.00\",\"start_date\":\"2021-10-01\",\"end_date\":\"2026-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-02-22 15:08:52\",\"created_at\":\"2024-02-22 15:08:52\",\"id\":304,\"documents\":[],\"media\":[]}','10.55.4.140','2024-02-22 20:08:52','2024-02-22 20:08:52');
