INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (678,'audit:updated',162,'App\\Models\\Contract#162',3,'{\"notes\":\"<p>*Two-year award for $15,000 annually ($30,000 total)<\\/p><p>**Requirements:&nbsp;<\\/p><p>&nbsp;11\\/7\\/2023 \\u2013 Interim Call&nbsp;<\\/p><p>&nbsp;05\\/15\\/2024 \\u2013 Final Report to be completed in the Provident Bank Portal<\\/p><p>*** Major Promotion and Publicity: All copy and materials must have PBF\\u2019s approval prior to circulation\\u2014this includes, but is not limited to, print and social media or other marketing collateral. Our complete name, The Provident Bank Foundation, must be used. Additional information may be found on our online Grantee Press Kit, here: <a href=\\\"https:\\/\\/www.theprovidentbankfoundation.org\\/media\\/grantee-press-kit\\\">Grantee Press Kit (theprovidentbankfoundation.org)<\\/a><\\/p><p>****Leadership Changes: If leadership changes at your organization occur during the grant term, you must notify PBF in writing.<\\/p>\",\"updated_at\":\"2024-02-29 12:45:58\",\"id\":162,\"documents\":[{\"id\":192,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":162,\"uuid\":\"0c46212d-5555-4ae6-8bee-0d8fca1fd107\",\"collection_name\":\"documents\",\"name\":\"6446e289da775_2023SSS_Provident Bank Foundation_Award Notification\",\"file_name\":\"6446e289da775_2023SSS_Provident-Bank-Foundation_Award-Notification.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":91292,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-04-24T20:17:54.000000Z\",\"updated_at\":\"2023-04-24T20:17:54.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/192\\/6446e289da775_2023SSS_Provident-Bank-Foundation_Award-Notification.pdf\",\"preview_url\":\"\"},{\"id\":193,\"model_type\":\"App\\\\Model