INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (683,'audit:created',309,'App\\Models\\Contract#309',3,'{\"title\":\"2024HCP_BOA_Homebuyer Education and Counseling Agreement\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-Reimbursement for Homeownership Education Counseling as outlined in 1.1.3.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/728\\/image.png\\\"><\\/figure><p>-Provide Proof of completion of Homebuyer Education to counselee and to BOA.<\\/p><p>-Acquire written permission to share counselee information with BOA if requested by the counselee<\\/p><p>-BOA shall pay Counselor a fee of $500 for instructor led classes and $100 for self-guided classes<\\/p><p>-Please see exhibit A for Counseling Responsibilities<\\/p><p>-Please see Exhibit B for Logo and License Agreement.<\\/p>\",\"funder_id\":\"169\",\"amount\":\"0.00\",\"start_date\":\"2024-04-01\",\"end_date\":\"2026-03-31\",\"notes\":\"<p>-Section 2.2 Payment Process fee and Invoice Submission<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/729\\/image.png\\\"><\\/figure>\",\"grant_code\":null,\"updated_at\":\"2024-03-18 09:38:30\",\"created_at\":\"2024-03-18 09:38:30\",\"id\":309,\"documents\":[],\"media\":[]}','10.55.0.62','2024-03-18 13:38:30','2024-03-18 13:38:30');
