INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (700,'audit:created',313,'App\\Models\\Contract#313',45,'{\"title\":\"2023_SHFB_VeteransTrust_MilitaryShare\",\"contract_number\":null,\"cfda_number\":\"10.568\",\"purpose\":null,\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":null,\"end_date\":null,\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-03-19 07:20:04\",\"created_at\":\"2024-03-19 07:20:04\",\"id\":313,\"documents\":[],\"media\":[]}','10.55.4.152','2024-03-19 11:20:04','2024-03-19 11:20:04');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (701,'audit:updated',313,'App\\Models\\Contract#313',45,'{\"purpose\":\"<p>This $40,000 grant will support the Military Share program during the grant period of <strong>6\\/1\\/2024 - 5\\/31\\/2024<\\/strong>. Utilizing these funds, SHFB will:<\\/p><ul><li>Provide nutritious shelf-stable and fresh foods to at least 560 military families.<\\/li><li>Distribute 235,000 pounds of food.<\\/li><li>Engage 100 volunteers for packing and distribution of food boxes.<\\/li><\\/ul><p>Funds received will be used for the following purposes:<\\/p><ul><li>Personnel and fringe benefits costs of $2,300 and $1,700 respectively, will support the Community Programs Coordinator at an hourly rate of $21.63.<\\/li><li>Commodities costs of $34,200 will support the purchase of food for Military Shares distribution.<\\/li><li>Supplies costs of $1,200 will support the purchase of 1,481 boxes at $.81\\/box.<\\/li><li>Distribution costs of $600 will support the cost of fuel for trucks to delivery Military Shares to distribution sites across six counties at $.65\\/mile.<\\/li><\\/ul><p>Regarding use of funds:&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/743\\/image.png\\\"><\\/figure><p>SHFB must submit a final audit, performed by a Certified Public Accountant, that accounts for all expenditures of grand funds and accrued interest therefrom <strong>no later than six (6) months<\\/strong> after the agreement period end.&nbsp;<\\/p><p>A Project Audit performed under the Single Audit Act of 1984 will not be accepted in lieu of a Project Audit required under this agreement.<\\/p><p>Quarterly progress reports must be submitted to the Department of Veterans\' Affairs no later than thrity (30) days after the end of each quarter, with the first report covering the months June - September. The template for these reports will be provided by the Department prior to the end of the first quarter.<\\/p><p>Contact email for this program is: <a href=\\\"RA-MVVetTrustFund@pa.gov\\\">RA-MVVetTrustFund@pa.gov<\\/a><\\/p><p>&nbsp;<\\/p>\",\"amount\":\"40000.00\",\"start_date\":\"2024-06-01\",\"end_date\":\"2025-05-31\",\"updated_at\":\"2024-03-19 07:43:36\",\"funder_id\":\"114\",\"id\":313,\"documents\":[],\"media\":[{\"id\":743,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":313,\"uuid\":\"133fed88-f11b-4c46-a8c1-11b83d8ee393\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":41525,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-03-19T12:32:02.000000Z\",\"updated_at\":\"2024-03-19T12:32:02.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/743\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/743\\/conversions\\/image-preview.jpg\"},{\"id\":744,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":313,\"uuid\":\"5bad2905-b89a-49d5-b885-8385b0b89c9c\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":18810,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-03-19T12:35:30.000000Z\",\"updated_at\":\"2024-03-19T12:35:30.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/744\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/744\\/conversions\\/image-preview.jpg\"},{\"id\":745,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":313,\"uuid\":\"903b37d1-682d-4f11-aef8-aab0766a14c2\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":