INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (750,'audit:created',327,'App\\Models\\Contract#327',45,'{\"title\":\"2023-2025SHFB_NCCDBG_FreshFoodDistribution\",\"contract_number\":\"327\",\"cfda_number\":\"14.218\",\"purpose\":\"<p>Northampton County has awarded $35,000 \\\"to purchase and distribute fresh foods (produce, dairy, eggs, and meat) to be distributed to the 19 Northampton County pantry sites listed in the attached contract, Exhibit A.<\\/p><p>Two reports are required; reporting deadlines are:<\\/p><p><strong>Report period April 1 \\u2013 Oct 31, 2024 due Nov 15, 2024<\\/strong><\\/p><p><strong>Report period Nov 1, 2024 \\u2013 Sept 30, 2025 due Oct 15, 2025<\\/strong><\\/p><p>Reporting template is provided on the last page of the attached contract. Reports and itemized invoices must be submitted to the county contact listed below.<\\/p><p>The budget allowance is as follows:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/803\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>Questions regarding the program can be addressed to:<\\/p><p>Frank Brooks<br>Northampton County Community &amp; Economic Development<br>610-829-6311<br>fbrooks@norcopa.gov<\\/p>\",\"funder_id\":\"2\",\"amount\":\"35000.00\",\"start_date\":\"2023-10-01\",\"end_date\":\"2025-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-04-18 14:20:29\",\"created_at\":\"2024-04-18 14:20:29\",\"id\":327,\"documents\":[],\"media\":[]}','10.55.4.95','2024-04-18 18:20:29','2024-04-18 18:20:29');
