INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (771,'audit:created',335,'App\\Models\\Contract#335',45,'{\"title\":\"2024SHFB_StarbucksFoodShareCapacity\",\"contract_number\":\"335\",\"cfda_number\":null,\"purpose\":\"<p>This is a <strong>$25,000.00 lump sum<\\/strong> grant, awarded by Starbucks to support it\'s FoodShare program. This program is designed to provide necessary infrastructure to partner agencies who receive product from the <a href=\\\"https:\\/\\/stories.starbucks.com\\/stories\\/hunger-relief\\/\\\">Starbucks FoodShare<\\/a> program.<\\/p><p>An itemized list of requested equipment has been submitted and accepted by Starbucks. Once funds are received, the Retail Recovery Coordinator will work with partner agencies to purchase and install equipment.<\\/p><p>A report is due on or before July 30, 2024, outlining the itemized expenditures and providing an Impact Statement on use of funds. Additional details are below.&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\\\"><\\/figure>\",\"funder_id\":\"194\",\"amount\":\"25000.00\",\"start_date\":\"2024-05-01\",\"end_date\":\"2024-07-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-05-08 10:51:23\",\"created_at\":\"2024-05-08 10:51:23\",\"id\":335,\"documents\":[],\"media\":[]}','10.55.4.124','2024-05-08 14:51:23','2024-05-08 14:51:23');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (772,'audit:updated',335,'App\\Models\\Contract#335',45,'{\"purpose\":\"<p>This is a <strong>$25,000.00 lump sum<\\/strong> grant, awarded by Starbucks to support it\'s <a href=\\\"https:\\/\\/stories.starbucks.com\\/stories\\/hunger-relief\\/\\\">FoodShare program<\\/a>; delivering frozen product daily directly to partner agencies. This program is designed to provide necessary infrastructure to those partner agencies who receive Starbucks product.<\\/p><p>An itemized list of requested equipment has been submitted and accepted by Starbucks. Once funds are received, the Retail Recovery Coordinator will work with partner agencies to purchase and install equipment.<\\/p><p>A report is due on or before July 30, 2024, outlining the itemized expenditures and providing an Impact Statement on use of funds. Additional details are below.&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2024-05-08 10:56:20\",\"id\":335,\"documents\":[{\"id\":825,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"3530efb0-7d09-4c3f-9c87-a3ee6fdcef04\",\"collection_name\":\"documents\",\"name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food Share\",\"file_name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":244628,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-08T15:51:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/825\\/663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":824,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"53a1f9c0-565c-420e-9588-5776608dba48\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":138433,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":5,\"created_at\":\"2024-05-08T15:48:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/824\\/conversions\\/image-preview.jpg\"},{\"id\":825,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"3530efb0-7d09-4c3f-9c87-a3ee6fdcef04\",\"collection_name\":\"documents\",\"name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food Share\",\"file_name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":244628,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-08T15:51:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/825\\/663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"preview_url\":\"\"}]}','10.55.4.124','2024-05-08 14:56:20','2024-05-08 14:56:20');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (773,'audit:updated',335,'App\\Models\\Contract#335',45,'{\"purpose\":\"<p>This is a <strong>$25,000.00 lump sum<\\/strong> grant, awarded by Starbucks to support it\'s <a href=\\\"https:\\/\\/stories.starbucks.com\\/stories\\/hunger-relief\\/\\\">FoodShare program<\\/a>; delivering frozen product daily directly to partner agencies. This program is designed to provide necessary infrastructure to those partner agencies who receive Starbucks product.<\\/p><p>An itemized list of requested equipment has been submitted and accepted by Starbucks (see below). Once funds are received, the Retail Recovery Coordinator will work with partner agencies to purchase and install equipment. Funds must be spent before July 30, 2024.<\\/p><p>A report is due on or before July 30, 2024, outlining the itemized expenditures, providing an Impact Statement on use of funds and social media coverage. Additional details are below.&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2024-05-08 11:07:19\",\"id\":335,\"documents\":[{\"id\":825,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"3530efb0-7d09-4c3f-9c87-a3ee6fdcef04\",\"collection_name\":\"documents\",\"name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food Share\",\"file_name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":244628,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-08T15:51:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/825\\/663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":824,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"53a1f9c0-565c-420e-9588-5776608dba48\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":138433,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":5,\"created_at\":\"2024-05-08T15:48:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/824\\/conversions\\/image-preview.jpg\"},{\"id\":825,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"3530efb0-7d09-4c3f-9c87-a3ee6fdcef04\",\"collection_name\":\"documents\",\"name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food Share\",\"file_name\":\"663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":244628,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-08T15:51:23.000000Z\",\"updated_at\":\"2024-05-08T15:51:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/825\\/663b9f4f80cde_2024SHFB_Starbucks_Food-Share.pdf\",\"preview_url\":\"\"}]}','10.55.4.124','2024-05-08 15:07:19','2024-05-08 15:07:19');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (774,'audit:created',336,'App\\Models\\Contract#336',3,'{\"title\":\"2024SSS_CityofAllentownESG_Rapid Rehousing\",\"contract_number\":\"700-01-9923-0404-40\",\"cfda_number\":\"14.231\",\"purpose\":\"<p>Provide housing identification, rental assistance, comprehensive case management and essential services for approximately 8 families.<\\/p><p>-The Sixth Street Shelter will offer this program to Category 1 families on the Coordinated Entry System\'s By-Name Lists (which will include families at the shelter). Set up a project in HMIS to pull applicants from in order to prioritize households who are at high risk.<\\/p><p>-The Sixth Street Shelter will participate in the Lehigh Valley Regional Homeless Advisory Board\'s Landlord Engagement Program.<\\/p><p>-Housing First best practices to remove barriers will be employed which include no requirement for employment, income, and sobriety or the absence of a criminal record.<\\/p><p><strong>Budget and Appropriate Use of Funds:<\\/strong><\\/p><p><strong>Services: $11,901.10<\\/strong><\\/p><p>-<i><strong>Housing search and placement<\\/strong> <\\/i>which includes but is not limited to assessment of housing barriers, needs and preferences, development of action plan, housing search, outreach and negotiation with owner, assistance submitting rental application, assessment of housing for ESG requirements for habitability, lead based paint and rent reasonableness, tenant counseling, etc...<\\/p><p>-<i><strong>Housing Stability Case Management<\\/strong><\\/i> which includes but is not limited to using the centralized or coordinated assessment system to conduct the initial evaluation and re-evaluation, counseling, developing, securing and coordinating services for Federal, state and local benefits, monitoring and evaluating participant progress, developing housing and service plan, follow up counseling and assessment at 3,6 and 12 months after the families have completed the program, etc... &nbsp;**(Case management cannot exceed 30 days during the period the program participant is seeking permanent housing and cannot exceed 24 months during the period the program participant is living in permanent housing.)<\\/p><p>-Family Service plan should be offered but is not required<\\/p><p>-Verify Homelessness or Risk of Homelessness Status<\\/p><p><strong>Financial Assistance: $7,500<\\/strong><\\/p><p>-Rental Application fees, security deposits (no more than two months of rent), last month\'s rent, moving costs, utility deposits, utility payments (up to 24 months or 6 months of arrears)<\\/p><p><strong>Rental Assistance: $20,000<\\/strong><\\/p><p>-Rental assistance for 3-6 months<\\/p><p>-Rent payments must not exceed Fair Market Rent established by HUD<\\/p><p>-Apartment must be assessed by the city of Allentown for HUD Habitability Standards<\\/p><p>-A rental assistance agreement must be created establishing the portion of rent being paid by the tenant and by SSS using a step-down method based on participant need. (Step-down method-security and first month\'s rent followed by 3-4 months of rental payment with increased responsibility placed on the participant based on family need.) &nbsp;A re-evaluation of eligibility must be done every 3 months if the participant is still receiving assistance. Participant must be under 30% of the median area income.<\\/p><p>-Obtain a legally binding lease<\\/p>\",\"funder_id\":null,\"amount\":\"39401.10\",\"start_date\":\"2024-01-26\",\"end_date\":\"2025-07-26\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-05-13 13:10:44\",\"created_at\":\"2024-05-13 13:10:44\",\"id\":336,\"documents\":[],\"media\":[]}','10.55.0.97','2024-05-13 17:10:44','2024-05-13 17:10:44');
