INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (783,'audit:updated',300,'App\\Models\\Contract#300',3,'{\"purpose\":\"<p>- Technical Assistance only (Business Counseling, Access to Capital, Loan Application preparation, post-loan technical assistance, Financial Literacy, Business Planning)<\\/p><p>-May be used to cover costs incurred on or after March 3, 2021.<\\/p><p>-We will receive these funds in a lump sum<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/677\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"notes\":\"<ul><li>Quarterly Project and Expenditure Reports<\\/li><li><strong>The report will ask for a short narrative\\/description of how businesses were negatively impacted by COVID 19.<\\/strong><\\/li><\\/ul><p><strong>Updates to terms:<\\/strong><\\/p><p>-\\\"Historically Disadvantages\\\" has been expanded to include women.<\\/p><p>-Any businesses receiving technical assistance not located in a QCT require backup documentation to support negative COVID 19 impact.<\\/p>\",\"updated_at\":\"2024-05-14 14:41:42\",\"id\":300,\"documents\":[{\"id\":678,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":300,\"uuid\":\"bfd2b7b1-d422-48fc-8274-34526b6c460e\",\"collection_name\":\"documents\",\"name\":\"65c23e5ce8a67_SBG II Agreement - Rising Tide Community Loan Fund.docx\",\"file_name\":\"65c23e5ce8a67_SBG-II-Agreement---Rising-Tide-Community-Loan-Fund.docx.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":414971,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-02-06T14:14:44.000000Z\",\"updated_at\":\"2024-02-06T14:14:44.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/678\\/65c23e5ce8a67_SBG-II-Agreement---Rising-Tide-Community-Loan-Fund.docx.pdf\",\"previe