INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (838,'audit:updated',334,'App\\Models\\Contract#334',3,'{\"purpose\":\"<p><strong>Weatherization Service Provider (WSP) Responsibilities:&nbsp;<\\/strong><\\/p><ul><li>Weatherization Services to include but not limited to: Attic and wall insulation, Air sealing, Duct Sealing and Repair, Door and window weather stripping, etc. see page 2 section 1 Scope of work in the Statement of Work document.<\\/li><li>Perform a full energy audit with pressure diagnostic and associated safety testing<\\/li><li>Must complete a minimum of 50 jobs<\\/li><li>WSP is responsible for recruiting and training personnel and securing criminal background checks within the last 7 years of all employees and subcontractors to be kept on file.<\\/li><li>WSP personnel must display and wear program identification badges while at customers\' homes. Badges must be returned to First Energy if and when employees terminate employment.<\\/li><li>BPI certifications must be kept current and on file.<\\/li><li>Potential quarterly Advisory Panel meeting participation.<\\/li><li>Attend all First Energy sponsored trainings<\\/li><li>Must have a dedicated quality control representative to ensure each job is inspected internally.<\\/li><li>WSP must resolve all customer complaints and document the process int the \\\"Job Notes\\\" section of the LEEN System.<\\/li><li>WSP is responsible for debris removal and cleanup of premises<\\/li><li>Energy Education sessions must be provided to customers during initial visit.<\\/li><li>Remedial education sessions may be required based on monthly reports provided to the WSP. Results and Conversations must be documented int he LEEN system before First Energy is invoiced.<\\/li><li>See page 10 in the Statement of Work Document for required equipment.<\\/li><li>See page 11 section 4.19 in the Statement of Work document for required diagnostic testing<\\/li><li>WSP is responsible for Weatherization Service Provider and Customer Health and Safety see page 11 sections 4.20-4.21 in the Statement of Work Document.<\\/li><li>Use LEEN System to manage assigned jobs and perform tasks. LEEN system to be used for reporting, tracking, invoices and program forms.<\\/li><\\/ul><p><strong>Publicity:<\\/strong><\\/p><ul><li>Any contact with news or media regarding this program needs to be approved by First Energy.<\\/li><li>Prohibition of publicity- WSP shall not reference \\\"First Energy\\\" in any advertising, promotional materials or social media without prior express written consent.<\\/li><\\/ul><p><strong>Invoicing and Payment:<\\/strong><\\/p><ul><li>See page 3 Article 4 in Master Service Agreement for Invoicing and Payment Procedures<\\/li><li>See page 9 section 4.17 in Statement of Work document for Job Completion and Invoicing. For jobs considered complete they must be coded as ready to inspect by a third-party Quality Assurance Inspector and all documents must be uploaded into the LEEN system. Invoicing to be submitted into LEEN system at the completion of the job within 30 days of the completion.<\\/li><\\/ul>\",\"notes\":\"<p><strong>Insurance Requirements:<\\/strong><\\/p><ul><li>General Commercial Liability $2,000,000 per occurrence<\\/li><li>Automobile Liability $1,000,000<\\/li><li>Professional Errors and Omissions $2,000,000 per occurrence<\\/li><li>Cyber Liability $2,000,000 per occurrence<\\/li><\\/ul><p><strong>First Energy:<\\/strong><\\/p><ul><li>First Energy will conduct Quality Assurance Visits, Job inspections and periodic evaluations<\\/li><li>Inspection, rejection, Revocation- work shall be subject to inspection, tests and count by First Energy anytime.<\\/li><\\/ul>\",\"updated_at\":\"2024-05-24 08:38:19\",\"id\":334,\"documents\":[{\"id\":843,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":334,\"uuid\":\"f3f8e7e2-6829-4356-90ab-2474316bb52d\",\"collection_name\":\"documents\",\"name\":\"6644ce28c8884_2024Wx_First Energy Warm_SOW-\",\"file_name\":\"6644ce28c8884_2024Wx_First-Energy-Warm_SOW-.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1028380,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-15T16:04:33.000000Z\",\"updated_at\":\"2024-05-15T16:04:33.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/843\\/6644ce28c8884_2024Wx_First-Energy-Warm_SOW-.pdf\",\"preview_url\":\"\"},{\"id\":844,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":334,\"uuid\":\"16905cae-8414-4d56-a6c2-4276ed7e94a9\",\"collection_name\":\"documents\",\"name\":\"6644cf08540fb_2024Wx_First Energy Warm_ Information Access Agreement\",\"file_name\":\"6644cf08540fb_2024Wx_First-Energy-Warm_-Information-Access-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":344055,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-05-15T16:04:33.000000Z\",\"updated_at\":\"2024-05-15T16:04:33.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/844\\/6644cf08540fb_2024Wx_First-Energy-Warm_-Information-Access-Agreement.pdf\",\"preview_url\":\"\"},{\"id\":845,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":334,\"uuid\":\"6a84b0e3-9f42-4e4b-855d-b2d48b97a6a5\",\"collection_name\":\"documents\",\"name\":\"6644cf0b78842_2024Wx_First Energy Warm_ Master Service Agreement\",\"file_name\":\"6644cf0b78842_2024Wx_First-Energy-Warm_-Master-Service-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":284232,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":3,\"created_at\":\"2024-05-15T16:04:33.000000Z\",\"updated_at\":\"2024-05-