INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (842,'audit:created',340,'App\\Models\\Contract#340',3,'{\"title\":\"2024REJ_PPL_ Power and Equity _SHEGENX\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-$10,000 for Generation Next and SHE to be used for general operating.<\\/p><p>-There is no reporting requirement at this time.<\\/p><p><strong>Marketing:<\\/strong><\\/p><p>-Please do not post on social media or prepare a news release prior to May 30th, 2024.<\\/p><p>-Tag PPL on a social media post by mentioning <strong>@PPLCorp<\\/strong>&nbsp;and <strong>@PPLElectric<\\/strong>&nbsp;and use the hashtag <strong>#pplcares.&nbsp; <\\/strong>The PPL Foundation logo is available to download <a href=\\\"https:\\/\\/www.pplweb.com\\/logo-downloads.\\/\\\">here<\\/a>.<\\/p><p>-Please see sample news release in the attached documents.<\\/p>\",\"funder_id\":\"82\",\"amount\":\"10000\",\"start_date\":\"2024-05-21\",\"end_date\":null,\"notes\":null,\"grant_code\":\"8000\",\"updated_at\":\"2024-05-28 13:49:47\",\"created_at\":\"2024-05-28 13:49:47\",\"id\":340,\"documents\":[],\"media\":[]}','10.55.0.204','2024-05-28 17:49:47','2024-05-28 17:49:47');
