INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (848,'audit:updated',338,'App\\Models\\Contract#338',45,'{\"purpose\":\"<p>Pike County has awarded SHFB a CDBG grant for $34,508.00 for the purchase of fresh food for Pike County. This is a <strong>reimbursable grant<\\/strong> with the grant period running from <strong>May 9, 2024 - August 31, 2025<\\/strong>. Food will be distributed to partner agencies serving Pike county.&nbsp;<\\/p><p>Fresh food includes dairy, meat, eggs, fruits, and vegetables. Whenever possible, fresh food shall be procured from farmers located in Pike County.<\\/p><p>Food pantries serviced with CDBG funds must prepare and submit a letter on letterhead stating they will collect a Self Declaration of Need form from each individual served and that no food or non-food items purchased through this grant will be distributed to individuals who have not completed a Self Declaration of need form or who are deemed to be ineligible due to income. A template for this letter can be found in Exhibit B of the contract attached.<\\/p><p>Reports are due bi-monthly, according to the chart below. Completed reports should be sent to Katie Blake at Hailstone Economic, LLC which administers the CDBG funds: <a href=\\\"kblake@hailstoneeconomic.com\\\">kblake@hailstoneeconomic.com<\\/a><\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/936\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/938\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2024-05-30 14:23:13\",\"funder_id\":\"206\",\"id\":338,\"documents\":[],\"media\":[{\"id\":936,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":338,\"uuid\":\"f037c807-4acb-4a91-9466-509bc9b2a7fb\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":105917,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-30T19:13:15.000000Z\",\"updated_at\":\"2024-05-30T19:13:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/936\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/936\\/conversions\\/image-preview.jpg\"},{\"id\":937,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":338,\"uuid\":\"b08b5827-6a8d-44d7-b963-53d991375e0d\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":105917,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-05-30T19:13:46.000000Z\",\"updated_at\":\"2024-05-30T19:13:46.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/937\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/937\\/conversions\\/image-preview.jpg\"},{\"id\":938,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":338,\"uuid\":\"49b4b248-6489-40b7-a9c3-327a5fe164da\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":74500,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":3,\"created_at\":\"2024-05-30T19:14:21.000000Z\",\"updated_at\":\"2024-05-30T19:14:21.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/938\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/938\\/conversions\\/image-preview.jpg\"}]}','10.55.4.170','2024-05-30 18:23:13','2024-05-30 18:23:13');
