INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (855,'audit:created',342,'App\\Models\\Contract#342',3,'{\"title\":\"2024 CADB_Lehigh University_Alley House Pilot Project\",\"contract_number\":\"Sub award# 545010-78001\",\"cfda_number\":null,\"purpose\":\"<p>Lead the community engagement process for the Alley House Pilot Project with all project partners. Please see \\\" Alley House Pilot Project Community Engagement Overview\\\" for more details. (Page 40 of the contract)<\\/p><figure class=\\\"image image-style-side\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/950\\/image.png\\\"><\\/figure><figure class=\\\"image image-style-side\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/951\\/image.png\\\"><\\/figure><p><strong>Invoicing:<\\/strong><\\/p><p>This is a reimbursable grant and requires submission of invoices with cost details, receipts and back up monthly or no less than quarterly. Submission for reimbursement to ininv@lehigh.edu.&nbsp;<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"10000\",\"start_date\":\"2024-03-01\",\"end_date\":\"2026-03-01\",\"notes\":\"<p><strong>Reporting:<\\/strong><\\/p><p>Will be done by Lehigh University and Karen Pooley (kbp312@lehigh.edu) will reach out for required data for reporting as needed.&nbsp;<\\/p><p><strong>Record Retention:<\\/strong><\\/p><p>All records must be maintained until HUD notifies us that they have closed the program year.<\\/p>\",\"grant_code\":null,\"updated_at\":\"2024-06-17 09:27:13\",\"created_at\":\"2024-06-17 09:27:13\",\"id\":342,\"documents\":[],\"media\":[]}','10.55.0.204','2024-06-17 13:27:13','2024-06-17 13:27:13');
