INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (869,'audit:updated',174,'App\\Models\\Contract#174',3,'{\"notes\":\"<p>-<strong>Other Specifications- <\\/strong>Property must be owner occupied, constructed before 1978, occupied by 1 child under 6 years old or a pregnant woman or visited by a child under 6 at least 60 hours per year, below 80% AMI, blood test screening or waiver\\/affidavit required. Up to $24,999 of lead hazard abatement assistance may be provided to any one household.&nbsp;<\\/p><ul><li>Please see page 31- 52 Contract Clauses Required for all CDBG Construction Grants<\\/li><li>This is a reimbursable grant.<\\/li><li>Adherence to Domestic Content Procurement Preference (page 5)<\\/li><li>Open and Competitive Bidding Requirements (Page 5 Section 21-26)<\\/li><li>Fiscal Year audit results to be sent to DCED<\\/li><li>Attachment E Section 3 Guidelines<\\/li><li>HUD Forms at the end of the contract to be used in cases of contracts more than $24,999.<\\/li><li>There are no reports due for this contract although&nbsp;detailed case files to be kept on each project and should include Environmental Clearance and Income Eligibility Review<\\/li><\\/ul>\",\"updated_at\":\"2024-06-25 14:33:44\",\"id\":174,\"documents\":[{\"id\":279,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":174,\"uuid\":\"f59e3b40-0482-4921-b28c-2e2412b67bad\",\"collection_name\":\"documents\",\"name\":\"647a03ff219a0_2023HRP_NCDCEDARP_ResidentialLeadHazardAbatementProgram_executedcontract\",\"file_name\":\"647a03ff219a0_2023HRP_NCDCEDARP_ResidentialLeadHazardAbatementProgram_executedcontract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":3624151,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2023-06-02T15:00:20.000000Z\",\"updated_at\":\"20