INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (872,'audit:created',347,'App\\Models\\Contract#347',3,'{\"title\":\"2024CALV_LC Aging and Adult Services\",\"contract_number\":\"24-AGNG-142\",\"cfda_number\":null,\"purpose\":\"<p>TEFAP-as authorized (.10 cents\\/lb. or actual cost)&nbsp;<\\/p><p>HAP Rental Assistance- $317,680<\\/p><p>HAP Rental Assistance Care Management (Salary for Fiscal staff to process HAP Checks)-$28,328- $38.17 hourly rate<\\/p><p>HAP Aftercare Managment (SSS Case Management)- $35,543- $39.58 hourly rate (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 3,6, and 12 months)<\\/p>\",\"funder_id\":\"73\",\"amount\":\"0.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":\"<p>-See Appendix B in contract for Budget and Rates (program CAP is set at $381,551)<\\/p><p>-Reimbursable Grant<\\/p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served. Billing statements not received by the 20th day of the month, following a month of service, can be subject to a late submission fee totaling 2% of the invoice.<\\/p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.<\\/p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services<\\/p><p>-Record retention must be no less than 4 years post final payment under the agreement.<\\/p>\",\"grant_code\":\"4200\",\"updated_at\":\"2024-07-01 08:41:07\",\"created_at\":\"2024-07-01 08:41:07\",\"id\":347,\"documents\":[],\"media\":[]}','10.55.0.204','2024-07-01 12:41:07','2024-07-01 12:41:07');
