INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (878,'audit:created',349,'App\\Models\\Contract#349',45,'{\"title\":\"2024SHFB_AldiRetailRecovery\",\"contract_number\":\"349\",\"cfda_number\":null,\"purpose\":\"<p>This grant is intended to support SHFB\'s retail recovery efforts.<\\/p><p>The grant amount is $1,000 and the grant period is from 6\\/1\\/2024 - 5\\/31\\/2025.<\\/p><p>If additional stores open in our service area before the end of the grant period, SHFB may be eligible for additional funding.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/989\\/image.png\\\"><\\/figure><p>SHFB will be asked to publicize the partnership with Aldi at such events as check presentations, new store openings, or any product drives.<\\/p><p>SHFB is strongly encouraged to plan an employee volunteer event.&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2024-06-01\",\"end_date\":\"2025-05-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-07-03 07:45:21\",\"created_at\":\"2024-07-03 07:45:21\",\"id\":349,\"documents\":[],\"media\":[]}','10.55.4.170','2024-07-03 11:45:21','2024-07-03 11:45:21');
