INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (880,'audit:updated',349,'App\\Models\\Contract#349',45,'{\"purpose\":\"<p>This grant is intended to support SHFB\'s retail recovery efforts.<\\/p><p>The grant amount is $1,000 and the grant period is from 6\\/1\\/2024 - 5\\/31\\/2025. The grant may be used toward salary and\\/or equipment and supplies to support retail recovery efforts. The grant may also be re-allocated to a partner agency to directly support their efforts in partnering with their local Aldi store.&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/991\\/image.png\\\"><\\/figure><p>If additional stores open in our service area before the end of the grant period, SHFB may be eligible for additional funding.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/989\\/image.png\\\"><\\/figure><p>SHFB will be asked to publicize the partnership with Aldi at such events as check presentations, new store openings, or any product drives.<\\/p><p>SHFB is strongly encouraged to plan an employee volunteer event.&nbsp;<\\/p>\",\"updated_at\":\"2024-07-03 07:59:59\",\"id\":349,\"documents\":[{\"id\":990,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":349,\"uuid\":\"fd304318-df01-490a-ac3c-3fd547b8c2f3\",\"collection_name\":\"documents\",\"name\":\"668547d187139_FY24 Aldi New Store_1000\",\"file_name\":\"668547d187139_FY24-Aldi-New-Store_1000.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":187672,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-03T12:45:21.000000Z\",\"updated_at\":\"2024-07-03T12:45:21.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/990\\/668547d187139_FY24-Aldi-New-Store_1000.pdf\",\"preview_url\":\"\"}],\"media\":[{\"i