INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (881,'audit:created',350,'App\\Models\\Contract#350',3,'{\"title\":\"2024HCP_LC Affordable Housing Trust\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-Salary, Benefits and program supplies for HCP.<\\/p><p>Can be used for work on Homebuyer seminars, pre-purchase counseling, pre-settlement counseling, loss mitigation services, applications for Homeowner emergency Mortgage Assistance program and foreclosure mitigation services.<\\/p><p>-See Exhibit A for more details.<\\/p>\",\"funder_id\":null,\"amount\":\"40000\",\"start_date\":\"2023-07-01\",\"end_date\":\"2025-06-30\",\"notes\":\"<p>-Invoices and reimbursement requests can be sent to Laurie Moyer via email at lauriemoyer@lehighcounty.org&nbsp;<\\/p><p>-Grantee must include \\\"This project is supported in part by a grant from the County of Lehigh\\\" in all publications relating to this project.<\\/p><p>-See page 3 Administrative Requirements part A, Section I for document retention requirements.<\\/p><p>-This contract can be renewed for an addition year and must be requested in writing.<\\/p>\",\"grant_code\":\"4100\",\"updated_at\":\"2024-07-03 08:54:37\",\"created_at\":\"2024-07-03 08:54:37\",\"id\":350,\"documents\":[],\"media\":[]}','10.55.0.204','2024-07-03 12:54:37','2024-07-03 12:54:37');
