INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (917,'audit:created',360,'App\\Models\\Contract#360',45,'{\"title\":\"2024-2025SHFB PMUW Monroe County Food Distribution\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The purpose of this grant is to support the purchase and distribution of fresh foods to Monroe County. This is a lump sum grant. Grant funds are outlined as below. Due to the final grant sum, food and staffing funding will be decreased by $2,500 each.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1027\\/image.png\\\"><\\/figure><p>A final report will be due approximately one month after the grant period ends. Reporting information will be sent to the planner-SHFB@caclv.org.<\\/p>\",\"funder_id\":\"115\",\"amount\":\"20000.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-07-17 14:48:19\",\"created_at\":\"2024-07-17 14:48:19\",\"id\":360,\"documents\":[],\"media\":[]}','10.55.4.176','2024-07-17 18:48:19','2024-07-17 18:48:19');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (918,'audit:updated',360,'App\\Models\\Contract#360',45,'{\"purpose\":\"<p>The purpose of this grant is to support the purchase and distribution of fresh foods to Monroe County. This is a lump sum grant. Grant funds are outlined as below. Due to the final grant sum, food and staffing funding will be decreased by $2,500 each.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1027\\/image.png\\\"><\\/figure><p>The proposal states a service goal of 17,000 individuals.<\\/p><p>A final report will be due approximately one month after the grant period ends. Reporting information will be sent to the planner-SHFB@caclv.org.<\\/p>\",\"updated_at\":\"2024-07-17 14:51:19\",\"id\":360,\"documents\":[{\"id\":1028,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":360,\"uuid\":\"8f92201d-2894-403f-ad6e-3148db1e16ea\",\"collection_name\":\"documents\",\"name\":\"66981f5c19a93_2024SHFB_Pocono Mountain United Way_executed\",\"file_name\":\"66981f5c19a93_2024SHFB_Pocono-Mountain-United-Way_executed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":335878,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-17T19:48:19.000000Z\",\"updated_at\":\"2024-07-17T19:48:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1028\\/66981f5c19a93_2024SHFB_Pocono-Mountain-United-Way_executed.pdf\",\"preview_url\":\"\"},{\"id\":1029,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":360,\"uuid\":\"bdbfe0ec-ab5a-43a5-ac3e-f089cd7a524b\",\"collection_name\":\"documents\",\"name\":\"66981f5c1b496_2024_SHFB_PMUW_ProposalSubmitted\",\"file_name\":\"66981f5c1b496_2024_SHFB_PMUW_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conver