INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (920,'audit:created',361,'App\\Models\\Contract#361',45,'{\"title\":\"2024SHFB_Wawa Foundation Fly Beyond\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This is a $25,000 grant award to support child nutrition initiatives, with a concentration on fresh produce. This is a lump sum grant.<\\/p><p>The grant was awarded June 2024; a final grant period is to be determined.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1031\\/image.png\\\"><\\/figure><p>A report is required; more information is forthcoming.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1032\\/image.png\\\"><\\/figure><p>Media\\/Publicity is requested. A press release template is provided below.&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1033\\/image.png\\\"><\\/figure>\",\"funder_id\":\"153\",\"amount\":\"25000.00\",\"start_date\":\"2024-06-05\",\"end_date\":\"2025-07-01\",\"notes\":null,\"grant_code\":\"8067\",\"updated_at\":\"2024-07-18 10:36:17\",\"created_at\":\"2024-07-18 10:36:17\",\"id\":361,\"documents\":[],\"media\":[]}','10.55.4.176','2024-07-18 14:36:17','2024-07-18 14:36:17');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (921,'audit:created',362,'App\\Models\\Contract#362',45,'{\"title\":\"2024-2025SHFB_Feeding PA_PASS_MOU\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The Pennsylvania Agricultural Surplus System (PASS) program was designed to support Pennsylvania\'s agricultural industry statewide - to reduce waste of surplus product, support local farms, and get more nutritious food into the hands of Pennsylvanians experiencing food insecurity.<br><br>Food must be grown or produced in PA; wholesale or retail products do not qualify.<\\/p><p>Assigned counties: Carbon, Lehigh, Monroe, Northampton, Pike, and Wayne.<\\/p><p>PASS Suppliers will ensure that PASS Funding is allocated for all 67 PA counties in accordance with the approved SFPP Allocation Ratios for FY2024-2025. It is the responsibility of the PASS Subcontractor to carry out these allocations and distribute product t a value as close as possible to the dollar values allocated to their assigned counties.<\\/p><p>An SHFB representative must attend a bi-weekly conference call led by Feeding PA\'s Director of Agricultural Partnerships to provide updates on food sourcing and distributions using PASS funds.<\\/p><p>All purchases and commitments must be made by June 30, 2025.<\\/p><p>All documentation of purchases and commitments must be submitted by July 10, 2025.<\\/p><p>All services must be complete by August 15, 2025.<\\/p><p>SHFB must distribute 50% or more of their total funding allocation by December 31, 2024.<\\/p><p>Monthly reports should be emailed to Feeding PA by the 10th day of the following month until program completion. Reports should include:<\\/p><ul><li>Source of product (vendor name, street address, county, and city of origin)<\\/li><li>Product types and unit cost<\\/li><li>Pounds and costs of food distributed<\\/li><li>The street address and manner of each distribution<\\/li><li>The number of households served and method of determining households served<\\/li><li>Expense\\/reimbursement reports in Microsoft Excel format<\\/li><\\/ul>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-07-18 14:27:37\",\"created_at\":\"2024-07-18 14:27:37\",\"id\":362,\"documents\":[],\"media\":[]}','10.55.4.176','2024-07-18 18:27:37','2024-07-18 18:27:37');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (922,'audit:updated',362,'App\\Models\\Contract#362',45,'{\"purpose\":\"<p>The Pennsylvania Agricultural Surplus System (PASS) program was designed to support Pennsylvania\'s agricultural industry statewide - to reduce waste of surplus product, support local farms, and get more nutritious food into the hands of Pennsylvanians experiencing food insecurity.<br><br>Food must be grown or produced in PA; wholesale or retail products do not qualify.<\\/p><p>Assigned counties: Carbon, Lehigh, Monroe, Northampton, Pike, and Wayne.<\\/p><p>PASS Suppliers will ensure that PASS Funding is allocated for all 67 PA counties in accordance with the approved SFPP Allocation Ratios for FY2024-2025. It is the responsibility of the PASS Subcontractor to carry out these allocations and distribute product t a value as close as possible to the dollar values allocated to their assigned counties.<\\/p><p>An SHFB representative must attend a bi-weekly conference call led by Feeding PA\'s Director of Agricultural Partnerships to provide updates on food sourcing and distributions using PASS funds.<\\/p><p>All purchases and commitments must be made by <strong>June 30, 2025<\\/strong>.<\\/p><p>All documentation of purchases and commitments must be submitted by <strong>July 10, 2025.<\\/strong><\\/p><p>All services must be complete by <strong>August 15, 2025<\\/strong>.<\\/p><p>SHFB must distribute 50% or more of their total funding allocation by <strong>December 31, 2024<\\/strong>.<\\/p><p>Monthly reports should be emailed to Feeding PA by the <strong>10th day of the following month<\\/strong> until program completion. Reports should include:<\\/p><ul><li>Source of product (vendor name, street address, county, and city of origin)<\\/li><li>Product types and unit cost<\\/li><li>Pounds and costs of food distributed<\\/li><li>The street address and manner