INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (932,'audit:created',363,'App\\Models\\Contract#363',45,'{\"title\":\"2024SHFB_NCCDBG_Pantry Improvement\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>T<\\/p><p>he purpose of this $25,000 grant is to support improvements to \\\"brick and mortar\\\" food pantries in Northampton County. Anticipated use is for capital improvements to the Whole Life Center in Wilson, with the end result of building out a food hub.<\\/p><p>This is a reimbursable grant.*<\\/p><p>There are no reporting requirements other than invoicing. Invoicing forms are below.<\\/p><p>Restrictions and requirements follow HUD funding guidelines, including the below.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1047\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1048\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1049\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1050\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1051\\/image.png\\\"><\\/figure>\",\"funder_id\":\"2\",\"amount\":\"25000.00\",\"start_date\":\"2024-06-10\",\"end_date\":\"2024-12-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-07-25 12:50:26\",\"created_at\":\"2024-07-25 12:50:26\",\"id\":363,\"documents\":[],\"media\":[]}','10.55.4.176','2024-07-25 16:50:26','2024-07-25 16:50:26');
