INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (934,'audit:updated',363,'App\\Models\\Contract#363',45,'{\"purpose\":\"<p>The purpose of this $25,000 grant is to support improvements to \\\"brick and mortar\\\" food pantries in Northampton County. Anticipated use is for capital improvements to the Whole Life Center in Wilson, with the end result of building out a food hub.<\\/p><p>This is a reimbursable grant.*<\\/p><p>There are no reporting requirements other than invoicing. Invoicing forms are below.<\\/p><p>Restrictions and requirements follow HUD funding guidelines, including the below.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1047\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1048\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1049\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1051\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1057\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-07-25 13:13:07\",\"id\":363,\"documents\":[{\"id\":1052,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":363,\"uuid\":\"77d3b917-5ec0-4b9f-9a0b-0ed402ff9d79\",\"collection_name\":\"documents\",\"name\":\"66a2900e05dfd_Northampton County RE_ Question - reporting deadlines for 2023-2025 CDBG Funding\",\"file_name\":\"66a2900e05dfd_Northampton-County-RE_-Question---reporting-deadlines-for-2023-2025-CDBG-Funding.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":360243,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-25T17:50:26.000000Z\",\"updated_at