INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (944,'audit:updated',367,'App\\Models\\Contract#367',3,'{\"purpose\":\"<p>TEFAP-as authorized (.10 cents\\/lb. or actual cost)&nbsp;<\\/p><p>HAP Rental Assistance- $317,680<\\/p><p>HAP Rental Assistance Care Management (Salary for Fiscal staff to process HAP Checks)-$28,328- $38.17 hourly rate<\\/p><p>HAP Aftercare Managment (SSS Case Management)- $35,543- $39.58 hourly rate (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 3,6, and 12 months)<\\/p>\",\"notes\":\"<p>-See Appendix B in contract for Budget and Rates (program CAP is set at $381,551)<\\/p><p>-Reimbursable Grant<\\/p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served. Billing statements not received by the 20th day of the month, following a month of service, <strong>can be subject to a late submission fee totaling 2% of the invoice.<\\/strong><\\/p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.<\\/p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services<\\/p><p>-Record retention must be no less than 4 years post final payment under the agreement.<\\/p>\",\"grant_code\":\"4200\",\"updated_at\":\"2024-07-30 09:03:44\",\"id\":367,\"documents\":[{\"id\":1067,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":367,\"uuid\":\"6c5d3a28-99ce-4ece-838c-1dbd04bd7da8\",\"collection_name\":\"documents\",\"name\":\"66a8d824ae703_2024CALV_LCAAA_executed contract\",\"file_name\":\"66a8d824ae703_2024CALV_LCAAA_executed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":4103312,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-30T12:10:17.000000Z\",\"updated_at\":\"2024-07-30T12:10:17.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1067\\/66a8d824ae703_2024CALV_LCAAA_executed-contract.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":1067,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":367,\"uuid\":\"6c5d3a28-99ce-4ece-838c-1dbd04bd7da8\",\"collection_name\":\"documents\",\"name\":\"66a8d824ae703_2024CALV_LCAAA_executed contract\",\"file_name\":\"66a8d824ae703_2024CALV_LCAAA_executed-contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":4103312,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-30T12:10:17.000000Z\",\"updated_at\":\"2024-07-30T12:10:17.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1067\\/66a8d824ae703_2024CALV_LCAAA_executed-contract.pdf\",\"preview_url\":\"\"}]}','10.55.0.204','2024-07-30 13:03:44','2024-07-30 13:03:44');
