ons\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2023-03-23T19:23:48.000000Z\",\"updated_at\":\"2023-03-23T19:23:48.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/91\\/641ca73e2eced_2023SHFB_UnitedWay_Grant-Award-Notification.pdf\",\"preview_url\":\"\"},{\"id\":92,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":127,\"uuid\":\"7a46e69f-7d9e-4363-b3bd-225a1f62756c\",\"collection_name\":\"documents\",\"name\":\"641ca741bcfcb_2023-2026SSSSHFBREJ_UnitedWay_signedMOU (1)\",\"file_name\":\"641ca741bcfcb_2023-2026SSSSHFBREJ_UnitedWay_signedMOU-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":337582,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":3,\"created_at\":\"2023-03-23T19:23:48.000000Z\",\"updated_at\":\"2023-03-23T19:23:48.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/92\\/641ca741bcfcb_2023-2026SSSSHFBREJ_UnitedWay_signedMOU-(1).pdf\",\"preview_url\":\"\"}]}','10.55.0.204','2024-07-30 18:43:25','2024-07-30 18:43:25');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (950,'audit:deleted',336,'App\\Models\\Contract#336',3,'{\"id\":336,\"title\":\"2024SSS_CityofAllentownESG_Rapid Rehousing\",\"contract_number\":\"700-01-9923-0404-40\",\"purpose\":\"<p>Provide housing identification, rental assistance, comprehensive case management and essential services for approximately 5 families.<\\/p><p>-The Sixth Street Shelter will offer this program to Category 1 families on the Coordinated Entry System\'s By-Name Lists (which will include families at the shelter). Set up a project in HMIS to pull applicants from in order to prioritize households who are at high risk. Contact Antonio Diaz at <a href=\\\"mailto:antdiaz@pa.gov\\\">antdiaz@pa.gov<\\/a> to get this set up.<\\/p><p>-The Sixth Street Shelter will participate in the Lehigh Valley Regional Homeless Advisory Board\'s Landlord Engagement Program.<\\/p><p>-Housing First best practices to remove barriers will be employed which include no requirement for employment, income, and sobriety or the absence of a criminal record.<\\/p><p><strong>Budget and Appropriate Use of Funds:<\\/strong><\\/p><p><strong>Services: $11,901.10<\\/strong><\\/p><p>-<i><strong>Housing search and placement<\\/strong> <\\/i>which includes but is not limited to assessment of housing barriers, needs and preferences, development of action plan, housing search, outreach and negotiation with owner, assistance submitting rental application, assessment of housing for ESG requirements for habitability, lead based paint and rent reasonableness, tenant counseling, etc...<\\/p><p>-<i><strong>Housing Stability Case Management<\\/strong><\\/i> which includes but is not limited to using the centralized or coordinated assessment system to conduct the initial evaluation and re-evaluation, counseling, developing, securing and coordinating services for Federal, state and local benefits, monitoring and evaluating participant progress, developing housing and service plan, follow up counseling and assessment at 3,6 and 12 months after the families have completed the program, etc... &nbsp;**(Case management cannot exceed 30 days during the period the program participant is seeking permanent housing and cannot exceed 24 months during the period the program participant is living in permanent housing.)<\\/p><p>-Family Service plan should be offered but is not required<\\/p><p>-Verify Homelessness or Risk of Homelessness Status<\\/p><p>-Keep timesheets and logs for all time spent client facing and non-client facing.<\\/p><p><strong>Financial Assistance: $7,500<\\/strong><\\/p><p>-Rental Application fees, security deposits (no more than two months of rent), last month\'s rent, moving costs, utility deposits, utility payments (up to 24 months or 6 months of arrears)<\\/p><p><strong>Rental Assistance: $20,000<\\/strong><\\/p><p>-Rental assistance for 3-6 months<\\/p><p>-Rent payments must not exceed Fair Market Rent established by HUD<\\/p><p>-Apartment must be assessed by the city of Allentown for HUD Habitability Standards. Lynda Burian is the contact for habitability inspections. Contact her via email at <a href=\\\"mailto:Lynda.burian@allentownpa.gov\\\">Lynda.burian@allentownpa.gov<\\/a> \\u2013 email should include the address and landlord information. Please note that units must be registered rentals with the city (the inspector will have that information).<\\/p><p>-Participants must meet with a case manager at least once a month for the duration of assistance.<\\/p><p>-A rental assistance agreement must be created between the SSS, and the landlord please see form attached below.&nbsp;<\\/p><p>-Rent should be paid using a step-down method based on participant need. (Step-down method-security and first month\'s rent followed by 3-4 months of rental payment with increased responsibility placed on the participant based on family need.) &nbsp;A re-evaluation of eligibility must be done every 3 months if the participant is still receiving assistance. Participant must be under 30% of the median area income.<\\/p><p>-Obtain a legally binding lease<\\/p>\",\"date_of_award\":null,\"amount\":\"39401.10\",\"start_date\":\"2024-01-26\",\"end_date\":\"2025-07-26\",\"archived\":null,\"date_archived\":null,\"notes\":\"<p>-Quarterly reports are required using the same form as the regular ESG.<\\/p>\",\"grant_code\":null,\"created_at\":\"2024-05-13 13:10:44\",\"updated_at\":\"2024-08-01 11:14:48\",\"deleted_at\":\"2024-08-01 11:14:48\",\"funder_id\":204,\"cfda_number\":\"14.231\",\"documents\":[{\"id\":828,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":336,\"uuid\":\"fd0b67ca-c927-45f0-8650-70f52002548d\",\"collection_name\":\"documents\",\"name\":\"66424d1b2888d_UpdatedSubrecipientBudget_ESG_SSS_2023\",\"file_name\":\"66424d1b2888d_UpdatedSubrecipientBudget_ESG_SSS_2023.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":38745,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-05-13T18:10:44.000000Z\",\"updated_at\":\"2024-05-13T18:10:44.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/828\\/66424d1b2888d_UpdatedSubrecipientBudget_ESG_SSS_2023.pdf\",\"preview_url\":\"\"},{\"id\":829,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":336,\"uuid\":\"8bcb48e7-0ad0-484f-8043-6d7551880280\",\"collection_name\":\"documents\",\"name\":\"66424d2608e0d_CCF-027_2020F ESG PPRF Form_SSS_2023\",\"file_name\":\"66424d2608e0d_CCF-027_2020F-ESG-PPRF-Form_SSS_2023.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":249425,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-05-13T18:10:44.000000Z\",\"updated_at\":\"2024-05-13T18:10:44.00000