INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (951,'audit:created',368,'App\\Models\\Contract#368',45,'{\"title\":\"2024SHFB_FeedingAmerica_Costco Food Purchase\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This is a lump-sum grant to support food purchase to support Child Nutrition efforts.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1071\\/image.png\\\"><\\/figure><p>There is one final report due for this grant. A template is provided below. Reports are to be submitted through the GMS.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1070\\/image.png\\\"><\\/figure><p>Additionally, the grant agreement requests:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1072\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>Questions on this grant should be directed to:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1073\\/image.png\\\"><\\/figure>\",\"funder_id\":\"149\",\"amount\":\"52578.00\",\"start_date\":\"2024-05-01\",\"end_date\":\"2025-02-28\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-08-02 09:50:54\",\"created_at\":\"2024-08-02 09:50:54\",\"id\":368,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-02 13:50:54','2024-08-02 13:50:54');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (952,'audit:updated',313,'App\\Models\\Contract#313',45,'{\"purpose\":\"<p>This $40,000 grant will support the Military Share program during the grant period of <strong>6\\/1\\/2024 - 5\\/31\\/2025<\\/strong>. Utilizing these funds, SHFB will:<\\/p><ul><li>Provide nutritious shelf-stable and fresh foods to at least 560 military families.<\\/li><li>Distribute 235,000 pounds of food.<\\/li><li>Engage 100 volunteers for packing and distribution of food boxes.<\\/li><\\/ul><p>Funds received will be used for the following purposes:<\\/p><ul><li>Personnel and fringe benefits costs of $2,300 and $1,700 respectively, will support the Community Programs Coordinator at an hourly rate of $21.63.<\\/li><li>Commodities costs of $34,200 will support the purchase of food for Military Shares distribution.<\\/li><li>Supplies costs of $1,200 will support the purchase of 1,481 boxes at $.81\\/box.<\\/li><li>Distribution costs of $600 will support the cost of fuel for trucks to delivery Military Shares to distribution sites across six counties at $.65\\/mile.<\\/li><\\/ul><p>Regarding use of funds:&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/743\\/image.png\\\"><\\/figure><p>SHFB must submit a final audit, performed by a Certified Public Accountant, that accounts for all expenditures of grand funds and accrued interest therefrom <strong>no later than six (6) months<\\/strong> after the agreement period end.&nbsp;<\\/p><p><i>A Project Audit performed under the Single Audit Act of 1984 will not be accepted in lieu of a Project Audit required under this agreement.<\\/i><\\/p><p>Quarterly progress reports must be submitted to the Department of Veterans\' Affairs no later than thrity (30) days after the end of each quarter, with the first report covering the months June - September. The template for these reports will be provided by the Department prior to the end of the first quarter.<\\/p><p>Regarding reporting of salary + fringe:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1077\\/image.png\\\"><\\/figure><p>Contact email for this program is: <a href=\\\"RA-MVVetTrustFund@pa.gov\\\">RA-MVVetTrustFund@pa.gov<\\/a><\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-08-05 12:33:56\",\"id\":313,\"documents\":[{\"id\":746,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":313,\"uuid\":\"8384ae0d-b828-47ae-9ed8-0679b2c919f3\",\"collection_name\":\"documents\",\"name\":\"65f98835d1239_2023_SHFB_VeteransTrustFund_ProposalSubmitted\",\"file_name\":\"65f98835d1239_2023_SHFB_VeteransTrustFund_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":284162,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":4,\"created_at\":\"2024-03-19T12:43:36.000000Z\",\"updated_at\":\"2024-03-19T12:43:36.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/746\\/65f98835d1239_2023_SHFB_VeteransTrustFund_ProposalSubmitted.pdf\",\"preview_url\":\"\"},{\"id\":747,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":313,\"uuid\":\"0e2fffb7-6d0f-4382-868b-07333e340ade\",\"collection_name\":\"documents\",\"name\":\"65f9884e03a86_2023 Vet Trust Award Letter\",\"file_name\":\"65f9884e03a86_2023-Vet-Trust-Award-Letter.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":164231,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":5,\"created_at\":\"2024-03-19T12:43:36.000000Z\",\"updated_at\":\"2024-03-19T12:43:36.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/747\\/65f9884e03a86_2023-Vet-Trust-Award-Letter.pdf\",\"preview_url\":\"\"},{\"id\":847,\"model_type\":\"App\\\\Models\\\\Contract\",\"mo