INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (954,'audit:created',369,'App\\Models\\Contract#369',45,'{\"title\":\"2025SHFB_Feeding America_CVS SNAP Application\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The purpose of this $38,089.00 award is to support SNAP Application assistance. This is a lump sum award.<\\/p><p><strong>Grant Activities\\/Expectations<\\/strong><\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1078\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1081\\/image.png\\\"><\\/figure><p><strong>Use of Funds<\\/strong><\\/p><p>Funds will be used to support current staff salaries to perform SNAP outreach and application assistance as well as create a marketing strategy to reach potential SNAP beneficiaries within our urban centers and remote, rural communities. Funding will also be allocated to marketing efforts, in the form of digital outreach campaigns and the creation of printed materials.<\\/p><p>Two reports are due. A sample template is provided below, but all reports must be submitted via the FA Grants Management System.<\\/p><ul><li>January 28, 2025 - Progress report covering August 1, 2024 - December 31, 2024<\\/li><li>July 29, 2025 - Final report covering the entire grant period<\\/li><\\/ul><p>Timeline for the grant is:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1082\\/image.png\\\"><\\/figure>\",\"funder_id\":\"149\",\"amount\":\"38089.00\",\"start_date\":\"2024-08-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-08-05 13:32:12\",\"created_at\":\"2024-08-05 13:32:12\",\"id\":369,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-05 17:32:12','2024-08-05 17:32:12');
