INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (962,'audit:created',371,'App\\Models\\Contract#371',3,'{\"title\":\"2024SSS_ Lehigh County Children and Youth\",\"contract_number\":\"24-CY-084\",\"cfda_number\":null,\"purpose\":\"<p>-11 apartments pre-paid at $70 per day. Ability to fill up to 15 apartments based on availability.<\\/p><p>-Supportive Services billed at $65 per hour.&nbsp;<\\/p><ul><li>Charge for case management and weekly apartment inspections (client facing). Be sure to obtain participant signature on the Children and Youth log.&nbsp;<\\/li><li>Charge 1 hour per day every day for curfew checks<\\/li><\\/ul><p>-Extraordinary Expenses for damage to apartments. Upon exit inspection note and photograph damage. Bill Children and Youth for the cost of repair and provide the evidence. They will assess and reimburse us if approved.<\\/p><p>-CAP for the Contract is $406,050<\\/p>\",\"funder_id\":\"159\",\"amount\":\"0.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":\"<p><strong>Billing:<\\/strong><\\/p><p>Invoices must be submitted by the 5th working day of the month following the month of service. A 2% late submission fee may be applied to invoices received past the 20th day of the month.<\\/p><p><strong>Reporting:<\\/strong><\\/p><p>-Monthly report\\/invoicing to go along with billing to be submitted to fiscal staff. This includes apartments that are filled and supportive services hours along with required back up.<\\/p><p>-Quarterly reports are to be submitted to Lehigh County. An email will be sent out by the county, typically from Sharon Dunn sharondunn@lehighcounty.org, informing you when the report is due.<\\/p><p>-Annual Report to be submitted to Lehigh County and follows the same protocol as the quarterly report listed above.<\\/p>\",\"grant_code\":\"1300\",\"updated_at\":\"2024-08-09 09:43:41\",\"created_at\":\"2024-08-09 09:43:41\",\"id\":371,\"documents\":[],\"media\":[]}','10.55.0.204','2024-08-09 13:43:41','2024-08-09 13:43:41');
