INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (965,'audit:created',372,'App\\Models\\Contract#372',45,'{\"title\":\"2024SHFB_FA_Cargill 2024 Food Safety Training\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This $2,000 grant provides funding for food safety training(s) for food bank staff. This is a lump sum award.<\\/p><p>Below is the list of eligible courses; detailed training information (including pricing) is available in the attached proposal.<\\/p><ul><li>Food Defense Update Webinar<\\/li><li>Food Protection for Warehouses and DC\'s Webinar Series<\\/li><li>Food Defense Coordinator<\\/li><li>Understanding Good Manufacturing Practices (GMP)<\\/li><li>Food Safety and Sanitation Online Individual Modules<\\/li><li>ServSafe Food Handler Guide for Food Banking &amp; Online Video Companion Bundle<\\/li><\\/ul><p>Grantees must register for trainings before September 30, 2024.<\\/p><p><strong>There is one final report due on Tuesday, October 29, 2024. A sample template is attached.<\\/strong><\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1101\\/image.png\\\"><\\/figure>\",\"funder_id\":\"149\",\"amount\":\"2000.00\",\"start_date\":\"2024-06-01\",\"end_date\":\"2024-09-30\",\"notes\":null,\"grant_code\":\"8000\",\"updated_at\":\"2024-08-13 12:37:40\",\"created_at\":\"2024-08-13 12:37:40\",\"id\":372,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-13 16:37:40','2024-08-13 16:37:40');
