INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (974,'audit:created',374,'App\\Models\\Contract#374',45,'{\"title\":\"2025SHFB_Cedar Crest College Nutrition Intern MOU\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The purpose of this MOU is to define the roles and responsibilities of Cedar Crest College (the College) and SHFB. SHFB has agreed to provide the clinical education necessary among the requirements for registration as a dietitian and to educate personnel at the post-baccalaureate level who can function effectively in a professional environment.<\\/p><p>The College will administer the program, curriculum content, evaluation, faculty appointments, admission requirements, promotion and graduation and such other matters as are internal to the College. The College will maintain the necessary records of the students.<\\/p><p>SHFB will provide access to the food bank\'s facilities and direct supervision by the Nutrition Educator, who will be directing the interns in 1,200 hours of practical study.<\\/p><p>Additional stipulations are set out in the attached contract.<\\/p><p>The SHFB points of contact for this MOU are the Nutrition Educator, who will be implementing the program, and the Volunteer Coordinator, who will recruit and retain the College interns.<\\/p><p>There is no reporting due for this program.<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2024-08-01\",\"end_date\":\"2029-08-01\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-08-16 08:33:00\",\"created_at\":\"2024-08-16 08:33:00\",\"id\":374,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-16 12:33:00','2024-08-16 12:33:00');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (975,'audit:updated',374,'App\\Models\\Contract#374',45,'{\"updated_at\":\"2024-08-16 08:33:36\",\"funder_id\":\"215\",\"id\":374,\"documents\":[{\"id\":1111,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":374,\"uuid\":\"a45d6e03-38e2-4cf5-96d7-9940fd71b2c3\",\"collection_name\":\"documents\",\"name\":\"66bf5504b54b9_PA 2024 SHFB Dietetic Intern Nutrition\",\"file_name\":\"66bf5504b54b9_PA-2024-SHFB-Dietetic-Intern-Nutrition.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":342151,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-08-16T13:33:00.000000Z\",\"updated_at\":\"2024-08-16T13:33:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1111\\/66bf5504b54b9_PA-2024-SHFB-Dietetic-Intern-Nutrition.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":1111,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":374,\"uuid\":\"a45d6e03-38e2-4cf5-96d7-9940fd71b2c3\",\"collection_name\":\"documents\",\"name\":\"66bf5504b54b9_PA 2024 SHFB Dietetic Intern Nutrition\",\"file_name\":\"66bf5504b54b9_PA-2024-SHFB-Dietetic-Intern-Nutrition.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":342151,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-08-16T13:33:00.000000Z\",\"updated_at\":\"2024-08-16T13:33:00.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1111\\/66bf5504b54b9_PA-2024-SHFB-Dietetic-Intern-Nutrition.pdf\",\"preview_url\":\"\"}]}','10.55.4.176','2024-08-16 12:33:36','2024-08-16 12:33:36');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (976,'audit:created',375,'App\\Models\\Contract#375',45,'{\"title\":\"2024SHFB_CSFP_Senior Food Box Home Delivery\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This agreement outlines the usage of funding for the Senior Food Box Home Delivery Program. The funding is to support the Senior Food Box Program and to assist lead agencies with costs incurred in recruiting and ultimately providing service to more seniors in PA via home delivery.<\\/p><p>This is a reimbursement program; reimbursement requests are requested 10 days after the reimbursement period (monthly) using <a href=\\\"https:\\/\\/docs.google.com\\/document\\/d\\/19XUeJyhCgkuCNkYVCIC_Uxk9r5YfAYQJerlr6Ryd3eM\\/edit?usp=drive_link\\\">Form 502069<\\/a>. If SHFB anticipates not being able to utilize all of the allocation, Hunger Free PA must be alerted as soon as possible.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1112\\/image.png\\\"><\\/figure><p>Capital expenditures are only available with prior approval:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1113\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p>\",\"funder_id\":\"172\",\"amount\":\"58152.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-08-20 10:50:27\",\"created_at\":\"2024-08-20 10:50:27\",\"id\":375,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-20 14:50:27','2024-08-20 14:50:27');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (977,'audit:updated',375,'App\\Models\\Contract#375',45,'{\"purpose\":\"<p>This agreement outlines the usage of funding for the Senior Food Box Home Delivery Program. The funding is to support the Senior Food Box Program and to assist lead agencies with costs incurred in recruiting and ultimately providing service to more seniors in PA via home delivery.<\\/p><p>This is a reimbursement program; reimbursement requests are to be submitted 10 days after the reimbursement period (monthly) using <a href=\\\"https:\\/\\/docs.google.com\\/document\\/d\\/19XUeJyhCgkuCNkYVCIC_Uxk9r5YfAYQJerlr6Ryd3eM\\/edit?usp=drive_link\\\">Form 502069<\\/a>. If SHFB anticipates not being able to utilize all of the allocation, Hunger Free PA must be alerted as soon as possible.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1112\\/image.png\\\"><\\/figure><p>Capital expenditures are only available with prior approval:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1113\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-08-20 10:51:20\",\"id\":375,\"documents\":[{\"id\":1114,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":375,\"uuid\":\"086d3dd8-0f27-4477-9cb0-3aad03255968\",\"collection_name\":\"documents\",\"name\":\"66c4b5df7e330_2024SHFB_CSFP_HFPA_ Senior Box Delivery\",\"file_name\":\"66c4b5df7e330_2024SHFB_CSFP_HFPA_-Senior-Box-Delivery.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":122497,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-08-20T15:50:27.000000Z\",\"updated_at\":\"2024-08-20T15:50:27.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1114\\/66c4b5df7e330_2024SHFB_CSFP_HFPA_-Senior-