INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (989,'audit:created',378,'App\\Models\\Contract#378',45,'{\"title\":\"2024-2025SHFB_United Way of Wayne and Lackawanna_Military Share\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The goal of this funding is to provide \\\"Expanded Food Access\\\" to Military Veterans and their families in Wayne County. The stated target is 27 Military Shares distributed monthly.<\\/p><p>A report will be due at the end of the grant period. More information, template and report due date will be emailed to the planner-SHFB@caclv.org email or through the portal: <a href=\\\"https:\\/\\/agency.e-cimpact.com\\/login.aspx?org=40570U\\\">https:\\/\\/agency.e-cimpact.com\\/login.aspx?org=40570U<\\/a> (UN: Briana.McGonagle PW: Shfb6969!!$$)<\\/p><p>A campaign kick-off event will be held 9\\/18. Additional details are available in the award letter.<\\/p><p>Contact for this campaign is:<\\/p><p>William Craven<br>Manager of Community Impact Funds<br>(570) 343-1267 ext 226<br>wcraven@uwlc.net<\\/p>\",\"funder_id\":\"95\",\"amount\":\"4000.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-08-27 10:23:41\",\"created_at\":\"2024-08-27 10:23:41\",\"id\":378,\"documents\":[],\"media\":[]}','10.55.4.176','2024-08-27 14:23:41','2024-08-27 14:23:41');
