INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (995,'audit:updated',348,'App\\Models\\Contract#348',3,'{\"title\":\"2024CAH_PHFA PHARE_ Healthy Homes\",\"purpose\":\"<p><strong>Grant Purpose:<\\/strong> To assist 10 homeowners in Lehigh and Northampton counties to improve their homes living conditions, health and safety. &nbsp;<\\/p><ol><li>See eligible improvements attached<\\/li><li>See contract attached<\\/li><li>See Budget attached<\\/li><\\/ol><ul><li>30% of the grant must be used to benefit households below 50% AMI<\\/li><li>No portion of the grant funds are to be used to benefit households above 200% AMI<\\/li><li>Contract expires 18 months post full execution date (TBD)<\\/li><li><strong>Read<\\/strong> Page 9, part C. Grantee responsibilities for provisions that need to carry over into subcontractor contracts<\\/li><li>Debarment searches required for all subcontractors<\\/li><li><strong>Read <\\/strong>page 17, Article XXIII Workers Protection and Investment for all applicable acts and laws such as PA Prevailing Wage requirements<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"end_date\":\"2026-01-31\",\"notes\":\"<ul><li><strong>Fiscal Requirement: <\\/strong>The funds are to be placed in a separate interest-bearing account. Interest to be used for project purposes.<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>Reports must be submitted 30 days from the end of each semi-annual period. Information to include itemized grant expenditures, HH income, geographic and demographic data, etc.&nbsp;<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>Maintain all records related to this grant for a minimum of 4 years post agreement termination.<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-09-11 10:42:05\",\"id\":348,\"documents\":[{\"id\":983,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":348,\"uuid\":\"2e7a5dec-5da3-4c41-97b3-4adbe76fb5f7\",\"collection_name\":\"documents\",\"name\":\"6682d21f29009_RE_ PHARE Award - Retroactive expenses\",\"file_name\":\"6682d21f29009_RE_-PHARE-Award---Retroactive-expenses.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":296071,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-01T16:06:12.000000Z\",\"updated_at\":\"2024-07-01T16:06:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/983\\/6682d21f29009_RE_-PHARE-Award---Retroactive-expenses.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":978,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":348,\"uuid\":\"2295ebeb-fcc5-4b32-b680-10f823df3031\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":78137,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":5,\"created_at\":\"2024-07-01T15:58:56.000000Z\",\"updated_at\":\"2024-07-01T16:06:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/978\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/978\\/conversions\\/image-preview.jpg\"},{\"id\":979,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":348,\"uuid\":\"3b0aac0f-da6a-4c49-9cc0-dc404366918b\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":78137,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":6,\"created_at\":\"2024-07-01T15:59:03.000000Z\",\"updated_at\":\"2024-07-01T16:06:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/979\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/979\\/conversions\\/image-pre