INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (996,'audit:created',380,'App\\Models\\Contract#380',3,'{\"title\":\"2024CADB_PHARE_Community Organizing and Tenant Advocacy\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>To support one on one tenant advocacy and education as well and landlord tenant mediation prior to eviction filings.<\\/p><ul><li>See attached budget<\\/li><li>See attached contract<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>30% of the grant must be used to benefit households below 50% AMI<\\/li><li>No portion of the grant funds are to be used to benefit households above 200% AMI<\\/li><li>Contract expires 18 months post full execution date (TBD)<\\/li><\\/ul>\",\"funder_id\":\"176\",\"amount\":\"150000\",\"start_date\":\"2024-09-11\",\"end_date\":null,\"notes\":\"<ul><li><strong>Fiscal Requirement: <\\/strong>The funds are to be placed in a separate interest-bearing account. Interest to be used for project purposes.<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>Reports must be submitted 30 days from the end of each semi-annual period. Information to include itemized grant expenditures, HH income, geographic and demographic data, etc.<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>Maintain all records related to this grant for a minimum of 4 years post agreement termination.<\\/li><\\/ul>\",\"grant_code\":null,\"updated_at\":\"2024-09-11 11:25:32\",\"created_at\":\"2024-09-11 11:25:32\",\"id\":380,\"documents\":[],\"media\":[]}','10.55.0.204','2024-09-11 15:25:32','2024-09-11 15:25:32');
