INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1052,'audit:created',384,'App\\Models\\Contract#384',45,'{\"title\":\"2024-2025SHFB_WayneCDBG\",\"contract_number\":null,\"cfda_number\":\"14.218\",\"purpose\":\"<p><strong>Purpose:<\\/strong> Wayne County has awarded SHFB a CDBG grant for $39,993.00 for the purchase of fresh food for Wayne County. This is a <strong>reimbursable grant<\\/strong> with the grant period running from May 9,2024 - August 31, 2025. Food will be distributed to partner agencies serving Wayne County.<\\/p><p>Fresh food includes dairy, meat, eggs, fruits, and vegetables. Whenever possible, fresh food shall be procured from farmers located in Pike County.<\\/p><p>Food pantries serviced with CDBG funds must prepare and submit a letter on letterhead stating they will collect a Self Declaration of Need form from each individual served and that no food or non-food items purchased through this grant will be distributed to individuals who have not completed a Self Declaration of need form or who are deemed ineligible due to income. A template for this letter can be found in Exhibit B of the contract attached.<\\/p><p><strong>Reports <\\/strong>are due bi-monthly, according to the chart below. Completed reports should be sent to Katie Blake at Hailstone Economic, LLC which administers the CDBG funds: kblake@hailstoneeconomic.com<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1159\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1160\\/image.png\\\"><\\/figure>\",\"funder_id\":null,\"amount\":\"39993.00\",\"start_date\":\"2024-09-24\",\"end_date\":\"2025-08-21\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-09-24 13:32:02\",\"created_at\":\"2024-09-24 13:32:02\",\"id\":384,\"documents\":[],\"media\":[]}','10.55.4.176','2024-09-24 17:32:02','2024-09-24 17:32:02');
