INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1099,'audit:created',387,'App\\Models\\Contract#387',45,'{\"title\":\"2024-2025SHFB_NAP-CFP\",\"contract_number\":\"202406281426\",\"cfda_number\":null,\"purpose\":\"<p>SHFB has been awarded a Neighborhood Assistance Program (NAP) for Charitable Food Program (CFP) in an amount not to exceep the tax credit amount of $435,500.00. The new tax credit percentage for CFP is 65%.<\\/p><p>This is a $385,000 in-kind food donation contribution from UNFI and $50,000 in cash from M&amp;T Bank. The cash distribution will be made in a lump-sum by M&amp;T Bank before June 30, 2025.<\\/p><p>Qualified investment or contributions to the project identified in the SHFB application totaling a maximum of $670,000.00 shall be accepted from project donors between July 1, 2024 and June 30, 2025. All funds must be spent by September 30, 2025.<\\/p><p>The budget submitted for this project is attached. Note the below regarding budget and invoicing:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1172\\/image.png\\\"><\\/figure><p>A report is due at the end of the grant period. More information will be sent to the planner-SHFB@caclv.org email.<\\/p><p>Contact at PA DCED is:<\\/p><p><strong>Dawn Bear<\\/strong>, Administrative Assistant<br>PA Department of Community &amp; Economic Development<br>Center for Community Services<br>Commonwealth Keystone Building<br>400 North Street, 4th Floor | Harrisburg, PA 17120-0225<br>Phone: 717-307-2782<br><a href=\\\"mailto:dabear@pa.gov\\\">dabear@pa.gov<\\/a><\\/p><p>Contact at M&amp;T Bank is:<\\/p><p><strong>Deanna L. Wells<\\/strong>, CRA Officer<br>213 Market Street, Harrisburg, PA 17101<br>717-241-8143<strong>&nbsp;<\\/strong><br><a href=\\\"mailto:dwells@mtb.com\\\">dwells@mtb.com<\\/a><br>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-10-01 11:59:10\",\"created_at\":\"2024-10-01 11:59:10\",\"id\":387,\"documents\":[],\"media\":[]}','10.55.4.176','2024-10-01 15:59:10','2024-10-01 15:59:10');
