INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1104,'audit:created',388,'App\\Models\\Contract#388',3,'{\"title\":\"2024CAH_LC CDBG CV_ Urgent Need Roof HVAC\",\"contract_number\":null,\"cfda_number\":\"14.218\",\"purpose\":\"<p>COVID money to provide new roof and\\/ or HVAC unit to approximately 10 properties.<\\/p><p><strong>Compliance Qualifications:<\\/strong><\\/p><ul><li>Each applicant must certify financial hardship due to COVID.&nbsp;<ul><li>Being elderly makes someone vulnerable to COVID and therefore they qualify. Still have them self-certify.<\\/li><\\/ul><\\/li><li>LMI Qualify all applicants<\\/li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.<\\/li><li>Environmental Review to be conducted and submitted to Lehigh County for review prior to beginning work on any home.<\\/li><li>&nbsp;<\\/li><\\/ul>\",\"funder_id\":\"145\",\"amount\":\"250000\",\"start_date\":\"2021-05-01\",\"end_date\":\"2025-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-10-03 12:55:31\",\"created_at\":\"2024-10-03 12:55:31\",\"id\":388,\"documents\":[],\"media\":[]}','10.55.0.204','2024-10-03 16:55:31','2024-10-03 16:55:31');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1105,'audit:updated',388,'App\\Models\\Contract#388',3,'{\"purpose\":\"<p>COVID money to provide new roof and\\/ or HVAC unit to approximately 10 properties.<\\/p><p><strong>Compliance Requirements:<\\/strong><\\/p><ul><li>Each applicant must certify financial hardship due to COVID.<ul><li>Being elderly makes someone vulnerable to COVID and therefore they qualify. They still must self-certify.<\\/li><\\/ul><\\/li><li>LMI Qualify all applicants and adult family members<\\/li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.<\\/li><li>Environmental Review to be conducted and submitted to Lehigh County for review and approval prior to beginning work on any home.&nbsp;<ul><li>Environmental Review paperwork is attached<\\/li><\\/ul><\\/li><li>Follow 3 bid procurement process with proper documentation<\\/li><li>A lien must be filed on each property (five-year self-forgiving lien based on the job cost, with forgiveness of 20% per year)<\\/li><li>Follow HUD Lead Based Paint Regulations<\\/li><li>Follow Historic Preservation requirements<\\/li><li>Contractors must produce COIs naming CALV and Lehigh County as additionally insured.&nbsp;<\\/li><li>Best effort to provide bidding opportunity to Women and Minority Owned Business (W\\/MBE)<\\/li><\\/ul>\",\"notes\":\"<p><strong>Reimbursement Process -<\\/strong>please read page 4 of the contract subsection I for full details.&nbsp;<\\/p><ul><li>Exhibit B- Reporting and Invoicing Deadlines is attached.&nbsp;<\\/li><\\/ul><p><strong>Reporting:<\\/strong><\\/p><ul><li>Required Quarterly and Annual report to be submitted to lauriemoyer@lehighcounty.org&nbsp;<ul><li>Reporting forms are attached.<\\/li><\\/ul><\\/li><\\/ul>\",\"updated_at\":\"2024-10-03 13:52:33\",\"id\":388,\"documents\":[],\"media\":[]}','10.55.0.204','2024-10-03 17:52:33','2024-10-03 17:52:33');
