INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1142,'audit:created',391,'App\\Models\\Contract#391',3,'{\"title\":\"2024CAH_Keystone Savings Foundation\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>Overall funding to support the&nbsp;Housing Rehabilitation Program (HRP). The fund serves as a gap funding to cover the construction cost (partial or full cost) to assist low-income families living in Lehigh and Northampton counties, and HRP program administration. The fund does not have specific number of households to be assisted, but rather to support HRP to achieve the FY24\\/25 annual goals of 40 families from the work plan<\\/p><ul><li>Total number of low-income assisted in FY24\\/25<\\/li><li>A story of low-income families receiving our help (preferred but optional<\\/li><\\/ul><p><strong>Budget: <\\/strong>$6,400 construction cost and $1,600 CAH staff salaries<\\/p>\",\"funder_id\":null,\"amount\":\"8000\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":\"<ul><li>Provide Annual report to funder.<\\/li><li>There is no reporting requirement for this grant.<\\/li><\\/ul>\",\"grant_code\":null,\"updated_at\":\"2024-10-18 09:58:54\",\"created_at\":\"2024-10-18 09:58:54\",\"id\":391,\"documents\":[],\"media\":[]}','10.55.0.204','2024-10-18 13:58:54','2024-10-18 13:58:54');
