_name\":\"documents\",\"name\":\"66981f5c19a93_2024SHFB_Pocono Mountain United Way_executed\",\"file_name\":\"66981f5c19a93_2024SHFB_Pocono-Mountain-United-Way_executed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":335878,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-17T19:48:19.000000Z\",\"updated_at\":\"2024-07-17T19:48:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1028\\/66981f5c19a93_2024SHFB_Pocono-Mountain-United-Way_executed.pdf\",\"preview_url\":\"\"},{\"id\":1029,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":360,\"uuid\":\"bdbfe0ec-ab5a-43a5-ac3e-f089cd7a524b\",\"collection_name\":\"documents\",\"name\":\"66981f5c1b496_2024_SHFB_PMUW_ProposalSubmitted\",\"file_name\":\"66981f5c1b496_2024_SHFB_PMUW_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":278908,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-07-17T19:48:19.000000Z\",\"updated_at\":\"2024-07-17T19:48:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1029\\/66981f5c1b496_2024_SHFB_PMUW_ProposalSubmitted.pdf\",\"preview_url\":\"\"},{\"id\":1030,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":360,\"uuid\":\"1d17e872-bb03-48c0-be52-0dfc859d7f79\",\"collection_name\":\"documents\",\"name\":\"66981f5c2a477_PMUW 2024 Proposal Narrative\",\"file_name\":\"66981f5c2a477_PMUW-2024-Proposal-Narrative.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":410038,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":3,\"created_at\":\"2024-07-17T19:48:19.000000Z\",\"updated_at\":\"2024-07-17T19:48:19.000000Z\",\"original_url\":\"http: