INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1146,'audit:updated',233,'App\\Models\\Contract#233',45,'{\"purpose\":\"<p>The purpose of this grant is to increase the sale of specialty crops through Farmers Market Nutrition Program (FMNP) checks distribution and redemption in Lehigh and Northampton Counties.<\\/p><p>This grant runs from 9\\/30\\/2022 - 6\\/30\\/2025. This is a <strong>reimbursable <\\/strong>grant. Grant is not to exceed $50,478.00.&nbsp;<\\/p><p>Information on reporting is pasted below. <strong>Final report is due by July 30, 2025<\\/strong>.<\\/p><p>SHFB has committed to helping increase redemption of FMNP checks by 10% over 2021 levels.<\\/p><p>SHFB will implement outreach initiatives including printed materials, event attendance, pop-up markets, and an online information portal. Specific activity details are available in the 2022 SCBGP State approved plan, linked below.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/444\\/image.png\\\"><\\/figure><p>The budget for this grant is as follows:<\\/p><p>Personnel: <strong>$32,760<\\/strong> (Salary for Local Food Sourcing Coordinator and Operations Manager)<br>Fringe: <strong>$3,486<\\/strong><br>Supplies: <strong>$9,993<\\/strong><br>Contractual: <strong>$500<\\/strong><br>Indirect: <strong>$3,739<\\/strong><br><strong>TOTAL: $50,478.00<\\/strong><br>&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-10-22 08:35:19\",\"id\":233,\"documents\":[{\"id\":445,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"a2a58f10-4a3f-4375-a7a0-65292a901070\",\"collection_name\":\"documents\",\"name\":\"651d9a148c927_Performance Report_Annual_Template\",\"file_name\":\"651d9a148c927_Performance-Report_Annual_Template.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":35879,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-10-04T17:02:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/445\\/651d9a148c927_Performance-Report_Annual_Template.docx\",\"preview_url\":\"\"},{\"id\":446,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"f003a913-f6d5-4279-b2c6-ee8ea719112a\",\"collection_name\":\"documents\",\"name\":\"651d9a150b457_2022 SCBGP State approved plan\",\"file_name\":\"651d9a150b457_2022-SCBGP-State-approved-plan.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":422590,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2023-10-04T17:02:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/446\\/651d9a150b457_2022-SCBGP-State-approved-plan.pdf\",\"preview_url\":\"\"},{\"id\":447,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"800c4c60-fa87-447b-bfe3-2c711575c3ed\",\"collection_name\":\"documents\",\"name\":\"651d9a15121e2_Spec Crop Grant Contract\",\"file_name\":\"651d9a15121e2_Spec-Crop-Grant-Contract.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1762113,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":3,\"created_at\":\"2023-10-04T17:02:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/447\\/651d9a15121e2_Spec-Crop-Grant-Contract.pdf\",\"preview_url\":\"\"},{\"id\":448,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"5fafb369-c8a7-4387-a59c-ee4fc39891eb\",\"collection_name\":\"documents\",\"name\":\"651d9a15199db_USDA_SCBGPPerformanceMeasures_Update11.2021\",\"file_name\":\"651d9a15199db_USDA_SCBGPPerformanceMeasures_Update11.2021.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":154162,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":4,\"created_at\":\"2023-10-04T17:02:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/448\\/651d9a15199db_USDA_SCBGPPerformanceMeasures_Update11.2021.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":444,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"f9d4e678-1af8-4856-86ca-00528ff12bb0\",\"collection_name\":\"ck-media\",\"name\":\"image\",\"file_name\":\"image.png\",\"mime_type\":\"image\\/png\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":131284,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-10-04T16:58:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/444\\/image.png\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/444\\/conversions\\/image-preview.jpg\"},{\"id\":445,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":233,\"uuid\":\"a2a58f10-4a3f-4375-a7a0-65292a901070\",\"collection_name\":\"documents\",\"name\":\"651d9a148c927_Performance Report_Annual_Template\",\"file_name\":\"651d9a148c927_Performance-Report_Annual_Template.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":35879,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-10-04T17:02:15.000000Z\",\"updated_at\":\"2023-10-04T17:02:15.000000Z\",\"original_url\":\"http:\\/\\/