INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1150,'audit:created',393,'App\\Models\\Contract#393',45,'{\"title\":\"2025SHFB_FeedingPA_ServiceInsightsSupport\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This is a $75,000 lump sum grant made available by Feeding PA to support the implementation of Service Insights to partner agencies.&nbsp;<\\/p><p>Goals:<\\/p><ul><li>Support personnel costs who will dedicate 1\\/4 of their time to the electronic data collection initiative<\\/li><li>Meet the technology needs of onboard partner agencies, including but not limited to the purchase of technology or technology incentives to support technology needs. Exact discretion of usage of funds is left to SHFB.<\\/li><li>Provide one analysis using the data from onboarded sites demonstrating the impact of Service Insights. The anticipated completion dates for these analyses are between June 1, 2025 and June 30, 2025.<\\/li><\\/ul><p>As a condition of this grant, appropriate personnel must participate in the Data Project Taskforce calls hosted by FeedingPA and submit two brief reports summary the progress of implementation. The reports are due January 1, 2025 and June 30, 2025.<\\/p><p>Grant period is July 1, 2024 - June 30, 2025.&nbsp;<\\/p><p>Questions regarding this grant should be directed to Shea Saman, Chief Financial Officer, at <a href=\\\"mailto:ssaman@feedingpa.org\\\">ssaman@feedingpa.org<\\/a>.<\\/p>\",\"funder_id\":\"165\",\"amount\":\"75000.00\",\"start_date\":\"2024-07-01\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-10-23 13:42:01\",\"created_at\":\"2024-10-23 13:42:01\",\"id\":393,\"documents\":[],\"media\":[]}','172.16.100.57','2024-10-23 17:42:01','2024-10-23 17:42:01');
