INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1160,'audit:updated',348,'App\\Models\\Contract#348',3,'{\"purpose\":\"<p><strong>Grant Purpose:<\\/strong> To assist 10 homeowners in Lehigh and Northampton counties to improve their homes living conditions, health and safety. &nbsp;<\\/p><ol><li>See eligible improvements attached<\\/li><li>See contract attached<\\/li><li>See Budget attached<\\/li><li>Grant Modification attached below -<strong>$50,000 to be used to modify 10 rental properties.<\\/strong><\\/li><\\/ol><ul><li>30% of the grant must be used to benefit households below 50% AMI<\\/li><li>No portion of the grant funds are to be used to benefit households above 200% AMI<\\/li><li>Contract expires 18 months post full execution date<\\/li><li><strong>Read<\\/strong> Page 9, part C. Grantee responsibilities for provisions that need to carry over into subcontractor contracts<\\/li><li>Debarment searches required for all subcontractors<\\/li><li><strong>Read <\\/strong>page 17, Article XXIII Workers Protection and Investment for all applicable acts and laws such as PA Prevailing Wage requirements<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2024-10-24 14:05:55\",\"id\":348,\"documents\":[{\"id\":983,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":348,\"uuid\":\"2e7a5dec-5da3-4c41-97b3-4adbe76fb5f7\",\"collection_name\":\"documents\",\"name\":\"6682d21f29009_RE_ PHARE Award - Retroactive expenses\",\"file_name\":\"6682d21f29009_RE_-PHARE-Award---Retroactive-expenses.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":296071,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-01T16:06:12.000000Z\",\"updated_at\":\"2024-07-01T16:06:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/983\\/6682d21f29009_