INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1169,'audit:updated',388,'App\\Models\\Contract#388',3,'{\"purpose\":\"<p>CDBG COVID money to provide new roof and\\/ or HVAC unit to approximately 10 properties.<\\/p><p><strong>Compliance Requirements: <\\/strong>Pay attention to <strong>all Special Conditions<\\/strong> outlined in section VI. starting on page 3. Some of them are outlined below:<\\/p><ul><li>Each applicant must certify financial hardship due to COVID.<ul><li>Being elderly makes someone vulnerable to COVID and therefore they qualify. They still must self-certify.<\\/li><\\/ul><\\/li><li>LMI Qualify all applicants and adult family members<\\/li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.<\\/li><li>Environmental Review to be conducted and submitted to Lehigh County for review and approval prior to beginning work on any home.<ul><li>Environmental Review paperwork is attached<\\/li><\\/ul><\\/li><li>Follow 3 bid procurement process with proper documentation<\\/li><li>A lien must be filed on each property (five-year self-forgiving lien based on the job cost, with forgiveness of 20% per year)<\\/li><li>If the subrecipient receives income from the satisfaction of liens prior to the completion of the forgiveness period, the program income must be returned to Lehigh County.<\\/li><li>Follow HUD Lead Based Paint Regulations<\\/li><li>Follow Historic Preservation requirements<\\/li><li>Contractors must produce COIs naming CALV and Lehigh County as additionally insured.<\\/li><li>Best effort to provide bidding opportunity to Women and Minority Owned Business (W\\/MBE)<\\/li><li>Staff who have salary reimbursed trough this grant must keep detail on duties performed during working hour to justify hours billed<\\/li><\\/ul>\",\"notes\":\"<p><strong>Reimbursement Process -<\\/strong>please read page 4 of the contract subsection I for full details.&nbsp;<\\/p><ul><li>Reporting and Invoicing Deadlines are attached.<\\/li><\\/ul><p><strong>Reporting:<\\/strong><\\/p><ul><li>Required Quarterly and Annual reports to be submitted to cyndiking@lehighcounty.org<ul><li>Reporting forms are attached.<\\/li><\\/ul><\\/li><\\/ul>\",\"updated_at\":\"2024-10-29 12:58:29\",\"id\":388,\"documents\":[{\"id\":1181,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":388,\"uuid\":\"fc6f10a0-b97d-4767-8120-d55c14e92cf3\",\"collection_name\":\"documents\",\"name\":\"66fee303202b8_Tier 2 Site-Specific Review Strategy and Checklist - Lehigh Co - CV-Urgent Rehab - FINAL (1)\",\"file_name\":\"66fee303202b8_Tier-2-Site-Specific-Review-Strategy-and-Checklist---Lehigh-Co---CV-Urgent-Rehab---FINAL-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":360867,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-10-03T18:52:33.000000Z\",\"updated_at\":\"2024-10-03T18:52:33.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1181\\/66fee303202b8_Tier-2-Site-Specific-Review-Strategy-and-Checklist---Lehigh-Co---CV-Urgent-Rehab---FINAL-(1).pdf\",\"preview_url\":\"\"},{\"id\":1182,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":388,\"uuid\":\"05b2c7af-d85e-4b99-b7f8-557424e4a9bb\",\"collection_name\":\"documents\",\"name\":\"66fee307c6cca_Tier 2 Site-Specific Review Strategy and Checklist - Lehigh Co - CV-Urgent Rehab - FINAL (1)\",\"file_name\":\"66fee307c6cca_Tier-2-Site-Specific-Review-Strategy-and-Checklist---Lehigh-Co---CV-Urgent-Rehab---FINAL-(1).docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":76356,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_imag