INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1178,'audit:updated',394,'App\\Models\\Contract#394',3,'{\"notes\":\"<p><strong>Name and Logo Usage:<\\/strong> Grant recipients are <strong>required<\\/strong> to acknowledge the Bank\\u2019s philanthropic support in online or printed materials in accordance with the guidelines below and the terms of the Grant Agreement.<\\/p><p>Santander Bank, N.A. is the legal name and may be used to reference the Bank in the absence of a trademark consent letter. The use of \\u201cSantander Bank Foundation\\u201d is not permitted.<\\/p><p>Linking Registered Trademarks to Website. With written permission, our name or logo may link directly to the Santander Bank, N. A. website in online materials: <a href=\\\"https:\\/\\/www.santanderbank.com\\/\\\">https:\\/\\/www.santanderbank.com<\\/a><\\/p><p>Official Social Media Accounts. Tagging on social media is permitted using our handles on the following sites:<\\/p><ul><li>Instagram \\u2013 santanderbankus<\\/li><li>LinkedIn \\u2013 Santander Bank, N.A.<\\/li><li>Facebook \\u2013 Santander Bank US<\\/li><\\/ul><p><br>Questions and requests for permission to use trademarks, or for quotes and other media resources should be directed to the Philanthropy Team at <a href=\\\"mailto:giving@santander.us\\\">giving@santander.us<\\/a>.<\\/p>\",\"updated_at\":\"2024-11-12 08:48:34\",\"id\":394,\"documents\":[{\"id\":1248,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":394,\"uuid\":\"2bf22f58-c5fc-40b4-9e42-178963053088\",\"collection_name\":\"documents\",\"name\":\"67335b2d9ae01_2024RTCLF Santander Grant Agreement (1)\",\"file_name\":\"67335b2d9ae01_2024RTCLF-Santander-Grant-Agreement-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":356163,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":