INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1180,'audit:created',395,'App\\Models\\Contract#395',3,'{\"title\":\"2024SSS_ Kiwanis\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>To purchase fire blankets for the Shelter.<\\/p><p><strong>To receive funds<\\/strong>: Annual Foundation Grant Awards Luncheon, to be held on Thursday, December 12, 2024 from 12:00 PM to 1:30 PM at the Shanty on 19th restaurant in Allentown. A representative from the Shelter will attend to be presented with the grant check and offer brief remarks on how the funds will be used to serve the community.&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Report<\\/strong> due by October 1st, 2025.&nbsp;<\\/p>\",\"funder_id\":\"179\",\"amount\":\"1000\",\"start_date\":\"2024-12-12\",\"end_date\":null,\"notes\":null,\"grant_code\":\"8000\",\"updated_at\":\"2024-11-12 09:41:35\",\"created_at\":\"2024-11-12 09:41:35\",\"id\":395,\"documents\":[],\"media\":[]}','10.55.0.204','2024-11-12 14:41:35','2024-11-12 14:41:35');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1181,'audit:created',396,'App\\Models\\Contract#396',3,'{\"title\":\"2024CADB_ City of Bethlehem CDBG_ Tenant Advocacy\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-Personnel Costs for the Tenant Advocate.&nbsp;<\\/p><ul><li>Tenant advocate to conduct tenant advocacy, LL\\/Tenant mediations, Program Coordination, and Tenant Education and Empowerment. See detailed Scope of Activity (Exhibit A-on page 19 of the contract).<\\/li><li>Goals and Performance (see page 20 of the contract) specifies what to track and keep record of.&nbsp;<\\/li><li>&nbsp;Specified qualifications for tenant advocate to include obtaining HUD certification (see Exhibit A-1- on page 21 of the contract).<\\/li><\\/ul><p><strong>Grantee Recognition:<\\/strong> Must include reference to the support provided from the City of Bethlehem CDBG in all the publications made possible with funds made available under this agreement.<\\/p><p><strong>Record Retention:<\\/strong> Hold all records until HUD formally closes the program year with the City of Bethlehem.<\\/p><p><strong>Client Data to collect: <\\/strong>Demonstrate client eligibility for services provided. Collect name, address, income level and household size data and description of services provided.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1253\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":\"171\",\"amount\":\"50000\",\"start_date\":\"2024-01-01\",\"end_date\":\"2024-12-31\",\"notes\":\"<ul><li>Quarterly program income reports to be sent to the City of Bethlehem<\\/li><\\/ul><p>&nbsp;<\\/p><ul><li>Request for Reimbursement Instruction:<\\/li><\\/ul><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1252\\/image.png\\\"><\\/figure>\",\"grant_code\":null,\"updated_at\":\"2024-11-12 10:11:07\",\"