INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1184,'audit:updated',396,'App\\Models\\Contract#396',3,'{\"purpose\":\"<p>-Personnel Costs for the Tenant Advocate.&nbsp;<\\/p><ul><li>Tenant advocate to conduct tenant advocacy, LL\\/Tenant mediations, Program Coordination, and Tenant Education and Empowerment. See detailed Scope of Activity (Exhibit A-on page 19 of the contract).<\\/li><li>Goals and Performance (see page 20 of the contract) specifies what to track and keep record of.<\\/li><li>Specified qualifications for tenant advocate to include obtaining HUD certification (see Exhibit A-1- on page 21 of the contract).<\\/li><\\/ul><p><strong>Grantee Recognition:<\\/strong> Must include reference to the support provided from the City of Bethlehem CDBG in all the publications made possible with funds made available under this agreement.<\\/p><p><strong>Record Retention:<\\/strong> Hold all records until HUD formally closes the program year with the City of Bethlehem.<\\/p><p><strong>Client Data to collect: <\\/strong>Demonstrate client eligibility for services provided. Collect name, address, income level and household size data and description of services provided.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1253\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"notes\":\"<p>&nbsp;<\\/p><ul><li>Request for Reimbursement Instruction:<\\/li><\\/ul><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1252\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2024-11-12 14:10:51\",\"id\":396,\"documents\":[{\"id\":1254,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":396,\"uuid\":\"8c0c3e73-a547-49d5-962a-149904f0a67e\",\"collection_name\":\"documents\",\"name\":\"67336ae879b24_2024CADB_ Bethlehem CDBG_ Tenant Advocacy\",\"file_name\":\"67336ae879b24_2024CADB_-Bethlehem-CDBG_-Tenant-Advocacy.pdf\",\"m