INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1186,'audit:created',397,'App\\Models\\Contract#397',45,'{\"title\":\"2025SHFB_MARC Membership Agreement\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This agreement is between the Mid-Atlantic Regional Cooperative (MARC), a program of Feeding PA, and SHFB. The document outlines the responsibilities and expectations of both parties. <i>This agreement shall continue until terminated by either party.<\\/i><\\/p><p>As a member, SHFB commits to the following:<\\/p><ul><li>Commitment to a minimum of a bi-annual ordering schedule.<\\/li><li>Commitment to providing a signed copy of the Bill-of-Lading and Receiving Report to the MARC for all received loads upon request.<\\/li><li>Commitment to a timely response to all MARC product inquiry communications.<\\/li><li>Commitment to a net 30-day timely payment of all invoices.<\\/li><li>Provide a single point of contact that can be immediately contacted by the MARC should the need arise.<\\/li><li>Provide an annual update of current contacts for the food bank.<\\/li><\\/ul><p>An authorized representative from SHFB is required to serve as the primary point of contact for matters related to compliance with the Membership Agreement and represent SHFB in any votes or surveys regarding membership matters. The authorized representative is required to ensure that the member food bank meets all program and policy requirements, including:<\\/p><ul><li>Maintain confidentiality of information garnered through participation in MARC programs and not to share information or use it to the detriment of MARC of any of its members.<\\/li><li>Attend and participate in all required meetings.<\\/li><li>Meet program participation agreements and program standards, including timely submittal of data.<\\/li><\\/ul><p>Additional stipulations and requirements are available in the Member Agreement below.<\\/p><p>The Schedule of Fees is available in the Agreement document and is outlined below:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1260\\/image.png\\\"><\\/figure>\",\"funder_id\":\"165\",\"amount\":\"0.00\",\"start_date\":\"2024-11-01\",\"end_date\":null,\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-11-14 13:45:18\",\"created_at\":\"2024-11-14 13:45:18\",\"id\":397,\"documents\":[],\"media\":[]}','10.55.4.152','2024-11-14 18:45:18','2024-11-14 18:45:18');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1187,'audit:updated',352,'App\\Models\\Contract#352',45,'{\"purpose\":\"<p>The purpose of this $8,000 award is to support Child Nutrition programs. Costs will be split between product purchasing and administrative costs.<\\/p><p>There is one report due on Jan 14, 2025. A template will be provided to the planner-SHFB@caclv.org email address.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1265\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2024-11-18 14:56:26\",\"id\":352,\"documents\":[{\"id\":998,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":352,\"uuid\":\"32361616-ab73-4375-8c16-57319977f219\",\"collection_name\":\"documents\",\"name\":\"6685681d8780c_Sheetz FY24-25 Application\",\"file_name\":\"6685681d8780c_Sheetz-FY24-25-Application.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":181228,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-07-03T15:05:14.000000Z\",\"updated_at\":\"2024-07-03T15:05:14.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/998\\/6685681d8780c_Sheetz-FY24-25-Application.pdf\",\"preview_url\":\"\"},{\"id\":999,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":352,\"uuid\":\"a4b21774-b981-49ea-8d19-b02e4ef9e138\",\"collection_name\":\"documents\",\"name\":\"6685684784498_FY24_Sheetz_For_the_Kidz_Child_Hunger_Grant_Agreement\",\"file_name\":\"6685684784498_FY24_Sheetz_For_the_Kidz_Child_Hunger_Grant_Agreement.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":44059,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"c