INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1204,'audit:created',404,'App\\Models\\Contract#404',3,'{\"title\":\"2024CAH_City of Bethlehem PHARE_ Alley House\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-To construct an affordable housing unit located at 1604 W Broad Street, Bethlehem, PA<\\/p><p><strong>-Reimbursable Grant:<\\/strong><\\/p><ul><li>Section 5, page 3<strong> Disbursement of Subaward Funds, <\\/strong>including financial reports to be submitted by e-mail to Sara Satullo at ssatullo@bethlehem-pa.gov for reimbursement. Requests for reimbursement every 30 calendar days.<\\/li><li>Program Budget is the last three pages of the uploaded contract<\\/li><li>20% markup of construction costs will cover CALV staff salary as previously agreed upon with the City. Email uploaded here.<\\/li><\\/ul><p><strong>Other Provisions of Importance:<\\/strong><\\/p><ul><li>Contractors COIs must name \\\"The City of Bethlehem\\\" and \\\" Community Action Lehigh Valley\\\" with coverages shown on page 5 section 13 of the contract.<\\/li><li>Contractor Contracts must include the section 16 Subrecipient Integrity Provisions on pages 6-9 of the contract.<\\/li><li>Contractor Contracts must include section 18 Nondiscrimination and Sexual Harassment provision on pages 10-12 of the contract.<\\/li><li>Follow formal Bidding procedures<\\/li><li>PA Prevailing wage requirement over $24,999<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"funder_id\":\"171\",\"amount\":\"372447.05\",\"start_date\":\"2024-12-04\",\"end_date\":null,\"notes\":null,\"grant_code\":null,\"updated_at\":\"2024-12-04 10:58:49\",\"created_at\":\"2024-12-04 10:58:49\",\"id\":404,\"documents\":[],\"media\":[]}','10.55.0.204','2024-12-04 15:58:49','2024-12-04 15:58:49');
