INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1206,'audit:created',405,'App\\Models\\Contract#405',3,'{\"title\":\"2024CAH_LC CDBG_ Urgent Need Roof HVAC\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>-Rehabilitation of 18 properties providing new roof and or HVAC system. &nbsp;Also, modifications to homes of homeowners who wish to age in place.<\\/p><ul><li>LMI Qualify all applicants and adult family members<\\/li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.<\\/li><li>Environmental Review to be conducted and submitted to Lehigh County for review and approval prior to beginning work on any home.<ul><li>Environmental Review paperwork is attached<\\/li><\\/ul><\\/li><li>Follow 3 bid procurement process with proper documentation<\\/li><li>A lien must be filed on each property (five-year self-forgiving lien based on the job cost, with forgiveness of 20% per year)<\\/li><li>If the subrecipient receives income from the satisfaction of liens prior to the completion of the forgiveness period, the program income must be returned to Lehigh County.<\\/li><li>Follow HUD Lead Based Paint Regulations<\\/li><li>Follow Historic Preservation requirements<\\/li><li>Contractors must produce COIs naming CALV and Lehigh County as additionally insured.<\\/li><li>Best effort to provide bidding opportunity to Women and Minority Owned Business (W\\/MBE)<\\/li><li>Staff who have salary reimbursed trough this grant must keep detail on duties performed during working hour to justify hours billed<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"funder_id\":\"145\",\"amount\":\"341371.04\",\"start_date\":\"2025-01-01\",\"end_date\":\"2026-09-30\",\"notes\":\"<p><strong>Reimbursement Requests:&nbsp;<\\/strong><\\/p><ul><li>Documents listed on page 4-5 subsection n. must be included in reimbursement 