INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1234,'audit:updated',272,'App\\Models\\Contract#272',45,'{\"purpose\":\"<p>SHFB has been awarded a $100,000.00 grant from the AllOne Foundation to increase access to nutritious foods for the people of Carbon, Monroe, Pike, and Wayne Counties.<\\/p><p>Grant period starts Dec 18, 2023 and ends Dec 17, 2024.<\\/p><p>A full and complete narrative and financial report to the Foundation at the mid-project date as stated in the proposal as well as 30 days following the conclusion of the grant period. Information on submitting the report will be emailed to planner-SHFB@caclv.org.<\\/p><p>Proposed budget is below:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1305\\/image.png\\\" alt=\\\"\\\"><\\/figure>\",\"updated_at\":\"2024-12-17 11:10:53\",\"id\":272,\"documents\":[{\"id\":590,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":272,\"uuid\":\"7211a295-87c7-45c4-96f6-fd94c82661e2\",\"collection_name\":\"documents\",\"name\":\"658ec5fa4cf68_AOF Agreement Template Second Harvest Food Bank 11-21-23\",\"file_name\":\"658ec5fa4cf68_AOF-Agreement-Template-Second-Harvest-Food-Bank-11-21-23.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":207741,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-29T13:15:12.000000Z\",\"updated_at\":\"2023-12-29T13:15:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/590\\/658ec5fa4cf68_AOF-Agreement-Template-Second-Harvest-Food-Bank-11-21-23.pdf\",\"preview_url\":\"\"},{\"id\":591,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":272,\"uuid\":\"2858ea06-ac6e-4519-b270-20274330d5e9\",\"collection_name\":\"documents\",\"name\":\"658ec6567fa77_AllOneFoundation 2024 proposal\",\"file_name\":\"658ec6