INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1270,'audit:created',420,'App\\Models\\Contract#420',45,'{\"title\":\"2025SHFB_C&S Wholesale Grocers Child and Family Feeding\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This is a $10,000 lump sum grant to support the start-up, sustainment, or expansion of Child and Family Feeding Programs.<\\/p><p>Funds can be used to support the costs <strong>directly associated<\\/strong> with this program:<\\/p><ul><li>Staff salary &amp; benefits<\\/li><li>Food<\\/li><li>Equipment<\\/li><li>Supplies<\\/li><li>Outreach<\\/li><li>Training<\\/li><li>Cost-share for home delivery services<\\/li><li>Program evaluation<\\/li><li>SNAP outreach and\\/or application assistance targeted toward families with children<\\/li><li>Educational activities to engage policy &amp; decision-makers, with the goal of improving child nutrition programs and ultimately reaching more children and their families.<\\/li><\\/ul><p><strong>Reporting Requirements<\\/strong><\\/p><p>There will be one (1) final report required for this grant, due August 26, 2025 and covering entire grant period, 2\\/1\\/25-7\\/31\\/25 <i>(6 months)<\\/i><\\/p><p>Report requirements include but are not limited to:<\\/p><ul><li>Grant impact and program description<\\/li><li>Confirmation of funds expenditure<\\/li><li>Metrics<\\/li><li># meals and\\/or pounds distributed<\\/li><li># of children served (unduplicated)<\\/li><li># of households served (unduplicated)<\\/li><li># of program\\/distribution sites<\\/li><li>Successes and challenges<\\/li><li>Stories, photos, and testimonials<\\/li><li>Media and communications<\\/li><li>Donor engagement<\\/li><\\/ul><p><strong>Publicity Requirements<\\/strong><\\/p><p>As a grant recipient, your food bank is encouraged to recognize the donor for this grant award throughout the grant period using social media and online platforms to help promote the partnership and create community visibility of this grant award.<\\/p><p>While reports are an important method\\u202fused to foster donor relations, they are no substitute for hearing directly from you. \\u202fWe encourage you to email a thank-you letter to the following:&nbsp;<\\/p><p><strong>Kate Cote<\\/strong>&nbsp;<br><i>C&amp;S Wholesale Grocers<\\/i>&nbsp;<br>c\\/o Brandon Sampson<br><i>Feeding America Corporate Partnerships Team<\\/i>&nbsp;<br><a href=\\\"mailto:bsampson@feedingamerica.org\\\">bsampson@feedingamerica.org<\\/a>&nbsp;<\\/p><p>Questions related to Feeding America\\u2019s relationship with the donor, please contact Brandon Sampson, <i>Manager, Corporate Partnerships<\\/i>, at&nbsp;<a href=\\\"mailto:bsampson@feedingamerica.org\\\">bsampson@feedingamerica.org.<\\/a><\\/p><p>Technical GMS questions related to proposal or report submission, please contact Sally Yan, <i>Sr. Manager, Member Grants<\\/i>, at&nbsp;<a href=\\\"mailto:syan@feedingamerica.org\\\">syan@feedingamerica.org<\\/a>&nbsp;&nbsp;<\\/p>\",\"funder_id\":\"211\",\"amount\":\"10000.00\",\"start_date\":\"2025-02-01\",\"end_date\":\"2025-07-31\",\"notes\":null,\"grant_code\":\"8095\",\"updated_at\":\"2025-01-16 11:00:30\",\"created_at\":\"2025-01-16 11:00:30\",\"id\":420,\"documents\":[],\"media\":[]}','10.55.4.138','2025-01-16 16:00:30','2025-01-16 16:00:30');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1271,'audit:updated',420,'App\\Models\\Contract#420',45,'{\"purpose\":\"<p>This is a $10,000 lump sum grant to support the start-up, sustainment, or expansion of Child and Family Feeding Programs.<\\/p><p>Funds can be used to support the costs <strong>directly associated<\\/strong> with this program:<\\/p><ul><li>Staff salary &amp; benefits<\\/li><li>Food<\\/li><li>Equipment<\\/li><li>Supplies<\\/li><li>Outreach<\\/li><li>Training<\\/li><li>Cost-share for home delivery services<\\/li><li>Program evaluation<\\/li><li>SNAP outreach and\\/or application assistance targeted toward families with children<\\/li><li>Educational activities to engage policy &amp; decision-makers, with the goal of improving child nutrition programs and ultimately reaching more children and their families.<\\/li><\\/ul><p><strong>Reporting Requirements<\\/strong><\\/p><p>There will be one (1) final report required for this grant, due <strong>August 26, 2025<\\/strong> and covering entire grant period, 2\\/1\\/25-7\\/31\\/25 <i>(6 months)<\\/i><\\/p><p>Report requirements include but are not limited to:<\\/p><ul><li>Grant impact and program description<\\/li><li>Confirmation of funds expenditure<\\/li><li>Metrics<\\/li><li># meals and\\/or pounds distributed<\\/li><li># of children served (unduplicated)<\\/li><li># of households served (unduplicated)<\\/li><li># of program\\/distribution sites<\\/li><li>Successes and challenges<\\/li><li>Stories, photos, and testimonials<\\/li><li>Media and communications<\\/li><li>Donor engagement<\\/li><\\/ul><p><strong>Publicity Requirements<\\/strong><\\/p><p>As a grant recipient, your food bank is encouraged to recognize the donor for this grant award throughout the grant period using social media and online platforms to help promote the partnership and create community visibility of this grant award.<\\/p><p>While reports are an important method\\u202fused to foster donor relations, they are no substitute for hearing directly from you. \\u202fWe encourage you to email a thank-you letter to the following:&nbsp;<\\/p><p><strong>Kate Cote<\\/strong>&nbsp;<br><i>C&amp;S Wholesale Grocers<\\/i>&nbsp;<br>c\\/o Brandon Sampson<br><i>Feeding America Corporate Partnerships Team<\\/i>&nbsp;<br><a href=\\\"mailto:bsampson@feedingamerica.org\\\">bsampson@feedingamerica.org<\\/a>&nbsp;<\\/p><p>Questions related to Feeding America\\u2019s relationship with the donor, please contact Brandon Sampson, <i>Manager, Corporate Partnerships<\\/i>, at&nbsp;<a href=\\\"mailto:bsampson@feedingamerica.org\\\">bsampson@feedingamerica.org.<\\/a><\\/p><p>Technical GMS questions related to proposal or report submission, please contact Sally Yan, <i>Sr. Manager, Member Grants<\\/i>, at&nbsp;<a href=\\\"mailto:syan@feedingamerica.org\\\">syan@feedingamerica.org<\\/a>&nbsp;&nbsp;<\\/p>\",\"updated_at\":\"2025-01-16 11:00:47\",\"id\":420,\"documents\":[{\"id\":1365,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":420,\"uuid\":\"d41d2c0b-3870-4d51-82c0-6c20b770e553\",\"collection_name\":\"documents\",\"name\":\"67892d0feeb57_Report Template_FY25 C&S Wholesale Grocers Child and Family\",\"file_name\":\"67892d0feeb57_Report-Template_FY25-C&S-Wholesale-Grocers-Child-and-Family.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":30157,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-01-16T16:00:30.000000Z\",\"updated_at\":\"2025-01-16T16:00:30.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1365\\/67892d0feeb57_Report-Template_FY25-C&S-Wholesale-Grocers-Child-and-Family.docx\",\"preview_url\":\"\"},{\"id\":1366,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":420,\"uuid\":\"b2baf5fa