INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1274,'audit:created',421,'App\\Models\\Contract#421',45,'{\"title\":\"2024-2025SHFB_NCTEFAP Agreement\",\"contract_number\":\"24-1066\",\"cfda_number\":\"10.225\",\"purpose\":\"<p>SHFB shall accept for storage, prepare for distribution, distribute via its network of affiliated food pantries, and account for food commodities made available to Northampton County residents via TEFAP. SHFB shall publicize availability of foods via public service announcements.&nbsp;<\\/p><p>This is a reimbursement grant. Billing and invoicing instructions are below. Reports must be submitted according to the schedule outlined below.&nbsp;<\\/p><p>&nbsp;<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1370\\/image.png\\\"><\\/figure>\",\"funder_id\":\"2\",\"amount\":\"0.00\",\"start_date\":\"2024-12-26\",\"end_date\":\"2025-09-30\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-01-16 14:22:55\",\"created_at\":\"2025-01-16 14:22:55\",\"id\":421,\"documents\":[],\"media\":[]}','10.55.4.138','2025-01-16 19:22:55','2025-01-16 19:22:55');
