INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1281,'audit:updated',160,'App\\Models\\Contract#160',3,'{\"notes\":\"<p>-Money must be fully obligated by December 31, 2024.<\\/p><p>-Funds must be kept in an interest-bearing account<\\/p><p>-PA Prevailing Wage -Prime construction contracts in excess of $24,999 must pay PA prevailing wage&nbsp;<\\/p><p>-Open and Competitive bidding procedures for any contract in excess of $10,000 (must have 3 arm length bids)<\\/p><p>&nbsp;<strong>-COVID Impact Eligibility Question<\\/strong><\\/p><p>*The project\\/client is presumed eligible if the household is a low- or moderate-income household as defined by the State and Local Fiscal Recovery fund guidance.&nbsp; Per SLFRF, Low- or moderate-income households and communities are those with (i) income at or below 300 percent of the Federal Poverty Guidelines for the size of the household based on the most recently published poverty guidelines or (ii) income at or below 65 percent of the area median income for the county and size of household based on the most recently published data. **For households whose income exceeds the federal definition as defined above but falls within the WHR requirement for an eligible homeowner (household income not to exceed 80% of the area median income), the Grantee should document the Covid impact (\\u201cimpacted or \\u201cdisproportionately impacted\\u201d) using the attached FRAMEWORK FOR ELIGIBLE USES BEYOND THOSE ENUMERATED found within the SLFRF Final Rule Overview.<\\/p><p>-All work needs to be done by a qualified contractor who is licensed and insured. Habitat for Humanity cannot use volunteers who do not meet this criterion.<\\/p><p>&nbsp;<\\/p><p><strong>***Update***<\\/strong><\\/p><p><strong>Program monitoring to take place in the Spring. A predetermined percentage of projects will be selected at random for review. Requested documents to include- project\\/ case files, invoices, proof of eligibility and photos.<\\/strong><\\/p>\",\"updated_at\":\"2025-01-22 15:29:39\",\"id\":160,\"documents\":[{\"id\":148,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":160,\"uuid\":\"a2f5e6ad-e51e-4f61-9ce7-4e24ad08f99a\",\"collection_name\":\"documents\",\"name\":\"642afc88a7163_SLFRF Final Rule Overview _ FRAMEWORK FOR ELIGIBLE USES BEYOND THOSE ENUMERATED (1)\",\"file_name\":\"642afc88a7163_SLFRF-Final-Rule-Overview-_-FRAMEWORK-FOR-ELIGIBLE-USES-BEYOND-THOSE-ENUMERATED-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":2121442,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-04-03T16:19:50.000000Z\",\"updated_at\":\"2023-04-03T16:19:50.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/148\\/642afc88a7163_SLFRF-Final-Rule-Overview-_-FRAMEWORK-FOR-ELIGIBLE-USES-BEYOND-THOSE-ENUMERATED-(1).pdf\",\"preview_url\":\"\"},{\"id\":149,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":160,\"uuid\":\"9a306298-d79c-429a-b932-c0f61451aebe\",\"collection_name\":\"documents\",\"name\":\"642afc943ec55_Whole-Home Repairs - Reporting Template\",\"file_name\":\"642afc943ec55_Whole-Home-Repairs---Reporting-Template.eml\",\"mime_type\":\"message\\/rfc822\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":77310,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2023-04-03T16:19:50.000000Z\",\"updated_at\":\"2023-04-03T16:19:50.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/149\\/642afc943ec55_Whole-Home-Repairs---Reporting-Template.eml\",\"preview_url\":\"\"},{\"id\":150,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":160,\"uuid\":\"918e53ea-521e-4bac-9a7d-1c1519c677a4\",\"collection_name\":\"documents\",\"name\":\"642afc980d606_Whole-Home Rep