INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1284,'audit:updated',298,'App\\Models\\Contract#298',3,'{\"purpose\":\"<p><strong>Purpose: THIS EXPIRED AND THE FUNDS WERE NEVER USED.<\\/strong><br>&nbsp;<\\/p><p>Pennsylvania Dept of Agriculture has awarded SHFB $40,330.00 TEFAP Reach &amp; Resiliency for Warehouse Infrastructure. Per the contract:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/665\\/image.png\\\"><\\/figure><p>The budget submitted is as follows:<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/666\\/image.png\\\"><\\/figure><p>This is a reimbursable grant.&nbsp;<\\/p><p>Payment by PDA shall be made not more more than once each month, upon submission of a certified invoice, on a reimbursement of costs incurred basis. Invoices shall indicate expenditures incurred by budget categories.<\\/p><p>At the conclusion of the TEFAP Reach and Resiliency Grant Award period, you will have 45 days in which to submit a final report on your project to the Pennsylvania Department of Agriculture\\u2019s Bureau of Food Assistance. <strong>By no later than July 15, 2024, please submit a final report to Caryn Long Earl (<\\/strong><a href=\\\"mailto:cearl@pa.gov\\\"><strong>cearl@pa.gov<\\/strong><\\/a><strong>)&nbsp;<\\/strong>detailing the following:<\\/p><ul><li>Final project expenditures<\\/li><li>Information on any new partner agencies through whom you are distributing TEFAP<\\/li><li>Information detailing how you have used these funds to expanded the reach of TEFAP in your service territory<\\/li><li>If applicable, information regarding increased geographic areas served through this project<\\/li><li>Metrics on the increased numbers of individuals served and demographics of increased individuals served<\\/li><li>Pounds of TEFAP distributed before and after implementation of project<\\/li><li>Information regarding client satisfaction<\\/li><li>Other relevant data or information regarding improved TEFAP reach in the community being served<\\/li><\\/ul>\",\"grant_code\":\"F8093\",\"updated_at\":\"2025-01-23 13:06:33\",\"id\":298,\"documents\":[{\"id\":668,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":298,\"uuid\":\"dbf27b22-afd7-41d0-b7f3-aab86ee4673d\",\"collection_name\":\"documents\",\"name\":\"65b2b16198692_2023_SHFB_TEFAPR&R_ProposalSubmitted\",\"file_name\":\"65b2b16198692_2023_SHFB_TEFAPR&R_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":198360,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-01-25T19:07:16.000000Z\",\"updated_at\":\"2024-01-25T19:07:16.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/668\\/65b2b16198692_2023_SHFB_TEFAPR&R_ProposalSubmitted.pdf\",\"preview_url\":\"\"},{\"id\":700,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":298,\"uuid\":\"9eb17053-3aa2-4d86-a754-cab087e7c790\",\"collection_name\":\"documents\",\"name\":\"65ccdb54cd554_TEFAP Reach and Resiliency Contract Executed\",\"file_name\":\"65ccdb54cd554_TEFAP-Reach-and-Resiliency-Contract-Executed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1198423,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":5,\"created_at\":\"2024-02-14T15:25:22.000000Z\",\"updated_at\":\"2024-02-14T15:25:22.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/700\\/65ccdb54cd554_TEFAP-Reach-and-Resiliency-Contract-Executed.pdf\",\"preview_url\":\"\"},{\"id\":777,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":298,\"uuid\":\"31ce71b3-6426-421a-a0ea-29e4ed2c8899\",\"collection_name\":\"documents\",\"name\":\"6615874e79597_TEFAP Reimbursment Request_ReachResiliency\",\"file_