INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1291,'audit:updated',412,'App\\Models\\Contract#412',3,'{\"purpose\":\"<p>-Use for Supportive Services for Shelter Residents including:<\\/p><ul><li>Salary and benefits for the Overnight Caretaker, Intake Specialist, Office Administrator, Maintenance Person, Case Manager, and Housing Specialist.<\\/li><li>Please see Scope of Services and Deliverables (Exhibit B page 18-19 of the contract attached) for detailed activities to be carried out with this grant funding.<\\/li><\\/ul><p><strong>Reporting:<\\/strong><\\/p><ul><li>Quarterly Expense Reports are required (Use exhibit C on page 20 of the contract attached and send to latarsha.brown@allentownpa.gov and grants@allentownpa.gov with all appropriate supporting back up)<\\/li><li>Quarterly Touch base, which can be conducted by a scheduled phone call or Teams Meeting.<\\/li><li>&nbsp;Mid-Point Report, which will measure the progress of goals and scope of services.<\\/li><li>&nbsp;Final Report due upon the depletion of the grant allocation or end term of the grant agreement.<\\/li><li>For all reporting requirements the city will reach out to schedule or request information.<\\/li><li>&nbsp;If you have any questions regarding these reports, please contact grants@allentownpa.gov&nbsp;<\\/li><\\/ul><p><strong>******THIS MONEY WILL COME IN LUMP SUM<\\/strong><\\/p>\",\"start_date\":\"2024-12-30\",\"updated_at\":\"2025-01-30 15:37:17\",\"cfda_number\":\"21.027\",\"id\":412,\"documents\":[{\"id\":1306,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":412,\"uuid\":\"5048da1c-2830-4b60-9a7e-287558852820\",\"collection_name\":\"documents\",\"name\":\"6761cee0321f4_2024SSS_City of Allentown_ Community Reinvestment Agreement\",\"file_name\":\"6761cee0321f4_2024SSS_City-of-Allentown_-Community-Reinvestment-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"c