INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1326,'audit:created',429,'App\\Models\\Contract#429',3,'{\"title\":\"CADCA Allentown School District 21 Century Grant 24\\/25 SY\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>Allentown School District will pay CADA $25,000 during the 2024\\/2025 School Year for the administration of the Excelsior Program in three of their schools. CADA will subcontract with the Fine Feather Foundation who will administer the program in the schools.&nbsp;<\\/p><ul><li>$23,000 will be used to pay the Fine Feather Foundation and $1500 will be used for Administration (Salary and Benefits for CALV, CADA Employees)<\\/li><\\/ul><p>We will bill ASD for a total of:<\\/p><ul><li>$7000 for William Allen Highschool<\\/li><li>$9000 for Trexler Middle School<\\/li><li>$9000 for Central Elementary School<\\/li><\\/ul><p>Fine Feather Foundation will invoice CADA:<\\/p><ul><li>$750 for each weekly session at William Allen Highschool<\\/li><li>$850 for each weekly session at Trexler Middle School<\\/li><li>$850 for each weekly session at Central Elementary School<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"25000\",\"start_date\":\"2025-01-23\",\"end_date\":\"2025-06-30\",\"notes\":null,\"grant_code\":\"F1405\",\"updated_at\":\"2025-02-21 13:19:22\",\"created_at\":\"2025-02-21 13:19:22\",\"id\":429,\"documents\":[],\"media\":[]}','10.55.0.88','2025-02-21 18:19:22','2025-02-21 18:19:22');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1327,'audit:updated',425,'App\\Models\\Contract#425',3,'{\"purpose\":\"<p>NC Local Share money for Facade Improvements and Mural Program.<\\/p><ul><li>This grant requires a 1-1 match.<\\/li><li>$8,000 for Rehabilitation and Renovation and $2,000 for Administration<\\/li><li>You must notify the county in writing 60 days prior to the termination of the contract to request an extension if needed.<\\/li><li>Any publications or media referencing a project funding with these funds must Acknowledge Assistance of NC. See section 39 on page 10 for details.<\\/li><\\/ul>\",\"updated_at\":\"2025-02-21 15:45:34\",\"id\":425,\"documents\":[{\"id\":1391,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":425,\"uuid\":\"a19bc27a-883f-430c-8360-d2a164d2ff4d\",\"collection_name\":\"documents\",\"name\":\"679d0dd87e456_2025SBR NC Grow Norco Facade and Mural signed\",\"file_name\":\"679d0dd87e456_2025SBR-NC-Grow-Norco-Facade-and-Mural-signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":2744227,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-01-31T17:52:26.000000Z\",\"updated_at\":\"2025-01-31T17:52:26.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1391\\/679d0dd87e456_2025SBR-NC-Grow-Norco-Facade-and-Mural-signed.pdf\",\"preview_url\":\"\"}],\"media\":[{\"id\":1391,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":425,\"uuid\":\"a19bc27a-883f-430c-8360-d2a164d2ff4d\",\"collection_name\":\"documents\",\"name\":\"679d0dd87e456_2025SBR NC Grow Norco Facade and Mural signed\",\"file_name\":\"679d0dd87e456_2025SBR-NC-Grow-Norco-Facade-and-Mural-signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":2744227,\"manipu