INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1355,'audit:created',436,'App\\Models\\Contract#436',45,'{\"title\":\"2024-2025SHFB City of Bethlehem Community Recovery Fund\",\"contract_number\":\"25000149\",\"cfda_number\":\"21.027\",\"purpose\":\"<p>This is a $16,000 reimbursable grant. Grant funds will be used to support allocations to 16 food pantries in Bethlehem (listed below) for Shared Maintenance Fee costs and participation in the Bulk Purchasing Program, and any related expenses incurred by Recipient for the completion of the project.<\\/p><p>Contract period is from January 1, 2025 - December 31, 2026.<\\/p><p>Pantries in this program are:<\\/p><ul><li>Bethlehem Salvation Army Pantry<\\/li><li>Calvary Baptist Pantry<\\/li><li>Central Assembly of God<\\/li><li>Central Moravian Food Pantry<\\/li><li>Ebenezer New Reformed Pantry<\\/li><li>Hispanic Center Lehigh Valley<\\/li><li>Lynfiled Community Center Food Pantry &nbsp;<\\/li><li>Marvine Elementary Food Pantry &nbsp;<\\/li><li>Meals on Wheels of The Greater Lehigh Valley<\\/li><li>Moravian University Food Pantry<\\/li><li>New Bethany Food Pantry<\\/li><li>New Jerusalem Lutheran Church Pantry<\\/li><li>Northampton Community College Pantry (H.O.P.E.)<\\/li><li>Northeast Community Center<\\/li><li>Second Baptist Pantry<\\/li><li>SS Simon &amp; Jude SVDP Pantry<\\/li><li>Trinity UCC Pantry<\\/li><\\/ul><p>Reimbursement requests may be submitted quarterly, beginning Q1 2025, through the City\'s grant portal, Neighborly (link will be emailed to planner-SHFB@caclv.org).<\\/p><p>There are four (4) reports:<\\/p><p>June 30, 2025<br>December 31, 2025<br>June 30, 2026<br>December 31, 2026<\\/p><p>A list of all data required for the reporting is available in the document Exhibit B below.<br><br>Contact for this program is:<\\/p><p>Lori Gilio<br>Grants Administrator for Community and Economic Development&nbsp;<br>City of Bethlehem, 10 E. Church Street, Bethlehem, PA 18018<br>o: 610-997-7970<br>c: 610-703-6335<br><a href=\\\"mailto:lgilio@bethlehem-pa.gov\\\">lgilio@bethlehem-pa.gov&nbsp;<\\/a><\\/p>\",\"funder_id\":null,\"amount\":\"16000.00\",\"start_date\":\"2025-01-01\",\"end_date\":\"2026-12-31\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-03-06 11:11:14\",\"created_at\":\"2025-03-06 11:11:14\",\"id\":436,\"documents\":[],\"media\":[]}','10.55.4.124','2025-03-06 16:11:14','2025-03-06 16:11:14');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1356,'audit:updated',436,'App\\Models\\Contract#436',45,'{\"purpose\":\"<p>This is a $16,000 reimbursable grant. Grant funds will be used to support allocations to 16 food pantries in Bethlehem (listed below) for Shared Maintenance Fee costs and participation in the Bulk Purchasing Program, and any related expenses incurred by Recipient for the completion of the project.<\\/p><p>Contract period is from January 1, 2025 - December 31, 2026.<\\/p><p>Pantries in this program are:<\\/p><ul><li>Bethlehem Salvation Army Pantry<\\/li><li>Calvary Baptist Pantry<\\/li><li>Central Assembly of God<\\/li><li>Central Moravian Food Pantry<\\/li><li>Ebenezer New Reformed Pantry<\\/li><li>Hispanic Center Lehigh Valley<\\/li><li>Lynfiled Community Center Food Pantry<\\/li><li>Marvine Elementary Food Pantry<\\/li><li>Meals on Wheels of The Greater Lehigh Valley<\\/li><li>Moravian University Food Pantry<\\/li><li>New Bethany Food Pantry<\\/li><li>New Jerusalem Lutheran Church Pantry<\\/li><li>Northampton Community College Pantry (H.O.P.E.)<\\/li><li>Northeast Community Center<\\/li><li>Second Baptist Pantry<\\/li><li>SS Simon &amp; Jude SVDP Pantry<\\/li><li>Trinity UCC Pantry<\\/li><\\/ul><p>Reimbursement requests may be submitted quarterly, beginning Q1 2025, through the City\'s grant portal, Neighborly (link will be emailed to planner-SHFB@caclv.org).<\\/p><p>There are four (4) reports:<\\/p><p>June 30, 2025<br>December 31, 2025<br>June 30, 2026<br>December 31, 2026<\\/p><p>A list of all data required for the reporting is available in the document Exhibit B below.<br><br>Contact for this program is:<\\/p><p>Lori Gilio<br>Grants Administrator for Community and Economic Development&nbsp;<br>City of Bethlehem, 10 E. Church Street, Bethlehem, PA 18018<br>o: 610-997-7970<br>c: 610-703-6335<br><a href=\\\"mailto:lgilio@bethlehem-pa.gov\\\">lgilio@bethlehem-pa.gov&nbsp;<\\/a><\\/p>\",\"updated_at\":\"2025-03-06 11:18:30\",\"id\":436,\"documents\":[{\"id\":1456,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":436,\"uuid\":\"13b75718-f93e-46b0-8594-ac0aaf6782d8\",\"collection_name\":\"documents\",\"name\":\"67c9c91aec543_Bethlehem Community Recovery Fund Exhibit B Reporting\",\"file_name\":\"67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":123237,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-03-06T16:11:14.000000Z\",\"updated_at\":\"2025-03-06T16:11:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1456\\/67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1456\\/conversions\\/67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting-preview.jpg\"},{\"id\":1457,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":436,\"uuid\":\"c2fcac21-6bd9-4a7b-beae-1419787bf808\",\"collection_name\":\"documents\",\"name\":\"67c9c91b0a431_24-25SHFB City of Bethlehem Community Recovery Fund signed\",\"file_name\":\"67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":641196,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2025-03-06T16:11:15.000000Z\",\"updated_at\":\"2025-03-06T16:11:18.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1457\\/67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1457\\/conversions\\/67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed-preview.jpg\"}],\"media\":[{\"id\":1456,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":436,\"uuid\":\"13b75718-f93e-46b0-8594-ac0aaf6782d8\",\"collection_name\":\"documents\",\"name\":\"67c9c91aec543_Bethlehem Community Recovery Fund Exhibit B Reporting\",\"file_name\":\"67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":123237,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-03-06T16:11:14.000000Z\",\"updated_at\":\"2025-03-06T16:11:15.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1456\\/67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1456\\/conversions\\/67c9c91aec543_Bethlehem-Community-Recovery-Fund-Exhibit-B-Reporting-preview.jpg\"},{\"id\":1457,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":436,\"uuid\":\"c2fcac21-6bd9-4a7b-beae-1419787bf808\",\"collection_name\":\"documents\",\"name\":\"67c9c91b0a431_24-25SHFB City of Bethlehem Community Recovery Fund signed\",\"file_name\":\"67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":641196,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2025-03-06T16:11:15.000000Z\",\"updated_at\":\"2025-03-06T16:11:18.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1457\\/67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1457\\/conversions\\/67c9c91b0a431_24-25SHFB-City-of-Bethlehem-Community-Recovery-Fund-signed-preview.jpg\"}]}','10.55.4.124','2025-03-06 16:18:30','2025-03-06 16:18:30');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1357,'audit:updated',429,'App\\Models\\Contract#429',3,'{\"purpose\":\"<p>Allentown School District will pay CADA $25,000 during the 2024\\/2025 School Year for the administration of the Excelsior Program in three of their schools. CADA will subcontract with the Fine Feather Foundation who will administer the program in the schools.&nbsp;<\\/p><ul><li>$23,000 will be used to pay the Fine Feather Foundation and $1500 will be used for Administration (Salary and Benefits for CALV, CADA Employees)<\\/li><\\/ul><p>We will bill ASD for a total of:<\\/p><ul><li>$7000 for William Allen Highschool<\\/li><li>$9000 for Trexler Middle School<\\/li><li>$9000 for Central Elementary School<\\/li><\\/ul><p>Fine Feather Foundation will invoice CADA:<\\/p><ul><li>$650 for each weekly session at William Allen Highschool for a total of $6,500<\\/li><li>$850 for each weekly session at Trexler Middle School for a total of $8,500<\\/li><li>$850 for each weekly session at Central Elementary School for a total of $8,500<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2025-03-06 12:04:54\",\"id\":429,\"documents\":[],\"media\":[]}','10.55.0.108','2025-03-06 17:04:54','2025-03-06 17:04:54');
