INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1390,'audit:created',440,'App\\Models\\Contract#440',45,'{\"title\":\"2024-2025SHFB_TRHWF School Pantry Program\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This is a $10,000 lump sum grant to support SHFB\'s school pantry program in Northampton County.<\\/p><p>The grant will be applied 100% toward the salary + benefits of the Community Services Manager.<\\/p><p>This grant will serve the below pantries:<\\/p><ul><li>Marvine Elementary School<\\/li><li>Slater Family Network<\\/li><li>Wilson Area LINCS Family Center<\\/li><li>George Wolf Elementary School<\\/li><li>The Easton Area Neighborhood Center<\\/li><\\/ul><p>A narrative report is required to apply for future funding. The request for the report will be emailed to the planner-SHFB@caclv.org, usually around September.<\\/p>\",\"funder_id\":\"202\",\"amount\":\"10000.00\",\"start_date\":\"2025-03-01\",\"end_date\":\"2025-09-30\",\"notes\":null,\"grant_code\":\"6260\",\"updated_at\":\"2025-03-25 08:55:44\",\"created_at\":\"2025-03-25 08:55:44\",\"id\":440,\"documents\":[],\"media\":[]}','10.55.4.149','2025-03-25 12:55:44','2025-03-25 12:55:44');
