INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1392,'audit:created',441,'App\\Models\\Contract#441',45,'{\"title\":\"2025SHFB_AllOneFoundation\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The purpose of this $200,000 grant is to support increased distribution of healthy foods to Carbon, Monroe, Pike, and Wayne Counties. This is a lump-sum award.<\\/p><p>Below is the goal and outcome information submitted in the 2025 Proposal.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1517\\/image.png\\\"><\\/figure><p>The proposed budget is below.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1518\\/image.png\\\"><\\/figure><p>&nbsp;<\\/p><p>Two reports are required for this grant, a midterm and final. The report template and deadline will be sent to the planner-SHFB@caclv.org email address.<\\/p>\",\"funder_id\":\"188\",\"amount\":\"200000.00\",\"start_date\":\"2025-03-17\",\"end_date\":\"2026-03-16\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-03-25 13:25:13\",\"created_at\":\"2025-03-25 13:25:13\",\"id\":441,\"documents\":[],\"media\":[]}','10.55.4.149','2025-03-25 17:25:13','2025-03-25 17:25:13');
