INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1409,'audit:updated',440,'App\\Models\\Contract#440',45,'{\"purpose\":\"<p>This is a $10,000 lump sum grant to support SHFB\'s school pantry program in Northampton County.<\\/p><p>The grant will be applied 100% toward the salary + benefits of the Community Services Manager.<\\/p><p>This grant will serve the below pantries:<\\/p><ul><li>Marvine Elementary School<\\/li><li>Slater Family Network<\\/li><li>Wilson Area LINCS Family Center<\\/li><li>George Wolf Elementary School<\\/li><li>The Easton Area Neighborhood Center<\\/li><\\/ul><p>A narrative report is required to apply for future funding. The request for the report will be emailed to the planner-SHFB@caclv.org, usually around September.<\\/p><p>There is no contract for this grant; the check linked below serves as confirmation of grant award.<\\/p>\",\"updated_at\":\"2025-04-01 08:48:11\",\"id\":440,\"documents\":[{\"id\":1515,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":440,\"uuid\":\"880fcd45-fc09-48d3-b278-8f9b4502146d\",\"collection_name\":\"documents\",\"name\":\"67e2b59d63405_2024_SHFB_TRHWF_ProposalSubmitted\",\"file_name\":\"67e2b59d63405_2024_SHFB_TRHWF_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":707374,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-03-25T13:55:44.000000Z\",\"updated_at\":\"2025-03-25T13:55:49.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1515\\/67e2b59d63405_2024_SHFB_TRHWF_ProposalSubmitted.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1515\\/conversions\\/67e2b59d63405_2024_SHFB_TRHWF_ProposalSubmitted-preview.jpg\"},{\"id\":1516,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":440,\"uuid\":\"