INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1420,'audit:updated',384,'App\\Models\\Contract#384',45,'{\"purpose\":\"<p><strong>Purpose:<\\/strong> Wayne County has awarded SHFB a CDBG grant for $39,993.00 for the purchase of fresh food for Wayne County. This is a <strong>reimbursable grant<\\/strong> with the grant period running from May 9,2024 - August 31, 2025. Food will be distributed to partner agencies serving Wayne County.<\\/p><p>Fresh food includes dairy, meat, eggs, fruits, and vegetables. Whenever possible, fresh food shall be procured from farmers located in Pike County.<\\/p><p>Food pantries serviced with CDBG funds must prepare and submit a letter on letterhead stating they will collect a Self Declaration of Need form from each individual served and that no food or non-food items purchased through this grant will be distributed to individuals who have not completed a Self Declaration of need form or who are deemed ineligible due to income. A template for this letter can be found in Exhibit B of the contract attached.<\\/p><p><strong>Reports <\\/strong>are due bi-monthly, according to the chart below. Completed reports should be sent to Katie Blake at Hailstone Economic, LLC which administers the CDBG funds: kblake@hailstoneeconomic.com<\\/p><p><strong>In March 2025, SHFB received permission to reallocate Outreach funds to Fresh Food Purchase. See letter below.<\\/strong><\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1159\\/image.png\\\"><\\/figure><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1160\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2025-04-03 14:06:32\",\"id\":384,\"documents\":[{\"id\":1161,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":384,\"uuid\":\"3681f2ff-a557-4960-aa8c-ce5361eedfaf\",\"collection_name\":\"documents\",\"name\":\"66f30582d38bd_2024SHFB_WayneCounty CDBG\",\"file_name\":\"66f30582d38bd_2024SHFB_WayneCounty-CDBG.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1278428,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-09-24T18:32:02.000000Z\",\"updated_at\":\"2024-09-24T18:32:02.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1161\\/66f30582d38bd_2024SHFB_WayneCounty-CDBG.pdf\",\"preview_url\":\"\"},{\"id\":1278,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":384,\"uuid\":\"e1ed7d8f-01ed-4232-805f-be75f4b3f782\",\"collection_name\":\"documents\",\"name\":\"674f0c36095e1_2023_SHFB_WayneCoCDBG_ProposalSubmitted\",\"file_name\":\"674f0c36095e1_2023_SHFB_WayneCoCDBG_ProposalSubmitted.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":148870,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":7,\"created_at\":\"2024-12-03T13:48:40.000000Z\",\"updated_at\":\"2024-12-03T13:48:40.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1278\\/674f0c36095e1_2023_SHFB_WayneCoCDBG_ProposalSubmitted.pdf\",\"preview_url\":\"\"},{\"id\":1534,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":384,\"uuid\":\"e498be18-8261-43a3-88dd-558c14cb729d\",\"collection_name\":\"documents\",\"name\":\"67eac0b62b755_Re_ SHFB budget reallocations for Wayne_Pike CDBG grants\",\"file_name\":\"67eac0b62b755_Re_-SHFB-budget-reallocations-for-Wayne_Pike-CDBG-grants.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":318794,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":8,\"created_at\":\"2025-03-31T16:20:06.000000Z\",\"updated_at\":\"2025-03-31T16:20:08.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.