INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1445,'audit:updated',458,'App\\Models\\Contract#458',45,'{\"purpose\":\"<p>This grant provides $12,002.21 to The Seed Farm in the form of gift cards to purchase supplies and equipment needed for a Home Depot Foundation volunteer project.<\\/p><p>The anticipated project date is <strong>June 19,2025<\\/strong>.<\\/p><p>&nbsp;The Project Scope is below.&nbsp;<\\/p><ul><li>Build and install 11\'x20\' Gazebo<\\/li><li>Build and stain 6 sales tables<\\/li><li>Build and stain a sales counter<\\/li><li>Lay stone<\\/li><li>Build 4-6 chalkboard signs<\\/li><li>Build 2 sandwich board signs<\\/li><li>Assemble and install picnic tables and park benches on property<\\/li><li>Plant shrubs, flowers, and mulch at main entrance and around perimeter of produce area<\\/li><li>Weeding, raking, and cleaning around the property as well as mulching, planting, and seeding in the greenhouse<\\/li><\\/ul><p>All associates and volunteers must sign the Volunteer Participation Waiver (attached below) in order to participate.<\\/p><p>Any recognition regarding this grant should be made in the name of The Home Depot Foundation. Prior to posting, please send all press release and social media content to the HD public relations team for review at TeamDepotPR@homedepot.com. SHFB is also encouraged to post project photos on the Home Depot Foundation Facebook page (\\/homedepotfoundation) or post about your project on other platforms using <strong>@HomeDepotFound<\\/strong> and <strong>#TeamDepot<\\/strong>.<\\/p><p>There is no report for this grant.<\\/p><p>Contact for this grant is:<\\/p><p>The Home Depot Foundation<br><strong>Adam Goslin<\\/strong><br>Foundation Field Manager<br>770-384-4309<br><a href=\\\"mailto:Adam_Goslin@homedepot.com\\\">Adam_Goslin@homedepot.com<\\/a><\\/p><p>Sponsoring Captain - Store 4140 - Allentown South (District 057)<br><strong>David Dimick<\\/strong><br>ASM_4140@HomeDepot.com<br>484-809-4256<\\/p>\",\"updated_at\":\"2025-04-22 11:22:39\",\"id\":458,\"documents\":[{\"id\":1592,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":458,\"uuid\":\"9de4b0f2-2e23-4d93-af05-349f9216b38a\",\"collection_name\":\"documents\",\"name\":\"6807c17658c9a_APPROVED \\u2013 The Home Depot Foundation Grant #202501176\",\"file_name\":\"6807c17658c9a_APPROVED-\\u2013-The-Home-Depot-Foundation-Grant--202501176.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":117224,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-04-22T16:19:08.000000Z\",\"updated_at\":\"2025-04-22T16:19:10.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1592\\/6807c17658c9a_APPROVED-\\u2013-The-Home-Depot-Foundation-Grant--202501176.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1592\\/conversions\\/6807c17658c9a_APPROVED-\\u2013-The-Home-Depot-Foundation-Grant--202501176-preview.jpg\"},{\"id\":1593,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":458,\"uuid\":\"0f3f3df2-22ab-4e27-a133-d916b7e99b77\",\"collection_name\":\"documents\",\"name\":\"6807c1765c1cb_Team_Depot_Volunteer_Waiver\",\"file_name\":\"6807c1765c1cb_Team_Depot_Volunteer_Waiver.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":66567,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true},\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2025-04-22T16:19:10.000000Z\",\"updated_at\":\"2025-04-22T16:19:12.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1593\\/6807c1765c1cb_Team_Depot_Volunteer_Waiver.pdf\",\"preview_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1593\\/conversions\\/6807c1765c1cb_Team_Depot_Volunteer_Waiver-preview.jpg\"}],\"med