INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1446,'audit:updated',445,'App\\Models\\Contract#445',3,'{\"purpose\":\"<p><strong>To be used for:&nbsp;<\\/strong><\\/p><ol><li>Roofing improvements, HVAC and electrical upgrades&nbsp;<\\/li><li>Salary and benefits for CALV Housing Team.<\\/li><\\/ol><p><strong>Requirements:&nbsp;<\\/strong><\\/p><ul><li>For at least 10 income qualified households particularly in neighborhoods of Linden and Chew from North Law to North Fountain Streets.<\\/li><li>Specific Demographic information to be collected with each application on page 11 subsection D, section 5.<\\/li><li>Use Exhibit D Income Verification Form for Applicants<\\/li><li>Closeout requirements in subsection G, section 3.<\\/li><li>Bidding requirements: 3 arm\'s length bids<\\/li><li>Lead Pain regulations<\\/li><li>Historic Preservation Regulations<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"amount\":\"260000\",\"start_date\":\"2024-01-01\",\"end_date\":\"2025-12-31\",\"notes\":\"<p>Document retention: all documents to be kept until HUD closes out the grant year. Compliance Director will notify you when this has happened.&nbsp;<\\/p><p>Grantee Recognition requirements on page 9 section 4, subsection M.<\\/p><p>Payment Schedule is Exhibit C<\\/p><p>Quarterly Reports are required.<\\/p>\",\"updated_at\":\"2025-04-22 11:30:38\",\"id\":445,\"documents\":[{\"id\":1532,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":445,\"uuid\":\"180859af-7f8c-4813-a4ce-27f60914303b\",\"collection_name\":\"documents\",\"name\":\"67e6b9fe8e0e3_2024CAH City of Allentown CDBG Better Homes signed (1)\",\"file_name\":\"67e6b9fe8e0e3_2024CAH-City-of-Allentown-CDBG-Better-Homes-signed-(1).pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":1280411,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":{\"thumb\":true,\"preview\":true}