INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1450,'audit:updated',444,'App\\Models\\Contract#444',3,'{\"purpose\":\"<p>DO NOT USE YET- Need Executed Contract and Maps<\\/p><p><strong>Purpose:<\\/strong><\\/p><ul><li>To be used on LMI Single Unit Residential homes in the NRSA Area and Southside Area of Bethlehem. (Please follow target area maps)<\\/li><li>Minimum of 3 owner occupied residential units with 2 being in the NRSA area.&nbsp;<\\/li><li>No more than 4 units to be rehabilitated with these funds<\\/li><\\/ul><p><strong>Budget:<\\/strong><\\/p><ol><li>$5,000 for personnel costs&nbsp;<\\/li><li>$44,500 for hard and soft construction costs<\\/li><\\/ol>\",\"notes\":\"<p><strong>Other Requirements:&nbsp;<\\/strong><\\/p><ul><li>Please see eligible expenses in Section 4, subsection B.<\\/li><li>Follow proper procurements procedures- 3 arm\'s length bids using proper forms<\\/li><li>Lead Based Paint Requirements<\\/li><li>&nbsp;Historic Preservation Requirements<\\/li><li>Radon Testing Requirements even if solely focusing on exterior. (You must test for radon or have other evidence showing radon is not an issue)<\\/li><li>MBE\\/WBE solicitation form is required to be completed and submitted for every contract.<\\/li><li>See Attachment A for required supporting documentation for Payment Requests.<\\/li><\\/ul><p>Contact for this grant is Laura Collins: lcollins@bethlehem-pa.gov&nbsp;<\\/p>\",\"updated_at\":\"2025-04-22 11:59:01\",\"id\":444,\"documents\":[{\"id\":1530,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":444,\"uuid\":\"442a61fc-7f4c-4304-ac26-7d53917eb054\",\"collection_name\":\"documents\",\"name\":\"67e586e9c7d7a_2025CADB City of Bethlehem CDBG Exterior Rehabilitation and Weatherization amendment signed\",\"file_name\":\"67e586e9c7d7a_2025CADB-City-of-Bethlehem-CDBG-Exterior-Rehabilitation-and-Weatherization-amendment-signed.pdf\",\"mime_type\"