INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1457,'audit:updated',445,'App\\Models\\Contract#445',3,'{\"title\":\"2024CAH City of Allentown CDBG Better Homes\",\"contract_number\":\"#302\",\"purpose\":\"<p><strong>To be used for:&nbsp;<\\/strong><\\/p><ol><li>Roofing improvements, HVAC and electrical upgrades<\\/li><li>Salary and benefits for CALV Housing Team.<\\/li><\\/ol><p><strong>Requirements:&nbsp;<\\/strong><\\/p><ul><li>For at least 10 income qualified households particularly in neighborhoods of Linden and Chew from North Law to North Fountain Streets.<\\/li><li>Specific Demographic information to be collected with each application on page 11 subsection D, section 5.<\\/li><li>&nbsp;Exhibit D Income Verification Form for Applicants<\\/li><li>Please read Closeout Requirements section 5 subsection G on page 13.<\\/li><li>Bidding requirements: 3 arm\'s length bids<\\/li><li>Lead Paint regulations<\\/li><li>Historic Preservation Regulations<\\/li><li>Grantee Recognition requirements on page 9 section 4, subsection M.<\\/li><li>Payment Schedule (Exhibit C)<\\/li><li>Quarterly and Annual Performance Reports are required.<\\/li><\\/ul><p><strong>Please see detailed Budget (Exhibit A)<\\/strong><\\/p><ul><li>$50,000 for program personnel costs<\\/li><li>$200,000 for Program Deliver<\\/li><li>$10,000 for administrative costs<\\/li><\\/ul>\",\"notes\":\"<ul><li><strong>Document retention:<\\/strong> all documents to be kept until HUD closes out the grant year. Compliance Director will notify you when this has happened.<\\/li><\\/ul>\",\"updated_at\":\"2025-04-29 13:38:37\",\"cfda_number\":\"14.218\",\"id\":445,\"documents\":[{\"id\":1532,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":445,\"uuid\":\"180859af-7f8c-4813-a4ce-27f60914303b\",\"collection_name\":\"documents\",\"name\":\"67e6b9fe8e0e3_2024CAH City of Allentown CDBG Better Homes signed (1)\",\"file_