INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1470,'audit:updated',335,'App\\Models\\Contract#335',45,'{\"purpose\":\"<p>This is a <strong>$25,000.00 lump sum<\\/strong> grant, awarded by Starbucks to support it\'s <a href=\\\"https:\\/\\/stories.starbucks.com\\/stories\\/hunger-relief\\/\\\">FoodShare program<\\/a>; delivering frozen product daily directly to partner agencies. This program is designed to provide necessary infrastructure to those partner agencies who receive Starbucks product.<\\/p><p>An itemized list of requested equipment has been submitted and accepted by Starbucks (see below). Once funds are received, the Retail Recovery Coordinator will work with partner agencies to purchase and install equipment. Funds must be spent before July 30, 2024.<\\/p><p>A report is due on or before July 30, 2024, outlining the itemized expenditures, providing an Impact Statement on use of funds and social media coverage. Additional details are below.&nbsp;<\\/p><p>Per the below email, an additional $5,000 was requested and received.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/824\\/image.png\\\"><\\/figure>\",\"amount\":\"30000.00\",\"updated_at\":\"2025-05-02 11:40:06\",\"id\":335,\"documents\":[{\"id\":827,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":335,\"uuid\":\"b37c639b-23f5-4d04-a731-5e2fa78e420a\",\"collection_name\":\"documents\",\"name\":\"663ba2ea20472_Starbucks Food Share Itemized Pricing\",\"file_name\":\"663ba2ea20472_Starbucks-Food-Share-Itemized-Pricing.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":67139,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":6,\"created_at\":\"2024-05-08T16:07:19.000000Z\",\"updated_at\":\"2024-05-08T16:07:19.000000Z\",\"original_url\":\"http:\\/\\/10.55.0