INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1473,'audit:updated',267,'App\\Models\\Contract#267',45,'{\"contract_number\":\"C990004163\",\"purpose\":\"<p>Grant awarded from the PA Department of Environmental Protection for <strong>$47,488.00<\\/strong> for warehouse equipment purchase. We were approved to purchase 6 walk behinds jacks and 2 riding jacks.<\\/p><p><i>Approval was also given to purchase caster wheels to stabilize the walk behinds, as the original project came in $1,013 under budget.<\\/i><\\/p><p>Grant period extends from July 1, 2022 - November 28, 2025.<\\/p><p>Request for reimbursement must be submitted on the Disbursement Request Form below.&nbsp;<\\/p><p>Final reimbursement request is due on or before November 28.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1637\\/image.png\\\"><\\/figure><p>There is no reporting requirement.<\\/p><p>Questions should be directed to:<\\/p><p>Jessica Shilladay<br>Dept of Environmental Protection, Bureau of Waste Management<br>Division of Waste Minimization and Planning<br>Rachel Carson State Office Bldg<br>PO Box 8472<br>Harrisburg, PA 17105-8472<br>jesshillad@pa.gov<br>717-787-0125<\\/p>\",\"updated_at\":\"2025-05-06 07:42:43\",\"id\":267,\"documents\":[{\"id\":561,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":267,\"uuid\":\"5edcea5e-394e-456d-a972-2dd16b8f349f\",\"collection_name\":\"documents\",\"name\":\"657a078838f9c_DEP Recovery Fully Executed Grant Agreement\",\"file_name\":\"657a078838f9c_DEP-Recovery-Fully-Executed-Grant-Agreement.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":569896,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2023-12-13T19:44:33.000000Z\",\"updated_at\":\"2023-12-13T19:44:33.000000Z\",\"original_u