INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1474,'audit:created',464,'App\\Models\\Contract#464',45,'{\"title\":\"2025SHFB)_CheckOutHunger_CFBNJ\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This agreement is between the Community FoodBank of NJ (CFBNJ) and SHFB regarding funds raised at round-up campaigns at Wawa \\/ Wegmans stores in our service area.<\\/p><p>Campaigns run from approximately Oct-Jan of each year.&nbsp;<\\/p><ul><li>SHFB is responsible for:<\\/li><li>When we become aware, notifying CFBNJ of any issues (e.g., store is not properly displaying materials and\\/or informing customers of the Campaign) within Retailer stores that occur during the Campaign Term. (We do not need to actively schedule site visits)<\\/li><li>Notifying CFBNJ if we receive additional funds related to the campaign but not part of the direct contribution made by CFBNJ.<\\/li><\\/ul><p>Checks will be mailed directly to CALV\\/SHFB from either CFBNJ (for Wawa) or Wegmans within 90 days from the conclusion of each campaign. Campaign reports will also be mailed out at that time.<\\/p><p>There is no media requirement for this contract. However:&nbsp;<\\/p><p><i>CFBNJ hereby grants to the Food Bank a non\\u00adexclusive right to use its logo, name and\\/or marks (\\\"CFBNJ Marks\\\") and\\/or Campaign logos, names and\\/or marks (\\\"Check-Out Hunger Marks\\\") in any media (a) during the Campaign Term in connection with the Campaign, and (b) during and after the Campaign Term on its website(s) and in publicity materials to describe the Campaign and\\/or Food Bank\'s contribution to the Campaign.<\\/i><\\/p><p>Contact for this agreement is:<\\/p><p>Leah Galamba<br>Community Outreach Specialist &nbsp;<br>Community FoodBank of New Jersey<br>31 Evans Terminal - Hillside NJ 07205<br>lgalamba@cfbnj.org<br>908-882-0668<br>www.cfbnj.org&nbsp;<\\/p><p>&nbsp;<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2024-10-01\",\"end_date\":\"2029-01-13\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-05-08 08:41:08\",\"created_at\":\"2025-05-08 08:41:08\",\"id\":464,\"documents\":[],\"media\":[]}','10.55.4.149','2025-05-08 12:41:08','2025-05-08 12:41:08');
