INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1539,'audit:created',477,'App\\Models\\Contract#477',45,'{\"title\":\"2025SHFB_MANA Rose Garden Farmers Market\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This contract establishes the regulations and requirements for SHFB to retain space at the Bethlehem Rose Garden Farmers Market, held at the Rose Garden in Bethlehem between Union Blvd, 8th Avenue and W. Broad St. The market will be open Saturdays from 9:00 am - 1:00 pm, beginning on June 07, 2025 and ending on October 11, 2025. The Mount Airy Neighborhood Assoc (MANA) is responsible for the operation and management of the market.<\\/p><p>Vendors must arrive no later than 8:40 am and must be set up and ready by opening time.<\\/p><p>Contact information is:<\\/p><p>Mary Toulouse<br>484-767-6585<br>toulousm@gmail.com<\\/p><p>Diana or John Worley<br>worleyd84@yahoo.com<\\/p><p>Katie Stafford<br>484-602-0243<br>kostafford@gmail.com<\\/p>\",\"funder_id\":null,\"amount\":\"0.00\",\"start_date\":\"2025-06-07\",\"end_date\":\"2025-10-11\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-06-05 09:20:41\",\"created_at\":\"2025-06-05 09:20:41\",\"id\":477,\"documents\":[],\"media\":[]}','10.55.4.149','2025-06-05 13:20:41','2025-06-05 13:20:41');
