INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1552,'audit:updated',475,'App\\Models\\Contract#475',3,'{\"contract_number\":\"25-CY-084\",\"purpose\":\"<p>To provide housing and supportive services to shelter guests referred by Lehigh County Office of Children and Youth.<\\/p><ul><li>8 apartments reserved at a rate of $70 per day (Potential to fill and bill for additional apartments)<\\/li><li>Supportive Services at an hourly rate of $65 (Includes face to face meetings\\/be sure to have the resident sign the appointment log)<\\/li><li>Curfew checks billed at an hour per day at a rate of $65&nbsp;<\\/li><li>CAP on this contract is $355,000<\\/li><\\/ul><p><strong>Compliance Requirements:<\\/strong><\\/p><ul><li>SSS staff must have all required background checks on file and renew them every 60 months. Please see Appendix E page 11 for required clearances<\\/li><li>All Staff must complete 12 hours of training per year. Training determined by Shelter Director.<\\/li><li>Comply with Limited English Proficiency Guidelines (Appendix E)<\\/li><li>Comply with HIPAA Requirements (Appendix G)<\\/li><\\/ul><p>&nbsp;<\\/p><p><i><strong>***In October 2025 Lehigh County Children and Youth will reassess the need to prepay for additional apartments if needed based on rate of filling the apartments<\\/strong><\\/i><strong>***<\\/strong><\\/p>\",\"amount\":\"355000\",\"start_date\":\"2025-07-01\",\"end_date\":\"2026-06-30\",\"notes\":\"<p><strong>Reports:&nbsp;<\\/strong><\\/p><ol><li>Discharge Summary- due 14 days post discharge emailed to the assigned OCYS Case Workers and Supervisor at ocysproviderreports@lehighcounty.org<\\/li><li>Submit daily availability list to include the number of active cases, openings, number on waitlist if applicable, and number of cases pending discharge within 2 weeks. Submitted to ocysreferralservices@lehighcounty.org<\\/li><li>Monthly FPP reports for invoicing and reimbursement requests<\\/li><li>Semi- Annual Report to cover July 1st- December 31st due January 15, 2026<\\/li><li>Final Report covering January 1st- June 30th due by July 15, 2026<ul><li><strong>Please see page 1 of appendix C for new requirements on reports and notes entered into \\\"ACYS\\\" system portal once implemented. Provider shall complete weekly contact notes to be submitted within 14 days from the end of the week of service.<\\/strong><\\/li><\\/ul><\\/li><\\/ol><p>&nbsp;<\\/p>\",\"updated_at\":\"2025-06-09 10:36:25\",\"id\":475,\"documents\":[{\"id\":1685,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":475,\"uuid\":\"c719f685-a3a4-4058-a6ae-5ee71df52cf7\",\"collection_name\":\"documents\",\"name\":\"683dc7c2a5026_APPENDIX B community action committee of the lv   RATES   cac   2526   05 15 25\",\"file_name\":\"683dc7c2a5026_APPENDIX-B-community-action-committee-of-the-lv---RATES---cac---2526---05-15-25.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":25870,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-06-02T15:49:58.000000Z\",\"updated_at\":\"2025-06-02T15:49:58.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1685\\/683dc7c2a5026_APPENDIX-B-community-action-committee-of-the-lv---RATES---cac---2526---05-15-25.docx\",\"preview_url\":\"\"},{\"id\":1686,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":475,\"uuid\":\"cb7751be-d909-4639-bf44-942a61fcb7b1\",\"collection_name\":\"documents\",\"name\":\"683dc7dfee969_25-CY  -084 (1)\",\"file_name\":\"683dc7dfee969_25-CY---084-(1).doc\",\"mime_type\":\"application\\/msword\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":98816,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created