INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1558,'audit:created',481,'App\\Models\\Contract#481',3,'{\"title\":\"2025CADB Keystone Savings Foundation via LVCF\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>&nbsp;To support Southside Tomorrow initiative specifically to cover program and operations costs incurred by the Community Housing Advocate Program, which can include: advertising, supplies, food, and space rental.&nbsp;<\\/p><p>&nbsp;<\\/p><p><br>&nbsp;<\\/p>\",\"funder_id\":\"218\",\"amount\":\"5000\",\"start_date\":\"2025-06-04\",\"end_date\":null,\"notes\":\"<ul><li>Please not that grants for operations and program will not be made to the same organization for more than three (3) consecutive years. After three consecutive years of funding, an organization must wait a minimum of one year before applying for another grant.<\\/li><\\/ul>\",\"grant_code\":\"F8000\",\"updated_at\":\"2025-06-12 06:58:16\",\"created_at\":\"2025-06-12 06:58:16\",\"id\":481,\"documents\":[],\"media\":[]}','172.16.100.37','2025-06-12 10:58:16','2025-06-12 10:58:16');
