INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1561,'audit:updated',422,'App\\Models\\Contract#422',45,'{\"purpose\":\"<p>The original scope of work provided with this grant has been amended to address capacity building\\/improvements at Northampton County pantries involved in the retail recovery program. The $50,000 revised budget is as follows:<\\/p><ul><li>$22,500 - Salary\\/fringe<\\/li><li>$2,500 - Travel<\\/li><li>$25,000 - Equipment<\\/li><\\/ul><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1730\\/image.png\\\"><\\/figure><p>The reporting schedule is below; a template for reporting is available in the contract.<\\/p><figure class=\\\"image\\\"><img src=\\\"http:\\/\\/10.55.0.10\\/storage\\/1405\\/image.png\\\"><\\/figure>\",\"updated_at\":\"2025-06-12 10:36:49\",\"id\":422,\"documents\":[{\"id\":1387,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":422,\"uuid\":\"fb64bd6a-ca36-4696-956a-d099ece55d70\",\"collection_name\":\"documents\",\"name\":\"679bb08cc39e9_2024SHFB NC CDBG Retail Recovery signed\",\"file_name\":\"679bb08cc39e9_2024SHFB-NC-CDBG-Retail-Recovery-signed.pdf\",\"mime_type\":\"application\\/pdf\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":2760215,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2025-01-30T17:02:17.000000Z\",\"updated_at\":\"2025-01-30T17:02:17.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1387\\/679bb08cc39e9_2024SHFB-NC-CDBG-Retail-Recovery-signed.pdf\",\"preview_url\":\"\"},{\"id\":1406,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":422,\"uuid\":\"d4ebe295-e056-4fcd-81c9-fc363e93d9a2\",\"collection_name\":\"documents\",\"name\":\"67af7dfd4a9c1_2024_SHFB_NCCDBG_AwardLetter Retail Recovery\",\"file_name\":\"67af7dfd4a9c1_2024_SHFB_NCCDBG_AwardLetter-Retail-Recover