INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1567,'audit:updated',411,'App\\Models\\Contract#411',3,'{\"purpose\":\"<p>Exterior work on the Grace Community Center Building- Detailed Scope of Work and Budget to come<\\/p><p>10% of the total contract amount may be used for CALV administrative expenses= $25,246.6<\\/p><p><strong>LSA Compliance Requirements<\\/strong><\\/p><ul><li>Must provide CFA with copies of all executed contracts for all Project-related work to be performed<\\/li><li>A certificate of insurance naming CALV, Lansford Borough, Commonwealth Finance Authority and Grace Community Church as additionally insured is required of all contractors&nbsp;<\\/li><li>Prevailing wage requirements with certified payrolls (first and last notarized) required to be submitted as part of the reimbursement process<\\/li><li>Open and Competitive Bidding Procedures as prescribed by Lansford Borough<\\/li><li>Document Retention 7 years post final activity<\\/li><li>Article XIII Acknowledgment of Commonwealth Assistance (page 18)<\\/li><li>ALL CONTRACTS MUST BE MADE WITH CALV AND SIGNED BY CALV<\\/li><li>Contractor Debarment Searches<\\/li><li>Collect Contractor Licenses and Insurance<\\/li><li>All subcontractor contracts must have language surrounding BABA, PA Prevailing Wage and non-discrimination and sexual harassment enclosed in Exhibit A.<\\/li><li>Performance and payment bonds are required, or no reimbursement will take place until 100% of the job is completed to satisfaction<\\/li><li>Subcontract to include Grantee Integrity Policy outlined in section C<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"notes\":\"<p><strong>Reimbursement Procedures:<\\/strong><\\/p><ul><li>Borough of Lansford will submit payment requests<\\/li><li>Complete payment request forms with 2 signatures from the borough<\\/li><li>Copies of invoices<\\/li><li>Proof of competitive procurement, process and results,<\\/li><li>Performance and payments bonds must be submitted, or no reimbursement may be requested until the entire project is completed<\\/li><li>Close out requirements include providing copies of all canceled checks by the expiration of the grant period for all applicable expenses<\\/li><\\/ul><p><strong>Annual Report to DCED:<\\/strong><\\/p><ul><li>This will be Lansford Borough\'s responsibility<\\/li><li>Included in Appendix A\\/B page 6<\\/li><\\/ul>\",\"updated_at\":\"2025-06-23 13:38:36\",\"id\":411,\"documents\":[{\"id\":1300,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":411,\"uuid\":\"2e904e77-51dd-47d7-b40e-6ad0a07b412f\",\"collection_name\":\"documents\",\"name\":\"675891d100943_Monroe LSA Application Working Doc\",\"file_name\":\"675891d100943_Monroe-LSA-Application-Working-Doc.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":58024,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":1,\"created_at\":\"2024-12-10T19:12:23.000000Z\",\"updated_at\":\"2024-12-10T19:12:23.000000Z\",\"original_url\":\"http:\\/\\/10.55.0.10\\/storage\\/1300\\/675891d100943_Monroe-LSA-Application-Working-Doc.docx\",\"preview_url\":\"\"},{\"id\":1301,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":411,\"uuid\":\"0bd4bbe1-bd4b-4bbc-be6f-c15ce8618a59\",\"collection_name\":\"documents\",\"name\":\"675891d855cbc_Monroe LSA Addenda Project Description_PVFP\",\"file_name\":\"675891d855cbc_Monroe-LSA-Addenda-Project-Description_PVFP.docx\",\"mime_type\":\"application\\/vnd.openxmlformats-officedocument.wordprocessingml.document\",\"disk\":\"public\",\"conversions_disk\":\"public\",\"size\":36956,\"manipulations\":[],\"custom_properties\":[],\"generated_conversions\":[],\"responsive_images\":[],\"order_column\":2,\"created_at\":\"2024-12-10T19:12:23.000000Z\",\"updated_at\":\"2024-12-10T19:12:2