INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1590,'audit:updated',411,'App\\Models\\Contract#411',3,'{\"purpose\":\"<p>Exterior work on the Grace Community Center Building- Detailed Scope of Work and Budget to come<\\/p><p>5% of the total contract amount may be used for CALV administrative expenses= $13,156.00<\\/p><p><strong>LSA Compliance Requirements<\\/strong><\\/p><ul><li>Must provide CFA with copies of all executed contracts for all Project-related work to be performed<\\/li><li>A certificate of insurance naming CALV, Lansford Borough, Commonwealth Finance Authority and Grace Community Church as additionally insured is required of all contractors<\\/li><li>Prevailing wage requirements with certified payrolls (first and last notarized) required to be submitted as part of the reimbursement process<\\/li><li>Open and Competitive Bidding Procedures as prescribed by Lansford Borough<\\/li><li>Document Retention 7 years post final activity<\\/li><li>Article XIII Acknowledgment of Commonwealth Assistance (page 18)<\\/li><li>ALL CONTRACTS MUST BE MADE WITH CALV AND SIGNED BY CALV<\\/li><li>Contractor Debarment Searches<\\/li><li>Collect Contractor Licenses and Insurance<\\/li><li>All subcontractor contracts must have language surrounding BABA, PA Prevailing Wage and non-discrimination and sexual harassment enclosed in Exhibit A.<\\/li><li>Performance and payment bonds are required, or no reimbursement will take place until 100% of the job is completed to satisfaction<\\/li><li>Subcontract to include Grantee Integrity Policy outlined in section C<\\/li><\\/ul><p>&nbsp;<\\/p>\",\"updated_at\":\"2025-06-30 08:46:33\",\"id\":411,\"documents\":[{\"id\":1300,\"model_type\":\"App\\\\Models\\\\Contract\",\"model_id\":411,\"uuid\":\"2e904e77-51dd-47d7-b40e-6ad0a07b412f\",\"collection_name\":\"documents\",\"name\":\"675891d100943_Monroe LSA Application Working Doc\",\"file_name\