INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1591,'audit:created',486,'App\\Models\\Contract#486',3,'{\"title\":\"2025 HCP SSS Santander\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<ul><li>General Operating for HCP ($5,000) and SSS ($5,000)<\\/li><li>Social Media post required<\\/li><\\/ul>\",\"funder_id\":\"105\",\"amount\":\"10000\",\"start_date\":\"2025-07-01\",\"end_date\":\"2026-07-31\",\"notes\":\"<p>Reporting:<\\/p><ul><li>6 month report due by January 15, 2026<\\/li><li>Final Report due by August 15, 2026<\\/li><li>See section 3 of the grant agreement for the required information<\\/li><\\/ul>\",\"grant_code\":\"F8000\",\"updated_at\":\"2025-06-30 10:59:48\",\"created_at\":\"2025-06-30 10:59:48\",\"id\":486,\"documents\":[],\"media\":[]}','10.55.0.183','2025-06-30 14:59:48','2025-06-30 14:59:48');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1592,'audit:created',487,'App\\Models\\Contract#487',45,'{\"title\":\"2025SHFB_Feeding America Advocacy\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>The purpose of this grant is to accelerate advocacy efforts on our shared legislative policy priorities and engage lawmakers in advance of the budget reconciliation in the House of Representatives. This is a lump sum grant for $7,500.<\\/p><p>Eligible Expenses<\\/p><ul><li>Staff salary and benefits<\\/li><li>Ads \\/ media buys<\\/li><li>Consultant or lobbying support<\\/li><li>Supplies<\\/li><li>Technology<\\/li><li>Program materials<\\/li><li>Neighbor compensation<\\/li><li>Travel and per diem costs, including expenses incurred from staff or neighbor attendance at lawmaker meetings<\\/li><\\/ul><p>Ineligible Expenses<\\/p><ul><li>Food for general distributions that do not engage lawmakers<\\/li><li>Other spending unrelated to advancing the Feeding America network\\u2019s legislative policies around budget reconciliation.<\\/li><\\/ul><p>All budget reconciliation activities\\/engagements should be logged in the <a href=\\\"https:\\/\\/feedingamerica.quorum.us\\/log\\/\\\"><strong>Feeding America Advocacy Tracker<\\/strong><\\/a><strong>. <\\/strong>There is no other reporting required for this grant.<br><br>Please direct legislative advocacy questions to Thao Nguyen, Vice President of Advocacy and CommunityEngagement, at <a href=\\\"thaonguyen@feedingamerica.org\\\">thaonguyen@feedingamerica.org<\\/a>.<\\/p><p>Please direct technical GMS-related questions, such as application or report submission, to Sally Yan, Sr.Manager, Member Grants, at <a href=\\\"syan@feedingamerica.org\\\">syan@feedingamerica.org<\\/a>.<\\/p>\",\"funder_id\":\"149\",\"amount\":\"7500.00\",\"start_date\":\"2025-06-01\",\"end_date\":\"2025-07-11\",\"notes\":null,\"grant_code\":\"8000\",\"updated_at\":\"2025-07-01 08:47:26\",\"created_at\":\"2025-07-01 08:47:26\",\"id\":487,\"documents\":[],\"media\":[]}','172.16.100.24','2025-07-01 12:47:26','2025-07-01 12:47:26');
