INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1634,'audit:created',491,'App\\Models\\Contract#491',45,'{\"title\":\"2025SHFB_Costco Food Purchase\",\"contract_number\":null,\"cfda_number\":null,\"purpose\":\"<p>This grant is to support food sourcing efforts and may be used <strong>for food purchases only<\\/strong>. Recipients are encouraged to spend the funds at a local Costco.<\\/p>\",\"funder_id\":\"149\",\"amount\":\"45454.00\",\"start_date\":\"2025-06-01\",\"end_date\":\"2026-02-28\",\"notes\":null,\"grant_code\":null,\"updated_at\":\"2025-07-15 09:27:10\",\"created_at\":\"2025-07-15 09:27:10\",\"id\":491,\"documents\":[],\"media\":[]}','172.16.100.47','2025-07-15 13:27:10','2025-07-15 13:27:10');
INSERT INTO `audit_logs` (`id`, `description`, `subject_id`, `subject_type`, `user_id`, `properties`, `host`, `created_at`, `updated_at`) VALUES (1635,'audit:updated',491,'App\\Models\\Contract#491',45,'{\"purpose\":\"<p>This grant is to support food sourcing efforts and may be used <strong>for food purchases only<\\/strong>. Recipients are encouraged to spend the funds at a local Costco.<\\/p><p>The food purchased with these funds should be receipted as purchased product and not donated product. Reach out to your ERP specialist if you need assistance with receipting your order.<\\/p><p><strong>Reporting Requirements<\\/strong><\\/p><p>There will be one (1) report required for this grant, to be collected via the GMS.<strong>&nbsp;<\\/strong><\\/p><p>Final report \\u2013 due March 24, 2026 \\u2013 covering entire grant period of June 1, 2025 through February 28, 2026 <i>(9 months). <\\/i>A sample report template is attached; the actual report should be submitted via the FA Grants Management System.<\\/p><p>Report requirements include, but are not limited to:<\\/p><ul><li>Confirmation of funds expenditure&nbsp;<\\/li><li>Amount spent and where the food was sourced &nbsp;<\\/li><li>Purchases (quantity &amp; description) tracked by food category, pounds, and cost<\\/li><li>Description of program(s) supported by the purchases<\\/li><li>Grant impact<\\/li><li>Stories\\/testimonials<\\/li><\\/ul><p><strong>Publicity Requirements<\\/strong><\\/p><p>The donor does not wish to have media or recognition around this grant; listing in an annual report is fine, but no further publicity is required.<\\/p><p>Questions regarding Feeding America\\u2019s relationship with Costco shall be directed to<strong> Charina Layman<\\/strong>, <i>Sr<\\/i>. <i>Manager, Corporate Partnerships<\\/i>,&nbsp;<a href=\\\"mailto:chlayman@feedingamerica.org\\\">chlayman@feedingamerica.org<\\/a>&nbsp;<\\/p>\",\"updated_at\":\"2025-07-15 09:47:40\",\"id\":491,\"documents\":[],\"media\":[]}','172.16.100.47','2025-07-15 13:47:40','2025-07-15 13:47:40');
