INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (154,'SSS_FEMA_EFSP',NULL,'<p>-Utilities, maintenance, salaries, eligible shelter supplies (See Mass Shelter quick Reference Guide included in the documents section)</p><p>-Phase 40 and 41</p>',NULL,NULL,NULL,NULL,'yes','2025-06-27','<p>Per Diem log needs to be kept for these funds on a daily basis. Shelter must keep track of the total residents per night and multiply that number by $12.50. Please see sample per diem log in the documents.</p><p>&nbsp;</p>','1400','2023-03-22 11:54:13','2025-06-27 16:42:57',NULL,139,'97.024');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (155,'2023SSS_ErieInsurance',NULL,'<p>-To be used for operating expenses for the SSS but <strong>NOT SALARY OR FRINGE BENEFITS. </strong>For example, shelter supplies, furniture, resident expenses, necessities, utilities, maintenance, repairs, etc...</p>',NULL,5000.00,'2023-03-22','2023-06-30','yes','2024-02-21','<p>-Marketing and Advertising please reach out to givingnetwork@erieinsurance.com to request a logo for media acknowledgment.&nbsp;</p><p>-Benevity Portal may be used for the purposes of this contract.&nbsp;</p><p><a href=\"https://causes.benevity.org/user\">Sign in to the Benevity Causes Portal</a></p><p>Username- planner_caclv@caclv.org</p><p>Password-Planning2022!</p><p>-There are no reports due for this grant</p>',NULL,'2023-03-22 14:02:02','2023-03-22 14:03:49',NULL,140,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (156,'2023RTCLF_PCA','C960004436','<p>Administration-salary and fringe benefits for RTCLF staff</p>',NULL,75000.00,'2023-03-23','2028-06-30',NULL,NULL,'<p>-PCA funding must be acknowledged in all published materials and announcements related to the grant process. Use approved language located in Article VI of the contract.</p><p>-A minimum of 5 Creative Business Loans must be given out in the Lehigh Valley</p><p>-Please see ineligible uses located in Grant Award Exhibit A Section 1.</p><p>-Required Reports: Quarterly and Final year-end report</p>','6000','2023-03-22 17:41:51','2024-09-18 14:50:17',NULL,141,NULL);
