INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (158,'2023HRP_NCCDBG_HomeImprovementProgram',NULL,'<p>-Roof replacement and HVAC for Seniors and other eligible populations. Wrap around service plans for mold and mildew.</p><p>$136,000 for Replacements, Renovations and Home Improvements</p><p>-$34,000 for project delivery costs</p><p>Amendment for an additional $75,940 and extension of expiration date attached.</p>',NULL,245940.00,'2023-04-01','2025-01-30','yes','2025-01-14','<p>-Gross AMI of each applicant is not to exceed 80%</p><p>-Follow all open and competitive bidding requirements on page 6 of contract</p><p>-This is a reimbursable grant</p><p>-Semi-Annual Reports Due by October 30th and April 30</p><p>-Audit report needs to be submitted to DCED for each fiscal year of this agreement.</p>','F2975','2023-03-31 11:55:53','2025-01-17 20:44:21',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (159,'2023SSS_SylviaPerkinsCharitableTrust',NULL,'<p>Purchase furniture (2 sofas, 2 love seats) for apartments at the SSS.</p>',NULL,6456.00,'2023-03-31',NULL,'yes','2024-10-01',NULL,'1211','2023-03-31 13:31:22','2024-10-01 14:45:37',NULL,142,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (160,'2023HRP_PADCED_ARPACOVID19_WholeHomeRepairs','C000084605','<p>-Address habitability and safety concerns, provide measures to improve energy or water efficiency and make units accessible for individuals with disabilities.&nbsp;</p><p>-$2,348,544 for eligible Whole-Home Repairs</p><p>-$109,000 for administrative costs</p><p>-$272,000 for provisions and enhancements</p><p>-This is not a reimbursable grant, and we will be receiving all of the funds upfront.</p>',NULL,2729544.00,'2022-12-12','2026-12-31',NULL,NULL,'<p>-Money must be fully obligated by December 31, 2024.</p><p>-Funds must be kept in an interest-bearing account</p><p>-PA Prevailing Wage -Prime construction contracts in excess of $24,999 must pay PA prevailing wage&nbsp;</p><p>-Open and Competitive bidding procedures for any contract in excess of $10,000 (must have 3 arm length bids)</p><p>&nbsp;<strong>-COVID Impact Eligibility Question</strong></p><p>*The project/client is presumed eligible if the household is a low- or moderate-income household as defined by the State and Local Fiscal Recovery fund guidance.&nbsp; Per SLFRF, Low- or moderate-income households and communities are those with (i) income at or below 300 percent of the Federal Poverty Guidelines for the size of the household based on the most recently published poverty guidelines or (ii) income at or below 65 percent of the area median income for the county and size of household based on the most recently published data. **For households whose income exceeds the federal definition as defined above but falls within the WHR requirement for an eligible homeowner (household income not to exceed 80% of the area median income), the Grantee should document the Covid impact (“impacted or “disproportionately impacted”) using the attached FRAMEWORK FOR ELIGIBLE USES BEYOND THOSE ENUMERATED found within the SLFRF Final Rule Overview.</p><p>-All work needs to be done by a qualified contractor who is licensed and insured. Habitat for Humanity cannot use volunteers who do not meet this criterion.</p><p>&nbsp;</p><p><strong>***Update***</strong></p><p><strong>Program monitoring to take place in the Spring. A predetermined percentage of projects will be selected at random for review. Requested documents to include- project/ case files, invoices, proof of eligibility and photos.</strong></p>','7000','2023-04-03 12:29:06','2025-03-06 16:08:12',NULL,143,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (161,'2023RTCLF_TDBank_InvestmentAgreement',NULL,'<p>To provide financial support to primarily minority-owned or minority-managed businesses.&nbsp;</p>',NULL,1000000.00,'2023-05-01',NULL,NULL,NULL,'<p>-Interest rate of 2.0% annually</p><p>- &nbsp;During the interest payment only period, which is 5 years from the effective date, interest payments are due on April 1, July 1 and October 1 and January 1 of each year. This interest only period can be extended for an additional 3 years by providing written notice to the lender not more than 90 days or less than 30 days before the expiration of the interest only period.</p><p>-Principal and interest payments shall commence quarterly after the 5-year interest only period.</p><p>-Audit report required within 120 days of the Fiscal year end.</p><p>-Lender requires tax returns within 30 days of filling</p><p>-Reporting- By April 30th each year- provide summary of portfolio investments, watch list and delinquency reports, capitalization report, capital deployment report and social impact summaries. See page 4 Section 8 of the contract for more details.</p>',NULL,'2023-04-21 12:02:51','2023-04-21 12:15:18',NULL,144,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (162,'2023SSS_Provident Bank Foundation',NULL,'<p>\"Case Manager Expansion\" and will support the SSS building out the educational component of our programming. Funds will be used to support Craig Taylor\'s salary, professional development opportunities for him, and to cover the costs of the residents\' Hi-Set tests.</p><p>*Year 1: Case Manager Salary = $8,320 Professional Development / Training = $4,180 Reimbursement Fund = $2,500</p><p>**Year 2: Case Manager Salary: $8,320 Professional Development / Training = $1,680 Reimbursement Fund = $5,000</p>',NULL,15000.00,'2023-05-01','2025-04-30',NULL,NULL,'<p>*Two-year award for $15,000 annually ($30,000 total)</p><p><strong>**Year 1 Requirements:&nbsp;</strong></p><p>&nbsp;11/7/2023 – Interim Call&nbsp;</p><p>&nbsp;05/15/2024 – Final Report to be completed in the Provident Bank Portal</p><p>*** Major Promotion and Publicity: All copy and materials must have PBF’s approval prior to circulation—this includes, but is not limited to, print and social media or other marketing collateral. Our complete name, The Provident Bank Foundation, must be used. Additional information may be found on our online Grantee Press Kit, here: <a href=\"https://www.theprovidentbankfoundation.org/media/grantee-press-kit\">Grantee Press Kit (theprovidentbankfoundation.org)</a></p><p>****Leadership Changes: If leadership changes at your organization occur during the grant term, you must notify PBF in writing.</p><p><strong>***Year 2 Requirements:</strong></p><p>11/7/24- Interim Call</p><p>5/15/25- Final Report to be completed in the Provident Bank Portal</p><p>*** Major Promotion and Publicity: All copy and materials must have PBF’s approval prior to circulation—this includes, but is not limited to, print and social media or other marketing collateral. Our complete name, The Provident Bank Foundation, must be used. Additional information may be found on our online Grantee Press Kit, here: <a href=\"https://www.theprovidentbankfoundation.org/media/grantee-press-kit\">Grantee Press Kit (theprovidentbankfoundation.org)</a></p><p>****Leadership Changes: If leadership changes at your organization occur during the grant term, you must notify PBF in writing.</p><p>&nbsp;</p>','1214','2023-04-24 19:17:54','2024-05-13 17:38:58',NULL,89,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (163,'2023CALV_LC Aging and Adult Services','23-AGNG-142','<p>TEFAP-as authorized (.10 cents per pound of food distributed)</p><p>HAP Rental Assistance- $517,680</p><p>HAP Rental Assistance Care Management (Salary for Fiscal staff to process HAP Checks)-$28,328</p><p>HAP Aftercare Managment (SSS Case Management)- $35,543 (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 3,6, and 12 months)</p>',NULL,0.00,'2023-07-01','2024-06-30','yes','2024-07-01','<p>-Reimbursable Grant</p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served.</p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.</p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services</p><p>-Keep records for 7 years</p>','F4200','2023-04-24 19:36:05','2024-07-01 12:31:47',NULL,73,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (164,'2023SSS_LC Covid Relief Non-Profit Block Grant Program',NULL,'<figure class=\"image\"><img src=\"http://10.55.0.10/storage/197/image.png\"></figure>',NULL,25000.00,'2023-01-01','2024-12-31','yes','2025-06-27',NULL,'1212','2023-04-25 13:01:12','2025-06-27 16:43:23',NULL,145,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (165,'2022REJ_PMUWGenerationNext',NULL,'<p>PMUW will be initiating the Generation Next Program in the Pocono Mountain School District (PMSD) with the potential to expand into the other Monroe County School Districts such as Stroudsburg, East Stroudsburg and Pleasant Valley.</p><p>-Initial $15,000 to be paid up front.</p><p>-$5,500 to be invoiced annually between June and August if curriculum updates are provided for PMSD</p><p>-$3,000 to be invoiced annually between June and August if no curriculum updates are provided for PMSD</p><p>-Additional $2,000 invoiced annually for each additional school district&nbsp;</p><p>&nbsp;</p>',NULL,0.00,'2022-09-01',NULL,NULL,NULL,'<p><strong>Responsibilities of Gen Next Staff:</strong></p><p>-Provide Curriculum updates to PMUW each year between June and August</p><p>-Provide Data on past program outcomes, measurements and performance data</p><p>-Visit PMSD at least twice per year to provide training and support (If additional districts are added then two visits per district are required annually)</p><p>-Provide shadowing opportunities twice per year for PMUW Gen Next staff for training purposes</p><p>-One visit per year to PMUW main office to ensure confidentiality of student files and data</p><p>-Provide survey tools and resources for data collection</p><p>-Provide updated marketing and branding materials when they become available</p><p>-CALV Gen Next advisory board will provide support twice per year at mid-year and end of year</p><p>-Conduct a mid-year and end of year progress review/evaluation and provide feedback</p><p><strong>***Gen Next Staff will be responsible for invoicing PMUW each year for the appropriate fee</strong></p><p><strong>**** This MOU can be terminated at any time by either party withing 60 days of written notice</strong></p>',NULL,'2023-04-26 14:50:33','2023-04-26 14:57:08',NULL,115,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (166,'2022SHFB_NCCDBGCV_Fresh Food Program',NULL,'<p>Purchase of food (consumable food supplies) for mobile pantries, drive thru pantries, senior food programs, SNAP application assistance, summer meal programs, backpack programs, school pantry programs and kids\' cafe in Northampton County <strong>- $55,000</strong></p><p>Salary and Fring benefits<strong>-$10,000</strong></p>',NULL,65000.00,'2022-10-01','2025-03-31',NULL,NULL,'<p>-Reimbursable grant-provide itemized invoices and vouchers monthly</p><p>-Use of competitive bidding requirements for expenditures over $5,001 in one transaction</p><p>-Reporting Requirements- semi-annual reports due May 15, 2023 (October1-April 30th) and November 15, 2023 (May 1st- October 30th)</p><p>-Audit is required for this grant</p><p>-County Contact is Frank Brooks</p><p><strong>Direct line (610) 829-6311</strong></p><p><a href=\"mailto:fbrooks@northamptoncounty.org\"><strong>fbrooks@norcopa.gov</strong></a></p>','F8091','2023-04-28 17:14:52','2024-11-07 18:13:12',NULL,2,'14.218');
