INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (171,'2023REJ_PPL',NULL,'<p>General Operating support GEN Next and SHE 50/50 split.</p>',NULL,10000.00,'2023-05-16',NULL,'yes','2024-10-01','<p>-Recommended Advertising Opportunity-PPL encourages us to tell others about this grant award via social media and other methods. Tag them on your posts by mentioning <strong>@PPLCorp</strong> and <strong>@PPLElectric</strong> and use the hashtag <strong>#pplcares.&nbsp; </strong>The PPL Foundation logo is available to download <a href=\"https://www.pplweb.com/logo-downloads./\">here</a>.</p><p>&nbsp;</p><p>-There is a report required that will be available 8/23/23 and due 8/24/24.<br><a href=\"https://www.cybergrants.com/pls/cybergrants/ao_login.login?x_gm_id=6446&amp;x_proposal_type_id=47788\">PPL Foundation - Log In (cybergrants.com)</a></p><p>username: jgimpert@caclv.org</p><p>password: Caclv1337!</p>',NULL,'2023-05-15 16:05:03','2024-10-01 14:34:07',NULL,82,NULL);
