INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (173,'2023HRP_NCDCEDARPA_SeniorHomeMaintenance Roofing and Furnace Program',NULL,'<p>-Maintenance on 12 Senior Homes to include roof replacements, heating units, electrical panel/circuit breaker, removal of mold and mildew from leaky roofs and mobility concerns.&nbsp;</p><p>-Budget-$250,000 for Rehabilitation and Renovation-<strong>from this we may invoice, using the term \"Program Delivery\", 15-20% for HRP staff that deal directly with the project and up to 5% for admin. such as fiscal staff, compliance, etc...</strong></p>',NULL,250000.00,'2023-05-18','2025-12-31',NULL,NULL,'<ul><li>This is a reimbursable grant.</li><li>Adherence to Domestic Content Procurement Preference (page 5)</li><li>Open and Competitive Bidding Requirements (Page 5 Section 21-26)</li><li>Fiscal Year audit results to be sent to DCED</li><li>HUD Forms at the end of the contract to be used in cases of contracts more than $24,999.</li><li>There are no reports due for this contract although&nbsp;detailed case files to be kept on each project and should include Environmental Clearance and Income Eligibility Review</li></ul>','F2985','2023-05-16 14:57:41','2025-03-06 16:08:29',NULL,148,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (174,'2023HRP_NCDCEDARPA_ResidentialLeadHazardAbatementProgram',NULL,'<figure class=\"image\"><img src=\"http://10.55.0.10/storage/232/image.png\"></figure>',NULL,1000000.00,'2022-05-18','2025-12-31',NULL,NULL,'<p>-<strong>Other Specifications- </strong>Property must be owner occupied, constructed before 1978, occupied by 1 child under 6 years old or a pregnant woman or visited by a child under 6 at least 60 hours per year, below 80% AMI, blood test screening or waiver/affidavit required. Up to $24,999 of lead hazard abatement assistance may be provided to any one household.&nbsp;</p><ul><li>Please see page 31- 52 Contract Clauses Required for all CDBG Construction Grants</li><li>This is a reimbursable grant.</li><li>Adherence to Domestic Content Procurement Preference (page 5)</li><li>Open and Competitive Bidding Requirements (Page 5 Section 21-26)</li><li>Fiscal Year audit results to be sent to DCED</li><li>Attachment E Section 3 Guidelines</li><li>HUD Forms at the end of the contract to be used in cases of contracts more than $24,999.</li><li>There are no reports due for this contract although&nbsp;detailed case files to be kept on each project and should include Environmental Clearance and Income Eligibility Review</li></ul>','F0640','2023-05-16 15:02:08','2025-03-06 16:09:34',NULL,148,'21.027');
