INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (180,'2023SHFB_FASheetzfortheKids',NULL,'<p>Kids hunger initiatives- school pantries.</p><p>&nbsp;</p>',NULL,7000.00,'2023-05-01','2023-11-30','yes','2024-02-21','<p>-Social Media acknowledgment, media stories, press releases and testimonials are highly encouraged and asked for in the regular reporting cycle.</p><p>Per donor request and as stated in the grant award notification, as a grant recipient, your food bank is required to submit a minimum of one (1) testimonial &amp; photo of a child impacted by this grant funding.&nbsp; &nbsp;</p><ol><li>Please provide and/or upload <strong>stories, testimonials, photographs, and children’s artwork</strong> illustrating the effect of your program.&nbsp; Please also upload any photographs and/or video footage of employee events/activities.&nbsp;Please upload release forms with photographs and videos, if they are available.&nbsp; If not, Feeding America will assume that they are for our internal use only and can be shared with the donor for its internal use only.</li></ol>','8016','2023-05-18 17:11:59','2023-07-20 18:24:25',NULL,149,NULL);
