INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (182,'2023SHFB_UrbanAgriculture_Seed Farm',NULL,'<p>Capacity building for the Seed Farm. Greenhouse purchase and construction, growing partner materials, seeds, transplants, construction of raised beds, delivery of transplants to growing partners.</p><p><strong>Equipment: $12,953.90</strong></p><p><strong>Supplies: $6,501</strong></p><p><strong>Contractual: $8,300</strong></p>',NULL,27754.00,'2022-07-01','2024-06-30','yes','2024-09-23','<p>**This is a reimbursable grant.</p><p>*** Grant funds may not exceed 85% of the total project cost a minimum match of $4, 897.93 must be shown.</p><p>****Upon completion of your project, you must submit a final report with your invoice. Invoice will not be paid without a report. Final Report template and reimbursement template is attached. Reimbursement request must come with the receipts showing the expenses and must be dated within terms of the contract. These items will only be accepted electronically via a PDF. Reimbursement and reports must be sent to this email address for prompt review and process of reimbursements. <a href=\"mailto:ra-agpafarmbillgrant@pa.gov\">ra-agpafarmbillgrant@pa.gov</a></p>',NULL,'2023-05-22 15:18:27','2024-09-23 16:36:01',NULL,150,NULL);
