INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (187,'2023SSS_City of Allentown Lead Abatement Paperwork',NULL,'<p>Paperwork signed by Dawn for the Lead Risk Assessment and Abatement at the SSS by the City of Allentown.</p>',NULL,0.00,NULL,NULL,'yes','2025-06-27',NULL,NULL,'2023-06-06 17:32:28','2025-06-27 16:43:53',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (188,'2023CADA_EDSI_Paid Work Experience Worksite Agreement',NULL,'<p>This contract does not generate revenue for CADA.</p><p>This contract sets up an agreement between CADA and EDSI in conjunction with Workforce Board Lehigh Valley to provide paid work experience to youth in Allentown.</p><p>This program will take place at 215 North 9th Street and be supervised by Pas Simpson of Big Happy Consultants.</p><p>&nbsp;</p>',NULL,0.00,'2023-06-06',NULL,NULL,NULL,'<p>Compliance:</p><p>-1 supervisor-12 participants</p><p>-Cooperation with PA CareerLink to provide training and education</p><p>-Assess participants with pre and post testing with a Work Readiness Attainment Rating sheet and provide testing to EDSI</p><p>-Summer Youth Program shall not exceed 8 wees continuously and no more than 30 hours a week inclusive of lunch and breaks.</p><p>-Time and attendance signed by participant and supervisor is required to be turned into PA Career Link Lehigh Valley and EDSI staff on a weekly basis.</p>',NULL,'2023-06-09 13:33:01','2023-06-09 13:35:31',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (189,'2023SHFB_FACostcoFoodPurchase',NULL,'<p>-Purchase food from Costco\'s to primarily support rural and or communities of color.</p><p>-Social Media acknowledgment, media stories, press releases and testimonials are highly encouraged and asked for in the regular reporting cycle.</p><p>&nbsp;</p>',NULL,40625.00,'2023-06-01','2024-02-29','yes','2024-10-15','<p>Reporting:</p><p>Initial Progress Report due October 31, 2023, covering June 1, 2023- September 30, 2023.</p><p>Final Report due March 19th, 2024, covering entire grant period of June 1st, 2023- February 29, 2024.&nbsp;</p><p>****Final report will only be required if the funds were not fully expended by the initial progress report.</p><p>Information to be collected:</p><p>-Confirmation of fund expenditures, purchase (quantity and description) tracked by food category, pounds and costs, description of programs supported by the purchases, grant impact, stories and testimonials.</p><p>&nbsp;</p>','8061','2023-06-09 13:56:38','2024-10-15 12:14:31',NULL,149,NULL);
