INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (199,'HUD Approval As Housing Counseling Agency',NULL,'<p>HUD Certification Documents post HUD review.</p><p>HCS Certification #81337</p>',NULL,0.00,'2023-07-01','2026-07-11',NULL,NULL,NULL,NULL,'2023-07-19 11:53:41','2023-07-19 11:53:41',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (200,'2023HRP_Dual Temp Air Conditioner Initiative',NULL,'<p>HRP will purchase 20 window air-conditioning units at $250 a piece and be reimbursed by Dual Temp in the amount of $5000 within 30 days of receipt of invoice.</p><p>HRP will assess the location for compatibility with the air-conditioning unit and select recipients for this program from existing clients.</p><p>Upon receipt of referral, Dual Temp will pick up AC unit, install at location and train the client on usage.</p><p>Dual Temp is volunteering its time and labor for this initiative.</p>',NULL,5000.00,NULL,NULL,NULL,NULL,NULL,NULL,'2023-07-19 12:41:40','2023-07-19 12:42:20',NULL,156,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (201,'2023SF_PNLV',NULL,'<p>-Promise Neighborhoods of the Lehigh Valley will be granted the use of 1/8th acre of land in exchange for PNLV Promise Corps members providing volunteer labor towards the general upkeep of the Seed Farm as described in the MOA.</p><p>-This MOA will automatically renew each year as long as all the terms and conditions listed in the MOA are met. This MOA can be terminated by CALV permanently if PNLV fails to abide by the terms and conditions.</p>',NULL,0.00,'2023-07-11','2023-12-31','yes','2024-02-21',NULL,NULL,'2023-07-20 16:58:35','2023-07-20 16:59:48',NULL,157,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (202,'2023HCPHRP_WellsFargoFoundation',NULL,'<p>General operating expenses for HCP ($15,000) and HRP ($10,000).</p><p>Impact report TBD.</p>',NULL,25000.00,'2023-07-20',NULL,'yes','2024-10-01',NULL,'8000','2023-07-21 14:36:11','2024-10-01 14:50:12',NULL,158,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (203,'2023SSS_LCC&Y','23-CY-084','<p>Daily Apartment Rate=$65</p><p>Supportive Services Rate/Case Management=$62 per hour</p><p>Extraordinary Expenses for damages per agreed cost (must get prior approval and provide receipt for damages or repair)</p><p>Curfew Cheks-1 hour per day at $62</p><p>SHIFT rate= $60 per hour</p><p>Family Emergency Fund- $9,375 per receipt for move in expenses for SHIFT clients.</p><p><strong>*This grant is reimbursable.</strong>&nbsp;</p><p>**Daily apartment rate, Supportive Services, Curfew Checks and SHIFT rate <strong>billed monthly</strong> with appropriate signed logs and back up</p><p>*** Family Emergency fund reimbursable per instance with proper receipts and backup</p><p>****Extraordinary Expenses reimbursable per instance with proper receipts and backup</p>',NULL,0.00,'2023-07-01','2024-06-30','yes','2024-08-09','<p><strong>Other requirements</strong>-Case Workers are required to take 12 hours of training per year.</p><p><strong>Reporting Requirements:</strong></p><p>-Monthly reports with invoice as usual with apartment occupancy and case managements times accompanies by signed logs</p><p>-Quarterly Numbers as requested by Children and Youth (they send out an email request)</p><p>-Semi-Annual Reports and Final Report (they send out an email request)</p><p>-Outcome reports due Mid-January for July 1-December 2023 and July 1st for January- June 2024 (send this to Sharon Dunn)</p>','1300','2023-07-24 19:32:12','2024-08-09 13:44:00',NULL,159,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (204,'2023SSS_TJX Foundation',NULL,'<p>-General Operating SSS.</p><p>-NO restrictions or reporting requirements.</p><p>-Was included in the budget for FY2023-2024</p>',NULL,10000.00,'2023-07-25',NULL,'yes','2024-10-01',NULL,'8000','2023-07-26 18:13:03','2024-10-01 14:46:41',NULL,131,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (205,'2022-2025SHFB_ USDA Feeding PA_LFPA_ MOU',NULL,'<p>The Pennsylvania Local Food Purchase Assistance Cooperative Agreement Program (PA-LFPA) will work with Pennsylvania’s local food system to procure top-graded, high-quality products for distribution through the charitable food system serving all 67 of Pennsylvania’s counties. PDA will distribute food products produced in-state with a goal of reaching at least 1 million low-income households by working with at least 40 farms, producers, and food companies, including at least 10 vendors which identify as underserved and at least 10 direct-to-agency delivery partnerships.</p>',NULL,0.00,'2023-07-27','2025-12-31',NULL,NULL,'<p>-All purchases must be made or committed to by <strong>July 31, 2025.</strong></p><p>-Final invoices to be submitted on or before <strong>August 10, 2025</strong></p><p>-All services must be complete by <strong>November 1, 2025</strong></p><p>Reports due to tmainzer@feedingpa.org by the 10th calendar day of the following month until program completion.&nbsp;</p><p>Reports should include:</p><ul><li>Expense and Reimbursement Reports in Microsoft Excel Format</li><li>Product Info (including source, types, unit cost)</li><li>Pounds of food distributed</li><li>Address and manner of distribution</li><li>Number of households served</li></ul><p>SHFB must also obtain written testimonials and feedback from member agencies, clients and agriculture partners.</p>','4701','2023-07-27 14:45:07','2025-02-06 17:01:00',NULL,165,'10.182');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (206,'2023-2024SHFB_Feeding PA_PASS_MOU',NULL,'<p>The Pennsylvania Agricultural Surplus System (PASS) program was designed to support Pennsylvania’s agricultural industry statewide – to reduce waste of surplus product, support local farms, and getting more nutritious food into the hands of Pennsylvanians at risk of hunger. Food must be grown or produced in PA.</p><p>-Assigned Counties- Carbon, Lehigh, Monroe, Northampton, Pike and Wayne</p><p>-Pass Supplier will ensure that PASS Funding is allocated for all 67 PA counties in accordance with the approved SFPP Allocation ratios for FY 2023-2024. <strong>It is the responsibility of the PASS Subcontractor to carry out these allocations and distribute product at a value as close as possible to the dollar values allocated to their assigned counties.&nbsp;</strong></p>',NULL,0.00,'2023-07-27','2024-12-31','yes','2024-07-18','<p>-SHFB representative must attend a bi-weekly conference call led by Feeding Pennsylvania\'s Director of Agricultural Partnerships to provide updates on food sourcing and distributions using PASS funds.</p><p>-All purchases and commitments must be made by <strong>June 30, 2024</strong></p><p>-All documentation of purchases and commitments must be submitted by <strong>July 10, 2024</strong></p><p>-All services must be complete by <strong>August 15, 2024</strong></p><p>-SHFB must distribute 50% or more of their total funding allocation by <strong>December 31, 2023</strong>.</p><p>-Monthly reports should be emailed to tmainzer@feedingpa.org by the 10th day of the following month until program completion.</p><p>Reports should include:</p><ul><li>Source of product</li><li>Product type and unit cost</li><li>Pounds of food distributed</li><li>Address and manner of distribution</li><li>The number of households served</li><li>Expense and Reimbursement reports in Microsoft Excel format</li></ul><p>SHFB is also required to obtain written testimonials and other feedback from member Agencies, clients and agriculture partners.</p>',NULL,'2023-07-27 14:58:19','2024-07-18 18:50:05',NULL,165,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (207,'2023SBR_ GLV ChamberofCommerce',NULL,'<p>-Support for the Kayak Project in Portland</p>',NULL,2000.00,'2023-07-01','2024-12-31',NULL,NULL,'<p>-Reporting Requirements:</p><p>Submit before and after photos of the project by June 30, 2024. (Report to -Lorie Reinert lorier@lehighvalleychamber.org)&nbsp;</p><p>-Submit payment reimbursement request together with $4,000 expenses receipts. $2,000 from CALV and $2,000 from the matching source (Portland Borough) Total project cost =$4,000 (Reimbursement request to -Lorie Reinert lorier@lehighvalleychamber.org)</p>','F2995','2023-07-28 13:54:47','2024-10-16 15:23:21',NULL,160,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (208,'2023SHFB_FirstEnergyFoundation',NULL,'<p>General operating for SHFB.</p><p>&nbsp;</p>',NULL,5000.00,'2023-07-01',NULL,'yes','2024-10-24','<p>Reporting-</p><p>On 91/2023 planner-SHFB@calv.org will receive an email requesting a short evaluation report which we will have 30 days to complete.</p><p>Please touch base with Briana McGonagle for this email with instructions for the evaluation (how the money was used or benefited SHFB).</p>','8000','2023-07-28 16:45:05','2024-10-24 13:27:53',NULL,161,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (209,'2023CADB_WindCreek',NULL,'<p>-General operating support CADB.</p><p>-There are no reporting requirements at this time.</p>',NULL,20000.00,'2023-07-25',NULL,'yes','2025-06-27',NULL,NULL,'2023-07-31 17:11:13','2025-06-27 16:46:24',NULL,162,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (210,'2023HCP_PHFA_PHARE',NULL,'<p>Salary and benefits HCP and admin expenses for first time homebuyer seminars.</p><p>Please see attached PHARE Budget (included in the contract upload) for more details.</p><p>-`30% of the grant to assist households below 50% AMI.</p><p>-No amount of the grant will be used to assist households with AMI greater than 200% AMI</p><p>&nbsp;</p><p>Extension given until May 31, 2026.</p>',NULL,40000.00,'2023-09-07','2026-05-31',NULL,NULL,'<p>-Semi-Annuals reports due by January 31st and July 31st until funds are expended. Reports are available 90 prior to the due date.</p>','F0618','2023-07-31 18:28:55','2025-06-03 11:34:28',NULL,99,NULL);
