INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (218,'2023HRP_LVCF_Downtown Allentown Community Initiative Fund',NULL,'<p>-Restricted grant to be used for the Hamilton Street Facade Program</p><p>-When reporting or acknowledging this grant, you refer to it as “a grant from the Downtown Allentown Community Development Initiative Fund of the Lehigh Valley Community Foundation.”</p>',NULL,135116.21,'2023-08-14',NULL,NULL,NULL,NULL,'4900','2023-08-14 19:38:40','2023-12-05 16:30:51',NULL,167,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (219,'2023SHFB_FA_EmployeeEngagementSurvey','219','<p>The goal of this grant is to subsidize the incremental cost for partner food banks to contract with a third-party (Quantum) directly to conduct FY24 Employee Engagement Surveys. Previously, FA managed the Employee Survey Initiative. This grant will be used by FA to determine the best way to conduct this annual research project moving forward.</p><p>This grant will be awarded in a lump sum payment and is restricted for use only on the Employee Engagement Survey.</p><p><strong>Grant Activities/Expectations</strong></p><p>Grantees will be responsible for contacting Quantum and partnering with them directly on their employee engagement survey in FY24. A link to initiate the process will be provided to grantees when the grant is awarded.</p><p>The preferred rates will cover Quantum’s Signature Service, which includes:</p><ul><li>1:1 onboarding and setup</li><li>HRIS integration and SSO</li><li>Assistance in yearly engagement survey administration</li><li>Dedicated CSM</li><li>Ongoing touchpoints</li><li>Bi-annual strategic business reviews</li><li>1:1 admin training</li><li>Open invite group webinars</li><li>Help library of videos and guides</li><li>Engagement survey toolkit</li><li>Email, chat, phone support for admins and all users</li></ul><p>Members have the option of upgrading to the Signature Plus package, which includes a 60-minute Strategic Insights Report for an additional $2,500 at the member’s expense.</p><p>All grantees are required to use a consistent core set of questions for benchmarking purposes. Additional survey questions can be added and customized.&nbsp;</p><p>Participating members will be able to conduct their annual engagement survey at a time/location most appropriate for them.</p><p>There is no report due for this grant.</p><p>Contact is Lindsey Iero liero@feedingamerica.org</p>',NULL,3350.00,'2023-07-01','2024-06-30','yes','2025-05-20',NULL,'F4652','2023-08-24 11:24:53','2025-05-20 16:47:11',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (220,'2023RTCLF_Santander',NULL,'<p>General Operating RTCLF</p>',NULL,10000.00,'2023-10-01','2024-09-30','yes','2024-11-12','<p>-6-month grant report due April 30, 2024</p><p>-Final report- November 15, 2024</p><p>-Recognition of Santander through social media or other publications is highly recommended. Please see Consent to Use Trademark uploaded here.</p>',NULL,'2023-08-29 17:52:13','2024-11-12 13:48:50',NULL,105,NULL);
