INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (222,'2023RTCLFHRPHCP_Bank of America',NULL,'<p>General operating expenses:</p><p>RTCLF - $3,000</p><p>HCP - $4,000</p><p>HRP - $3,000</p><p>&nbsp;</p>',NULL,10000.00,'2023-08-30',NULL,'yes','2024-10-01','<ul><li>Social media thank you is recommended. Limited trademark usage agreement signed.</li></ul>',NULL,'2023-08-30 17:50:45','2024-10-01 14:50:22',NULL,169,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (223,'United Way of Lackawanna and Wayne Counties Military Share','223','<p>The goal of this grant is to support the Military Share distribution in Wayne County at the Hamlin Assembly of God distribution site (25 boxes).</p><p>A report will be due at the end of the grant period. More information, template, and report due date will be forthcoming.</p><p>Application/Report: https://agency.e-cimpact.com/login.aspx?org=40520F&nbsp;<br>(UN: Briana.McGonagle PW: Shfb6969!!$$)</p><p>A campaign kick-off event will be held on 9/19.</p><p>Contact is&nbsp;</p><p>William Craven<br>Manager of Community Impact Funds<br>(570) 343-1267 ext. 226<br>wcraven@uwlc.net</p>',NULL,4000.00,'2023-08-30','2024-06-30','yes','2025-05-20',NULL,'8051','2023-08-31 13:16:39','2025-05-20 16:49:01',NULL,95,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (224,'2023-2024CALV_ Keystone Communities Development Grant',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,'2023-09-05 12:39:33','2024-10-24 15:19:36','2024-10-24 15:19:36',170,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (225,'2023CADB_BethlehemCDBG_Friendship Park Residential Facades',NULL,'<p>-$3,000 for salary (Amendment 2 allows for full grant amount to be used for construction hard and soft costs)</p><p>-$27,000 for construction costs&nbsp;</p><p>Funds to be used to improve at least 2 residential facades in the Friendship Park Target Area.</p>',NULL,30000.00,'2023-01-01','2024-12-31','yes','2025-06-27','<p>-Quarterly Reporting through Neighborly Portal</p><p>-Reimbursable Grant- see Attachment A of contract</p><p>-See Guidelines for grant terms and eligible improvements</p><p>-Payment must go directly to contractor</p><p>-Rental units benefiting from CDBG dollars must be occupied at an affordable rent and we must maintain documentation</p><p>-We must income qualify applicants</p>','2142','2023-09-07 14:31:18','2025-06-27 16:44:28',NULL,171,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (226,'2023SHFB_FA_CVS General Operating Funds',NULL,'<p><strong>Purpose:</strong></p><p>This grant supports SHFB\'s Retail Recovery Initiative. CVS General Operating Funds will be used for salary and benefits for SHFB\'s Retail Recovery Coordinator at $21,210.19 per year for two years, totaling $42,420.38.</p><p>Grant period is from 8/1/2023 - 7/31/2025.</p><p>Two reports are due via the Feeding America Grants Management System:</p><p>Year 1 Final Report Deadline, Tuesday, September 10, 2024<br>Year 2 Final Report Deadline, Tuesday, September 9, 2025</p><p>SHFB commits to:</p><ul><li>Engaging a group of CVS employees in at lease one volunteer activity per year</li><li>Hosting a CVS meeting/event at SHFB</li><li>Publicly recognizing the support of CVS through social media, print publications and a check presentation event at the SHFB.</li></ul>',NULL,42420.38,'2023-08-01','2025-07-31',NULL,NULL,NULL,'8018','2023-09-11 12:36:05','2023-09-29 18:19:39',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (227,'2023SHFB_PATEFAP_ Management Agreement','227','<p>This agreement between SHFB and the PA Dept of Agriculture (PDA), establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;</p><p>The program directs SHFB in the receipt of food provided by PDA/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the Counties in Eastern PA.</p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.</p><p>This is a <strong>reimbursable grant</strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms.</p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.</p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.</p>',NULL,0.00,'2023-10-01','2028-09-30',NULL,NULL,NULL,'1188','2023-09-13 13:30:13','2023-09-19 12:08:28',NULL,172,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (228,'2023SHFB_CarbonCountyTEFAP','228','<p>This agreement between SHFB and Carbon County establishes the terms and conditions for SHFB to provide TEFAP services to Carbon County.</p><p>SHFB must prepare a budget for the fiscal period of 10/1/2023 - 9/30/2024 identifying estimated operating costs for the distribution of Federal and State issued food commodities, using the following Allowable Costs line items as determined by PDA.</p><ul><li>Storage costs</li><li>Transportation Costs</li><li>Equipment Rental Costs</li><li>Printing/Copying Costs</li><li>Administrative Costs</li></ul><p>Services provided from 10/01/2023 - 9/30/2024 will be reimbursed at $.12 per lb distributed.</p><p>Invoices are required quarterly as follows:</p><ul><li>Invoice #1 for (10/01/2023-12/31/2023); Due: <strong>01/20/2024</strong></li><li>Invoice #2 for (01/01/2024-03/31/2024); Due: <strong>04/20/2024</strong></li><li>Invoice #3 for (04/01/2024-06/30/2024); Due: <strong>07/20/2024</strong></li><li>Invoice #4 for (07/01/2024-09/30/2024); Due: <strong>10/20/2024</strong></li></ul><p><strong>NOTE</strong>: The invoice shall be accompanied by a completed TEFAP INVENTORY/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \"TEFAP INVENTORY/PARTICIPATION REPORT\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED.</p><p>Contact:</p><p><strong>Cindy Bizarre</strong><br>401 Delaware Avenue, Third Floor<br>Palmerton, PA &nbsp;18071<br>Phone: 1-800-441-1315 ext. 4511 or 610-824-7830 ext. 4511<br>Fax: &nbsp;610-824-7836<br>Email: &nbsp;cbizarre@ptd.net</p><p>&nbsp;</p>',NULL,0.00,'2023-10-01','2024-09-30','yes','2025-07-10',NULL,'1189','2023-09-13 18:37:00','2025-07-10 11:23:19',NULL,173,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (229,'2021RTCLF_CDFI_RRP','21RRP056787','<ul><li>Used to create small business loans</li><li>Financial Statement Audit Report required</li><li>In AMIS submit; Transaction Level Report, Performance progress report, Uses of Award Report and Annual Certification Report</li></ul>',NULL,1000000.00,'2021-06-15','2023-06-30','yes','2024-02-21',NULL,NULL,'2023-09-21 14:04:26','2023-10-13 16:46:38',NULL,174,'21.024');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (230,'2020RTCLF_CDFI_TA','201TA054558','<p>-Technical assistance fund, salaries, advertising, printing, travel, equipment, etc.</p><p>-Requires proof of matching funds</p><p>&nbsp;</p>',NULL,125000.00,'2020-09-24','2023-12-31','yes','2024-02-21',NULL,NULL,'2023-09-21 14:13:27','2023-10-13 16:52:54',NULL,174,'21.024');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (231,'2023-2024REJ_ScholarBlueprint_SATPrep',NULL,'<ul><li>CALV will be making three payments to Rosalind Lucien of The Scholar Blueprint, for SAT Prep services, on the following schedule pending the receipt of a proper invoice:<ul><li>$7,000 DISBURSED BY 1/5/23</li><li>$7,000 DISBURSED BY 3/15/23</li><li>$7,000 DISBURSED BY 6/7/23</li></ul></li></ul>',NULL,0.00,'2023-09-21','2024-06-30','yes','2024-12-05','<p>-The contractor (Rosalind Lucien) will provide SAT Prep courses to Generation Next Students in Liberty, Easton Area and Freedom High School according to the schedule outlined in the MOA. Scope of services provided by the contractor are outlined in the MOA.</p><p>-Please read the MOA for CALV scope of administrative support</p>',NULL,'2023-09-25 16:41:20','2024-12-05 18:53:48',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (232,'2023SHFB_Sanofi_SeedFarmMilitaryShare','232','<p>This grant provides $9,000 in funding: Funds will be used to support the purchase and distribution of food for the MilitaryShare program ($4,500) and supplies for The Seed Farm ($4,500).</p><p>Funds must be used by 12/31/2023.</p><p>SHFB has agreed to acknowledge the contribution from Sanofi on our social media platforms.</p><p>SHFB has offered to host a volunteer event for Sanofi employees. More information is available to them on volunteermark.com/shfb or contacting Allison Czapp at aczapp@calv.org .</p><p>There is no reporting requirement for this contract.</p><p>Two distinct funds have been established:</p><p>F8042 - $4,500 Supplies for The Seed Farm</p><p>F8052 - $4,500 MilitaryShare</p>',NULL,9000.00,'2023-09-27','2023-12-31','yes','2024-02-21',NULL,'F8042(SeedFarmSANOFI) F8052(MilitaryShareSANOFI)','2023-09-29 15:48:56','2023-09-29 16:01:31',NULL,119,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (233,'2022SHFB_SpecialtyCropBlockGrant','233','<p>The purpose of this grant is to increase the sale of specialty crops through Farmers Market Nutrition Program (FMNP) checks distribution and redemption in Lehigh and Northampton Counties.</p><p>This grant runs from 9/30/2022 - 6/30/2025. This is a <strong>reimbursable </strong>grant. Grant is not to exceed $50,478.00.&nbsp;</p><p>***** Budget and Project Revision submitted and accepted by the state. Project completion deadline is <strong>September 30, 2025. See the amended plan below.</strong></p><p>Information on reporting is pasted below. <strong>Final report is due by October 30, 2025</strong>.</p><p>SHFB has committed to helping increase redemption of FMNP checks by 10% over 2021 levels.</p><p>SHFB will implement outreach initiatives including printed materials, event attendance, pop-up markets, and an online information portal. Specific activity details are available in the 2022 SCBGP State approved plan, linked below.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/444/image.png\"></figure><p>The budget for this grant is as follows:</p><p>Personnel: <strong>$32,760</strong> (Salary for Local Food Sourcing Coordinator and Operations Manager)<br>Fringe: <strong>$3,486</strong><br>Supplies: <strong>$9,993</strong><br>Contractual: <strong>$500</strong><br>Indirect: <strong>$3,739</strong><br><strong>TOTAL: $50,478.00</strong><br>&nbsp;</p><p>&nbsp;</p>',NULL,50478.00,'2022-09-30','2025-09-30',NULL,NULL,NULL,'8070','2023-10-04 16:02:15','2025-07-02 18:28:31',NULL,172,'10.170');
