INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (243,'2023SHFB_DEPFoodRecoveryInfrastructure','243','<p>This grant is from the PA Dept of Environmental Protection, for the purchase of warehouse equipment.</p><p>This is a reimbursable grant, not to exceed <strong>$47,488.00</strong>.</p><p>Unique invoices must be submitted for every purchase. Disbursement request forms will be forwarded by Berit Case (bcase@pa.gov).</p><p>Project completion deadline is June 30, 2024. &nbsp;There is no report due.</p><p>The original quote came in higher than the actual cost. SHFB applied to the state to spend the remaining funds on caster wheels. That spending was approved per the below email.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/472/image.png\"></figure><p>The original quote came in higher than the actual cost. SHFB applied to the state to spend the remaining funds on caster wheels. That spending was approved per the below email.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1653/image.png\"></figure>',NULL,47488.00,'2022-07-01','2024-06-30',NULL,NULL,NULL,NULL,'2023-10-18 11:38:19','2025-05-20 16:54:25',NULL,185,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (244,'2020SBR_NCGrow Norco',NULL,'<ul><li>Requires matching funds.</li><li>Open and competitive bidding requirements (Pages 4-5)</li><li>Money to be used for Rehabilitation and Renovations; facade improvements (commercial and residential) and murals in Wind Gap, Pen Argyl, Bangor and Portland</li><li>See Residential Facade Program Guidelines and Procedures for eligible improvements and applicant qualifications in the original contract.</li></ul>',NULL,50000.00,'2020-11-21','2025-12-31',NULL,NULL,NULL,'F0820','2023-10-23 15:03:42','2024-09-13 15:40:38',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (245,'2021SBR_NCHotel Tax-Slate Belt Marketing and Promotions',NULL,'<p>-$2,500 for wayfinding and directional signage</p><p>-$7,500 for Marketing and Advertising</p><p>-$2,500 in matching funds required</p><p>-Reimbursable grant</p>',NULL,10000.00,'2021-11-01','2023-12-31','yes','2024-02-21',NULL,NULL,'2023-10-23 15:34:49','2023-10-23 15:34:49',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (246,'2023HRP_NCDCEDARP_Western Area Food Hub',NULL,'<p>-Walk in freezer, upgrades to the facilities (upgrades can include but are not limited to: energy efficient lighting, pallet lift, and energy efficient refrigerators) in the Northampton Area Food Bank.</p><p>-Open and Competitive Bidding Requirements (page 5 section 19)</p><p>-Reporting of Financial Information and program activities when requested</p><p>&nbsp;</p>',NULL,300000.00,'2022-10-01','2025-12-31',NULL,NULL,'<p>-Any materials funded under this agreement must have the following acknowledgement (Page 9 section 47)</p><p>&nbsp;</p><p>47. The financial assistance provided by the CITY, as well as, any state or federal sources related to this AGREEMENT, must be acknowledged as follows:&nbsp;</p><p>A. Any materials funded under this AGREEMENT must have the following acknowledgement citation (“This project is being supported, in whole or in part, by federal funds awarded from the Coronavirus State Fiscal Recovery Fund to Northampton County by the U.S. Department of Treasury”) on any material(s) created.&nbsp;</p><p>B. Acknowledgement examples include: improvements to public facilities that were planned, purchased, constructed, renovated, and/or rehabilitated under this AGREEMENT shall include the acknowledgement citation on permanent signage at the public facility where it can be readily viewed by the public. Doc ID: 0e5553f59477c5717c91b6b662e7ae54ac051bdc 10 | Page C. Events planned or conducted under this AGREEMENT shall include the citation as listed in #46(a) above in any marketing materials. D. Operational support that is subsidized under this AGREEMENT shall include the citation acknowledgement being referred to at events and included within any organizational and donor recognition publications</p>','F2940','2023-10-23 16:51:37','2024-09-16 16:30:57',NULL,2,'93.498');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (247,'2020SHFB_SFPP_LehighCounty','247','<p>The State Food Purchase Program (SFPP) for Lehigh County provides funds for the purchase, transportation, storage and distribution of food to program participants in Lehigh County who self-identify as 150% or more below the poverty level using the TEFAP Self-Declaration of Need form.&nbsp;</p><p>The 2020 SFPP Contract extends through June 30, 2025.</p><p>The initial program award for Lehigh County is $553,453.44 for the period July 1, 2020 - June 30, 2021. In each subsequent Program years, PDA shall provide written notice of the maximum grant amount awarded. For 2023, allocations are:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/484/image.png\"></figure><p>By July 1 of each calendar year of the Program, SFHB must deliver a Plan of Operation to PDA for how the funds will be allocated to partner agency food pantries across the service area. Previous plans can be found <a href=\"https://caclv.sharepoint.com/:f:/s/SecondHarvestFoodBank/ElpIq8Vg5ONPqypOHaeIjwAB54CkMCDGqSNtEleNTgaG-w?e=xfdnZK\">here</a>.&nbsp;</p><p>Allowable costs include:</p><ul><li>Purchase of food consistent with the PDA\'s Food Standard Guidelines for State Food Purchase program (below).</li><li>Processing and repackaging of food for distribution with prior approval by PDA</li><li>Transportation, storage fees and direct administrative costs of the Program, per PDA\'s maximum administrative allowance percentage.</li><li>Capital asset funds may be used to purchase capital equipment or develop new initiatives seeking to increase volumes of food available. More information on capital asset allowances can be found <a href=\"https://caclv.sharepoint.com/:b:/s/SecondHarvestFoodBank/EQqsv46YzjRDuR0W5MEYJXMBEPdL_4DpOCg9LZD-jYKZiw?e=YKKZ3A\">here</a>. (A capital expense allowance form is attached below.)</li></ul><p><strong>Reporting</strong></p><p><i>Annually</i>, SHFB must submit to PDA an Expense and Data Report for each program year within 30 days of the close of the Program year and reflect activity for the entire period. The report shall include, but not be limited to:</p><ul><li>Allocation and expenditure of funds</li><li>Number of individuals/households served</li><li>Variety, pounds and cost of food purchase.</li></ul><p><i>Quarterly</i>, SHFB must submit to PDA quarterly report and copies of all detailed itemized invoices paid for with Program funds during the quarter, within 20 days after the end of each quarter. The next quarter funds will not be released until all required documents are submitted.</p><p>Contact at the PA Dept of Agriculture for SFPP-related inquiries is:</p><p><strong>Melissa Patterson | Assistant Bureau Director</strong></p><p>PA Department of Agriculture | Bureau of Food Assistance</p><p>2301 North Cameron Street | Harrisburg, PA 17110</p><p>Office: 717-772-2694 | Work Cell: 717-836-2003 | Fax 717-787-2387</p><p>melpatters@pa.gov</p><p>&nbsp;</p>',NULL,630870.44,'2020-07-01','2025-06-30',NULL,NULL,NULL,'4600','2023-10-24 16:58:24','2023-12-04 20:41:31',NULL,145,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (248,'2023HCP_JP Morgan Chase',NULL,'<ul><li>General Operating HCP</li><li>Contact is Mikaela Ferrill (mikaela.ferrill@jpmchase.com)</li><li>There are no restrictions or reporting requirements for this grant</li></ul>',NULL,10000.00,'2023-10-25',NULL,'yes','2024-10-01',NULL,'8000','2023-10-25 13:35:35','2024-10-01 14:36:43',NULL,178,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (249,'2020SHFB_SFPP_NorthamptonCounty','248','<p>The State Food Purchase Program (SFPP) for Northampton County provides funds for the purchase, transportation, storage and distribution of food to program participants in Lehigh County who self-identify as 150% or more below the poverty level using the TEFAP Self-Declaration of Need form. &nbsp;</p><p>The 2020 SFPP Contract extends through June 30, 2025.</p><p>The initial program award for Northampton County was $341,237.17 for the period July 1, 2020 - June 30, 2021. In each subsequent Program years, PDA shall provide written notice of the maximum grant amount awarded. For 2023, allocations are:</p><p>&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/488/image.png\"></figure><p>By July 1 of each calendar year of the Program, SFHB must deliver a Plan of Operation to PDA for how the funds will be allocated to partner agency food pantries across the service area. Previous plans can be found <a href=\"https://caclv.sharepoint.com/:f:/s/SecondHarvestFoodBank/ElpIq8Vg5ONPqypOHaeIjwAB54CkMCDGqSNtEleNTgaG-w?e=cDXUgg\">here</a>. &nbsp;</p><p>Allowable costs include:</p><ul><li>Purchase of food consistent with the PDA\'s Food Standard Guidelines for State Food Purchase program (below).</li><li>Processing and repackaging of food for distribution with prior approval by PDA</li><li>Transportation, storage fees and direct administrative costs of the Program, per PDA\'s maximum administrative allowance percentage.</li><li>Capital asset funds may be used to purchase capital equipment or develop new initiatives seeking to increase volumes of food available. More information on capital asset allowances can be found here. (A capital expense allowance form is attached below.)</li></ul><p><strong>Reporting</strong></p><p><i>Annually</i>, SHFB must submit to PDA an Expense and Data Report for each program year within 30 days of the close of the Program year and reflect activity for the entire period. The report shall include, but not be limited to:</p><ul><li>Allocation and expenditure of funds</li><li>Number of individuals/households served</li><li>Variety, pounds and cost of food purchase.</li></ul><p><i>Quarterly</i>, SHFB must submit to PDA quarterly report and copies of all detailed itemized invoices paid for with Program funds during the quarter, within 20 days after the end of each quarter. The next quarter funds will not be released until all required documents are submitted.</p><p>Contact at the PA Dept of Agriculture for SFPP-related inquiries is:<br>Melissa Patterson | Assistant Bureau Director<br>PA Department of Agriculture | Bureau of Food Assistance<br>2301 North Cameron Street | Harrisburg, PA 17110<br>Office: 717-772-2694 | Work Cell: 717-836-2003 | Fax 717-787-2387<br>melpatters@pa.gov</p>',NULL,376053.37,'2020-07-01','2025-06-30',NULL,NULL,NULL,'4650','2023-10-25 13:42:16','2023-12-04 20:41:50',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (250,'2023SSS_KiwanisClub_Mosaic Project',NULL,'<ul><li>to purchase equipment and supplies to create a Mosaic on the Family Resource Center.</li><li>Project to be completed by Spring 2024</li><li>Report due by October 1, 2024, form attached. (required to apply for new funding)</li><li>December 7th, 2023, luncheon to receive check (Location: Shanty on 19th in Allentown from 12:00-1:30 pm)</li></ul>',NULL,1000.00,'2023-12-12','2024-05-31','yes','2024-10-01','<figure class=\"image\"><img src=\"http://10.55.0.10/storage/498/image.png\"></figure>','8000','2023-10-30 14:46:47','2024-10-01 14:46:59',NULL,179,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (251,'2023RTCLF_AllentownCDBG_Retail Mosaic Loan Program','C24-000528','<p>-CDBG Year 49</p><p>-Underwriting applications for a maximum of 5 qualified loan recipients (up to $15,000 of self-forgiving loans) and partial salary for Rising Tide Staff (up to 50 hours per grant year).</p><p>-Reimbursable grant</p><p>-Income verification forms included in contract need to be filled out for each applicant</p><p>-Applicant must hire one low-moderate-income full-time employee amongst other qualifications. Please see program guidelines uploaded here.</p>',NULL,85000.00,'2023-01-01','2026-12-01',NULL,NULL,'<p>-Quarterly CDBG reports will be due each April, July, October and January for the life of the program. Please reach out to Megan Brehm megan.brehm@allentownpa.gov or Daniel Diaz daniel.diaz@allentownpa.gov for reporting form/required information. &nbsp;</p>','0501','2023-11-07 18:12:36','2024-12-05 17:21:02',NULL,77,'14.218');
