INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (262,'2023HRP_City of Allentown_HOME_CHDO_136N8thStreet','700-01-7907-0303-40','<p>-Money to be used for 136 North 8th Street Rehabilitation</p><p>-Homeownership to low-income families</p><p>-Reimbursable grant</p><p>-Project shall be considered finished when the homeownership unit has been purchased by a qualifying individual and this must occur within 9 months of completion</p><p><strong>-Reporting Requirements Section XIX Page 15 every April 1st, July 1st, October 1st, January 1st (Quarterly) Please send quarterly update on progress of the grant to megan.brehm@allentownpa.gov.&nbsp;</strong></p><p>-Please see Budget Exhibit 1&nbsp;</p><p>-HOME funds must be matched by a non-federal source</p>',NULL,215525.00,'2023-01-01','2027-12-31',NULL,NULL,'<p><i><strong>******Areas of Compliance </strong></i><strong>******</strong></p><ul><li>Grantee will ensure compliance with HOME requirements for 15 years from the date of occupancy.<ul><li>Monitor units for principal residency and recapture funds at time of resale. &nbsp;For rentals ongoing property standards, occupancy and rent limits.</li></ul></li><li>See scope of work section III on pages 3-4 must follow property standards, HUD Requirements, Rehabilitation Standards, etc...</li><li>See Affordability Restrictions section IV- pages 5 -6</li><li>See Reimbursement of Expenses VI page 6.</li><li>See Project Requirements section VII pages 6-8</li><li>IX page 9 we must maintain CHDO status throughout this project agreement.</li><li>See procurement standards section X pages 9-10</li><li>See Budget Revisions and Un-reimbursable Expenses Section V pages 5-6.</li><li>Follow income Qualification requirements page 552.</li><li>Qualification as affordable housing: Rental Income pages 575-577 (See DEED restrictions)</li><li>Qualification as affordable housing: Homeownership pages 580-582 (See Recapture)</li><li>Labor page 594 (See Prevailing wage)</li><li>Lead-Based Pain pages 594-595 (See Lead Pain)</li></ul><p>&nbsp;</p>','F0530 Service Code: S12130','2023-12-04 15:01:29','2024-03-19 17:36:41',NULL,197,'14.239');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (263,'2023HCP_BHAP_CDBG',NULL,'<p>-Assist LMI first time homebuyers at or below 80% AMI with down payment and closing costs.&nbsp;</p><p>-Salary and Benefits for HCP</p><p>-If personnel expenses are not 100% covered for by CDBG funds under this Agreement, copies of allocations showing a split of funding between CDBG, and other funding sources must be submitted with draw down request.</p><p>-Please see Exhibit A for Program requirements.&nbsp;</p>',NULL,20000.00,'2023-01-01','2024-06-30','yes','2024-10-01',NULL,'0550','2023-12-04 19:48:29','2024-10-01 14:37:18',NULL,103,'14.218');
