INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (265,'2022-2026RTCLF_PACDFI_ARPA_Small Business Growth Program',NULL,'<p>-Original Contract $232,944 ($184,000 for small business loans, maximum loan amount can be $35,000, $48,941 for technical assistance)</p><p>-At least 5 business loans must be provided, and technical assistance must be provided to at least 30 businesses.</p><p>-All funds must be fully obligated by December 31, 2024, and fully expended by December 31st, 2026.&nbsp;</p><p>-Grantee must attend regular CDFI network meeting and complete accurate quarterly reports.</p><p>-All compliance and program administration requirements in Appendices A, B and C of original contract must be followed.</p><p>&nbsp;</p>',NULL,232944.00,'2022-06-27','2026-12-31',NULL,NULL,NULL,'F3590','2023-12-11 17:41:37','2025-03-06 16:09:49',NULL,186,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (266,'2023SHFB_PositiveNRG','266','<p>$10,000 grant toward General Operating. Announcement email pasted below.</p><p>Impact statement due approximately 10/31/2024. An email with instructions will be sent to planner-SHFB@caclv.org.</p><p>Login Information is</p><p>Username: planner-SHFB@caclv.org</p><p>Password: caclv1337</p><p>Last year\'s report can be found <a href=\"https://caclv.sharepoint.com/:b:/s/SecondHarvestFoodBank/EcJfovpJQipBuBvoy8BA_sIBEU6K8G4KHDK9B0ZqzpiuNA?e=RMuf53\">here</a>.</p>',NULL,10000.00,'2023-11-03','2024-10-31','yes','2025-05-20',NULL,NULL,'2023-12-11 18:48:29','2025-05-20 12:59:46',NULL,120,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (267,'2022-2025SHFB_DEP_FoodRecoveryInfrastructure','C990004163','<p>Grant awarded from the PA Department of Environmental Protection for <strong>$47,488.00</strong> for warehouse equipment purchase. We were approved to purchase 6 walk behinds jacks and 2 riding jacks.</p><p><i>Approval was also given to purchase caster wheels to stabilize the walk behinds, as the original project came in $1,013 under budget.</i></p><p>Grant period extends from July 1, 2022 - November 28, 2025.</p><p>Request for reimbursement must be submitted on the Disbursement Request Form below.&nbsp;</p><p>Final reimbursement request is due on or before November 28.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1637/image.png\"></figure><p>There is no reporting requirement.</p><p>Questions should be directed to:</p><p>Jessica Shilladay<br>Dept of Environmental Protection, Bureau of Waste Management<br>Division of Waste Minimization and Planning<br>Rachel Carson State Office Bldg<br>PO Box 8472<br>Harrisburg, PA 17105-8472<br>jesshillad@pa.gov<br>717-787-0125</p>',NULL,47488.00,'2022-07-01','2025-11-28',NULL,NULL,NULL,NULL,'2023-12-13 19:44:33','2025-05-06 11:42:43',NULL,185,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (268,'2023-2024CADA_NPP Agreement',NULL,'<p>Neighborhood Partnership Program for CADA.</p>',NULL,520000.00,'2023-07-01','2024-06-30','yes','2024-10-01',NULL,'0411','2023-12-14 14:27:27','2024-10-01 14:33:19',NULL,143,NULL);
