INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (270,'2023CADB_Weyerhaeuser Giving Fund_Public and Green Space Project',NULL,'<p>-Community Action Development Bethlehem\'s Public and Green Spaces projects (gardening supplies and equipment only).</p><p>-Funds may not be used for general administrative costs.</p><p>-12-month progress report required. An automated generated request will be sent when the report is due.</p>',NULL,3000.00,'2023-12-14',NULL,'yes','2025-06-27',NULL,'3500','2023-12-14 16:11:38','2025-06-27 16:45:11',NULL,187,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (271,'2023SHFB_ClifFamilyFoundation_SeedFarm','271','<p>The Clif Family Foundation has awarded a $15,000 grant to The Seed Farm for general operating purposes. The grant period begins on 12/18/2023 and ends 12/18/2024. The Foundation will send information regarding the final report to the <a href=\"mailto:planner-shfb@caclv.org\">planner-shfb@caclv.org</a> email. Last year the Foundation requested a general Seed Farm <a href=\"https://caclv.sharepoint.com/:b:/s/SecondHarvestFoodBank/EYKNuEp_XYtAoKBJPY6hZJQBALrQxoJvuQEPg7EfDqDksA?e=GLtfU3\">Impact Statement</a> as the final report.</p><p>This is a lump sum award and is unrestricted.</p><p>The email linked below contains important information regarding the Clif Family Foundation\'s support of The Seed Farm.</p><p>&nbsp;</p>',NULL,15000.00,'2023-12-18','2024-12-18','yes','2025-05-20',NULL,'8040','2023-12-20 13:42:23','2025-05-20 16:57:51',NULL,116,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (272,'2024SHFB_AllOne_GeneralOperating','272','<p>SHFB has been awarded a $100,000.00 grant from the AllOne Foundation to increase access to nutritious foods for the people of Carbon, Monroe, Pike, and Wayne Counties.</p><p>Grant period starts Dec 18, 2023 and ends Dec 17, 2024.</p><p>A full and complete narrative and financial report to the Foundation at the mid-project date as stated in the proposal as well as 30 days following the conclusion of the grant period. Information on submitting the report will be emailed to planner-SHFB@caclv.org.</p><p>Proposed budget is below:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1305/image.png\" alt=\"\"></figure>',NULL,100000.00,'2023-12-18','2024-12-17','yes','2025-05-15',NULL,'F8064','2023-12-29 13:15:12','2025-05-15 13:38:49',NULL,188,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (273,'2023-2024SHFB_NCTEFAP','23-1066','<p>SHFB shall accept for storage, prepare for distribution, distribute via its network of affiliated food pantries, and account for food commodities made available to Northampton County residents via TEFAP. SHFB shall publicize availability of foods via public service announcements.&nbsp;</p><p>This is a reimbursement grant. Billing and invoicing instructions are below. Reports must be submitted according to the schedule outlined below.&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/592/image.png\"></figure><p>&nbsp;</p>',NULL,0.00,'2023-10-01','2024-09-30','yes','2025-01-16',NULL,'F8079','2023-12-29 14:44:28','2025-01-16 19:32:54',NULL,2,'10.568');
