INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (292,'2021HRP_Redevelopment Authority of Bethlehem_ Blight Remediation_723 Broadway',NULL,'<p>-Hard construction costs for 723 Broadway</p><p><strong>&nbsp;4rth Amendment</strong></p><ul><li>&nbsp;Reduced the contract amount to $270,909.03 which is a reduction of $22,907.71.</li><li>Changed the expiration of the contract and all previous amendments to June 30, 2024.</li><li>States that the City of Bethlehem will reimburse us for costs incurred after June 30, 2024, with HOME funds.</li></ul>',NULL,270909.03,NULL,'2024-06-30',NULL,NULL,NULL,'F2990','2024-01-17 19:07:55','2025-03-12 18:22:30',NULL,192,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (293,'2024SHFB_FeedingPA_Service Insights','293','<p>Feeding PA has provided a $50,000.00 grant to support implementation of Service Insights to partner agencies. This is a lump sum grant.</p><ul><li>Hire a Community Programs&nbsp;Coordinator&nbsp;who will dedicate¾&nbsp;of their time to the electronic data collection initiative (approximately&nbsp;.75 FTE).</li><li>Work through the Feeding America checklists to&nbsp;create a framework for building out an electronic data collection pilot program, identify and begin implementation with an initial cohort&nbsp;of five (S) partner&nbsp;agencies,&nbsp;and subsequently continue implementation with additional partners.</li></ul><p>A SHFB representative&nbsp;must participate in the monthly Data Project Taskforce calls hosted by FPA and&nbsp;submit two&nbsp;brief reports summarizing the&nbsp;progress of implementation.&nbsp;</p><p>Reports are due as follows: on or before <strong>June 1, 2024</strong>; and on or before <strong>December 31, 2024</strong>. Guidelines regarding the report will be forthcoming from Feeding PA.</p><p>Questions may be submitted to Shea Saman at Feeding PA (ssaman@feedingpa.org).</p>',NULL,50000.00,'2024-01-01','2024-12-31','yes','2025-06-16',NULL,'F8086','2024-01-18 20:30:48','2025-06-16 12:10:39',NULL,165,NULL);
