INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (295,'2024SBR_ Totts Gap Arts Insitute',NULL,'<p>-to cover expenses for workshops for 40 children and youth</p><p><strong>Budget:</strong></p><p>Instructor $2,800</p><p>Art supplies $1,031</p><p>Exhibition rental $200</p><p>Drinks and food $150</p><p>SBR operating $1,000</p><p>Total $5,181</p><p>&nbsp;</p><p><strong>Sources:</strong></p><p>TGAI $5,000</p><p>NPP $181 (depending on the final drinks and food spending, it may or may not be used)</p><p>&nbsp;</p><p>-Reporting Requirements TBD</p><p>&nbsp;</p>',NULL,5000.00,'2024-04-01',NULL,NULL,NULL,NULL,'F6520','2024-01-19 14:44:44','2024-02-27 18:59:07',NULL,193,NULL);
