INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (297,'2024SHFB_TEFAP Reach and Resiliency','297',NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,'2024-01-25 18:43:41','2024-02-22 19:57:46','2024-02-22 19:57:46',NULL,'10');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (298,'2024SHFB_TEFAP Reach and Resiliency ARPA_ Warehouse Infrastructure','C940001540','<p><strong>Purpose: THIS EXPIRED AND THE FUNDS WERE NEVER USED.</strong><br>&nbsp;</p><p>Pennsylvania Dept of Agriculture has awarded SHFB $40,330.00 TEFAP Reach &amp; Resiliency for Warehouse Infrastructure. Per the contract:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/665/image.png\"></figure><p>The budget submitted is as follows:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/666/image.png\"></figure><p>This is a reimbursable grant.&nbsp;</p><p>Payment by PDA shall be made not more more than once each month, upon submission of a certified invoice, on a reimbursement of costs incurred basis. Invoices shall indicate expenditures incurred by budget categories.</p><p>At the conclusion of the TEFAP Reach and Resiliency Grant Award period, you will have 45 days in which to submit a final report on your project to the Pennsylvania Department of Agriculture’s Bureau of Food Assistance. <strong>By no later than July 15, 2024, please submit a final report to Caryn Long Earl (</strong><a href=\"mailto:cearl@pa.gov\"><strong>cearl@pa.gov</strong></a><strong>)&nbsp;</strong>detailing the following:</p><ul><li>Final project expenditures</li><li>Information on any new partner agencies through whom you are distributing TEFAP</li><li>Information detailing how you have used these funds to expanded the reach of TEFAP in your service territory</li><li>If applicable, information regarding increased geographic areas served through this project</li><li>Metrics on the increased numbers of individuals served and demographics of increased individuals served</li><li>Pounds of TEFAP distributed before and after implementation of project</li><li>Information regarding client satisfaction</li><li>Other relevant data or information regarding improved TEFAP reach in the community being served</li></ul>',NULL,40330.00,'2022-06-13','2025-06-30','yes','2025-01-23','<p>Amendment Contract #-C940001540-01</p><p>The purpose of the amendment is to extend the original TEFAP Reach &amp; Resiliency grant period to expiration on <strong>June 30, 2024</strong>.</p><p>The final report is now due July 30, 2024.</p>','F8093','2024-01-25 19:07:16','2025-01-23 19:11:25',NULL,172,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (299,'2024HCP_ NCDCED_Affordable Housing Program',NULL,'<p>-Salary and benefits for HCP staff&nbsp;</p><p>-Reporting semi-annually July 28, 2024, and January 8th, 2025, to be completed in the Neighborly Portal. (See page 7 section 27 in the contract)</p><p>&nbsp;</p>',NULL,10000.00,'2024-01-01','2024-12-31','yes','2025-03-20',NULL,'4250','2024-02-01 17:20:01','2025-03-20 18:32:37',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (300,'2024RTCLF_PACDFI_ARPA_HDBA_SBGII','C000086369','<p>- Technical Assistance only (Business Counseling, Access to Capital, Loan Application preparation, post-loan technical assistance, Financial Literacy, Business Planning)</p><p>-May be used to cover costs incurred on or after March 3, 2021.</p><p>-We will receive these funds in a lump sum</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/677/image.png\"></figure><p>&nbsp;</p><p>&nbsp;</p>',NULL,250000.00,'2024-02-05','2026-06-30',NULL,NULL,'<ul><li>Quarterly Project and Expenditure Reports</li><li><strong>The report will ask for a short narrative/description of how businesses were negatively impacted by COVID 19.</strong></li></ul><p><strong>Updates to terms:</strong></p><p>-\"Historically Disadvantages\" has been expanded to include women.</p><p>-Any businesses receiving technical assistance not located in a QCT require backup documentation to support negative COVID 19 impact.</p>','3595','2024-02-06 14:14:44','2025-03-06 16:10:58',NULL,186,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (301,'2024REJ_ Nature Nurture Center_ CBO _ Create Connections: Linking a Vision of Resilience to Action',NULL,'<p>Community Based Partner with the Nurture Nature Center for project entitled \"CREATE Connections: Linking a Vision of Resilience to Action\"</p><p>&nbsp;</p><p>This agreement spans 4 years and ends on August 31, 2027.</p><p>&nbsp;</p><p>Responsibilities of the CBO (REJ) are:&nbsp;</p><p>      -&nbsp;participate in project meetings and provide input</p><p>      -help disseminate outreach and educational materials through its community networks on an ongoing basis</p><p>      -&nbsp;participate in evaluation activities and report on project activities.&nbsp;</p><p>&nbsp;Please see agreement for more details.&nbsp;</p><p>Total yearly compensation to REJ is $500. Invoice template attached.</p>',NULL,0.00,NULL,'2027-08-31',NULL,NULL,NULL,NULL,'2024-02-09 17:57:02','2024-10-07 16:05:27',NULL,181,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (302,'2024SHFB_TEFAP_CountyCommoditiesAgreements','302','<p>These are the TEFAP Commodities Agreements between SHFB and the counties of <strong>Carbon</strong>, <strong>Lehigh</strong>, and <strong>Northampton</strong>. These agreements, establishes the terms and conditions for participation in The Emergency Food Assistance Program (TEFAP).&nbsp;</p><p>The program directs SHFB in the receipt of food provided by PDA/USDA and equitable distribution to partner agencies (food pantries). This contract gives SHFB the right to continue TEFAP contracts with the counties listed above.</p><p>Food designated as TEFAP must be accounted for separately from other food in the warehouse.</p><p>This is a <strong>reimbursable grant</strong>. Invoices submitted to the PDA must have a unique invoice number. Invoices must be submitted along with quarterly Inventory Utilization Report Forms. These forms and invoices are found on the PA Meals portal: https://www.pameals.pa.gov/ .</p><p>SHFB may not charge any partner agency a shared maintenance fee. PDA may elect to reimburse expenses; SHFB is responsible for providing an Inventory Utilization Report Form quarterly to the PDA.</p><p>Additional TEFAP bonus streams may be awarded during the contract period. These funds may be disbursed without an additional contract.</p><p>The statewide TEFAP agreement can be found here: <a href=\"http://contracts.caclv.org/contracts/227\">http://contracts.caclv.org/contracts/227</a></p><p>&nbsp;</p>',NULL,0.00,'2021-10-01','2026-09-30',NULL,NULL,NULL,NULL,'2024-02-14 14:25:57','2024-09-17 13:56:30',NULL,172,'10.569');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (303,'2024SHFB_FA_StarbucksGlobalMonthofGood',NULL,'<p>The goal of this grant is to deepen relationships with Starbucks employees through volunteering and to educate them on the impact of the FoodShare program. The FoodShare program connects SHFB and its partner agencies with donated, ready-to-eat foods from local Starbucks stores.</p><p>This is a lump sum grant and will be used 100% toward Salary &amp; Fringe for the Volunteer Coordinator position.</p><p>Grantees are asked to recognize Starbucks for this grant award during the grant period at least once using social media and online platforms. A communications toolkit will be made available on or before April 1, 2024. The PR/Communication contact is Casey Cora (Director Donor Partnership Communication) at <a href=\"ccora@feedingamerica.org\">ccora@feedingamerica.org&nbsp;</a></p><p>A volunteer event must be held in April 2024; see below:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/702/image.png\"></figure><p>A final report is due on May 28, 2024 including:</p><ul><li>Budget breakdown on use of funds to support volunteer event</li><li>Starbucks staff: 1 - 3 photos during event along with a few quotes from both Starbucks staff and SHFB employees</li><li>At least one social media or external publicity</li></ul>',NULL,10000.00,'2024-02-01','2024-05-31','yes','2025-04-24',NULL,'F8090','2024-02-14 16:40:11','2025-04-24 13:20:27',NULL,194,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (304,'2021_2026SHFB_LehighCountyTEFAP',NULL,'<p>This is a reimbursement grant. Billing and invoicing instructions are below. Reports must be submitted according to the schedule outlined below. &nbsp;</p><p><strong>Purpose:</strong></p><p>This agreement between SHFB and Lehigh County establishes the terms and conditions for SHFB to provide TEFAP services to Lehigh County. SHFB shall accept for storage, prepare for distribution, distribute via its network of affiliated food pantries, and account for food commodities made available to Lehigh County residents via TEFAP. SHFB shall publicize availability of foods via public service announcements. &nbsp;</p><p>The following costs are allowable:</p><ul><li>Storage costs</li><li>Transportation Costs</li><li>Equipment Rental Costs</li><li>Printing/Copying Costs</li><li>Administrative Costs</li></ul><p>Services provided from 10/01/2021 - 9/30/2026 will be reimbursed at $.12 per lb distributed, unless otherwise communicated by the State or County.</p><p>Invoices are required quarterly for all program years as follows:</p><p><strong>Invoice #1</strong> for (10/01-12/31); Due: 01/30</p><p><strong>Invoice #2</strong> for (01/01-03/31; Due: 04/30</p><p><strong>Invoice #3</strong> for (04/01-06/30); Due: 07/30</p><p><strong>Invoice #4</strong> for (07/01-09/30); Due: 10/30 &nbsp;</p><p>NOTE: The invoice shall be accompanied by a completed TEFAP INVENTORY/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \"TEFAP INVENTORY/PARTICIPATION REPORT\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED.</p><p>Contact:<br>Joel Pattison<br>County of Lehigh<br>Lehigh County Aging &amp; Adult Services<br>610-782-3442<br>joelpattison@lehighcounty.org</p>',NULL,0.00,'2021-10-01','2026-09-30',NULL,NULL,NULL,'F8077','2024-02-22 20:08:52','2024-10-07 17:24:20',NULL,145,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (305,'2024SBR_NC Hotel Tax',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,'F0811','2024-02-27 18:59:58','2024-12-10 20:51:27','2024-12-10 20:51:27',NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (306,'2021_SHFB_CSFP_SeniorFoodBoxes','306','<p>This CSFP Administration Agreement between SHFB and Hunger Free PA (HFPA) establishes the terms and conditions for SHFB to administer the Commodity Supplemental Food Program (CSFP) Senior Food Box Program. &nbsp;</p><p>This is a reimbursable program; reimbursement rates are made on an annual basis, adjusted for inflation. <strong>Rate for FY2024 is $6.58/box</strong>. SHFB will be paid monthly after verification of reporting on Form FNS-153 (Ex: below)</p><p>Caseload (number of sites and/or number of boxes prepared) is assigned by HFPA and will vary based on resources and funds; HFPA may make changes to caseload at any time.</p><p>As Lead Agency, SHFB will act in accordance with PA Dept of Agriculture\'s regulations as established in the contract. SHFB agrees to:</p><ul><li>Select Sub-Agencies to operate the program in accordance with Federal/State regulations and dependent upon service area need</li><li>Receive and store commodity in an appropriate manner to prevent theft, spoilage, damage or destruction, or other loss</li><li>Maintain accurate inventory records</li><li>Distribute commodities to participant/caretaker/proxy each month in accordance with CSFP guidelines</li><li>Ensure Sub-Agencies are collecting and inputting participant information utilizing the Link2Feed platform</li><li>Ensure participants are provided with appropriate and accessible information, are made aware of their rights and responsibilities, are provided with educational information as outlined in the contract</li><li>Complete all forms and reports as outlined in the contract</li></ul><p>An extension to the funding period was announced on May 14, 2024. The new ending date for the grant is <strong>12/31/2024.</strong></p><p>Contact for the CSFP Senior Food Box Program is:<br>Sheila Christopher<br>Hunger-Free Pennsylvania Executive Director&nbsp;<br>412-290-3045<br><a href=\"mailto:sachristopher@pafoodbanks.org?subject=PA%20Hunger%20Action%20Coalition\">sachristopher@pafoodbanks.org</a></p><p>Program rules and regulations are in accordance with Title 7. Agriculture Subtitle B. Regulations of the Department of Agriculture Chapter II. FOOD AND NUTRITION SERVICE, DEPARTMENT OF AGRICULTURE Subchapter B. GENERAL REGULATIONS AND POLICIES - FOOD DISTRIBUTION Part 250. DONATION OF FOODS FOR USE IN THE UNITED STATES, ITS TERRIRTORIES AND POSSESSIONS AND AREAS UNDER ITS JURISDICTION Subpart F. Household Programs.</p>',NULL,0.00,'2021-08-16','2024-12-31',NULL,NULL,NULL,'F1000','2024-02-27 20:43:37','2024-09-20 12:48:15',NULL,172,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (307,'2024SBR_NCHotel Tax_ Slate Belt Public Art Trail',NULL,'<p>$2,525 for Marketing and Advertising</p><p>$1,675 for App Subscription (Interactive Map)</p><p>-25-50% matching funds required see section 8 of contract for details</p>',NULL,4200.00,'2024-01-01','2025-06-30',NULL,NULL,'<p>Reports-</p><p>Semi- annual due July 31, 2024 and March 31, 2025.</p><p>Provide Fiscal Information and Activity Progress.</p><p>Complete in Neighborly Portal</p><p><a href=\"https://portal.neighborlysoftware.com/NORTHAMPTONCOUNTYPA/participant\">Neighborly Software</a></p><p>&nbsp;</p>','F8011','2024-03-08 16:32:15','2025-01-23 18:30:25',NULL,195,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (308,'2023SBR_NCCDBG_Program Administration',NULL,'<p>-Salary and Benefits for SBR Director</p><p>&nbsp;</p>',NULL,25000.00,'2023-10-01','2025-09-30','yes','2025-02-21','<p>Reports-</p><p>Semi- annual Reports due October 30th and April 30th and go to Frank Brooks at fbrooks@norcopa.gov</p><p>Forms located on last two pages of the contract.</p>','F0750','2024-03-08 17:01:39','2025-02-21 17:20:01',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (309,'2024HCP_BOA_Homebuyer Education and Counseling Agreement',NULL,'<p>-Reimbursement for Homeownership Education Counseling as outlined in 1.1.3.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/728/image.png\"></figure><p>-Provide Proof of completion of Homebuyer Education to counselee and to BOA.</p><p>-Acquire written permission to share counselee information with BOA if requested by the counselee</p><p>-BOA shall pay Counselor a fee of $500 for instructor led classes and $100 for self-guided classes</p><p>-Please see exhibit A for Counseling Responsibilities</p><p>-Please see Exhibit B for Logo and License Agreement.</p>',NULL,0.00,'2024-04-01','2026-03-31',NULL,NULL,'<p>-Section 2.2 Payment Process fee and Invoice Submission</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/729/image.png\"></figure>','8000','2024-03-18 13:38:30','2024-06-20 16:39:06',NULL,169,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (310,'2023HCP_NCCDBG_Housing Counseling Program',NULL,'<p>-Salary and Benefits&nbsp;</p><p>-Reimbursable</p>',NULL,21000.00,'2023-10-01','2025-09-30','yes','2025-03-25','<ul><li>Semi- Annual Reports due October 30th and April 30th to Fbrooks@norcopa.gov.</li><li>Reporting Forms are Exhibit B-4 of contract</li></ul>','0753','2024-03-18 13:47:13','2025-03-25 11:41:04',NULL,106,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (311,'2024CADB_Collabo_City of Bethlehem_Pembroke Choice Neighborhood Plan',NULL,'<p>-Attend Public and Staff Meetings</p><p>-Provide approx. 6 training sessions over a one-year period beginning January 2024 for neighborhood residents to build their capacity to participate in the planning process.&nbsp;</p><p>-See Attachment B for full Scope of Work.</p><p>&nbsp;</p>',NULL,20000.00,'2024-02-29','2025-01-31',NULL,NULL,'<p>-Invoices to be submitted monthly and include a summary of activity and number of hours related Scope of Service exhibit B and list of reimbursable expenses.</p><p>-Reimbursable expenses can be travel, meals, meeting refreshments, printing, graphic reproduction, telephone and mail delivery, maps, plans and rereporting or other similar expenses.</p>','F2145','2024-03-18 14:56:21','2025-02-07 18:37:42',NULL,171,'N/A');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (312,'2022-2025REJ_BASD_SHE/GenNxt',NULL,'<p>-General Operating Expenses for the SHE and Generation Next Programs at partnering Bethlehem Area School District Schools.</p><p>Payments Per School Year are as follows:</p><p>2022-2023 School Year- $42,500 for SHE and $42,500 for Generation next for a total of $85,000 for the year</p><p>2023-2024 School Year- $30,000 for SHE and $30,000 for Generation next for a total of $60,000 for the year</p><p>2024-2025 School Year- $30,000 for SHE and $30,000 for Generation next for a total of $60,000 for the year</p><p>Invoices should be sent to Brenda Ortega bortega@basdschools.org.</p><p>&nbsp;</p>',NULL,205000.00,'2022-10-01','2025-06-09',NULL,NULL,NULL,'8000','2024-03-18 18:47:13','2024-03-18 19:02:27',NULL,196,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (313,'2023_SHFB_VeteransTrust_MilitaryShare','DMVA-2024-053','<p>This $40,000 grant will support the Military Share program during the grant period of <strong>6/1/2024 - 5/31/2025</strong>. Utilizing these funds, SHFB will:</p><ul><li>Provide nutritious shelf-stable and fresh foods to at least 560 military families.</li><li>Distribute 235,000 pounds of food.</li><li>Engage 100 volunteers for packing and distribution of food boxes.</li></ul><p>Funds received will be used for the following purposes:</p><ul><li>Personnel and fringe benefits costs of $2,300 and $1,700 respectively, will support the Community Programs Coordinator at an hourly rate of $21.63.</li><li>Commodities costs of $34,200 will support the purchase of food for Military Shares distribution.</li><li>Supplies costs of $1,200 will support the purchase of 1,481 boxes at $.81/box.</li><li>Distribution costs of $600 will support the cost of fuel for trucks to delivery Military Shares to distribution sites across six counties at $.65/mile.</li></ul><p>Regarding use of funds:&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/743/image.png\"></figure><p>SHFB must submit a final audit, performed by a Certified Public Accountant, that accounts for all expenditures of grand funds and accrued interest therefrom <strong>no later than six (6) months</strong> after the agreement period end.&nbsp;</p><p><i>A Project Audit performed under the Single Audit Act of 1984 will not be accepted in lieu of a Project Audit required under this agreement.</i></p><p>Quarterly progress reports must be submitted to the Department of Veterans\' Affairs no later than thrity (30) days after the end of each quarter, with the first report covering the months June - September. The template for these reports will be provided by the Department prior to the end of the first quarter.</p><p>Regarding reporting of salary + fringe:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1077/image.png\"></figure><p>Contact email for this program is: <a href=\"RA-MVVetTrustFund@pa.gov\">RA-MVVetTrustFund@pa.gov</a></p><p>&nbsp;</p>',NULL,40000.00,'2024-06-01','2025-05-31','yes','2025-07-02','<p><i><strong>-Travel Costs.&nbsp;</strong></i></p><p><i><strong>Travel costs incurred by the Grantee that are paid with grant funds awarded pursuant to this Agreement shall not exceed those established by the Commonwealth Management Directive 230.10 as revised, Commonwealth Travel Policy.</strong></i></p><p>If grant funds are spent on travel, please make sure that the supporting documentation shows that you abided by the Commonwealth Management Directive on travel costs.&nbsp;&nbsp; I am including a link where the Commonwealth Travel Information can be found.&nbsp;&nbsp; <a href=\"https://www.budget.pa.gov/Services/ForCommonwealthTravelers/PoliciesAndProcedures/Pages/default.aspx\">Policies &amp; Procedures (pa.gov)</a></p>','8068','2024-03-19 11:20:04','2025-07-02 14:46:29',NULL,114,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (314,'2024SSS_Sylvia Perkins',NULL,'<p>-To be used for general operating. More specifically furniture.</p><p>Please see attached budget.</p>',NULL,5000.00,'2024-03-12',NULL,'yes','2025-03-25',NULL,'1211','2024-03-20 12:51:06','2025-03-25 17:48:23',NULL,142,NULL);
