INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (316,'2024 RTCLF_Embassy Bank Loan',NULL,'<p>-Money to be used to finance LC and NC local small businesses</p><p>-2% interest (Principal and balance due and payable 7 years from receipt of investment)</p><p>-We may pre-pay the loan in whole or part at any time without penalty</p><p>-Investor will be allowed to attend RTCLF Board meetings as an observer</p><p>-Embassy requires audited Financial Statements</p><p>-Annual Report of Loan activity due upon request of the investor</p><p>&nbsp;</p>',NULL,100000.00,'2024-03-15','2031-03-15',NULL,NULL,NULL,'0100','2024-03-29 14:22:30','2024-03-29 14:40:16',NULL,199,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (317,'2024CADA_City of Allentown ARPA_ Youth Center','C24-000545','<p>-To be used to demolish and reconstruct 424 N Ninth Street, Allentown, PA. This site will be used to provide educational and recreation activities to Allentown youth.</p><p>-See page 2 section 3 of the contract for Reimbursement Instructions</p><p>-City of Allentown must be provided a copy of the certificate of occupancy and final cost certification submitted to the PHFA agency.</p><p>-Must use and have procurement rules, standards and procedures that are consistent with <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-I/part-180\">2 CFR 180</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.317\">200.317</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.318\">200.318</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.319\">200.319</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.320\">200.320</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.321\">200.321,</a><a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.322\"> 200.322</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.323\">200.323</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.324\">200.324,</a> <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.325\">200.325</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.326\">200.326</a>, <a href=\"https://www.ecfr.gov/current/title-2/subtitle-A/chapter-II/part-200/subpart-D/subject-group-ECFR45ddd4419ad436d/section-200.327\">299.327. &nbsp;</a>(Click on links for more details)</p><p>-All documents pertaining to this grant must be retained for 7 years.</p>',NULL,1000000.00,'2024-04-05','2026-12-31',NULL,NULL,NULL,'F3251','2024-03-29 14:28:47','2025-03-06 16:10:45',NULL,200,'21.027');
