INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (323,'2024RTCLF_ Wells Fargo',NULL,'<ul><li>To be used for Non- Marketing Technical Assistance</li><li>There is no indication of a report due</li></ul>',NULL,25000.00,'2024-04-18',NULL,NULL,NULL,NULL,'8000','2024-04-18 12:12:34','2024-04-18 12:15:31',NULL,79,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (324,'2024_SHFB_CrayolaCares','324','<p>Crayola has awarded SHFB $5,000 in general operating expenses. There is no submitted budget. A final report/impact statement is required on or before December 2, 2024; template is available at www.crayolacares.com. This evaluation is required in order to receive future funding.</p><p>There is no media/acknowledgement requirement, but a logo and brand kit may be requested through communityengagment@crayola.com.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/792/image.png\"></figure><p>&nbsp;</p>',NULL,5000.00,'2024-03-12','2024-12-02','yes','2025-04-02',NULL,'8000','2024-04-18 14:16:32','2025-04-02 17:55:34',NULL,201,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (325,'2024_SHFB_TwoRiversHealthWellness','325','<p>Two Rivers Health &amp; Wellness has made a $10,000 grant available to support nutrition education in Northampton County through the Cooking Matters® curriculum. The grant will be applied in its entirety to the salary/fringe of the Nutrition Educator.</p><p>A final outcomes report will be required. More information will be sent to the planner-shfb@caclv.org.</p><p>&nbsp;</p>',NULL,10000.00,'2024-02-16','2024-09-01','yes','2025-03-20',NULL,'6260','2024-04-18 15:36:13','2025-03-20 16:57:55',NULL,202,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (326,'2024_SHFB_FirstEnergy','326','<p>FirstEnergy has made a $5,000.00 grant to SHFB for general operating support.&nbsp;</p><p>The grant period runs from April 4 - July 31, 2024. An impact statement will be requested in fall of 2024; the 2023 Impact Statement was due 9/30.</p><p>Questions may be directed to FEC_Comm_Involve@firstenergycorp.com.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/802/image.png\"></figure>',NULL,5000.00,'2024-04-04','2024-07-31','yes','2025-04-02',NULL,'8000','2024-04-18 16:00:33','2025-04-02 17:54:18',NULL,161,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (327,'2023-2025SHFB_NCCDBG_FreshFoodDistribution','327','<p>Northampton County has awarded $35,000 \"to purchase and distribute fresh foods (produce, dairy, eggs, and meat)\" to the 19 Northampton County pantry sites listed in the attached contract, Exhibit A.</p><p><i><strong>This is a reimbursable grant.</strong></i></p><p>There is no reporting due for this grant (See excerpt below). Itemized invoices must be submitted to the county contact listed below.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/807/image.png\"></figure><p>The budget allowance is as follows:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/805/image.png\"></figure><p>&nbsp;</p><p>Questions regarding the program can be addressed to:</p><p>Frank Brooks<br>Northampton County Community &amp; Economic Development<br>610-829-6311<br>fbrooks@norcopa.gov</p>',NULL,35000.00,'2023-10-01','2025-09-30',NULL,NULL,NULL,'F8074','2024-04-18 18:20:29','2024-08-22 16:29:39',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (328,'2024HCP_ PNC',NULL,'<p>-No more than 50% of the grant can be used for salaries and benefits. ($3,750)</p><p>- The rest can be spread across the categories in the budget (Supplies; Furniture &amp; Equipment Expense; Postage &amp; Shipping; Printing &amp; Copying; Staff Development &amp; Training; Travel &amp; Conferences; Insurance (non-employee related)).&nbsp;</p><p>-Report TBD</p>',NULL,7500.00,'2024-04-09',NULL,'yes','2025-07-09',NULL,'8000','2024-04-24 14:57:52','2025-07-09 11:30:34',NULL,78,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (329,'2024SSS_St Paul\'s UCC',NULL,'<p>-Supportive Services fund for residents: &nbsp;used for a variety of expenses that may arise for residents during their stay at the Shelter. This may include tuition assistance, books and course materials, computers, rental application fees, establishing renters’ insurance, the acquisition or replacement of documents (Social Security cards, birth certificates, and driver’s licenses), childcare, food, transportation costs, hygiene items, cleaning supplies, emergency assistance, and diapers and other supplies for children.</p><p>-There are no reporting requirements.&nbsp;</p>',NULL,1500.00,'2024-04-17',NULL,'yes','2025-03-27',NULL,'8000','2024-04-29 18:49:24','2025-03-27 12:25:22',NULL,154,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (330,'2024SSS_TrexlerTrust',NULL,'<p>-$20,000 for general operating</p><p>*There will be a report prior to November 1, 2024. The Stewardship Report Guidelines can be found on www.TrexlerTrust.org.&nbsp;</p><p><strong>**Failure to file a timely report will result in the elimination of the Grantee\'s eligibility for any grant in 2025.&nbsp;</strong></p><p>&nbsp;</p>',NULL,20000.00,'2024-04-16',NULL,'yes','2025-04-30',NULL,'1215','2024-05-02 17:07:19','2025-04-30 11:30:32',NULL,146,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (331,'2024SSS_Erie Insurance',NULL,'<p>This is to be used for general operating, but <strong>it cannot be used for salary and benefits</strong>.&nbsp;</p><p>*Media opportunities stated in the proposal: Sixth Street Shelter and CALV could include a sponsorship shout out on our Facebook and Instagram posts and stories. We also send out a bi-monthly Sixth Street Shelter e-blast that reaches over 9,000 contacts, including donors and local press. Reach out to givingnetwork@erieinsurance.com for approved logo, ad, banner or are planning a press release.</p><p>&nbsp;</p>',NULL,5000.00,'2024-04-27',NULL,NULL,NULL,NULL,NULL,'2024-05-02 17:23:43','2024-05-02 17:23:43',NULL,140,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (332,'2024SSS_Erie Insurance',NULL,'<p>This is to be used for general operating, but <strong>it cannot be used for salary and benefits</strong>.&nbsp;</p><p>*Media opportunities stated in the proposal: Sixth Street Shelter and CALV could include a sponsorship shout out on our Facebook and Instagram posts and stories. We also send out a bi-monthly Sixth Street Shelter e-blast that reaches over 9,000 contacts, including donors and local press. Reach out to givingnetwork@erieinsurance.com for approved logo, ad, banner or are planning a press release.</p><p>&nbsp;</p>',NULL,5000.00,'2024-04-27',NULL,NULL,NULL,NULL,NULL,'2024-05-02 17:43:11','2024-05-02 17:52:40','2024-05-02 17:52:40',140,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (333,'2024HCP_PAHAF_ PA Homeowner Assistance Program',NULL,'<p>-Agreement in reference to the HCA Master Agreement (2022- MCA-054)</p><p>-See eligibility requirements <strong>page</strong> <strong>4 section \"Eligible Homeowners\"</strong> and <strong>page 5 section \" Eligible Expenses\"</strong></p><p>-See<strong> page 7 section \"Housing Counseling Agencies\" </strong>for roles and responsibilities of HCP.</p><p>-Eligible counseling hours = 4 hours of counseling per client (one Houshold = 1 client)</p><ul><li>Time spent completing HEMAP application is not eligible for reimbursement</li></ul>',NULL,0.00,'2024-05-01',NULL,NULL,NULL,'<p>-Request for payment requires PAHAF one -on-one invoice in excel format and PAHAF report from RX office in excel format. PAHAF application must be submitted for the client prior to request for reimbursement. Reimbursement in 1 hours increments at $100 per hour.</p>','F0603','2024-05-06 12:14:40','2024-05-06 12:41:21',NULL,203,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (334,'2024Wx_First Energy Warm_Master Service Agreement',NULL,'<p><strong>Weatherization Service Provider (WSP) Responsibilities:&nbsp;</strong></p><ul><li>Weatherization Services to include but not limited to: Attic and wall insulation, Air sealing, Duct Sealing and Repair, Door and window weather stripping, etc. see page 2 section 1 Scope of work in the Statement of Work document.</li><li>Perform a full energy audit with pressure diagnostic and associated safety testing</li><li>Must complete a minimum of 50 jobs</li><li>WSP is responsible for recruiting and training personnel and securing criminal background checks within the last 7 years of all employees and subcontractors to be kept on file.</li><li>WSP personnel must display and wear program identification badges while at customers\' homes. Badges must be returned to First Energy if and when employees terminate employment.</li><li>BPI certifications must be kept current and on file.</li><li>Potential quarterly Advisory Panel meeting participation.</li><li>Attend all First Energy sponsored trainings</li><li>Must have a dedicated quality control representative to ensure each job is inspected internally.</li><li>WSP must resolve all customer complaints and document the process int the \"Job Notes\" section of the LEEN System.</li><li>WSP is responsible for debris removal and cleanup of premises</li><li>Energy Education sessions must be provided to customers during initial visit.</li><li>Remedial education sessions may be required based on monthly reports provided to the WSP. Results and Conversations must be documented int he LEEN system before First Energy is invoiced.</li><li>See page 10 in the Statement of Work Document for required equipment.</li><li>See page 11 section 4.19 in the Statement of Work document for required diagnostic testing</li><li>WSP is responsible for Weatherization Service Provider and Customer Health and Safety see page 11 sections 4.20-4.21 in the Statement of Work Document.</li><li>Use LEEN System to manage assigned jobs and perform tasks. LEEN system to be used for reporting, tracking, invoices and program forms.</li></ul><p><strong>Publicity:</strong></p><ul><li>Any contact with news or media regarding this program needs to be approved by First Energy.</li><li>Prohibition of publicity- WSP shall not reference \"First Energy\" in any advertising, promotional materials or social media without prior express written consent.</li></ul><p><strong>Invoicing and Payment:</strong></p><ul><li>See page 3 Article 4 in Master Service Agreement for Invoicing and Payment Procedures</li><li>See page 9 section 4.17 in Statement of Work document for Job Completion and Invoicing. For jobs considered complete they must be coded as ready to inspect by a third-party Quality Assurance Inspector and all documents must be uploaded into the LEEN system. Invoicing to be submitted into LEEN system at the completion of the job within 30 days of the completion.</li></ul>',NULL,1500000.00,'2024-06-01','2027-05-03',NULL,NULL,'<p><strong>Insurance Requirements:</strong></p><ul><li>General Commercial Liability $2,000,000 per occurrence</li><li>Automobile Liability $1,000,000</li><li>Professional Errors and Omissions $2,000,000 per occurrence</li><li>Cyber Liability $2,000,000 per occurrence</li></ul><p><strong>First Energy:</strong></p><ul><li>First Energy will conduct Quality Assurance Visits, Job inspections and periodic evaluations</li><li>Inspection, rejection, Revocation- work shall be subject to inspection, tests and count by First Energy anytime.</li></ul>','7750','2024-05-06 12:43:36','2024-05-30 11:38:36',NULL,205,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (335,'2024SHFB_StarbucksFoodShareCapacity','335','<p>This is a <strong>$25,000.00 lump sum</strong> grant, awarded by Starbucks to support it\'s <a href=\"https://stories.starbucks.com/stories/hunger-relief/\">FoodShare program</a>; delivering frozen product daily directly to partner agencies. This program is designed to provide necessary infrastructure to those partner agencies who receive Starbucks product.</p><p>An itemized list of requested equipment has been submitted and accepted by Starbucks (see below). Once funds are received, the Retail Recovery Coordinator will work with partner agencies to purchase and install equipment. Funds must be spent before July 30, 2024.</p><p>A report is due on or before July 30, 2024, outlining the itemized expenditures, providing an Impact Statement on use of funds and social media coverage. Additional details are below.&nbsp;</p><p>Per the below email, an additional $5,000 was requested and received.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/824/image.png\"></figure>',NULL,30000.00,'2024-05-01','2024-07-30',NULL,NULL,NULL,NULL,'2024-05-08 14:51:23','2025-05-02 15:40:06',NULL,194,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (336,'2024SSS_CityofAllentownESG_Rapid Rehousing','700-01-9923-0404-40','<p>Provide housing identification, rental assistance, comprehensive case management and essential services for approximately 5 families.</p><p>-The Sixth Street Shelter will offer this program to Category 1 families on the Coordinated Entry System\'s By-Name Lists (which will include families at the shelter). Set up a project in HMIS to pull applicants from in order to prioritize households who are at high risk. Contact Antonio Diaz at <a href=\"mailto:antdiaz@pa.gov\">antdiaz@pa.gov</a> to get this set up.</p><p>-The Sixth Street Shelter will participate in the Lehigh Valley Regional Homeless Advisory Board\'s Landlord Engagement Program.</p><p>-Housing First best practices to remove barriers will be employed which include no requirement for employment, income, and sobriety or the absence of a criminal record.</p><p><strong>Budget and Appropriate Use of Funds:</strong></p><p><strong>Services: $11,901.10</strong></p><p>-<i><strong>Housing search and placement</strong> </i>which includes but is not limited to assessment of housing barriers, needs and preferences, development of action plan, housing search, outreach and negotiation with owner, assistance submitting rental application, assessment of housing for ESG requirements for habitability, lead based paint and rent reasonableness, tenant counseling, etc...</p><p>-<i><strong>Housing Stability Case Management</strong></i> which includes but is not limited to using the centralized or coordinated assessment system to conduct the initial evaluation and re-evaluation, counseling, developing, securing and coordinating services for Federal, state and local benefits, monitoring and evaluating participant progress, developing housing and service plan, follow up counseling and assessment at 3,6 and 12 months after the families have completed the program, etc... &nbsp;**(Case management cannot exceed 30 days during the period the program participant is seeking permanent housing and cannot exceed 24 months during the period the program participant is living in permanent housing.)</p><p>-Family Service plan should be offered but is not required</p><p>-Verify Homelessness or Risk of Homelessness Status</p><p>-Keep timesheets and logs for all time spent client facing and non-client facing.</p><p><strong>Financial Assistance: $7,500</strong></p><p>-Rental Application fees, security deposits (no more than two months of rent), last month\'s rent, moving costs, utility deposits, utility payments (up to 24 months or 6 months of arrears)</p><p><strong>Rental Assistance: $20,000</strong></p><p>-Rental assistance for 3-6 months</p><p>-Rent payments must not exceed Fair Market Rent established by HUD</p><p>-Apartment must be assessed by the city of Allentown for HUD Habitability Standards. Lynda Burian is the contact for habitability inspections. Contact her via email at <a href=\"mailto:Lynda.burian@allentownpa.gov\">Lynda.burian@allentownpa.gov</a> – email should include the address and landlord information. Please note that units must be registered rentals with the city (the inspector will have that information).</p><p>-Participants must meet with a case manager at least once a month for the duration of assistance.</p><p>-A rental assistance agreement must be created between the SSS, and the landlord please see form attached below.&nbsp;</p><p>-Rent should be paid using a step-down method based on participant need. (Step-down method-security and first month\'s rent followed by 3-4 months of rental payment with increased responsibility placed on the participant based on family need.) &nbsp;A re-evaluation of eligibility must be done every 3 months if the participant is still receiving assistance. Participant must be under 30% of the median area income.</p><p>-Obtain a legally binding lease</p>',NULL,39401.10,'2024-01-26','2025-07-26',NULL,NULL,'<p>-Quarterly reports are required using the same form as the regular ESG.</p>',NULL,'2024-05-13 17:10:44','2024-08-01 15:14:48','2024-08-01 15:14:48',204,'14.231');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (337,'2024HCPHRP_Wells Fargo',NULL,'<p>-general operating</p>',NULL,45000.00,'2024-03-28',NULL,NULL,NULL,NULL,NULL,'2024-05-22 12:50:03','2024-05-22 12:58:32','2024-05-22 12:58:32',79,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (338,'2024-2025SHFB_PikeCDBG',NULL,'<p>Pike County has awarded SHFB a CDBG grant for $34,508.00 for the purchase of fresh food for Pike County. This is a <strong>reimbursable grant</strong> with the grant period running from <strong>May 9, 2024 - August 31, 2025</strong>. Food will be distributed to partner agencies serving Pike county.&nbsp;</p><p>Fresh food includes dairy, meat, eggs, fruits, and vegetables. Whenever possible, fresh food shall be procured from farmers located in Pike County.</p><p>Food pantries serviced with CDBG funds must prepare and submit a letter on letterhead stating they will collect a Self Declaration of Need form from each individual served and that no food or non-food items purchased through this grant will be distributed to individuals who have not completed a Self Declaration of need form or who are deemed to be ineligible due to income. A template for this letter can be found in Exhibit B of the contract attached.</p><p>Reports are due bi-monthly, according to the chart below. Completed reports should be sent to Katie Blake at Hailstone Economic, LLC which administers the CDBG funds: <a href=\"kblake@hailstoneeconomic.com\">kblake@hailstoneeconomic.com</a></p><p><strong>In March 2025, SHFB received permission to reallocate Outreach funds to Fresh Food Purchase. See letter below.</strong></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/936/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/938/image.png\"></figure>',NULL,34508.00,'2024-05-09','2025-08-31',NULL,NULL,NULL,'8069','2024-05-28 13:45:00','2025-04-03 18:06:56',NULL,206,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (339,'2024SSS_TJX Foundation',NULL,'<p>-$10,000 general operating for SSS</p><p>-No report required</p>',NULL,10000.00,'2024-05-15',NULL,NULL,NULL,NULL,'8000','2024-05-28 17:35:53','2024-05-28 17:35:53',NULL,131,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (340,'2024REJ_PPL_ Power and Equity _SHEGENX',NULL,'<p>-$10,000 for Generation Next and SHE to be used for general operating.</p><p>-There is no reporting requirement at this time.</p><p><strong>Marketing:</strong></p><p>-Please do not post on social media or prepare a news release prior to May 30th, 2024.</p><p>-Tag PPL on a social media post by mentioning <strong>@PPLCorp</strong>&nbsp;and <strong>@PPLElectric</strong>&nbsp;and use the hashtag <strong>#pplcares.&nbsp; </strong>The PPL Foundation logo is available to download <a href=\"https://www.pplweb.com/logo-downloads./\">here</a>.</p><p>-Please see sample news release in the attached documents.</p>',NULL,10000.00,'2024-05-21',NULL,NULL,NULL,NULL,'8000','2024-05-28 17:49:47','2024-05-28 17:49:47',NULL,82,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (341,'2024SHFB_FoodConnect_CSFP_Phase1',NULL,'<p>This Service Agreement establishes the relationship between SHFB and FoodConnect, a nonprofit organization focused on technology and logistics services in relation to hunger relief. This is a trial partnership, limited to Lehigh and Northampton County CSFP delivery, with the potential for expansion. This agreement is funded through a <a href=\"http://contracts.caclv.org/contracts/306\">Feeding PA grant</a>.</p><p>FoodConnect will be providing delivery services for CSFP boxes in Lehigh and Northampton Counties. Boxes will be distributed directly to seniors\' homes. FoodConnect will provide detailed distribution reports, for use in reporting back to Feeding PA.</p><p>The date of this agreement runs from March 1, 2024 - June 30, 2024.</p><p>FoodConnect will bill monthly on actual delivery volumes, according to the below payment schedule.</p><p>Questions regarding this service agreement should be directed to Kate Colyer, Regional Program Director, Northeast at <a href=\"kate@foodconnectgroup.com\">kate@foodconnectgroup.com</a>.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/941/image.png\"></figure><p>&nbsp;</p>',NULL,0.00,'2024-03-01','2024-06-30','yes','2024-09-24',NULL,'F1000','2024-05-31 15:54:11','2024-09-24 18:24:37',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (342,'2024 CADB_Lehigh University_Alley House Pilot Project','Sub award# 545010-78001','<p>Lead the community engagement process for the Alley House Pilot Project with all project partners. Please see \" Alley House Pilot Project Community Engagement Overview\" for more details. (Page 40 of the contract)</p><p><strong>Invoicing:</strong></p><p>This is a reimbursable grant and requires submission of invoices with cost details, receipts and back up monthly or no less than quarterly. Submission for reimbursement to ininv@lehigh.edu.&nbsp;</p><p>See program <i><strong>budget and allowable expenses</strong></i> on pages 40-41 of the contract (last two pages).</p><p>&nbsp;</p>',NULL,10000.00,'2024-03-01','2026-02-28',NULL,NULL,'<p><strong>Reporting:</strong></p><p>Will be done by Lehigh University and Karen Pooley (kbp312@lehigh.edu) will reach out for required data for reporting as needed.&nbsp;</p><p><strong>Record Retention:</strong></p><p>All records must be maintained until HUD notifies us that they have closed the program year.</p>','F2800','2024-06-17 13:27:13','2025-02-27 14:37:52',NULL,207,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (343,'2024HCPHRP_TD Charitable Foundation',NULL,'<p>General operating support HCP and CAH.&nbsp;</p><p>Impact report is required although due date is to be determined.</p><p>&nbsp;</p>',NULL,15000.00,'2024-06-13',NULL,NULL,NULL,NULL,'8000','2024-06-18 16:37:49','2024-06-18 18:16:35',NULL,144,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (344,'2024SSS_ National Giving Alliance',NULL,'<p>-Donations received through the National Giving Alliance must be used for current residents and must not be given out exclusively as holiday or birthday gifts.</p><p>-Donations cannot be exchanged for money.</p><p>-Accurate records must be maintained and provided to NGA for their donations.</p><p>-NGA would also like to be acknowledged by means of a newsletter, social media, marketing materials or a letter of appreciation.</p>',NULL,0.00,'2024-01-31',NULL,NULL,NULL,NULL,NULL,'2024-06-18 17:55:44','2024-06-18 17:56:38',NULL,208,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (345,'2024HCP_ Hoch Foundation',NULL,'<p>- $3,000 for HCP for general operating expenses.</p><p>No reports required.&nbsp;</p>',NULL,3000.00,'2024-06-18',NULL,NULL,NULL,NULL,'8000','2024-06-25 17:50:15','2024-06-25 17:50:15',NULL,155,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (346,'2024CACLV_LC Aging and Adult Services','24-AGNG-142','<p>TEFAP- As authorized</p><p>HAP Rental Payments- $317, 680</p><p>HAP Rental Assistance Aftercare-</p>',NULL,0.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F4200','2024-06-25 18:18:50','2024-07-01 12:41:48','2024-07-01 12:41:48',73,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (347,'2024CALV_LC Aging and Adult Services','24-AGNG-142','<p>TEFAP-as authorized (.10 cents/lb. or actual cost)&nbsp;</p><p>HAP Rental Assistance- $317,680</p><p>HAP Rental Assistance Care Management (Salary for Fiscal staff to process HAP Checks)-$28,328- $38.17 hourly rate</p><p>HAP Aftercare Managment (SSS Case Management)- $35,543- $39.58 hourly rate (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 3,6, and 12 months)</p>',NULL,0.00,'2024-07-01','2025-06-30','yes','2024-07-30','<p>-See Appendix B in contract for Budget and Rates (program CAP is set at $381,551)</p><p>-Reimbursable Grant</p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served. Billing statements not received by the 20th day of the month, following a month of service, can be subject to a late submission fee totaling 2% of the invoice.</p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.</p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services</p><p>-Record retention must be no less than 4 years post final payment under the agreement.</p>','4200','2024-07-01 12:41:07','2024-07-30 13:03:56',NULL,73,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (348,'2024CAH_PHFA PHARE_ Healthy Homes',NULL,'<p><strong>Grant Purpose:</strong> To assist 10 homeowners in Lehigh and Northampton counties to improve their homes living conditions, health and safety. &nbsp;</p><ol><li>See eligible improvements attached</li><li>See contract attached</li><li>See Budget attached</li><li>Grant Modification attached below -<strong>$50,000 to be used to modify 10 rental properties.</strong></li></ol><ul><li>30% of the grant must be used to benefit households below 50% AMI</li><li>No portion of the grant funds are to be used to benefit households above 200% AMI</li><li>Contract expires 18 months post full execution date</li><li><strong>Read</strong> Page 9, part C. Grantee responsibilities for provisions that need to carry over into subcontractor contracts</li><li>Debarment searches required for all subcontractors</li><li><strong>Read </strong>page 17, Article XXIII Workers Protection and Investment for all applicable acts and laws such as PA Prevailing Wage requirements</li></ul><p>&nbsp;</p>',NULL,300000.00,'2024-07-01','2026-03-12',NULL,NULL,'<ul><li><strong>Fiscal Requirement: </strong>The funds are to be placed in a separate interest-bearing account. Interest to be used for project purposes.</li></ul><p>&nbsp;</p><ul><li>Reports must be submitted 30 days from the end of each semi-annual period. Information to include itemized grant expenditures, HH income, geographic and demographic data, etc.</li></ul><p>&nbsp;</p><ul><li>Maintain all records related to this grant for a minimum of 4 years post agreement termination.</li></ul><p>&nbsp;</p>','F0621','2024-07-01 15:06:12','2024-11-13 13:50:11',NULL,209,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (349,'2024SHFB_AldiRetailRecovery','349','<p>This grant is intended to support SHFB\'s retail recovery efforts.</p><p>The grant amount is $1,000 and the grant period is from 6/1/2024 - 5/31/2025. The grant may be used toward salary and/or equipment and supplies to support retail recovery efforts. The grant may also be re-allocated to a partner agency to directly support their efforts in partnering with their local Aldi store.&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/991/image.png\"></figure><p>If additional stores open in our service area before the end of the grant period, SHFB may be eligible for additional funding.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/989/image.png\"></figure><p>SHFB will be asked to publicize the partnership with Aldi at such events as check presentations, new store openings, or any product drives.</p><p>SHFB is strongly encouraged to plan an employee volunteer event.&nbsp;</p>',NULL,1000.00,'2024-06-01','2025-05-31','yes','2025-07-02',NULL,'F8000','2024-07-03 11:45:21','2025-07-02 14:46:46',NULL,210,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (350,'2024HCP_LC Affordable Housing Trust',NULL,'<p>-Salary, benefits and program supplies for HCP.</p><p>-Can be used for work on Homebuyer seminars, pre-purchase counseling, pre-settlement counseling, loss mitigation services, applications for Homeowner emergency Mortgage Assistance program and foreclosure mitigation services.</p><p>-See Exhibit A for more details.</p>',NULL,40000.00,'2023-07-01','2025-06-30',NULL,NULL,'<p>-Invoices and reimbursement requests can be sent to Laurie Moyer via email at lauriemoyer@lehighcounty.org&nbsp;</p><p>-Grantee must include \"This project is supported in part by a grant from the County of Lehigh\" in all publications relating to this project.</p><p>-See page 3 Administrative Requirements part A, Section I for document retention requirements.</p><p>-This contract can be renewed for an additional year and must be requested in writing.</p>','4100','2024-07-03 12:54:37','2024-07-03 12:58:38',NULL,145,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (351,'2024SHFB_C&S Wholesale','351','<p>The purpose of this grant is to support SHFB\'s Child Nutrition program. The budget breakdown will be split between product purchasing and admin costs.&nbsp;</p><p>There is no reporting required for this grant.&nbsp;</p><p>There is no specific publicity requirement for this grant, but thank you letters and social media posts are encouraged. Copies of communications may be emailed to:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/996/image.png\"></figure><p>&nbsp;</p>',NULL,9000.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F8067','2024-07-03 13:32:24','2024-10-09 14:23:30',NULL,211,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (352,'2024SHFB_Sheetz For The Kidz','352','<p>The purpose of this $8,000 award is to support Child Nutrition programs. Costs will be split between product purchasing and administrative costs.</p><p>There is one report due on Jan 14, 2025. A template will be provided to the planner-SHFB@caclv.org email address.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1265/image.png\"></figure>',NULL,8000.00,'2024-05-01','2024-11-30','yes','2025-04-02',NULL,'F8016','2024-07-03 14:05:14','2025-04-02 17:48:48',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (353,'2024SHFB_Villaume Foundation','353','<p>This $10,000.00 grant will support food purchase and distribution costs to partner agencies in <strong>Wayne County</strong>.&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1000/image.png\"></figure><p>There will be a request for an impact statement sent to the planner-SHFB@caclv.org email. No other reporting is required.</p><p>There is no explicit requirement for publicity.</p>',NULL,10000.00,'2024-05-28','2024-12-31',NULL,NULL,NULL,'8000','2024-07-03 14:37:13','2024-07-05 13:50:52',NULL,212,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (354,'2024SHFB_Sanofi_Monroe County','354','<p>This grant is intended to cover transportation costs to distribute food to our Monroe County partner agencies.</p><p>This is a lump sum grant.</p><p>There is no report due.</p>',NULL,5000.00,'2024-06-11','2025-06-10',NULL,NULL,NULL,'F8000','2024-07-05 12:49:33','2025-05-20 12:48:24',NULL,119,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (355,'2024SHFB_VernoCanova The Seed Farm','355','<p>The purpose of this grant is to support general operating expenses for The Seed Farm.</p><p>This is a lump sum grant.</p><p>There is a progress report due January 31, 2025. The template is provided below.</p>',NULL,5000.00,'2024-06-14','2025-01-31','yes','2025-04-03',NULL,'8040','2024-07-05 13:20:14','2025-04-03 13:26:20',NULL,213,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (356,'2024SHFB_ShopRiteLPGA','356','<p>The purpose of this grant is to support food distribution to our partner agencies. Funding will be applied to food purchasing.</p><p>This is a lump sum grant.</p><p>There is no report due for this grant.</p>',NULL,20000.00,'2024-05-10','2025-05-31',NULL,NULL,NULL,'F6230','2024-07-05 13:55:32','2024-10-14 14:39:16',NULL,164,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (357,'2024SHFB_FeedingAmerica 2024 Paychex General Operating','357','<p>This grant applies to General Operating expenses.</p><p>This is a lump sum grant.</p><p>There will be one report due June 10, 2025, to be submitted through the Feeding America Grants Management System. A draft template is attached below.</p><p>There is a publicity requirement to this grant:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1012/image.png\"></figure><p>Employee engagement / volunteer activities are strongly encouraged. A list of Paychex representatives can be found here: <a href=\"https://feedingamerica.smartsimple.com/files/705864/f511762/Paychex_Local_Volunteer_Contacts.xlsx\">https://feedingamerica.smartsimple.com/files/705864/f511762/Paychex_Local_Volunteer_Contacts.xlsx</a></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1014/image.png\"></figure>',NULL,20957.06,'2024-06-01','2025-04-30','yes','2025-06-10',NULL,'8000','2024-07-05 14:53:00','2025-06-10 12:20:25',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (358,'2024SHFB_TEFAP Reach & Resiliency Amendment','C940001540','<p>The purpose of this amendment is to extend the original TEFAP Reach &amp; Resiliency grant period to expiration on <strong>June 30, 2024</strong>.</p><p>The final report is now due July 30, 2024.</p><p>The original TEFAP Reach &amp; Resiliency contract can be found here: <a href=\"http://contracts.caclv.org/contracts/298\">http://contracts.caclv.org/contracts/298</a></p>',NULL,0.00,'2024-01-23','2024-06-30',NULL,NULL,NULL,NULL,'2024-07-05 15:34:42','2024-07-09 12:07:39','2024-07-09 12:07:39',172,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (359,'2024SHFB_FeedingAmerica Hershey Child and Family Feeding',NULL,'<p>This grant is to support child nutrition efforts. Eligible expenditures include:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1021/image.png\"></figure><p>The grant period runs from 07/01/2024 - 01/31/2025.&nbsp;</p><p>A final report is due February 25, 2025 covering the full grant cycle. A template is attached below.</p><p>Employee engagement events are highly recommended:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1022/image.png\"></figure><p>Publicity and Media Coverage is highly recommended:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1023/image.png\"></figure>',NULL,14053.25,'2024-07-01','2025-01-31','yes','2025-04-02',NULL,'F8075','2024-07-17 12:57:33','2025-04-02 17:29:57',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (360,'2024-2025SHFB PMUW Monroe County Food Distribution',NULL,'<p>The purpose of this grant is to support the purchase and distribution of fresh foods to Monroe County. This is a lump sum grant. Grant funds are outlined as below.&nbsp;</p><p>Food Purchase: <strong>$5,000</strong><br>Fuel and Vehicle Maintenance: <strong>$5,00</strong><br>Staff Wage and Benefits: <strong>$10,000</strong> (agency relations coordinator for Monroe County)</p><p>The proposal states a service goal of 17,000 individuals.</p><p>A final report will be due approximately one month after the grant period ends. Reporting information will be sent to the planner-SHFB@caclv.org.</p>',NULL,20000.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F8065','2024-07-17 18:48:19','2024-10-22 12:19:15',NULL,115,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (361,'2024SHFB_Wawa Foundation Fly Beyond',NULL,'<p>This is a $25,000 grant award to support child nutrition initiatives, with a concentration on fresh produce. This is a lump sum grant.</p><p>The grant was awarded June 2024; a final grant period is to be determined.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1031/image.png\"></figure><p>A report is required; more information is forthcoming.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1032/image.png\"></figure><p>Media/Publicity is requested. A press release template is provided below.&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1033/image.png\"></figure>',NULL,25000.00,'2024-06-05','2025-07-01','yes','2025-06-02',NULL,'F8085','2024-07-18 14:36:17','2025-06-02 14:06:42',NULL,153,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (362,'2024-2025SHFB_Feeding PA_PASS_MOU',NULL,'<p>The Pennsylvania Agricultural Surplus System (PASS) program was designed to support Pennsylvania\'s agricultural industry statewide - to reduce waste of surplus product, support local farms, and get more nutritious food into the hands of Pennsylvanians experiencing food insecurity.<br><br>Food must be grown or produced in PA; wholesale or retail products do not qualify.</p><p>Assigned counties: Carbon, Lehigh, Monroe, Northampton, Pike, and Wayne.</p><p>PASS Suppliers will ensure that PASS Funding is allocated for all 67 PA counties in accordance with the approved SFPP Allocation Ratios for FY2024-2025. It is the responsibility of the PASS Subcontractor to carry out these allocations and distribute product t a value as close as possible to the dollar values allocated to their assigned counties.</p><p>An SHFB representative must attend a bi-weekly conference call led by Feeding PA\'s Director of Agricultural Partnerships to provide updates on food sourcing and distributions using PASS funds.</p><p>All purchases and commitments must be made by <strong>June 30, 2025</strong>.</p><p>All documentation of purchases and commitments must be submitted by <strong>July 10, 2025.</strong></p><p>All services must be complete by <strong>August 15, 2025</strong>.</p><p>SHFB must distribute 50% or more of their total funding allocation by <strong>December 31, 2024</strong>.</p><p>Monthly reports should be emailed to Feeding PA by the <strong>10th day of the following month</strong> until program completion. Reports should include:</p><ul><li>Source of product (vendor name, street address, county, and city of origin)</li><li>Product types and unit cost</li><li>Pounds and costs of food distributed</li><li>The street address and manner of each distribution</li><li>The number of households served and method of determining households served</li><li>Expense/reimbursement reports in Microsoft Excel format</li></ul>',NULL,0.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F4700','2024-07-18 18:27:37','2024-07-18 18:49:05',NULL,165,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (363,'2024SHFB_NCCDBG_Pantry Improvement',NULL,'<p>The purpose of this $25,000 grant is to support improvements to \"brick and mortar\" food pantries in Northampton County. Anticipated use is for capital improvements to the Whole Life Center in Wilson, with the end result of building out a food hub.</p><p><strong>Updated SOW and approval email attached to allow for improvements to SHFB such as Fire alarm system or new generator.</strong></p><p>This is a reimbursable grant.</p><p>There are no reporting requirements other than invoicing. Invoicing forms are below.</p><p>Restrictions and requirements follow HUD funding guidelines, including the below.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1047/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1048/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1049/image.png\"></figure><p>&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1051/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1057/image.png\"></figure><p>&nbsp;</p>',NULL,25000.00,'2024-06-10','2024-12-31',NULL,NULL,NULL,'F8071','2024-07-25 16:50:26','2024-11-19 15:50:45',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (364,'2024CADB_ M&T',NULL,'<p>-to be used for CADB general operating expenses for Southside Tomorrow Neighborhood Program.</p><p>-the funder would like to be recognized as a program supporter through social media and the approved logo is attached.</p>',NULL,5000.00,'2024-07-19',NULL,'yes','2025-06-27',NULL,'8000','2024-07-29 14:13:19','2025-06-27 16:46:06',NULL,147,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (365,'2024HCP_M&T',NULL,'<ul><li>general operating expenses HCP</li><li>funder would like to be recognized on social media and the approved logo is attached.</li><li>funder is also open to creation of a press release or an in person check presentation or other event.</li></ul>',NULL,5000.00,'2024-07-22',NULL,NULL,NULL,NULL,'8000','2024-07-29 14:25:34','2024-07-29 14:25:34',NULL,147,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (366,'2024HCP_SSS_Santander',NULL,'<p>-General operating expenses for HCP ($5,000) and SSS ($5,000).</p><p>-There will be a 6-month progress report and a final report. Email notifications will be received by the planner when these reports become available in the system.</p>',NULL,10000.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'8000','2024-07-29 14:34:47','2024-07-30 14:48:43',NULL,105,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (367,'2024CALV_LC Aging and Adult Services','24-AGNG-142','<p>TEFAP-as authorized (.10 cents/lb. or actual cost)&nbsp;</p><p>HAP Rental Assistance- $317,680</p><p>HAP Rental Assistance Care Management (Salary for Fiscal staff to process HAP Checks)-$28,328- $38.17 hourly rate</p><p>HAP Aftercare Managment (SSS Case Management)- $35,543- $39.58 hourly rate (Reimbursable for weekly case management prior to discharge from the shelter, weekly apartment inspections, and follow up case management post discharge at 30,60, and 90 days)</p>',NULL,0.00,'2024-07-01','2025-06-30',NULL,NULL,'<p>-See Appendix B in contract for Budget and Rates (program CAP is set at $381,551)</p><p>-Reimbursable Grant</p><p>-Invoices for SSS Aftercare and Clearinghouse Services to be received on or before the 10th day following the month services were provided (monthly basis). This includes statistical information required as back up of each unduplicated person served. Billing statements not received by the 20th day of the month, following a month of service, <strong>can be subject to a late submission fee totaling 2% of the invoice.</strong></p><p>-TEFAP reimbursement to be submitted quarterly for distribution costs at .10 cents per pound of food distributed.</p><p>-Audit report required by March 31st-sent to Lehigh County Aging and Adult Services</p><p>-Record retention must be no less than 4 years post final payment under the agreement.</p>','4200','2024-07-30 11:10:17','2024-07-30 14:02:27',NULL,73,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (368,'2024SHFB_FeedingAmerica_Costco Food Purchase',NULL,'<p>This is a lump-sum grant to support food purchase.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1071/image.png\"></figure><p>There is one final report due for this grant. A template is provided below. Reports are to be submitted through the GMS.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1070/image.png\"></figure><p>Additionally, the grant agreement requests:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1072/image.png\"></figure><p>&nbsp;</p><p>SHFB received approval to spend the money after the official grant period close. Please see emails below from Feeding America.</p><p>Questions on this grant should be directed to:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1073/image.png\"></figure>',NULL,52578.00,'2024-05-01','2025-02-28','yes','2025-07-15',NULL,'8072','2024-08-02 13:50:54','2025-07-15 13:23:38',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (369,'2025SHFB_Feeding America_CVS SNAP Application',NULL,'<p>The purpose of this $38,089.00 award is to support SNAP Application assistance. This is a lump sum award.</p><p><strong>Grant Activities/Expectations</strong></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1078/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1081/image.png\"></figure><p><strong>SHFB is required to track the below data points and share results in network engagements and reports.</strong></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1085/image.png\"></figure><p><strong>Use of Funds</strong></p><p>Funds will be used to support current staff salaries to perform SNAP outreach and application assistance as well as create a marketing strategy to reach potential SNAP beneficiaries within our urban centers and remote, rural communities. Funding will also be allocated to marketing efforts, in the form of digital outreach campaigns and the creation of printed materials.</p><p>Two reports are due. Sample templates are provided below, but all reports must be submitted via the FA Grants Management System.</p><ul><li>January 28, 2025 - Progress report covering August 1, 2024 - December 31, 2024</li><li>July 29, 2025 - Final report covering the entire grant period</li></ul><p>Timeline for the grant is:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1082/image.png\"></figure>',NULL,38089.00,'2024-08-01','2025-06-30',NULL,NULL,NULL,'F8076','2024-08-05 17:32:12','2024-10-07 17:22:49',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (370,'2024-2025_LC Children and Youth',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,'1300','2024-08-06 12:55:44','2024-12-05 19:02:56','2024-12-05 19:02:56',NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (371,'2024SSS_ Lehigh County Children and Youth','24-CY-084','<p>-11 apartments pre-paid at $70 per day. Ability to fill up to 15 apartments based on availability.</p><p>-Supportive Services billed at $65 per hour.&nbsp;</p><ul><li>Charge for case management and weekly apartment inspections (client facing). Be sure to obtain participant signature on the Children and Youth log.</li><li>Charge 1 hour per day every day for curfew checks</li></ul><p>-Extraordinary Expenses for damage to apartments. Upon exit inspection note and photograph damage. Bill Children and Youth for the cost of repair and provide the evidence. They will assess and reimburse us if approved.</p><p>-CAP for the Contract is $406,050</p>',NULL,0.00,'2024-07-01','2025-06-30',NULL,NULL,'<p><strong>Billing:</strong></p><p>Invoices must be submitted by the 5th working day of the month following the month of service. A 2% late submission fee may be applied to invoices received past the 20th day of the month.</p><p><strong>Reporting:</strong></p><p>-Monthly report/invoicing to go along with billing to be submitted to fiscal staff. This includes apartments that are filled and supportive services hours along with required back up.</p><p>-Quarterly reports are to be submitted to Lehigh County. An email will be sent out by the county, typically from Sharon Dunn sharondunn@lehighcounty.org, informing you when the report is due.</p><p>-Annual Report to be submitted to Lehigh County and follows the same protocol as the quarterly report listed above.</p><p><strong>Other Requirements:</strong></p><p>-Shelter staff must attend 12 hours of training per year</p><p>-Retain all records 7 years post completion of audit</p><p>-All shelter staff must have PA State Criminal History, Child Abuse Clearance, and Fingerprints with Federal Criminal History check. These clearances mut be renewed every 60 months.</p>','1300','2024-08-09 13:43:41','2024-08-09 13:52:44',NULL,159,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (372,'2024SHFB_FA_Cargill 2024 Food Safety Training',NULL,'<p>This $2,000 grant provides funding for food safety training(s) for food bank staff. This is a lump sum award.</p><p>Below is the list of eligible courses; detailed training information (including pricing and links for registration) is available in the attached proposal.</p><ul><li>Food Defense Update Webinar</li><li>Food Protection for Warehouses and DC\'s Webinar Series</li><li>Food Defense Coordinator</li><li>Understanding Good Manufacturing Practices (GMP)</li><li>Food Safety and Sanitation Online Individual Modules</li><li>ServSafe Food Handler Guide for Food Banking &amp; Online Video Companion Bundle</li></ul><p><strong>Grantees must register for trainings before</strong> <strong>September 30, 2024.</strong></p><p><strong>There is one final report due on Tuesday, October 29, 2024. </strong>A sample template is attached.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1101/image.png\"></figure>',NULL,2000.00,'2024-06-01','2024-09-30','yes','2025-04-02',NULL,'8000','2024-08-13 16:37:40','2025-04-02 17:10:36',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (373,'2025SHFB_FA_Agency Partner Capacity Building',NULL,'<p>The purpose of this grant is to provide funding for three (3) Agency Relations staff to participate in the FY25 Agency Partner Capacity Building Foundations Institute. The event will be held <strong>October 29 - 30 at the Feeding America National Office, 161 N Clark Street Chicago, IL 60601.</strong> This is a lump-sum grant. <i>Funds must be used to cover expenses related to attending the institute (travel, lodging, meals, etc).</i></p><p>The grant period runs from <strong>September 1, 2024 - October 31, 2024</strong>. It is encouraged but not mandatory that travel arrangements be finalized by September 30, 2024.</p><p>Participants must attend both days of the institute. Each attendee is expected to fill out a brief pre-institute survey to help provide food bank staff with a better learning experience. The pre-institute survey is due <strong>Thursday, September 12</strong>; links will be sent to registrants directly.</p><p>An optional pre-attendance call will <strong>be scheduled to review logistics and other details prior to the institute. </strong>The call will be held<strong> Wednesday, September 25</strong> from 1:00-1:45 pm CT and will be recorded. Details will be sent to registrants directly.</p><p>Attendees must complete an evaluation survey after the institute. These evaluations will be sent to registrants directly and must be completed by <strong>November 15</strong>.</p><p>Food banks must complete an Agency Relations Self-Assessment, if not already done so.&nbsp;</p><p>There is no report required for this grant.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1107/image.png\"></figure><p>For questions related to the Partner Network Services Training, please contact Jennifer Sheda, Senior Manager, Partner Network Services at <a href=\" jsheda@feedingamerica.org\">jsheda@feedingamerica.org</a>.</p>',NULL,4500.00,'2024-09-01','2024-10-31','yes','2025-04-02',NULL,'8000','2024-08-15 18:50:57','2025-04-02 17:10:03',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (374,'2025SHFB_Cedar Crest College Nutrition Intern MOU',NULL,'<p>The purpose of this MOU is to define the roles and responsibilities of Cedar Crest College (the College) and SHFB. SHFB has agreed to provide the clinical education necessary among the requirements for registration as a dietitian and to educate personnel at the post-baccalaureate level who can function effectively in a professional environment.</p><p>The College will administer the program, curriculum content, evaluation, faculty appointments, admission requirements, promotion and graduation and such other matters as are internal to the College. The College will maintain the necessary records of the students.</p><p>SHFB will provide access to the food bank\'s facilities and direct supervision by the Nutrition Educator, who will be directing the interns in 1,200 hours of practical study.</p><p>Additional stipulations are set out in the attached contract.</p><p>The SHFB points of contact for this MOU are the Nutrition Educator, who will be implementing the program, and the Volunteer Coordinator, who will recruit and retain the College interns.</p><p>There is no reporting due for this program.</p>',NULL,0.00,'2024-08-01','2029-08-01',NULL,NULL,NULL,'F8000','2024-08-16 12:33:00','2025-05-20 12:49:52',NULL,215,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (375,'2024SHFB_CSFP_Senior Food Box Home Delivery',NULL,'<p>This agreement outlines the usage of funding for the Senior Food Box Home Delivery Program. The funding is to support the Senior Food Box Program and to assist lead agencies with costs incurred in recruiting and ultimately providing service to more seniors in PA via home delivery.</p><p>The main contract was issued in December 2023, with an allowable reimbursement of $65,275. In July 2024, additional funding for Home Delivery was announced, with an allowable reimbursement of $58,152.00.</p><p>This is a reimbursement program; reimbursement requests are to be submitted 10 days after the reimbursement period (monthly) using <a href=\"https://docs.google.com/document/d/19XUeJyhCgkuCNkYVCIC_Uxk9r5YfAYQJerlr6Ryd3eM/edit?usp=drive_link\">Form 502069</a>. If SHFB anticipates not being able to utilize all of the allocation, Hunger Free PA must be alerted as soon as possible.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1112/image.png\"></figure><p>Capital expenditures are only available with prior approval:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1113/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1154/image.png\"></figure><p>The FoodConnect contract is available <a href=\"http://contracts.caclv.org/contracts/341\">here</a>.</p><p>Contact for the program is Sean Kerins (skerins@pafoodbanks.org).</p>',NULL,123427.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F8073','2024-08-20 14:50:27','2024-10-15 12:29:25',NULL,172,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (376,'2024SHFB_SF_ Davis & Smith Family Foundation',NULL,'<p>-General operating for the Seed Farm</p><ul><li>The money will come in two annual payments of $75,000 for a grand total of $150,000</li></ul><p>&nbsp;</p><p>&nbsp;</p><p><i><strong>-There is a report due after all the funds have been expended, please see below:</strong></i></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1116/image.png\"></figure>',NULL,150000.00,'2024-08-20',NULL,NULL,NULL,NULL,'F8040','2024-08-26 11:25:30','2024-08-26 12:05:30',NULL,166,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (377,'2024RTCLF_PPL',NULL,'<p>-To be used for day-to-day program management not for operational expenses</p><ul><li>Code F6360 set up for salary for Stephen Planisky</li></ul><p>-PPL would like us to acknowledge them through social media or other methods.&nbsp;</p><ul><li>There is more information such as an official logo and preferred tags in the attached award email.</li><li>There is also a sample press release attached.</li><li>Please wait until after September 2nd to acknowledge them publicly.</li></ul><p>-At this time there are no reporting requirements</p>',NULL,25000.00,'2024-08-21',NULL,NULL,NULL,NULL,'F6365','2024-08-26 12:15:12','2024-09-30 12:43:57',NULL,82,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (378,'2024-2025SHFB_United Way of Wayne and Lackawanna_Military Share',NULL,'<p>The goal of this funding is to provide \"Expanded Food Access\" to Military Veterans and their families in Wayne County. The stated target is 27 Military Shares distributed monthly.</p><p>A report will be due at the end of the grant period. More information, template and report due date will be emailed to the planner-SHFB@caclv.org email or through the portal: https://agency.e-cimpact.com/login.aspx?org=40520F (UN: Briana.McGonagle PW: Shfb6969!!$$)</p><p>A campaign kick-off event will be held 9/18. Additional details are available in the award letter.</p><p>Contact for this campaign is:</p><p>William Craven<br>Manager of Community Impact Funds<br>(570) 343-1267 ext 226<br>wcraven@uwlc.net</p>',NULL,4000.00,'2024-07-01','2025-06-30','yes','2025-07-09',NULL,'F8051','2024-08-27 14:23:41','2025-07-09 16:07:32',NULL,95,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (379,'2024_2025SHFB_CarbonCountyTEFAP',NULL,'<p><strong>Purpose:</strong></p><p>This agreement between SHFB and Carbon County establishes the terms and conditions for SHFB to provide TEFAP services to Carbon County.</p><p>SHFB must prepare a budget for the fiscal period of 10/1/2024 - 9/30/2025 identifying estimated operating costs for the distribution of Federal and State issued food commodities, using the following Allowable Costs line items as determined by PDA.</p><ul><li>Storage costs</li><li>Transportation Costs</li><li>Equipment Rental Costs</li><li>Printing/Copying Costs</li><li>Administrative Costs</li></ul><p>With prior approval, administrative monies may be used to purchase capital assets; i.e., freezers, refrigerators, and other equipment used to support emergency food assistance programs.</p><p>Services provided from 10/01/2024 - 9/30/2025 will be reimbursed at $.12 per lb distributed.</p><p>Reports are required quarterly as follows:</p><ul><li>Report #1 for (10/01/2024-12/31/2024); Due: <strong>01/20/2025</strong></li><li>Report #2 for (01/01/2025-03/31/2025); Due: <strong>04/20/2025</strong></li><li>Report #3 for (04/01/2025-06/30/2025); Due: <strong>07/20/2025</strong></li><li>Report #4 for (07/01/2025-09/30/2025); Due: <strong>10/20/2025</strong></li></ul><p><strong>NOTE</strong>: The invoice shall be accompanied by a completed TEFAP INVENTORY/PARTICIPATION REPORT for the respective quarter\'s activity, to support the amount being invoiced according to TEFAP regulations. ANY INVOICE NOT ACCOMPANIED BY A \"TEFAP INVENTORY/PARTICIPATION REPORT\" WILL NOT BE PAID UNTIL SUCH TIME AS THE COMPLETED REPORT IS RECEIVED. Reports are filed via the <a href=\"https://www.pameals.pa.gov/Authentication/Login\">PAmeals.pa.gov</a> website.</p><p><strong>Special Provisions outlined in the contract include:</strong></p><ul><li>When SHFB accepts commodities allocated by PDA under the program, it must remove the product(s) within ninety (90) days of the allocation notice.</li><li>SHFB agrees to distribute all commodities received by the county within a maximum time period of sixty (60) days from the date of acceptance by the county.</li></ul><p>&nbsp;</p><p><strong>Contact:</strong><br>Cindy Bizarre<br>401 Delaware Avenue, Third Floor<br>Palmerton, PA &nbsp;18071<br>Phone: 1-800-441-1315 ext. 4511 or 610-824-7830 ext. 4511<br>Fax: &nbsp;610-824-7836<br>Email: &nbsp;cbizarre@ptd.net</p>',NULL,0.00,'2024-10-01','2025-09-30',NULL,NULL,NULL,'F8078','2024-08-27 17:33:43','2024-10-07 17:24:52',NULL,173,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (380,'2024CADB_PHARE_Community Organizing and Tenant Advocacy',NULL,'<p>To support one on one tenant advocacy and education as well and landlord tenant mediation prior to eviction filings.</p><ul><li>See attached budget</li><li>See attached contract</li></ul><p>&nbsp;</p><ul><li>30% of the grant must be used to benefit households below 50% AMI</li><li>No portion of the grant funds are to be used to benefit households above 200% AMI</li><li>Contract expires 18 months post full execution date</li></ul>',NULL,150000.00,'2024-09-12','2026-03-12',NULL,NULL,'<ul><li><strong>Fiscal Requirement: </strong>The funds are to be placed in a separate interest-bearing account. Interest to be used for project purposes.</li></ul><p>&nbsp;</p><ul><li>Reports must be submitted 30 days from the end of each semi-annual period. Information to include itemized grant expenditures, HH income, geographic and demographic data, etc.</li></ul><p>&nbsp;</p><ul><li>Maintain all records related to this grant for a minimum of 4 years post agreement termination.</li></ul>','F0645','2024-09-11 15:25:32','2024-09-12 15:43:45',NULL,176,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (381,'2024RTCLF_ M&T Charitable Foundation',NULL,'<p>-general operating funds for RTCLF</p><p>-no required report</p>',NULL,5000.00,'2024-08-30',NULL,NULL,NULL,NULL,'8000','2024-09-11 16:59:27','2024-09-11 16:59:27',NULL,147,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (382,'2024CALV_ NC DHS_ Drug and Alcohol','#24-505','<p>CALV will act as the fiscal agent for authorized clients in their rental/ security fee as well as client supports. CALV will submit a check written to the landlord to secure housing for NC Drug and Alcohol clients. The fee for this service will be 5% of the amount of the check executed and reimbursement of the rental amount.&nbsp;</p><ul><li>See page 21 of the contract for Fee Schedule and billing codes</li><li>Billing should take place by the 10th of the month</li></ul>',NULL,20000.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'4300','2024-09-12 15:29:16','2025-03-25 11:26:54',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (383,'2024HCP_JP Morgan Chase',NULL,'<p>-HCP staff salary and benefits</p>',NULL,10000.00,'2024-09-14',NULL,NULL,NULL,NULL,'8000','2024-09-16 16:53:45','2024-09-16 16:53:45',NULL,178,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (384,'2024-2025SHFB_WayneCDBG',NULL,'<p><strong>Purpose:</strong> Wayne County has awarded SHFB a CDBG grant for $39,993.00 for the purchase of fresh food for Wayne County. This is a <strong>reimbursable grant</strong> with the grant period running from May 9,2024 - August 31, 2025. Food will be distributed to partner agencies serving Wayne County.</p><p>Fresh food includes dairy, meat, eggs, fruits, and vegetables. Whenever possible, fresh food shall be procured from farmers located in Pike County.</p><p>Food pantries serviced with CDBG funds must prepare and submit a letter on letterhead stating they will collect a Self Declaration of Need form from each individual served and that no food or non-food items purchased through this grant will be distributed to individuals who have not completed a Self Declaration of need form or who are deemed ineligible due to income. A template for this letter can be found in Exhibit B of the contract attached.</p><p><strong>Reports </strong>are due bi-monthly, according to the chart below. Completed reports should be sent to Katie Blake at Hailstone Economic, LLC which administers the CDBG funds: kblake@hailstoneeconomic.com</p><p><strong>In March 2025, SHFB received permission to reallocate Outreach funds to Fresh Food Purchase. See letter below.</strong></p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1159/image.png\"></figure><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1160/image.png\"></figure>',NULL,39993.00,'2024-09-24','2025-08-21',NULL,NULL,NULL,'F8084','2024-09-24 17:32:02','2025-04-03 18:06:32',NULL,216,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (385,'2024-2025SHFB_FoodConnect_CSFP_Phase2',NULL,'<p><strong>Purpose</strong></p><p>This Service Agreement establishes the relationship between SHFB and FoodConnect, a nonprofit organization focused on technology and logistics services in relation to hunger relief. This agreement is in relation to funding from a <a href=\"http://contracts.caclv.org/contracts/375\">Feeding PA grant</a>.&nbsp;</p><p>FoodConnect will be delivering senior boxes directly to seniors\' homes. FoodConnect will provide detailed distribution reports for use in reporting back to Feeding PA.</p><p>The date of this agreement is from July 1, 2024 - June 30, 2025.</p><p>FoodConnect will bill monhly on actual delivery volumes, according to the below schedule.</p><p>The relationship between SHFB and FoodConnect is being implemented in Phases, with the first phase being complete upon June 30, 2024. Additional phases will focus on participant expansion in Lehigh and Northampton Counties initially. A contract amendment signed November 2024 expands the scope of deliveries into Carbon and Monroe Counties.</p><p>Expansion scope and terms will be mutually agreed upon by SHFB and FoodConnect.</p><p>The tiered pricing model below is applicable to deliveries made in Lehigh and Northampton Counties only. Updated tiered pricing and contract addendum will be issued as necessary..</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1162/image.png\"></figure><p>Tiered pricing for Carbon and Monroe Counties:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1275/image.png\"></figure><p>Questions regarding this service agreement should be directed to Kate Colyer, Regional Program Director, Northeast at kate@foodconnectgroup.com.</p>',NULL,0.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F8000','2024-09-24 18:24:25','2025-05-20 12:49:30',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (386,'2024HCP_RTCLF_BOA',NULL,'<p>General Operating Support</p><p>-$5,000 HCP</p><p>-$5,000 RTCLF</p>',NULL,10000.00,'2024-09-18',NULL,NULL,NULL,NULL,'8000','2024-09-30 15:52:37','2024-09-30 16:14:56',NULL,169,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (387,'2024-2025SHFB_NAP-CFP','202406281426','<p>SHFB has been awarded a Neighborhood Assistance Program (NAP) for Charitable Food Program (CFP) in an amount not to exceep the tax credit amount of $435,500.00. The new tax credit percentage for CFP is 65%.</p><p>This is a $385,000 in-kind food donation contribution from UNFI and $50,000 in cash from M&amp;T Bank. The cash distribution will be made in a lump-sum by M&amp;T Bank before June 30, 2025. UNFI will continue it\'s existing pattern of donations, arranged via the food sourcing coordinator.</p><p>Qualified investment or contributions to the project identified in the SHFB application totaling a maximum of $670,000.00 shall be accepted from project donors between July 1, 2024 and June 30, 2025. All funds must be spent by September 30, 2025.</p><p>The budget submitted for this project is attached. The $50,000 contribution from M&amp;T will be applied to transportation. Note the below regarding budget and invoicing:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1172/image.png\"></figure><p>A report is due at the end of the grant period. More information will be sent to the planner-SHFB@caclv.org email.</p><p>Contact at PA DCED is:</p><p><strong>Dawn Bear</strong>, Administrative Assistant<br>PA Department of Community &amp; Economic Development<br>Center for Community Services<br>Commonwealth Keystone Building<br>400 North Street, 4th Floor | Harrisburg, PA 17120-0225<br>Phone: 717-307-2782<br><a href=\"mailto:dabear@pa.gov\">dabear@pa.gov</a></p><p>Contact at M&amp;T Bank is:</p><p><strong>Deanna L. Wells</strong>, CRA Officer<br>213 Market Street, Harrisburg, PA 17101<br>717-241-8143<strong>&nbsp;</strong><br><a href=\"mailto:dwells@mtb.com\">dwells@mtb.com</a><br>&nbsp;</p>',NULL,435500.00,'2024-07-01','2025-09-30',NULL,NULL,NULL,NULL,'2024-10-01 15:59:10','2024-10-02 15:45:18',NULL,NULL,'10.225');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (388,'2024CAH_LC CDBG CV_ Urgent Need Roof HVAC',NULL,'<p>CDBG COVID money to provide new roof and/ or HVAC unit to approximately 10 properties.</p><p><strong>Compliance Requirements: </strong>Pay attention to <strong>all Special Conditions</strong> outlined in section VI. starting on page 3. Some of them are outlined below:</p><ul><li>Each applicant must certify financial hardship due to COVID.<ul><li>Being elderly makes someone vulnerable to COVID and therefore they qualify. They still must self-certify.</li></ul></li><li>LMI Qualify all applicants and adult family members</li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.</li><li>Environmental Review to be conducted and submitted to Lehigh County for review and approval prior to beginning work on any home.<ul><li>Environmental Review paperwork is attached</li></ul></li><li>Follow 3 bid procurement process with proper documentation</li><li>A lien must be filed on each property (five-year self-forgiving lien based on the job cost, with forgiveness of 20% per year)</li><li>If the subrecipient receives income from the satisfaction of liens prior to the completion of the forgiveness period, the program income must be returned to Lehigh County.</li><li>Follow HUD Lead Based Paint Regulations</li><li>Follow Historic Preservation requirements</li><li>Contractors must produce COIs naming CALV and Lehigh County as additionally insured.</li><li>Best effort to provide bidding opportunity to Women and Minority Owned Business (W/MBE)</li><li>Staff who have salary reimbursed trough this grant must keep detail on duties performed during working hour to justify hours billed</li></ul>',NULL,250000.00,'2021-05-01','2026-04-30',NULL,NULL,'<p><strong>Reimbursement Process -</strong>please read page 4 of the contract subsection I for full details.&nbsp;</p><ul><li>Reporting and Invoicing Deadlines are attached.</li></ul><p><strong>Reporting:</strong></p><ul><li>Required Semi Annual and Annual reports to be submitted to cyndiking@lehighcounty.org<ul><li>Reporting forms are attached.</li></ul></li></ul><p><strong>Monitoring:</strong></p><ul><li>External monitoring to take place in June by Lehigh County.&nbsp;</li><li>All relevant documents attached.</li></ul>','F4205','2024-10-03 16:55:31','2025-04-21 15:53:19',NULL,145,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (389,'2024RTCLF_ Penn Community',NULL,'<p>-General Operating for RTCLF</p>',NULL,5000.00,'2024-10-10',NULL,NULL,NULL,NULL,'8000','2024-10-11 11:47:17','2024-10-11 11:47:44',NULL,217,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (390,'2024REJ_PPL_EITC',NULL,'<p>General operating for GENNXT $5,000 and SHE $5,000.00</p>',NULL,10000.00,'2024-09-30',NULL,NULL,NULL,NULL,'F8000','2024-10-11 11:52:36','2024-11-25 15:13:56',NULL,82,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (391,'2024CAH_Keystone Savings Foundation',NULL,'<p>Overall funding to support the&nbsp;Housing Rehabilitation Program (HRP). The fund serves as a gap funding to cover the construction cost (partial or full cost) to assist low-income families living in Lehigh and Northampton counties, and HRP program administration. The fund does not have specific number of households to be assisted, but rather to support HRP to achieve the FY24/25 annual goals of 40 families from the work plan</p><ul><li>Total number of low-income assisted in FY24/25</li><li>A story of low-income families receiving our help (preferred but optional</li></ul><p><strong>Budget: </strong>$6,400 construction cost and $1,600 CAH staff salaries</p>',NULL,8000.00,'2024-07-01','2025-06-30',NULL,NULL,'<ul><li>Provide Annual report to funder.</li><li>There is no reporting requirement for this grant.</li></ul>','F2850','2024-10-18 13:58:54','2025-03-25 14:39:59',NULL,218,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (392,'2025SHFB_Starbucks FoodShare Capacity Round 2',NULL,'<p><strong>Purpose</strong>:<br>This is a lump sum award of $31,003.00 awarded by Starbucks to support its <a href=\"https://stories.starbucks.com/stories/hunger-relief/\">FoodShare program</a>; delivering frozen product daily directly to partner agencies. This program is designed to provide necessary infrastructure to those partner agencies who receive Starbucks product.</p><p>Funds must be spent by September 30, 2025.</p><p>Starbucks will consider up to 1 year extension on fund expenditure. You may request an extension by contacting Starbucks via <a href=\"mailto:FoodShareUS@Starbucks.com\">FoodShareUS@Starbucks.com</a>, using the subject line: \"FY25 Capacity Building Grant Extension Request: SHFB Lehigh Valley\" prior to June 30, 2025.</p><p>Eligible expenses may include but are not limited to:</p><ul><li>Building infrastructure such as walk-in or reach-in coolers, freezers, or refurbishing a space for enhanced distribution.</li><li>Purchasing of receiving/distribution equipment and assets such as pallet jacks (electric or manual), scales, forklifts, push carts, shelving, associated sanitizing equipment, logistics equipment, etc.</li><li>Purchasing of Tote cleaning supplies (i.e. power washers).</li><li>Staff time related to FoodShare operation.</li><li>Establishment of sustainable food waste practices associated with downstream impact of increased product donation (i.e. composting).</li><li>Fuel stipends.</li><li>FoodShare communication amplification and 3PL and store-level stewardship.</li></ul><p><strong>Reporting:</strong></p><ul><li><strong>Midterm Report </strong>due February 16, 202<strong>5.</strong> Recipient will be provided with a brief template on learnings and challenges, along with opportunities to pivot funds, if needed.</li><li><strong>Budget Report </strong>due June 30, 2025, Recipient will be provided with a budget template to report on spend. Please note, grant funds are expected to be fully utilized by this date.</li><li><strong>Final Report</strong> due July 31, 2025,<strong> </strong>covering the 9-month grant period of 10/11/24- 6/30/25.</li></ul><p>More information on reporting can be found on the Report Due tab.</p><p><strong>Publicity/Recognition</strong></p><p>Recipient is required to recognize Starbucks at least one time during the grant period using social media and online platforms to help promote the partnership. Please reference the FoodShare Communications Toolkit for guidance, available on the Recipient\'s Versaic homepage.</p>',NULL,31003.00,'2024-10-01','2025-06-30',NULL,NULL,NULL,'F8089','2024-10-22 18:41:39','2024-10-28 13:47:01',NULL,194,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (393,'2025SHFB_FeedingPA_ServiceInsightsSupport',NULL,'<p>This is a $75,000 lump sum grant made available by Feeding PA to support the implementation of Service Insights to partner agencies.&nbsp;</p><p>Goals:</p><ul><li>Support personnel costs who will dedicate 1/4 of their time to the electronic data collection initiative</li><li>Meet the technology needs of onboard partner agencies, including but not limited to the purchase of technology or technology incentives to support technology needs. Exact discretion of usage of funds is left to SHFB.</li><li>Provide one analysis using the data from onboarded sites demonstrating the impact of Service Insights. The anticipated completion dates for these analyses are between June 1, 2025 and June 30, 2025.</li></ul><p>As a condition of this grant, appropriate personnel must participate in the Data Project Taskforce calls hosted by FeedingPA and submit two brief reports summary the progress of implementation. The reports are due January 1, 2025 and June 30, 2025.</p><p>Grant period is July 1, 2024 - June 30, 2025.&nbsp;</p><p>Questions regarding this grant should be directed to Shea Saman, Chief Financial Officer, at <a href=\"mailto:ssaman@feedingpa.org\">ssaman@feedingpa.org</a>.</p>',NULL,75000.00,'2024-07-01','2025-06-30',NULL,NULL,NULL,'F8087','2024-10-23 17:42:01','2024-10-28 13:34:54',NULL,165,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (394,'2024RTCLF_ Santander',NULL,'<p><strong>Purpose:</strong> General Operating support</p><p><strong>Reporting Schedule:</strong> Within six (6) months of the date of execution of this Agreement by the parties and within forty-five (45) days of the end date of the Grant term, and/or upon request of the Grantor.</p><p>6-Month Report from Grantee due April 30, 2025</p><p>Final Report from Grantee due November 15, 2025</p>',NULL,10000.00,'2024-10-01',NULL,NULL,NULL,'<p><strong>Name and Logo Usage:</strong> Grant recipients are <strong>required</strong> to acknowledge the Bank’s philanthropic support in online or printed materials in accordance with the guidelines below and the terms of the Grant Agreement.</p><p>Santander Bank, N.A. is the legal name and may be used to reference the Bank in the absence of a trademark consent letter. The use of “Santander Bank Foundation” is not permitted.</p><p>Linking Registered Trademarks to Website. With written permission, our name or logo may link directly to the Santander Bank, N. A. website in online materials: <a href=\"https://www.santanderbank.com/\">https://www.santanderbank.com</a></p><p>Official Social Media Accounts. Tagging on social media is permitted using our handles on the following sites:</p><ul><li>Instagram – santanderbankus</li><li>LinkedIn – Santander Bank, N.A.</li><li>Facebook – Santander Bank US</li></ul><p><br>Questions and requests for permission to use trademarks, or for quotes and other media resources should be directed to the Philanthropy Team at <a href=\"mailto:giving@santander.us\">giving@santander.us</a>.</p>','8000','2024-11-12 13:44:48','2024-12-05 19:04:30',NULL,105,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (395,'2024SSS_ Kiwanis',NULL,'<p>To purchase fire blankets for the Shelter.</p><p><strong>To receive funds</strong>: Annual Foundation Grant Awards Luncheon, to be held on Thursday, December 12, 2024 from 12:00 PM to 1:30 PM at the Shanty on 19th restaurant in Allentown. A representative from the Shelter will attend to be presented with the grant check and offer brief remarks on how the funds will be used to serve the community.&nbsp;</p><p><strong>Report</strong> due by October 1st, 2025.&nbsp;</p>',NULL,1000.00,'2024-12-12',NULL,NULL,NULL,NULL,'8000','2024-11-12 14:41:35','2024-11-12 15:26:40',NULL,179,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (396,'2024CADB_ City of Bethlehem CDBG_ Tenant Advocacy',NULL,'<p>-Personnel Costs for the Tenant Advocate.&nbsp;</p><ul><li>Tenant advocate to conduct tenant advocacy, LL/Tenant mediations, Program Coordination, and Tenant Education and Empowerment. See detailed Scope of Activity (Exhibit A-on page 19 of the contract).</li><li>Goals and Performance (see page 20 of the contract) specifies what to track and keep record of.</li><li>Specified qualifications for tenant advocate to include obtaining HUD certification (see Exhibit A-1- on page 21 of the contract).</li></ul><p><strong>Grantee Recognition:</strong> Must include reference to the support provided from the City of Bethlehem CDBG in all the publications made possible with funds made available under this agreement.</p><p><strong>Record Retention:</strong> Hold all records until HUD formally closes the program year with the City of Bethlehem.</p><p><strong>Client Data to collect: </strong>Demonstrate client eligibility for services provided. Collect name, address, income level and household size data and description of services provided.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1253/image.png\"></figure><p>&nbsp;</p><p>&nbsp;</p>',NULL,50000.00,'2024-01-01','2025-12-31',NULL,NULL,'<p>&nbsp;</p><ul><li>Request for Reimbursement Instruction:</li></ul><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1252/image.png\"></figure>','F2147','2024-11-12 15:11:07','2025-04-10 15:15:30',NULL,171,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (397,'2025SHFB_MARC Membership Agreement',NULL,'<p>This agreement is between the Mid-Atlantic Regional Cooperative (MARC), a program of Feeding PA, and SHFB. The document outlines the responsibilities and expectations of both parties. <i>This agreement shall continue until terminated by either party.</i></p><p>As a member, SHFB commits to the following:</p><ul><li>Commitment to a minimum of a bi-annual ordering schedule.</li><li>Commitment to providing a signed copy of the Bill-of-Lading and Receiving Report to the MARC for all received loads upon request.</li><li>Commitment to a timely response to all MARC product inquiry communications.</li><li>Commitment to a net 30-day timely payment of all invoices.</li><li>Provide a single point of contact that can be immediately contacted by the MARC should the need arise.</li><li>Provide an annual update of current contacts for the food bank.</li></ul><p>An authorized representative from SHFB is required to serve as the primary point of contact for matters related to compliance with the Membership Agreement and represent SHFB in any votes or surveys regarding membership matters. The authorized representative is required to ensure that the member food bank meets all program and policy requirements, including:</p><ul><li>Maintain confidentiality of information garnered through participation in MARC programs and not to share information or use it to the detriment of MARC of any of its members.</li><li>Attend and participate in all required meetings.</li><li>Meet program participation agreements and program standards, including timely submittal of data.</li></ul><p>Additional stipulations and requirements are available in the Member Agreement below.</p><p>The Schedule of Fees is available in the Agreement document and is outlined below:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1260/image.png\"></figure>',NULL,0.00,'2024-11-01',NULL,NULL,NULL,NULL,'F8000','2024-11-14 18:45:18','2025-05-20 12:49:06',NULL,165,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (398,'2024CADA_ GLV Auto Association',NULL,'<ul><li>Support for CADA Youth Entrepreneurship Program</li><li>Applicants are required to submit a report detailing fund usage, its impact on the community, and effects on donors and clients. Additionally, they must agree to present at a future GLVADA Board or General Membership meeting to discuss the grant’s impact.<strong>&nbsp;</strong></li><li><strong>No report required</strong></li></ul>',NULL,2500.00,'2024-11-10',NULL,NULL,NULL,NULL,'8000','2024-11-19 19:44:12','2024-12-04 13:53:50',NULL,219,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (399,'2024REJ-Fulton Bank_ EITC',NULL,'<p>-General Operating for SHE and Generation Next split 50/50</p>',NULL,2000.00,'2024-12-02',NULL,NULL,NULL,NULL,'8000','2024-11-22 18:07:11','2024-12-10 16:36:48',NULL,223,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (400,'2022-2025SHFB_LehighCountyCDBG CARES',NULL,'<p>The purpose of this grant is to purchase and distribute fresh produce to food panties within Lehigh County.&nbsp;</p><p>Proposed goals:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1270/image.png\"></figure><p>After initial grant implementation, four of the six pantries referenced above decided that level of data collection mandated by the CDBG agreement was prohibitive; the only two pantries utilizing funding for the contract period was WCHI and St. Stephen\'s Pantry at Whitehall.</p><p>Contract will allow for any produce and/or perishable proteins. Please see email from Laurie Moyer attached below.</p><p>Contract extended to make all purchases by Sept. 30, 2025. Please see email from Laurie Moyer attached below.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1642/image.png\"></figure>',NULL,74250.00,'2021-05-01','2025-09-30',NULL,NULL,NULL,'2910','2024-11-25 17:46:52','2025-05-12 12:42:24',NULL,145,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (401,'2024SHFB_Sanofi_Monroe County Transportation November',NULL,'<p>The purpose of this grant is to support distribution costs to Monroe County. This is a lump sum award.</p><p>There is no stipulated request for publicity.</p><p>Sanofi has indicated an interest in continuing volunteer involvement.</p><p>An impact report is due Sept 30, 2025. Information will be sent to the planner-shfb@caclv.org email address. The report can be found on the Sanofi portal at: <a href=\"https://www.cybergrants.com/sanofi/uscontributions\">https://www.cybergrants.com/sanofi/uscontributions</a></p><p>&nbsp;</p>',NULL,10000.00,'2024-11-20','2025-10-31',NULL,NULL,NULL,'F8000','2024-11-25 18:58:47','2025-05-20 12:48:07',NULL,119,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (402,'2024REJ_ American Bank_ EITC',NULL,'<p>-General operating for SHE and Generation Next</p>',NULL,6500.00,'2024-11-26',NULL,NULL,NULL,NULL,'8000','2024-11-26 14:12:15','2024-11-26 14:12:15',NULL,97,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (403,'2024REJ_QNB Bank_ EITC',NULL,'<p>-General Operating for <strong>Generation Next ONLY</strong></p>',NULL,1250.00,'2024-11-26',NULL,NULL,NULL,NULL,'8000','2024-11-26 14:13:29','2024-11-26 14:14:06',NULL,220,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (404,'2024CAH_City of Bethlehem PHARE_ Alley House',NULL,'<p>-To construct an affordable housing unit located at 1604 W Broad Street, Bethlehem, PA</p><p><strong>-Reimbursable Grant:</strong></p><ul><li>Section 5, page 3<strong> Disbursement of Subaward Funds, </strong>including financial reports to be submitted by e-mail to Sara Satullo at ssatullo@bethlehem-pa.gov for reimbursement. Requests for reimbursement every 30 calendar days.</li><li>Program Budget is the last three pages of the uploaded contract</li><li>20% markup of construction costs will cover CALV staff salary as previously agreed upon with the City. Email uploaded here.</li></ul><p><strong>Other Provisions of Importance:</strong></p><ul><li>Contractors COIs must name \"The City of Bethlehem\" and \" Community Action Lehigh Valley\" with coverages shown on page 5 section 13 of the contract.</li><li>Contractor Contracts must include the section 16 Subrecipient Integrity Provisions on pages 6-9 of the contract.</li><li>Contractor Contracts must include section 18 Nondiscrimination and Sexual Harassment provision on pages 10-12 of the contract.</li><li>Follow formal Bidding procedures</li><li>PA Prevailing wage requirement over $24,999</li></ul><p>&nbsp;</p>',NULL,372447.05,'2024-12-04','2026-12-09',NULL,NULL,NULL,'F0622','2024-12-04 15:58:49','2024-12-10 17:19:21',NULL,171,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (405,'2024CAH_LC CDBG_ Urgent Need Roof HVAC',NULL,'<p>-Rehabilitation of 18 properties providing new roof and or HVAC system. &nbsp;Also, modifications to homes of homeowners who wish to age in place.</p><ul><li>LMI Qualify all applicants and adult family members</li><li>Only Lehigh County residents living outside the city limits of Allentown and Bethlehem and not residents of Lower Milford Township qualify.</li><li>Environmental Review to be conducted and submitted to Lehigh County for review and approval prior to beginning work on any home.<ul><li>Environmental Review paperwork is attached</li></ul></li><li>Follow 3 bid procurement process with proper documentation</li><li>A lien must be filed on each property (five-year self-forgiving lien based on the job cost, with forgiveness of 20% per year)</li><li>If the subrecipient receives income from the satisfaction of liens prior to the completion of the forgiveness period, the program income must be returned to Lehigh County.</li><li>Follow HUD Lead Based Paint Regulations</li><li>Follow Historic Preservation requirements</li><li>Contractors must produce COIs naming CALV and Lehigh County as additionally insured.</li><li>Best effort to provide bidding opportunity to Women and Minority Owned Business (W/MBE)</li><li>Staff who have salary reimbursed trough this grant must keep detail on duties performed during working hour to justify hours billed</li></ul><p>&nbsp;</p>',NULL,341371.04,'2025-01-01','2026-09-30',NULL,NULL,'<p><strong>Reimbursement Requests:&nbsp;</strong></p><ul><li>Documents listed on page 4-5 subsection n. must be included in reimbursement requests</li><li>Invoicing Deadlines are attached.</li></ul><p><strong>Reporting:</strong></p><ul><li>Required Quarterly and Annual reports to be submitted to cyndiking@lehighcounty.org<ul><li>Reporting forms and deadlines are attached.</li></ul></li></ul><p>&nbsp;</p>','F4206','2024-12-04 19:19:34','2024-12-05 17:21:55',NULL,145,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (406,'2024REJ_Weis Markets_EITC',NULL,'<p>General operating for SHE and Generation Next split 50/50.</p>',NULL,2000.00,'2024-11-25',NULL,NULL,NULL,NULL,'8000','2024-12-05 19:07:53','2024-12-05 19:11:51',NULL,222,NULL);
