INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (409,'2024HCP_ City of Bethlehem CDBG_ BHAP',NULL,'<ul><li>Salary and benefits for the HCP to conduct First Time Homebuyer seminars, Pre-purchase counseling, Pre-settlement counseling (Homeownership Counseling Program)</li><li>Home ownership savings account program for down payment and closing costs.</li><li>See performance measures and goals on page 20 Exhibit A</li></ul><p>Amendment provided extends contract through 12/31/25 and provides an additional $10,000</p>',NULL,35000.00,'2024-01-01','2025-12-31',NULL,NULL,'<ul><li>Monthly reimbursement instructions page 20 Attachment A.</li><li>Quarterly Reports to be submitted in the Neighborly portal.</li></ul>','F0550','2024-12-10 16:52:54','2025-03-27 14:55:34',NULL,103,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (410,'2024SHFB_ Lansford_ Statewide LSA_ Grace Community Church',NULL,'<p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p>Budget:</p><ul><li>$1,218 for administrative costs for CALV staff</li><li>$43, 115 for two stair lifts</li><li>$17,760 installation of handicap ramp</li></ul>',NULL,62903.00,NULL,NULL,NULL,NULL,NULL,NULL,'2024-12-10 19:06:44','2024-12-10 19:07:25',NULL,224,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (411,'2024SHFB_ Lansford_Monroe County LSA_ Grace Community Church','C000089378','<p>Exterior work on the Grace Community Center Building- Detailed Scope of Work and Budget to come</p><p>5% of the total contract amount may be used for CALV administrative expenses= $13,156.00</p><p><strong>LSA Compliance Requirements</strong></p><ul><li>Must provide CFA with copies of all executed contracts for all Project-related work to be performed</li><li>A certificate of insurance naming CALV, Lansford Borough, Commonwealth Finance Authority and Grace Community Church as additionally insured is required of all contractors</li><li>Prevailing wage requirements with certified payrolls (first and last notarized) required to be submitted as part of the reimbursement process</li><li>Open and Competitive Bidding Procedures as prescribed by Lansford Borough</li><li>Document Retention 7 years post final activity</li><li>Article XIII Acknowledgment of Commonwealth Assistance (page 18)</li><li>ALL CONTRACTS MUST BE MADE WITH CALV AND SIGNED BY CALV</li><li>Contractor Debarment Searches</li><li>Collect Contractor Licenses and Insurance</li><li>All subcontractor contracts must have language surrounding BABA, PA Prevailing Wage and non-discrimination and sexual harassment enclosed in Exhibit A.</li><li>Performance and payment bonds are required, or no reimbursement will take place until 100% of the job is completed to satisfaction</li><li>Subcontract to include Grantee Integrity Policy outlined in section C</li></ul><p>&nbsp;</p>',NULL,252466.00,'2024-05-21','2027-06-30',NULL,NULL,'<p><strong>Reimbursement Procedures:</strong></p><ul><li>Borough of Lansford will submit payment requests</li><li>Complete payment request forms with 2 signatures from the borough</li><li>Copies of invoices</li><li>Proof of competitive procurement, process and results,</li><li>Performance and payments bonds must be submitted, or no reimbursement may be requested until the entire project is completed</li><li>Close out requirements include providing copies of all canceled checks by the expiration of the grant period for all applicable expenses</li></ul><p><strong>Annual Report to DCED:</strong></p><ul><li>This will be Lansford Borough\'s responsibility</li><li>Included in Appendix A/B page 6</li></ul>',NULL,'2024-12-10 19:12:23','2025-06-30 12:46:33',NULL,225,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (412,'2024SSS_City of Allentown_ Community Reinvestment Fund',NULL,'<p>-Use for Supportive Services for Shelter Residents including:</p><ul><li>Salary and benefits for the Overnight Caretaker, Intake Specialist, Office Administrator, Maintenance Person, Case Manager, and Housing Specialist.</li><li>Please see Scope of Services and Deliverables (Exhibit B page 18-19 of the contract attached) for detailed activities to be carried out with this grant funding.</li></ul><p><strong>Reporting:</strong></p><ul><li>Quarterly Expense Reports are required (Use exhibit C on page 20 of the contract attached and send to latarsha.brown@allentownpa.gov and grants@allentownpa.gov with all appropriate supporting back up)</li><li>Quarterly Touch base, which can be conducted by a scheduled phone call or Teams Meeting.</li><li>&nbsp;Mid-Point Report, which will measure the progress of goals and scope of services.</li><li>&nbsp;Final Report due upon the depletion of the grant allocation or end term of the grant agreement.</li><li>For all reporting requirements the city will reach out to schedule or request information.</li><li>&nbsp;If you have any questions regarding these reports, please contact grants@allentownpa.gov&nbsp;</li></ul><p><strong>******THIS MONEY WILL COME IN LUMP SUM</strong></p>',NULL,50000.00,'2024-12-30','2025-12-31',NULL,NULL,NULL,'F1220','2024-12-17 19:20:59','2025-01-30 20:37:17',NULL,226,'21.027');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (413,'2024-2025SHFB TEFAP Reach & Resiliency Round 2','C940001950','<p>This is a reimbursable grant for $47,299.00 designated for the purpose of purchasing a reach truck: Yale NRO35DC.<br><br>&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1307/image.png\"></figure><p>Payment will be made upon submission of an approved invoice. A report is due at the end of the grant period or after the project has been completed (if prior to the period ending).</p><p>Contact for this program is Caryn Long Earl at cearl@pa.gov.</p>',NULL,47299.00,'2024-05-23','2025-06-30',NULL,NULL,NULL,'F8094','2024-12-19 13:23:51','2025-01-23 16:24:17',NULL,NULL,'10.568');
