INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (416,'2025CADA_Iron Pigs_ Afterzone Flag Football',NULL,'<p>-Equipment purchase for AfterZone Flag Football Program</p>',NULL,2500.00,'2025-01-01','2025-12-31',NULL,NULL,'<ul><li>An end of project summary is required by November 3rd, 2025</li><li>Iron Pigs Charities would like a site visit during the grant period</li><li>Any publicity, advertisement or public comment related to this project must acknowledge and credit the participation of Iron Pigs Charities. Please use official Iron Pigs Charities logo.</li></ul><p>Contact Anne Culhane</p><p>aculhane@ironpigsbaseball.com</p><p>(610) 841- 1228</p>','F1404','2025-01-09 18:01:46','2025-01-09 18:06:01',NULL,227,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (417,'2024RTCLF_ PA CDFI Grit Fund',NULL,'<p>-General operating for RTCLF</p><p>Grantee Responsibilities:</p><p>-Attend PA CDFI Network meetings</p><p>-Complete at least 6 small business loans during the first year of the program when receiving GRIT Fund.</p><p>(More responsibilities on 2 of contract)</p>',NULL,10000.00,'2024-07-01','2025-06-30',NULL,NULL,'<p>Quarterly Reports</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1346/image.png\"></figure>','F3596','2025-01-13 16:18:31','2025-01-13 16:35:17',NULL,186,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (418,'2024RTCLF_ PNC',NULL,'<p>-$5,000 for general operating&nbsp;</p><p>-A <strong>report</strong> will be due at least one year of the paid date a notification will be sent via email once the report is available</p>',NULL,5000.00,'2024-12-23','2025-08-30',NULL,NULL,NULL,'8000','2025-01-13 21:01:19','2025-01-13 21:01:19',NULL,78,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (419,'2025CADB_ Martin Guitar',NULL,'<ul><li>CADB General operating</li></ul>',NULL,10000.00,'2024-12-16',NULL,'yes','2025-06-27','<p>-One page report due by November 21, 2025:&nbsp;</p><ul><li>Last year\'s report submitted is attached for reference</li><li>Foundation Guidelines attached also provide information as to what needs to be included in the report.</li></ul>','8000','2025-01-14 15:17:58','2025-06-27 16:46:43',NULL,189,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (420,'2025SHFB_C&S Wholesale Grocers Child and Family Feeding',NULL,'<p>This is a $10,000 lump sum grant to support the start-up, sustainment, or expansion of Child and Family Feeding Programs.</p><p>Funds can be used to support the costs <strong>directly associated</strong> with this program:</p><ul><li>Staff salary &amp; benefits</li><li>Food</li><li>Equipment</li><li>Supplies</li><li>Outreach</li><li>Training</li><li>Cost-share for home delivery services</li><li>Program evaluation</li><li>SNAP outreach and/or application assistance targeted toward families with children</li><li>Educational activities to engage policy &amp; decision-makers, with the goal of improving child nutrition programs and ultimately reaching more children and their families.</li></ul><p><strong>Reporting Requirements</strong></p><p>There will be one (1) final report required for this grant, due <strong>August 26, 2025</strong> and covering entire grant period, 2/1/25-7/31/25 <i>(6 months)</i></p><p>Report requirements include but are not limited to:</p><ul><li>Grant impact and program description</li><li>Confirmation of funds expenditure</li><li>Metrics<ul><li># meals and/or pounds distributed</li><li># of children served (unduplicated)</li><li># of households served (unduplicated)</li><li># of program/distribution sites</li></ul></li><li>Successes and challenges</li><li>Stories, photos, and testimonials</li><li>Media and communications</li><li>Donor engagement</li></ul><p><strong>Publicity Requirements</strong></p><p>As a grant recipient, your food bank is encouraged to recognize the donor for this grant award throughout the grant period using social media and online platforms to help promote the partnership and create community visibility of this grant award.</p><p>While reports are an important method used to foster donor relations, they are no substitute for hearing directly from you.  We encourage you to email a thank-you letter to the following:&nbsp;</p><p><strong>Kate Cote</strong>&nbsp;<br><i>C&amp;S Wholesale Grocers</i>&nbsp;<br>c/o Brandon Sampson<br><i>Feeding America Corporate Partnerships Team</i>&nbsp;<br><a href=\"mailto:bsampson@feedingamerica.org\">bsampson@feedingamerica.org</a>&nbsp;</p><p>Questions related to Feeding America’s relationship with the donor, please contact Brandon Sampson, <i>Manager, Corporate Partnerships</i>, at&nbsp;<a href=\"mailto:bsampson@feedingamerica.org\">bsampson@feedingamerica.org.</a></p><p>Technical GMS questions related to proposal or report submission, please contact Sally Yan, <i>Sr. Manager, Member Grants</i>, at&nbsp;<a href=\"mailto:syan@feedingamerica.org\">syan@feedingamerica.org</a>&nbsp;&nbsp;</p>',NULL,10000.00,'2025-02-01','2025-07-31',NULL,NULL,NULL,'8095','2025-01-16 16:00:30','2025-01-16 16:05:02',NULL,211,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (421,'2024-2025SHFB_NCTEFAP Agreement','24-1066','<p>SHFB shall accept for storage, prepare for distribution, distribute via its network of affiliated food pantries, and account for food commodities made available to Northampton County residents via TEFAP. SHFB shall publicize availability of foods via public service announcements.&nbsp;</p><p>This is a reimbursement grant. Billing and invoicing instructions are below. Reports must be submitted according to the schedule outlined below.&nbsp;</p><p>&nbsp;</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1370/image.png\"></figure>',NULL,0.00,'2024-10-01','2025-09-30',NULL,NULL,NULL,'F8092','2025-01-16 19:22:55','2025-01-23 15:33:16',NULL,2,'10.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (422,'2024SHFB NC CDBG Retail Recovery',NULL,'<p>The original scope of work provided with this grant has been amended to address capacity building/improvements at Northampton County pantries involved in the retail recovery program. The $50,000 revised budget is as follows:</p><ul><li>$22,500 - Salary/fringe</li><li>$2,500 - Travel</li><li>$25,000 - Equipment</li></ul><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1730/image.png\"></figure><p>The reporting schedule is below; a template for reporting is available in the contract.</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1405/image.png\"></figure>',NULL,50000.00,'2024-10-01','2025-09-30',NULL,NULL,NULL,'F8096','2025-01-30 17:02:17','2025-06-12 14:36:49',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (423,'2024SBR NC CDBG Program Administration',NULL,'<p>Salary and benefits for the Director of Slate Belt Rising.</p>',NULL,25000.00,'2024-10-24','2025-09-30',NULL,NULL,'<p>Semi- Annual Reports:</p><ul><li>April 30th, 2025, and October 30th, 2025.</li></ul>','F0750','2025-01-30 17:02:41','2025-02-21 17:24:14',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (424,'2024HCP NC CDBG Housing Counseling Program',NULL,'<ul><li>Salary and Benefits for all Housing Counseling activities for participants in Northampton County (First time homebuyer Seminars, Pre- Purchase Counseling, Foreclosure Mitigation Counseling, etc..)</li></ul>',NULL,10000.00,'2024-10-01','2025-09-30',NULL,NULL,'<p><strong>Reports:</strong></p><p>Semi- annual due on April 30th, 2025, and October 30th, 2025. Reporting template is page 43 and 44 of the contract.</p>','F0753','2025-01-30 20:59:03','2025-03-20 18:17:23',NULL,2,'14.218');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (425,'2025SBR NC Grow Norco Facade and Mural',NULL,'<p>NC Local Share money for Facade Improvements and Mural Program.</p><ul><li>This grant requires a 1-1 match.</li><li>$8,000 for Rehabilitation and Renovation and $2,000 for Administration</li><li>You must notify the county in writing 60 days prior to the termination of the contract to request an extension if needed.</li><li>Any publications or media referencing a project funding with these funds must Acknowledge Assistance of NC. See section 39 on page 10 for details.</li></ul>',NULL,10000.00,'2025-01-01','2025-12-31',NULL,NULL,'<p>Reports Due-</p><p>July 28, 2025, and January 28, 2026.</p><p>&nbsp;</p>','F0821','2025-01-31 17:52:26','2025-02-21 20:45:34',NULL,2,NULL);
