INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (428,'2025SBR NC Grow Norco Facade and Mural',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,'2025-01-31 17:59:35','2025-02-07 14:05:44','2025-02-07 14:05:44',NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (429,'CADCA Allentown School District 21 Century Grant 24/25 SY',NULL,'<p>Allentown School District will pay CADA $25,000 during the 2024/2025 School Year for the administration of the Excelsior Program in three of their schools. CADA will subcontract with the Fine Feather Foundation who will administer the program in the schools.&nbsp;</p><ul><li>$23,000 will be used to pay the Fine Feather Foundation and $1500 will be used for Administration (Salary and Benefits for CALV, CADA Employees)</li></ul><p>We will bill ASD for a total of:</p><ul><li>$7000 for William Allen Highschool</li><li>$9000 for Trexler Middle School</li><li>$9000 for Central Elementary School</li></ul><p>Fine Feather Foundation will invoice CADA:</p><ul><li>$650 for each weekly session at William Allen Highschool for a total of $6,500</li><li>$850 for each weekly session at Trexler Middle School for a total of $8,500</li><li>$850 for each weekly session at Central Elementary School for a total of $8,500</li></ul><p>&nbsp;</p>',NULL,25000.00,'2025-01-23','2025-06-30',NULL,NULL,'<p>&nbsp;</p><p><strong>Service Codes attached to the fund:</strong></p><p><strong>S20021 </strong>- ASD21 - William Allen High School</p><p><strong>S20022 </strong>- ASD21 - Trexler Middle School</p><p><strong>S20023 </strong>- ASD21 - Central Elementary School</p>','F1405','2025-02-21 18:19:22','2025-03-06 19:57:04',NULL,228,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (430,'2025 CADB NC Grow Norco South Bethlehem Facades',NULL,'<p>To be used for rehabilitation and renovation of facades in the Southside of Bethlehem to low-income homeowners.</p><ul><li>Open and Competitive Bidding Requirements on page 5</li><li>Acknowledgment of Assistance requirements page 10</li><li>This grant requires a 1-1 match of funds</li><li>Reports outlining fiscal activity and progress are due on July 8th, 2025, and January 28th, 2026. To be submitted via Neighborly Software.</li></ul><p>&nbsp;</p>',NULL,10000.00,'2025-01-01','2025-12-31',NULL,NULL,'<figure class=\"image\"><img src=\"http://10.55.0.10/storage/1426/image.png\"></figure>','F2141','2025-02-24 14:13:09','2025-02-24 15:42:03',NULL,2,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (431,'2025SSS Asbury In Mission',NULL,'<p>To support general operating of the Sixth Street Shelter.</p><p>The money will arrive in monthly payments throughout the 2025 calendar year. The February payment will reflect 2 months.&nbsp;</p>',NULL,5000.00,'2025-01-31',NULL,NULL,NULL,'<p>No reporting requirements.</p>','F8000','2025-02-24 18:26:36','2025-02-24 18:26:36',NULL,133,NULL);
