INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (434,'2024HCP City of Allentown CDBG Housing Counseling','#304','<ul><li>Personnel costs for Director, Counselors and Administrative Assistant.</li><li>Must be used for City of Allentown Residents for Pre-Purchase counseling and First time Homebuyer seminars</li></ul><p><strong>Grant goals:</strong></p><ul><li>10 residents will purchase a home</li></ul>',NULL,20000.00,'2024-01-01','2025-12-31',NULL,NULL,'<ol><li><i><strong>Please see exhibit D in the contract for required client documents.</strong></i></li><li><strong>Document Retention </strong>will be when HUD officially closes out the contract year. You will be notified when you can destroy documents by the Compliance Director.</li><li>-Quarterly Reports and Annual Performance Reports are required</li></ol>','F0500','2025-02-28 18:59:43','2025-04-29 17:23:36',NULL,226,'14.218');
