INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (457,'2025-2030 WX DOE Master Contract','C000093505','<p>Weatherization Assistance Program (WAP)</p><ul><li>Please see Appendix A for program Description and Special Conditions</li></ul>',NULL,0.00,'2025-07-01','2030-06-30',NULL,NULL,'<p><strong>Compliance Requirements:</strong></p><ul><li>Advanced funds must be kept in an interest-bearing account. We may retain up to $500 per calendar year of interest and must remit all other interest earned annually to the Department of Health and Human Services payment management system through ACH</li><li>Competitive Bidding requirements on subcontracts $10,000 or over</li><li>Acknowledgment of Commonwealth Assistance (page 14 article XIII)</li><li>Debarment and Suspension checks on contractors performing work under this grant</li></ul>',NULL,'2025-04-14 12:57:22','2025-06-09 16:06:21',NULL,136,'81.042');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (458,'2025SHFB_HomeDepotFoundation_TSF Volunteer Project','202501176','<p>This grant provides $12,002.21 to The Seed Farm in the form of gift cards to purchase supplies and equipment needed for a Home Depot Foundation volunteer project.</p><p>The anticipated project date is <strong>June 19,2025</strong>.</p><p>&nbsp;The Project Scope is below.&nbsp;</p><ul><li>Build and install 11\'x20\' Gazebo</li><li>Build and stain 6 sales tables</li><li>Build and stain a sales counter</li><li>Lay stone</li><li>Build 4-6 chalkboard signs</li><li>Build 2 sandwich board signs</li><li>Assemble and install picnic tables and park benches on property</li><li>Plant shrubs, flowers, and mulch at main entrance and around perimeter of produce area</li><li>Weeding, raking, and cleaning around the property as well as mulching, planting, and seeding in the greenhouse</li></ul><p>All associates and volunteers must sign the Volunteer Participation Waiver for <strong>both Home Depot and CALV</strong> (attached below) in order to participate.</p><p>Any recognition regarding this grant should be made in the name of The Home Depot Foundation. Prior to posting, please send all press release and social media content to the HD public relations team for review at TeamDepotPR@homedepot.com. SHFB is also encouraged to post project photos on the Home Depot Foundation Facebook page (/homedepotfoundation) or post about your project on other platforms using <strong>@HomeDepotFound</strong> and <strong>#TeamDepot</strong>.</p><p>There is no report for this grant.</p><p>Contact for this grant is:</p><p>The Home Depot Foundation<br><strong>Adam Goslin</strong><br>Foundation Field Manager<br>770-384-4309<br><a href=\"mailto:Adam_Goslin@homedepot.com\">Adam_Goslin@homedepot.com</a></p><p>Sponsoring Captain - Store 4140 - Allentown South (District 057)<br><strong>David Dimick</strong><br>ASM_4140@HomeDepot.com<br>484-809-4256</p>',NULL,0.00,'2025-04-01','2025-06-30',NULL,NULL,NULL,'F8040','2025-04-22 15:19:08','2025-05-20 12:44:39',NULL,229,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (459,'2024 SSS City of Allentown ESG',NULL,'<p>&nbsp;</p><ul><li>To be used for maintenance and utilities for the SSS</li><li>Please see section D on page 7 for Record Keeping and Monitoring</li><li>Page 2 subsection E Program Goals to be tracked below:</li></ul><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1660/image.png\"></figure>',NULL,41739.00,'2024-01-01','2025-12-31',NULL,NULL,NULL,'F1200','2025-04-22 15:44:39','2025-05-23 17:46:04',NULL,226,'14.231');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (460,'2025 CALV LC Aging and Adults Services','25-AGNG-142','<p>DO NOT USE!!!!!!</p><p><strong>HAP-Rental Assistance Payments-</strong> $317,680&nbsp;</p><p><strong>HAP- Rental Assistance Care Management-</strong> $38.17 per hour up to $28,328 for fiscal to process rental checks</p><p><strong>Food Storage and Distribution -TEFAP</strong> - lesser of .10 cents per pound or actual cost.</p><p><strong>Aftercare for the SSS Case Management-</strong> $39.58 per hour up to $35,543 for case management during client stay at the shelter and at 30,60 and 90 days post shelter exit.</p>',NULL,381551.00,'2025-07-01','2026-06-30',NULL,NULL,NULL,'F4200','2025-04-29 18:04:04','2025-05-19 13:54:47',NULL,73,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (461,'2025SSS Trexler Trust',NULL,'<p>-General Operating for the Sixth Street Shelter</p><p>-Stewardship Report due by November 1, 2025. Guidelines can be found at www.TrexlerTrust.org. <strong>Failure to file a timely report will result in the eliminations of Grantee\'s eligibility for any grant in 2026.</strong></p>',NULL,25000.00,'2025-04-25','2025-11-01',NULL,NULL,NULL,'F1215','2025-04-30 11:38:55','2025-04-30 11:38:55',NULL,146,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (462,'2025SHFB Trexler Trust Seed Farm Food Pantry Project',NULL,'<ul><li>To be used to Support the distribution of produce to Lehigh Country food pantries through Seed Farm food access Farm to Pantry initiative.</li><li>Stewardship Report due by November 1, 2025. Guidelines can be found at www.TrexlerTrust.org. <strong>Failure to file a timely report will result in the eliminations of Grantee\'s eligibility for any grant in 2026.</strong></li></ul>',NULL,15000.00,'2025-04-25','2025-11-01',NULL,NULL,NULL,'F8040','2025-04-30 11:45:36','2025-04-30 11:45:36',NULL,146,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (463,'2025 Gen Next Fulton Forward Foundation',NULL,'<p>-General Operating Support for the Generation next Program</p><ul><li><strong>Data Collection</strong> (The following should be tracked in order to apply for future funding)</li></ul><ol><li>Have you applied for an Impact Grant previously? If so, what was the project/program?</li><li>If a recurring program/project, what quantitative and qualitative measures do you currently utilize to measure success?</li><li>Please provide detailed examples of success from the past year.</li></ol>',NULL,25000.00,'2025-04-30',NULL,NULL,NULL,NULL,'8000','2025-05-05 14:13:06','2025-05-05 14:14:15',NULL,230,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (464,'2025SHFB_CheckOutHunger_CFBNJ',NULL,'<p>This agreement is between the Community FoodBank of NJ (CFBNJ) and SHFB regarding funds raised at round-up campaigns at Wawa / Wegmans stores in our service area.</p><p>Campaigns run from approximately Oct-Jan of each year.&nbsp;</p><ul><li>SHFB is responsible for:</li><li>When we become aware, notifying CFBNJ of any issues (e.g., store is not properly displaying materials and/or informing customers of the Campaign) within Retailer stores that occur during the Campaign Term. (We do not need to actively schedule site visits)</li><li>Notifying CFBNJ if we receive additional funds related to the campaign but not part of the direct contribution made by CFBNJ.</li></ul><p>The first payment for $34,613.59 will come from CFBNJ sometime during the June/July 2025 timeframe. A second check in the amount of $9,041.34 will come from Wakefern some time prior to the end of FY 2025. An additional payment will be made directly from Wegmans for an unknown amount.</p><p>Checks will be mailed directly to CALV/SHFB from either CFBNJ (for Wawa) or Wegmans within 90 days from the conclusion of each campaign. Campaign reports will also be mailed out at that time.</p><p>There is no media requirement for this contract. However:&nbsp;</p><p><i>CFBNJ hereby grants to the Food Bank a non­exclusive right to use its logo, name and/or marks (\"CFBNJ Marks\") and/or Campaign logos, names and/or marks (\"Check-Out Hunger Marks\") in any media (a) during the Campaign Term in connection with the Campaign, and (b) during and after the Campaign Term on its website(s) and in publicity materials to describe the Campaign and/or Food Bank\'s contribution to the Campaign.</i></p><p>Contact for this agreement is:</p><p>Leah Galamba<br>Community Outreach Specialist &nbsp;<br>Community FoodBank of New Jersey<br>31 Evans Terminal - Hillside NJ 07205<br>lgalamba@cfbnj.org<br>908-882-0668<br>www.cfbnj.org&nbsp;</p><p>&nbsp;</p>',NULL,0.00,'2024-10-01','2029-01-13',NULL,NULL,NULL,'F8000','2025-05-08 12:41:08','2025-05-20 12:45:44',NULL,231,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (465,'2025 SSS St. Paul\'s UCC Trexlertown',NULL,'<p><strong>Supportive Services Fund for residents</strong>. &nbsp;This may include but is not limited to tuition assistance, books and course materials, computers, rental application fees, establishing renters’ insurance, the acquisition or replacement of documents (Social Security cards, birth certificates, driver’s licenses), childcare, food, transportation costs, hygiene items, cleaning supplies, emergency assistance, and diapers and other supplies for children.&nbsp;</p>',NULL,1000.00,'2025-05-05',NULL,NULL,NULL,'<p>-There are no reporting requirements for this grant.</p>','F8000','2025-05-15 11:37:12','2025-05-15 11:37:12',NULL,154,NULL);
