INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (474,'2025 Generation Next Power and Equity Grant',NULL,'<p>DO NOT USE YET</p>',NULL,6500.00,'2025-05-30',NULL,NULL,NULL,NULL,NULL,'2025-06-02 13:55:31','2025-06-02 13:55:31',NULL,82,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (475,'2025 SSS Children and Youth','25-CY-084','<p>To provide housing and supportive services to shelter guests referred by Lehigh County Office of Children and Youth.</p><ul><li>8 apartments reserved at a rate of $70 per day (Potential to fill and bill for additional apartments)</li><li>Supportive Services at an hourly rate of $65 (Includes face to face meetings/be sure to have the resident sign the appointment log)</li><li>Curfew checks billed at an hour per day at a rate of $65&nbsp;</li><li>CAP on this contract is $355,000</li></ul><p><strong>Compliance Requirements:</strong></p><ul><li>SSS staff must have all required background checks on file and renew them every 60 months. Please see Appendix E page 11 for required clearances</li><li>All Staff must complete 12 hours of training per year. Training determined by Shelter Director.</li><li>Comply with Limited English Proficiency Guidelines (Appendix E)</li><li>Comply with HIPAA Requirements (Appendix G)</li></ul><p>&nbsp;</p><p><i><strong>***In October 2025 Lehigh County Children and Youth will reassess the need to prepay for additional apartments if needed based on rate of filling the apartments</strong></i><strong>***</strong></p>',NULL,355000.00,'2025-07-01','2026-06-30',NULL,NULL,'<p><strong>Reports:&nbsp;</strong></p><ol><li>Discharge Summary- due 14 days post discharge emailed to the assigned OCYS Case Workers and Supervisor at ocysproviderreports@lehighcounty.org</li><li>Submit daily availability list to include the number of active cases, openings, number on waitlist if applicable, and number of cases pending discharge within 2 weeks. Submitted to ocysreferralservices@lehighcounty.org</li><li>Monthly FPP reports for invoicing and reimbursement requests</li><li>Semi- Annual Report to cover July 1st- December 31st due January 15, 2026</li><li>Final Report covering January 1st- June 30th due by July 15, 2026<ul><li><strong>Please see page 1 of appendix C for new requirements on reports and notes entered into \"ACYS\" system portal once implemented. Provider shall complete weekly contact notes to be submitted within 14 days from the end of the week of service.</strong></li></ul></li></ol><p>&nbsp;</p>','F1300','2025-06-02 14:49:58','2025-06-09 14:36:25',NULL,159,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (476,'2025-2030 WX LIHEAP Master Contract','C000093487','<p>Weatherization Assistance Program- LIHEAP Crisis and Standard Weatherization</p>',NULL,0.00,'2025-10-01','2030-09-30',NULL,NULL,'<p><strong>Compliance Requirements:</strong></p><ul><li>Reimbursement for travel expenses or per diem must be at or below the Federal rate.</li><li>Advanced funds must be kept in an interest-bearing account. We may retain up to $500 per calendar year of interest and must remit all other interest earned annually to the Department of Health and Human Services payment management system through ACH</li><li>Competitive Bidding requirements on subcontracts $10,000 or over</li><li>Acknowledgment of Commonwealth Assistance (page 13 article XIII)</li><li>Debarment and Suspension checks on contractors performing work under this grant</li></ul>',NULL,'2025-06-03 18:36:26','2025-06-09 16:05:19',NULL,137,'93.568');
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (477,'2025SHFB_MANA Rose Garden Farmers Market',NULL,'<p>This contract establishes the regulations and requirements for SHFB to retain space at the Bethlehem Rose Garden Farmers Market, held at the Rose Garden in Bethlehem between Union Blvd, 8th Avenue and W. Broad St. The market will be open Saturdays from 9:00 am - 1:00 pm, beginning on June 07, 2025 and ending on October 11, 2025. The Mount Airy Neighborhood Assoc (MANA) is responsible for the operation and management of the market.</p><p>Vendors must arrive no later than 8:40 am and must be set up and ready by opening time.</p><p>A COI has been submitted naming MANA - please see below.</p><p>Contact information is:</p><p>Mary Toulouse<br>484-767-6585<br>toulousm@gmail.com</p><p>Diana or John Worley<br>worleyd84@yahoo.com</p><p>Katie Stafford<br>484-602-0243<br>kostafford@gmail.com</p>',NULL,0.00,'2025-06-07','2025-10-11',NULL,NULL,NULL,'8000','2025-06-05 13:20:41','2025-06-06 11:51:55','2025-06-06 11:51:55',232,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (478,'2025 RTCLF Northampton County Bar Association via Lehigh Valley Community Foundation',NULL,'<p>To be used to serve prospective, start- up and established businesses in Northampton County.</p>',NULL,5000.00,'2025-06-04',NULL,NULL,NULL,NULL,'F8000','2025-06-06 11:35:47','2025-06-06 11:35:47',NULL,177,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (479,'2025 SHFB Veterans Trust Fund','C890000013','<p>This is a $40,000 lump sum award to support the Military Shares program. The grant period runs from July 1, 2025 - June 30, 2026. The budget breakdown is as follows:</p><ul><li>$4,000 - Salary of Community Services Manager @ $30.25/hour</li><li>$32,500 - Purchase of food for Military Share distribution</li><li>$3,500 - Cost of final project audit</li></ul><p>Specified outcomes for the project are:</p><ul><li>Provide nutritious shelf-stable and fresh foods to at least 560 military families</li><li>Distribute 235,000 pounds of food</li><li>Engage 100 volunteers for packing and distribution</li></ul><p>Beginning with this grant period, all reporting will be done via an online portal, eGrants. Training on the eGrants portal will be announced in early- to mid-September. Reporting information:</p><figure class=\"image\"><img src=\"http://10.55.0.10/storage/1735/image.png\"></figure><p><i><strong>Funds must be kept in a separate, interest-bearing account.&nbsp;</strong></i></p><p><i><strong>An audit of all expenditures of grant funds must be completed no later than six (6) months after the termination of the agreement (Dec 30, 2026).</strong></i></p><p>Contact for this grant is:</p><p>Office of Veterans Affairs<br>Attn: Grants Team<br>Edward Martin Hall Building 0-47<br>Fort Indiantown Gap, Annville, PA 17003<br><strong>Tel</strong>: 717-376-4126<br><strong>E-mail</strong>: ra-mvvettrustfund@pa.gov</p>',NULL,40000.00,'2025-07-01','2026-06-30',NULL,NULL,NULL,'F8050','2025-06-06 14:51:16','2025-07-02 14:46:15',NULL,114,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (480,'2025 SSS Post Foundation',NULL,'<ul><li>General operating costs for the SSS.</li><li>They require a grant report (form attached) by May 30, 2026, as stated in the attached award letter.</li></ul>',NULL,20000.00,'2025-05-27',NULL,NULL,NULL,NULL,'F8000','2025-06-09 11:56:22','2025-06-09 12:12:27',NULL,151,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (481,'2025CADB Keystone Savings Foundation via LVCF',NULL,'<p>&nbsp;To support Southside Tomorrow initiative specifically to cover program and operations costs incurred by the Community Housing Advocate Program, which can include: advertising, supplies, food, and space rental.&nbsp;</p><p>&nbsp;</p><p><br>&nbsp;</p>',NULL,5000.00,'2025-06-04',NULL,NULL,NULL,'<ul><li>Please not that grants for operations and program will not be made to the same organization for more than three (3) consecutive years. After three consecutive years of funding, an organization must wait a minimum of one year before applying for another grant.</li></ul>','F8000','2025-06-12 10:58:16','2025-06-12 10:58:16',NULL,218,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (482,'2025 HCP TD Charitable Foundation',NULL,'<ul><li>HCP General Operating Support.</li><li>Report required TBD (email will be sent to planner when the report is due)</li></ul><p>&nbsp;</p>',NULL,7500.00,'2025-05-23',NULL,NULL,NULL,NULL,'F8000','2025-06-12 11:10:15','2025-06-12 11:11:14',NULL,233,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (483,'2025 SBR Greater Lehigh Valley Chamber of Commerce',NULL,'<p>River rock beautification project in the Borough of Portland. (See attached proposal)</p><ul><li>&nbsp;Before and after photos of the project and the check request form are required by the funder upon completion of the project.</li><li>Attendance at a grant reception on 8/20 is also required.&nbsp;</li><li>50% percent matching funds are required ($4000 of receipts must be shown for this project)</li></ul>',NULL,2000.00,'2025-07-01','2026-06-30',NULL,NULL,NULL,'F8000','2025-06-25 16:54:16','2025-06-25 16:54:16',NULL,163,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (484,'2025HCP National Community Reinvestment Coalition Field Empowerment Fund',NULL,'<p>To provide pre-purchase counseling to first time homebuyers</p><ul><li>Focus on underserved populations, BIPOC community</li><li>Eligible expenses are salaries, benefits, marketing, advertising, phone and internet, postage, printing, supplies, training and indirect costs.</li><li>Must have an active membership with NCRC</li><li>One member of the leadership team and one HUD certified housing counselor must attend a required training on heirs \'property challenges and best practices hosted by NCRC National Training Academy.</li></ul><p><strong>Please see Exhibit A for Payment Schedule</strong></p>',NULL,10000.00,'2025-06-01','2026-07-31',NULL,NULL,'<figure class=\"image\"><img src=\"http://10.55.0.10/storage/1745/image.png\"></figure><p>&nbsp;</p>','F0551','2025-06-27 12:57:10','2025-06-27 13:21:48',NULL,234,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (485,'SSS United Way Greater Lehigh Valley Housing Hero',NULL,'<p>General Operating Sixth Street Shelter</p>',NULL,20000.00,'2025-07-01','2026-07-31',NULL,NULL,'<p><strong>Payments will come in monthly at a rate of $1,666.66 per month.</strong></p><p><strong>Reporting due January 2026 and July 2026 reach out to Priscilla Rosado at priscillar@unitedwayglv.org</strong></p>','F8033','2025-06-27 14:43:41','2025-07-03 19:37:57',NULL,235,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (486,'2026 HCP SSS Santander',NULL,'<ul><li>General Operating for HCP ($5,000) and SSS ($5,000)</li><li>Social Media post required</li></ul>',NULL,10000.00,'2025-07-01','2026-07-31',NULL,NULL,'<p>Reporting:</p><ul><li>6 month report due by January 15, 2026</li><li>Final Report due by August 15, 2026</li><li>See section 3 of the grant agreement for the required information</li></ul>','F8000','2025-06-30 14:59:48','2025-07-09 12:03:57',NULL,105,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (487,'2025SHFB_Feeding America Advocacy',NULL,'<p>The purpose of this grant is to accelerate advocacy efforts on our shared legislative policy priorities and engage lawmakers in advance of the budget reconciliation in the House of Representatives. This is a lump sum grant for $7,500.</p><p>Eligible Expenses</p><ul><li>Staff salary and benefits</li><li>Ads / media buys</li><li>Consultant or lobbying support</li><li>Supplies</li><li>Technology</li><li>Program materials</li><li>Neighbor compensation</li><li>Travel and per diem costs, including expenses incurred from staff or neighbor attendance at lawmaker meetings</li></ul><p>Ineligible Expenses</p><ul><li>Food for general distributions that do not engage lawmakers</li><li>Other spending unrelated to advancing the Feeding America network’s legislative policies around budget reconciliation.</li></ul><p>All budget reconciliation activities/engagements should be logged in the <a href=\"https://feedingamerica.quorum.us/log/\"><strong>Feeding America Advocacy Tracker</strong></a><strong>. </strong>There is no other reporting required for this grant.<br><br>Please direct legislative advocacy questions to Thao Nguyen, Vice President of Advocacy and CommunityEngagement, at <a href=\"thaonguyen@feedingamerica.org\">thaonguyen@feedingamerica.org</a>.</p><p>Please direct technical GMS-related questions, such as application or report submission, to Sally Yan, Sr.Manager, Member Grants, at <a href=\"syan@feedingamerica.org\">syan@feedingamerica.org</a>.</p>',NULL,7500.00,'2025-06-01','2025-07-11',NULL,NULL,NULL,'F8000','2025-07-01 12:47:26','2025-07-01 12:47:58',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (488,'2025SHFB_Verna O. Canova Foundation_TSF',NULL,'<p>This is a $7,500 lump sum award to support general operating expenses for The Seed Farm.</p><p>There is one report due on January 31, 2026. The template can be found at https://vernacanovafoundation.com/ The report must be physically mailed to the office at:<br><br>THE VERNA 0. CANOVA FOUNDATION<br>C/O PHILIP E. CANOY A<br>P.O. BOX 74<br>MARINE ON ST. CROIX, MN 5504 7&nbsp;</p><p>&nbsp;</p>',NULL,7500.00,'2025-06-19','2025-12-31',NULL,NULL,NULL,'8040','2025-07-02 14:31:08','2025-07-03 12:56:31',NULL,NULL,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (489,'2026 HCP PNC',NULL,'<p>To be used as specified by the budget below:</p><ul><li>Program Staff salary and benefits: $5,000</li><li>Program Supplies, Equipment and Maintenance: $2,000</li><li>Books, Subscriptions, References and Advertising- $1,500</li><li>Staff Training, Tavel and Conferences- $500</li><li>Admin: $1,000</li></ul><p><strong>Report:</strong> An annual report will do due within one year of the paid date and an automatic email will be sent to indicate when the report is due.</p>',NULL,10000.00,'2025-06-18','2026-06-15',NULL,NULL,'<p><strong>Acknowledgment:</strong></p><p>The Grantee agrees to acknowledge the PNC Foundation’s Grant in accordance with acknowledgements customarily given by Grantee for similar size grants. The PNC Foundation may include information on this Grant in its periodic public reports.</p>','F8000','2025-07-09 11:30:09','2025-07-09 12:09:08',NULL,78,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (490,'2026 RTCLF Wells Fargo',NULL,'<p>General Operating</p><p>Detailed Budget:</p><ul><li>Salaries and Wages: $12,000</li><li>Employe Benefits: $4,250</li><li>Program Admin: $3,750</li><li>Bad Debt Expense/ Loan Loss Reserve: $5,000</li></ul>',NULL,25000.00,'2025-07-09',NULL,NULL,NULL,'<ul><li><strong>Report is required although due date is TBD.&nbsp;</strong></li><li><strong>An automatic email from the funder will be sent out when it is due.</strong></li></ul>','F8000','2025-07-11 11:47:30','2025-07-11 11:50:11',NULL,79,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (491,'2025SHFB_Costco Food Purchase',NULL,'<p>This grant is to support food sourcing efforts and may be used <strong>for food purchases only</strong>. Recipients are encouraged to spend the funds at a local Costco.</p><p>The food purchased with these funds should be receipted as purchased product and not donated product. Reach out to your ERP specialist if you need assistance with receipting your order.</p><p>Information regarding the receipting of these goods is attached below.</p><p><strong>Reporting Requirements</strong></p><p>There will be one (1) report required for this grant, to be collected via the GMS.<strong>&nbsp;</strong></p><p>Final report – due March 24, 2026 – covering entire grant period of June 1, 2025 through February 28, 2026 <i>(9 months). </i>A sample report template is attached; the actual report should be submitted via the FA Grants Management System.</p><p>Report requirements include, but are not limited to:</p><ul><li>Confirmation of funds expenditure</li><li>Amount spent and where the food was sourced</li><li>Purchases (quantity &amp; description) tracked by food category, pounds, and cost</li><li>Description of program(s) supported by the purchases</li><li>Grant impact</li><li>Stories/testimonials</li></ul><p><strong>Publicity Requirements</strong></p><p>The donor does not wish to have media or recognition around this grant; listing in an annual report is fine, but no further publicity is required.</p><p>Questions regarding Feeding America’s relationship with Costco shall be directed to<strong> Charina Layman</strong>, <i>Sr</i>. <i>Manager, Corporate Partnerships</i>,&nbsp;<a href=\"mailto:chlayman@feedingamerica.org\">chlayman@feedingamerica.org</a>&nbsp;</p>',NULL,45454.00,'2025-06-01','2026-02-28',NULL,NULL,NULL,NULL,'2025-07-15 13:27:10','2025-07-15 13:56:52',NULL,149,NULL);
INSERT INTO `contracts` (`id`, `title`, `contract_number`, `purpose`, `date_of_award`, `amount`, `start_date`, `end_date`, `archived`, `date_archived`, `notes`, `grant_code`, `created_at`, `updated_at`, `deleted_at`, `funder_id`, `cfda_number`) VALUES (492,'2025-2026 SSS Mental Health Initiative MOAs',NULL,NULL,NULL,0.00,NULL,NULL,NULL,NULL,NULL,NULL,'2025-07-21 18:38:09','2025-07-21 18:38:09',NULL,NULL,NULL);
