INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (18,'2023-04-14','incomplete','<p>CSBG 1st Quarter Report due by 4/14/23. Report on data from 1/1/23-3/31/23.</p><p>Individual program reporting forms for each program can be founds using the following link:</p><p><a href=\"https://caclv.sharepoint.com/sites/PlanningDepartment/GRANT%20PROPOSALS/Forms/AllItems.aspx?id=%2Fsites%2FPlanningDepartment%2FGRANT%20PROPOSALS%2FCSBG%2FCSBG%202022%2D2027%2FCSBG%202023%2FQuarterly%20Reporting&amp;p=true&amp;ct=1680017772247&amp;or=OWA%2DNT&amp;cid=e588569c%2Dc1ca%2D6850%2D5576%2D1ebf294d64d4&amp;ga=1\">Planning Department - Quarterly Reporting - All Documents (sharepoint.com)</a></p>',NULL,'2023-03-15 15:21:05','2024-01-16 17:35:31',NULL,77,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (19,'2023-07-14','incomplete','<p>CSBG 2nd Quarter Report due by 7/14/23. Report on data from 4/1/23-6/30/23.</p><p>Individualized forms for each program can be found suing the following link:</p><p><a href=\"https://caclv.sharepoint.com/sites/PlanningDepartment/GRANT%20PROPOSALS/Forms/AllItems.aspx?id=%2Fsites%2FPlanningDepartment%2FGRANT%20PROPOSALS%2FCSBG%2FCSBG%202022%2D2027%2FCSBG%202023%2FQuarterly%20Reporting&amp;p=true&amp;ct=1680017772247&amp;or=OWA%2DNT&amp;cid=e588569c%2Dc1ca%2D6850%2D5576%2D1ebf294d64d4&amp;ga=1\">Planning Department - Quarterly Reporting - All Documents (sharepoint.com)</a></p>',NULL,'2023-03-15 15:24:26','2024-01-16 17:35:31',NULL,77,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (20,'2023-10-13','incomplete','<p>CSBG 3rd Quarter Report due by 10/13/23. Report on data from 7/1/2023-9/31/2023.</p><p>Individualized forms for each program can be found using the following link:</p><p><a href=\"https://caclv.sharepoint.com/sites/PlanningDepartment/GRANT%20PROPOSALS/Forms/AllItems.aspx?id=%2Fsites%2FPlanningDepartment%2FGRANT%20PROPOSALS%2FCSBG%2FCSBG%202022%2D2027%2FCSBG%202023%2FQuarterly%20Reporting&amp;p=true&amp;ct=1680017772247&amp;or=OWA%2DNT&amp;cid=e588569c%2Dc1ca%2D6850%2D5576%2D1ebf294d64d4&amp;ga=1\">Planning Department - Quarterly Reporting - All Documents (sharepoint.com)</a></p>',NULL,'2023-03-15 15:25:48','2024-01-16 17:35:32',NULL,77,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (21,'2024-02-24','incomplete','<p>Evaluation report due within one year of receipt of funds.&nbsp;</p><p>Reporting Log In</p><p>Link to online reporting system: <a href=\"https://www.cybergrants.com/pls/cybergrants/ao_login.login?x_gm_id=4828&amp;x_proposal_type_id=30870\">PNC - Log In (cybergrants.com)&nbsp;</a></p><p>Log in: planner-CAFS@caclv.org</p><p>Password: Caclv1337!</p>',NULL,'2023-03-17 11:39:14','2024-01-16 17:35:32',NULL,153,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (22,'2023-06-01','incomplete','<p>Report due by 6/1/23 to be complete on the LVCF online portal.&nbsp;</p><p><a href=\"https://www.grantinterface.com/Home/Logon?urlkey=lehighvalley\">Logon - Grant Lifecycle Manager (grantinterface.com)</a>&nbsp;</p><p>Username: aboccadoro@caclv.org</p><p>Password: caclv1337</p><p>(Completion reports for your Laros grant-supported project are expected by June 1, 2023, through the <a href=\"https://www.grantinterface.com/Home/Logon?urlkey=lehighvalley\">LVCF portal</a>.</p><p>If you have any questions please contact Sharon Zondag&nbsp;@ <a href=\"http://larosfoundation.org/\">larosfoundation.org</a></p>',NULL,'2023-03-23 13:21:08','2024-01-16 17:35:32',NULL,102,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (23,'2024-02-01','incomplete','<p>Binal Report Due for the LVCF Synergy Fund for CALV.</p><p>Data to be collected:&nbsp;Brief one page summary of the activities and any outcomes associated with the project and how the funding was spent.</p><p>&nbsp;Submit by email to: Megan@lvcfoundation.org</p>',NULL,'2023-03-23 13:28:37','2024-01-16 17:35:33',NULL,120,1);
