INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (189,'2024-07-30','incomplete','<p>At the conclusion of the TEFAP Reach and Resiliency Grant Award period, you will have 45</p><p>days in which to submit a final report on your project to the Pennsylvania Department of</p><p>Agriculture’s Bureau of Food Assistance. By no later than July 30, 2024, please submit a final</p><p>report to Caryn Long Earl (<a href=\"cearl@pa.gov\">cearl@pa.gov</a>) detailing the following:</p><ul><li>Final project expenditures</li><li>Information on any new partner agencies through whom you are distributing TEFAP</li><li>Information detailing how you have used these funds to expanded the reach of TEFAP</li><li>in your service territory</li><li>If applicable, information regarding increased geographic areas served through this</li><li>project</li><li>Metrics on the increased numbers of individuals served and demographics of increased</li><li>individuals served</li><li>Pounds of TEFAP distributed before and after implementation of project</li><li>Information regarding client satisfaction</li><li>Other relevant data or information regarding improved TEFAP reach in the community</li><li>being served</li></ul>',NULL,'2024-01-25 19:12:01','2024-07-09 12:07:27',NULL,298,1);
INSERT INTO `report_due_dates` (`id`, `due_date`, `status`, `description`, `microsoft_event_id`, `created_at`, `updated_at`, `deleted_at`, `contract_id`, `invite_sent`) VALUES (190,'2024-07-28','incomplete','<p>-Reporting semi-annually July 28, 2024, and January 8th, 2025, to be completed in the Neighborly Portal. (See page 7 section 27 in the contract)</p><p>&nbsp;</p><p>https://portal.neighborlysoftware.com/northamptoncountypa/participant</p>',NULL,'2024-02-01 17:21:41','2024-02-03 01:22:03',NULL,299,1);
