INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (21,'2024-02-24','incomplete','<p>Evaluation report due within one year of receipt of funds.&nbsp;</p><p>Reporting Log In</p><p>Link to online reporting system: <a href=\"https://www.cybergrants.com/pls/cybergrants/ao_login.login?x_gm_id=4828&amp;x_proposal_type_id=30870\">PNC - Log In (cybergrants.com)&nbsp;</a></p><p>Log in: planner-CAFS@caclv.org</p><p>Password: Caclv1337!</p>','2023-03-17 11:39:14','2023-03-17 11:39:47',NULL,153);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (22,'2023-06-01','incomplete','<p>Report due by 6/1/23 to be complete on the LVCF online portal.&nbsp;</p><p><a href=\"https://www.grantinterface.com/Home/Logon?urlkey=lehighvalley\">Logon - Grant Lifecycle Manager (grantinterface.com)</a>&nbsp;</p><p>Username: aboccadoro@caclv.org</p><p>Password: caclv1337</p><p>(Completion reports for your Laros grant-supported project are expected by June 1, 2023, through the <a href=\"https://www.grantinterface.com/Home/Logon?urlkey=lehighvalley\">LVCF portal</a>.</p><p>If you have any questions please contact Sharon Zondag&nbsp;@ <a href=\"http://larosfoundation.org/\">larosfoundation.org</a></p>','2023-03-23 13:21:08','2023-05-05 11:59:40',NULL,102);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (23,'2024-02-01','incomplete','<p>Binal Report Due for the LVCF Synergy Fund for CALV.</p><p>Data to be collected:&nbsp;Brief one page summary of the activities and any outcomes associated with the project and how the funding was spent.</p><p>&nbsp;Submit by email to: Megan@lvcfoundation.org</p>','2023-03-23 13:28:37','2023-03-23 13:28:37',NULL,120);
