INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (37,'2023-04-21','incomplete','<p>The High Foundation is asking for the following:</p><ol><li><strong>Mission Statement &amp; Success Story</strong> | In approximately 100 words summarize your mission and include any success stories.</li><li><strong>Testimonial</strong> | A testimonial from your leadership about the impact of your work due to your partnership with the High Foundation.</li><li><strong>3-5 High Resolution Photos </strong>| These photos should tell the story of the High Foundation funding in action. Please note that all photos must have signed photo releases on file.</li></ol><p>How to upload content</p><p><a href=\"https://app.smartsheet.com/b/form/94ec8a7a2b294661a2287d9918b7fb5e\">Community Partner Content Request (smartsheet.com)</a></p><p>Deadline</p><ul><li><strong>Friday, April 21</strong></li></ul>','2023-03-30 13:45:55','2023-04-10 12:22:57','2023-04-10 12:22:57',124);
