INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (82,'2023-11-15','incomplete','<p>Written progress report due to the foundation by November 15, 2023. Please use the progress report form in the award notification document. Written report should be sent to:</p><p>&nbsp;</p><p>Sheri Utt</p><p>Trust Officer</p><p>100 North Main Street, D4000-065</p><p>Winston-Salen, NC, 27101</p><p>&nbsp;</p><p>or</p><p>Sheri.m.utt@wellsfargo.com</p>','2023-05-22 17:06:45','2023-05-22 17:06:45',NULL,183);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (83,'2024-06-28','incomplete','<p>****Upon completion of your project, you must submit a final report with your invoice. Invoice will not be paid without a report. Final Report template and reimbursement template is attached. Reimbursement request must come with the receipts showing the expenses and must be dated within terms of the contract. These items will only be accepted electronically via a PDF. Reimbursement and reports must be sent to this email address for prompt review and process of reimbursements. <a href=\"mailto:ra-agpafarmbillgrant@pa.gov\">ra-agpafarmbillgrant@pa.gov</a></p>','2023-05-24 16:58:32','2023-05-24 16:58:32',NULL,182);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (84,'2023-10-31','incomplete','<p>Reporting:</p><p>Initial Progress Report due October 31, 2023, covering June 1, 2023- September 30, 2023.</p><p>Final Report due March 19th, 2024, covering entire grant period of June 1st, 2023- February 29, 2024.&nbsp;</p><p>****Final report will only be required if the funds were not fully expended by the initial progress report.</p><p>Information to be collected:</p><p>-Confirmation of fund expenditures, purchase (quantity and description) tracked by food category, pounds and costs, description of programs supported by the purchases, grant impact, stories and testimonials.</p><p>&nbsp;</p>','2023-06-14 14:52:32','2023-06-14 18:59:17',NULL,189);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (85,'2024-03-19','incomplete','<p>Reporting:</p><p>Initial Progress Report due October 31, 2023, covering June 1, 2023- September 30, 2023.</p><p>Final Report due March 19th, 2024, covering entire grant period of June 1st, 2023- February 29, 2024.&nbsp;</p><p>****Final report will only be required if the funds were not fully expended by the initial progress report.</p><p>&nbsp;</p><p>Information to be collected:</p><p>-Confirmation of fund expenditures, purchase (quantity and description) tracked by food category, pounds and costs, description of programs supported by the purchases, grant impact, stories and testimonials.</p>','2023-06-14 14:53:28','2023-06-14 18:58:38',NULL,189);
INSERT INTO `report_due_dates_dev` (`id`, `due_date`, `status`, `description`, `created_at`, `updated_at`, `deleted_at`, `contract_id`) VALUES (86,'2024-01-31','incomplete','<p>6-month report due by 1/31/24&nbsp;</p><p>Items to be included:</p><p>-use of donated funds and progress towards achieving objectives, impact of grant funds, whether or not funds were diverted from the purpose of the grant, financial report of detailed expenditures.</p><p>Log in:</p><p><a href=\"https://apply.yourcausegrants.com/apply/programs/01f0a8c2-c027-408e-9e58-224e211617e2\">https://apply.yourcausegrants.com/apply/programs/01f0a8c2-c027-408e-9e58-224e211617e2</a></p><p>Email: <a href=\"mailto:planner-CACLV@caclv.org\">planner-CACLV@caclv.org</a></p><p>Password: CAClv1337!!!</p><p>As your planner for the code when you are attempting the log in.</p>','2023-06-21 13:38:04','2023-06-21 13:42:13',NULL,190);
